package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.ReflectAccess
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.InjectedUiLocale
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.TargetAppStorage
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.Method

/**
 * 详情页「含AI生成内容」拦截 + 补位。
 *
 * 落点与 [DetailUnitedModulePurifyFeatureInstaller] 相同（`viewunite.v1.ViewMoss` 的同步
 * `executeView` 与异步 `view`），但**只改 `ecode` / `ecode_config` 两个顶层字段**：
 *
 * - 命中声明、且相关推荐里有可用视频 → `ecode=CODE_404` + `redirect_url=<补位视频路由>`。
 *   宿主 `ViewRepository` 把它映射成 `ViewNotFoundException(jumpUrl)`，
 *   `BusinessScopeDriverImpl` 对非空 jumpUrl 执行 `BLRouter.routeTo` 并关掉当前页
 *   （8.89.0 反汇编实证；"NotFound, jump to:" 日志串与两个异常类 27 版宿主全在）。
 * - 没有可用补位、或连锁跳转超过上限 → `ecode=CODE_ARC_PRIVACY` + `msg=<提示>`，
 *   走宿主原生的"不可见"错误页，页面文案就是我们的提示。
 *
 * 没有命中时，若相关推荐里有本进程已知的 AI 视频，删掉那几张卡（第二条链，独立降级）。
 *
 * 边界纪律同详情页协议层净化：副本改写、排除默认实例、改完回读、任何异常交付原响应。
 */
internal class AiDeclaredVideoFeatureInstaller(
    private val enabled: Boolean,
    /** 强力模式 · 屏蔽发布者。 */
    private val strongMode: Boolean,
    /** 强力模式 · 获取 access_key 推荐预检；宿主入口已按「预检开 且 已授权」合成。 */
    private val precheck: Boolean = false
) : FeatureInstaller {

    override val id: String = AiDeclaredVideoPolicy.ID

    override val capabilityIds: List<String>
        get() = if (!enabled) emptyList() else buildList {
            add(AiDeclaredVideoPolicy.CAPABILITY_DETAIL)
            if (strongMode) add(AiDeclaredVideoPolicy.CAPABILITY_AUTHOR)
        }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val interceptor = AiDeclaredReplyInterceptor.resolve(loader)
            ?: return missing(environment, "not-applicable-host")
        val mossClass = KavaMemberLookup.classOrNull(loader, DetailUnitedModulePurifyPolicy.MOSS_CLASS)
            ?: return missing(environment, "not-applicable-host")
        val requestClass = KavaMemberLookup.classOrNull(loader, DetailUnitedModulePurifyPolicy.REQUEST_CLASS)
            ?: return missing(environment, "not-applicable-host")
        val handlerClass = KavaMemberLookup.classOrNull(loader, HANDLER_CLASS)

        AiDeclaredVideoRegistry.loadAsync {
            TargetAppStorage.cacheFile(AiDeclaredVideoRegistry.fileName())
        }
        val authors = if (strongMode) {
            ScanSnapshotPublisher(environment, MineComponentSnapshotCodec.SURFACE_AUTHOR_PICKS,
                setOf("home_recommend_author_block"))
        } else {
            null
        }
        val guard = AiRedirectGuard()
        // 缺了就一律按详情页处理：退化成"历史页也会拦"，不会退化成"详情页不拦"。
        val spmidGetter = KavaMemberLookup.methodOrNull(requestClass, "getSpmid")
            ?.takeIf { it.returnType == classOf<String>() }
        if (spmidGetter == null) {
            environment.logError("ai_declared_spmid_absent", "[BIL] ViewReq#getSpmid 不可用，无法区分历史页后台请求")
        }
        fun passive(request: Any?): Boolean = runCatching {
            request != null && spmidGetter != null &&
                AiDeclaredVideoPolicy.isPassiveRequest(spmidGetter.invoke(request) as? String)
        }.getOrDefault(false)
        val playlist = installPlaylistSkipper(environment, loader)
        // 连播的连锁保险单独计数：一个列表里连着几集 AI 很常见，额度比详情页补位宽。
        val playlistGuard = AiRedirectGuard(maxRedirects = PLAYLIST_SKIPS, windowMillis = 60_000L)
        val prechecker = if (precheck) installPrechecker(environment, loader, interceptor) else null
        val handle: (Any, Boolean) -> Any = { reply, passive ->
            interceptor.process(
                reply, environment, guard, passive,
                playlist = playlist, playlistGuard = playlistGuard,
                onRelateCandidates = prechecker?.let { it::submit }
            ) { name, mid ->
                authors?.let { recordAuthor(environment, it, name, mid) }
            }
        }

        var routes = 0
        runCatching {
            environment.registrar.exact(
                "ai_declared.sync.${DetailUnitedModulePurifyPolicy.SYNC_METHOD}",
                mossClass,
                DetailUnitedModulePurifyPolicy.SYNC_METHOD,
                requestClass
            ) {
                after {
                    if (hasThrowable) return@after
                    val original = result ?: return@after
                    val updated = handle(original, passive(argOrNull(0)) || AiRelatePrechecker.isQueryThread())
                    if (updated !== original) result = updated
                }
            }
            routes++
        }.onFailure {
            environment.logError("ai_declared_sync", "[BIL] AI 声明拦截同步响应 Hook 注册失败: $it")
        }
        if (handlerClass != null) {
            runCatching {
                environment.registrar.exact(
                    "ai_declared.async.${DetailUnitedModulePurifyPolicy.ASYNC_METHOD}",
                    mossClass,
                    DetailUnitedModulePurifyPolicy.ASYNC_METHOD,
                    requestClass,
                    handlerClass
                ) {
                    before {
                        val original = argOrNull(1) ?: return@before
                        val isPassive = passive(argOrNull(0)) || AiRelatePrechecker.isQueryThread()
                        val proxy = MossResponseHandlerProxy.wrapTransform(handlerClass, original) { reply ->
                            handle(reply, isPassive)
                        } ?: return@before
                        args[1] = proxy
                    }
                }
                routes++
            }.onFailure {
                environment.logError("ai_declared_async", "[BIL] AI 声明拦截异步响应 Hook 注册失败: $it")
            }
        } else {
            environment.logError(
                "ai_declared_handler_absent",
                "[BIL] 未找到 MossResponseHandler，AI 声明拦截只覆盖同步路径"
            )
        }
        if (routes == 0) return missing(environment, "no-safe-united-path")
        val feedRoutes = installRelatesFeed(environment, loader, mossClass, handlerClass, interceptor)

        environment.reportCapabilityCoverage(
            AiDeclaredVideoPolicy.CAPABILITY_DETAIL, ready = true, routes, PATHS
        )
        if (strongMode) {
            environment.reportCapabilityCoverage(
                AiDeclaredVideoPolicy.CAPABILITY_AUTHOR,
                ready = environment.writeScanSnapshot != null, routes, PATHS
            )
        }
        environment.reportRuntimeEvidence(id, FeatureRuntimeStage.ADAPTED)
        val partial = buildList {
            if (routes < PATHS) add("routes:$routes/$PATHS")
            if (!interceptor.relateStripReady) add("missing-relate-writeback")
            if (feedRoutes == 0) add("missing-relates-feed")
            if (precheck && prechecker == null) add("missing-precheck")
            if (playlist == null) add("missing-playlist-skip")
            if (strongMode && environment.writeScanSnapshot == null) add("missing-snapshot-sink")
        }
        environment.reportStatus(
            CHANNEL_STATUS,
            if (partial.isEmpty()) "success" else partial.joinToString(prefix = "partial:", separator = "+")
        )
        environment.logInfo(
            "ai_declared_installed",
            "[BIL] AI 声明拦截已安装，routes=$routes, strong=$strongMode, " +
                "relateStrip=${interceptor.relateStripReady}, relatesFeed=$feedRoutes, " +
                "precheck=${prechecker != null}, playlist=${playlist != null}"
        )
        return FeatureInstallResult.Installed(routes, complete = partial.isEmpty())
    }

    /**
     * 强力模式的推荐后台预检。账号令牌状态只在预检线程上读（读 AccountStorage 可能触盘，不放进 attach），
     * 状态变化才上报，报的只是 ready/not_logged_in/expired/unavailable，令牌原文不出这一层。
     */
    private fun installPrechecker(
        environment: HookEnvironment,
        loader: ClassLoader,
        interceptor: AiDeclaredReplyInterceptor
    ): AiRelatePrechecker? {
        val probe = BiliAccessKeyProbe.resolve(loader)
        val query = AiViewQuery.resolve(loader, interceptor::isDeclared)
        if (probe == null || query == null) {
            environment.logError(
                "ai_declared_precheck_missing",
                "[BIL] 推荐预检锚点缺失(account=${probe != null}, view=${query != null})，不做推荐预检"
            )
            return null
        }
        val lastState = java.util.concurrent.atomic.AtomicReference<BiliAccessKeyState?>(null)
        return AiRelatePrechecker(
            query = query::query,
            ready = {
                val context = ReflectAccess.currentApplication()
                val state = context?.let(probe::state) ?: BiliAccessKeyState.UNAVAILABLE
                if (lastState.getAndSet(state) != state) {
                    environment.reportStatus(ACCESS_KEY_STATUS, state.code)
                }
                state == BiliAccessKeyState.READY
            },
            onDeclared = { aid ->
                if (AiDeclaredVideoRegistry.add(aid)) {
                    environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.ID, FeatureRuntimeStage.APPLIED)
                }
            }
        )
    }

    /**
     * 推荐「加载更多」删已知 AI 卡；独立于详情页拦截，缺失只让这一条降级。
     * @return 注册成功的入口数（同步 + 异步，最多 2）。
     */
    private fun installRelatesFeed(
        environment: HookEnvironment,
        loader: ClassLoader,
        mossClass: Class<*>,
        handlerClass: Class<*>?,
        interceptor: AiDeclaredReplyInterceptor
    ): Int {
        val stripper = AiRelatesFeedStripper.resolve(loader)
        val requestClass = KavaMemberLookup.classOrNull(loader, AiRelatesFeedStripper.REQUEST_CLASS)
        if (stripper == null || requestClass == null) {
            environment.logError("ai_declared_feed_missing", "[BIL] 推荐续页结构缺失，加载更多的推荐不做 AI 声明过滤")
            return 0
        }
        val errorLogged = java.util.concurrent.atomic.AtomicBoolean(false)
        val transform: (Any) -> Any = transform@{ reply ->
            runCatching {
                val (updated, removed) = stripper.strip(reply, interceptor::isKnownAiCard) ?: return@transform reply
                environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.ID, FeatureRuntimeStage.APPLIED, removed)
                updated
            }.getOrElse {
                environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.ID, FeatureRuntimeStage.ERROR)
                if (errorLogged.compareAndSet(false, true)) {
                    environment.logError("ai_declared_feed_copy", "[BIL] 推荐续页 AI 卡过滤失败，保留原响应: ${it.javaClass.simpleName}")
                }
                reply
            }
        }
        var installed = 0
        runCatching {
            environment.registrar.exact(
                "ai_declared.feed.sync", mossClass, AiRelatesFeedStripper.SYNC_METHOD, requestClass
            ) {
                after {
                    if (hasThrowable) return@after
                    val original = result ?: return@after
                    val updated = transform(original)
                    if (updated !== original) result = updated
                }
            }
            installed++
        }.onFailure {
            environment.logError("ai_declared_feed_sync", "[BIL] 推荐续页同步 Hook 注册失败: $it")
        }
        if (handlerClass != null) {
            runCatching {
                environment.registrar.exact(
                    "ai_declared.feed.async", mossClass, AiRelatesFeedStripper.ASYNC_METHOD, requestClass, handlerClass
                ) {
                    before {
                        val original = argOrNull(1) ?: return@before
                        args[1] = MossResponseHandlerProxy.wrapTransform(handlerClass, original, transform) ?: return@before
                    }
                }
                installed++
            }.onFailure {
                environment.logError("ai_declared_feed_async", "[BIL] 推荐续页异步 Hook 注册失败: $it")
            }
        }
        return installed
    }

    /**
     * 连播跳过的两个 Hook：记下最新的连播调度对象、在条目构造时给已知 AI 标失效。
     * 任一环节缺失返回 null，连播退回详情页那条行为（离开列表跳转补位），状态报 partial。
     */
    private fun installPlaylistSkipper(environment: HookEnvironment, loader: ClassLoader): AiPlaylistSkipper? {
        val skipper = AiPlaylistSkipper.resolve(loader) ?: run {
            environment.logError("ai_declared_playlist_missing", "[BIL] 连播跳过锚点缺失，连播中将按详情页方式改道")
            return null
        }
        return runCatching {
            val director = checkNotNull(KavaMemberLookup.classOrNull(loader, AiPlaylistSkipper.DIRECTOR_CLASS))
            val descriptor = checkNotNull(KavaMemberLookup.classOrNull(loader, AiPlaylistSkipper.MEDIA_DESCRIPTOR_CLASS))
            director.declaredConstructors.forEachIndexed { index, constructor ->
                environment.registrar.constructor("ai_declared.playlist.director.$index", constructor) {
                    after { thisObject?.let(skipper::onDirectorCreated) }
                }
            }
            environment.registrar.exact(
                "ai_declared.playlist.construct", descriptor, "constructWith", classOf<Array<Any>>()
            ) {
                before {
                    val target = thisObject ?: return@before
                    @Suppress("UNCHECKED_CAST")
                    val values = argOrNull(0) as? Array<Any?> ?: return@before
                    if (skipper.onConstruct(target, values)) {
                        environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.CAPABILITY_DETAIL, FeatureRuntimeStage.APPLIED)
                    }
                }
            }
            skipper
        }.getOrElse {
            environment.logError("ai_declared_playlist_register", "[BIL] 连播跳过 Hook 注册失败: $it")
            null
        }
    }

    /**
     * 本进程已发布过的发布者（名字小写）。
     *
     * 发布与否**只**看这份集合：`AuthorPickSession` 上限 64 且与三点面板共用，写满后 `add` 恒为 false，
     * 早先以它的返回值决定发布，会让第 33 位之后的发布者既不即时生效也进不了名单。
     */
    private val publishedAuthors = AiAuthorLedger(MineComponentSnapshotCodec.MAX_ENTRY_COUNT)

    /** 强力模式：本进程立即生效（尽力而为）+ 发布到点选观测面，长期名单由模块 App 并入。 */
    private fun recordAuthor(
        environment: HookEnvironment,
        publisher: ScanSnapshotPublisher,
        name: String?,
        mid: Long
    ) {
        val safeName = name?.trim()?.takeIf(String::isNotEmpty)
        mid.takeIf { it > 0 }?.let { AuthorPickSession.add(it.toString()) }
        if (safeName == null) return
        AuthorPickSession.add(safeName)
        if (!publishedAuthors.claim(safeName)) return
        publisher.accumulate(
            MineComponentScanEntry.create(
                "author", safeName, safeName, AiDeclaredVideoPolicy.AUTHOR_PICK_ORIGIN_URI, true
            )?.copy(selectionToken = java.util.UUID.randomUUID().toString())
        )
        environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.CAPABILITY_AUTHOR, FeatureRuntimeStage.APPLIED)
        // 日志只记事件，不记 UP 名（名字会经观测快照呈现给用户，不必再进日志）。
        environment.logInfo("ai_declared_author_recorded", "[BIL] 强力模式已记下一位发布者，待模块 App 并入名单")
    }

    private fun missing(environment: HookEnvironment, reason: String): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("ai_declared_missing", "[BIL] AI 声明拦截适配不完整: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    private companion object {
        const val TARGET_PACKAGE = "tv.danmaku.bili"
        const val CHANNEL_STATUS = "ai_declared_video_status"
        const val ACCESS_KEY_STATUS = "ai_declared_access_key_status"
        const val HANDLER_CLASS = "com.bilibili.lib.moss.api.MossResponseHandler"
        const val PATHS = 2
        const val PLAYLIST_SKIPS = 10
    }
}

/**
 * 强力模式"这位发布者本进程发布过没有"的账本；与 [AuthorPickSession] 的容量彻底脱钩。
 * 上限对齐观测快照的条目上限——再多发布也会被快照截断。
 */
internal class AiAuthorLedger(private val max: Int) {
    private val names = HashSet<String>()

    /** 返回 true 表示这次应当发布（首次见到且未超上限）。 */
    @Synchronized
    fun claim(name: String): Boolean {
        val key = name.trim().lowercase()
        if (key.isEmpty() || key in names || names.size >= max) return false
        return names.add(key)
    }
}

/** 安装期解析全部反射，回调内只 `invoke`。 */
internal class AiDeclaredReplyInterceptor private constructor(
    private val reply: Class<*>,
    private val replyPlan: ProtobufBuilderPlan,
    private val defaultInstance: Any?,
    private val read: Readers,
    private val rewrite: EcodeWriter,
    private val strip: RelateStripChain?
) {
    val relateStripReady: Boolean get() = strip != null

    /** 一份 View 响应是不是带声明（预检查询用）。 */
    fun isDeclared(candidate: Any): Boolean = reply.isInstance(candidate) && read.facts(candidate).declared

    /** 推荐卡是不是本进程已知的 AI 视频；推荐续页复用同一判定。 */
    fun isKnownAiCard(card: Any): Boolean = read.isKnownAiCard(card)

    /** 从一份响应里读出的最小事实；宿主消息不越过这一层。 */
    private data class Facts(
        val aid: Long,
        val ownerName: String?,
        val ownerMid: Long,
        val declared: Boolean,
        val candidates: List<AiDeclaredVideoPolicy.RelateCandidate>
    )

    /**
     * @param passive 非详情页的后台请求（见 [AiDeclaredVideoPolicy.isPassiveRequest]）：
     *   只把命中的 aid 记进注册表，不改写、不提示、不记发布者、不占连锁保险。
     */
    fun process(
        original: Any,
        environment: HookEnvironment,
        guard: AiRedirectGuard,
        passive: Boolean = false,
        playlist: AiPlaylistRoute? = null,
        playlistGuard: AiRedirectGuard = guard,
        onRelateCandidates: ((List<Long>) -> Unit)? = null,
        onDeclaredAuthor: (String?, Long) -> Unit
    ): Any = runCatching {
        if (!reply.isInstance(original)) return@runCatching original
        if (defaultInstance != null && original === defaultInstance) return@runCatching original
        environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.ID, FeatureRuntimeStage.OBSERVED)
        val facts = read.facts(original)
        if (passive) {
            if (facts.declared) AiDeclaredVideoRegistry.add(facts.aid)
            return@runCatching original
        }
        // 服务端已经下发了错误码（真的 404、仅自己可见、青少年模式）就交给宿主，不覆盖。
        if (rewrite.hasHostError(original)) return@runCatching original
        if (facts.declared) {
            environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.CAPABILITY_DETAIL, FeatureRuntimeStage.OBSERVED)
            AiDeclaredVideoRegistry.add(facts.aid)
            runCatching { onDeclaredAuthor(facts.ownerName, facts.ownerMid) }.onFailure {
                environment.logError("ai_declared_author_failed", "[BIL] 强力模式记录发布者失败: ${it.javaClass.simpleName}")
            }
            playlist?.takeIf { it.ownsPlaylistItem(facts.aid) }?.let { route ->
                return@runCatching skipInPlaylist(original, route, environment, playlistGuard)
            }
            return@runCatching intercept(original, facts, environment, guard)
        }
        // 强力模式预检：只为用户真正打开的详情页排队，失败不影响本次响应。
        onRelateCandidates?.let { submit ->
            runCatching { submit(facts.candidates.filter { it.isVideo }.map { it.aid }) }
        }
        val chain = strip ?: return@runCatching original
        if (facts.candidates.none { it.isVideo && AiDeclaredVideoRegistry.contains(it.aid) }) {
            return@runCatching original
        }
        val removed = intArrayOf(0)
        val updated = chain.rebuild(original) { card ->
            val hit = read.isKnownAiCard(card)
            if (hit) removed[0]++
            !hit
        } ?: return@runCatching original
        check(read.facts(updated).candidates.none { it.isVideo && AiDeclaredVideoRegistry.contains(it.aid) }) {
            "relate strip readback failed"
        }
        environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.ID, FeatureRuntimeStage.APPLIED, removed[0])
        updated
    }.getOrElse {
        environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.ID, FeatureRuntimeStage.ERROR)
        environment.logError("ai_declared_copy_failed", "[BIL] AI 声明拦截改写失败，保留原响应: $it")
        original
    }

    /**
     * 连播里的条目：不改写跳转（那会离开整个列表），让宿主自己切下一集，响应原样交付。
     * 没有下一集、连播已销毁或连续跳太多次 → 宿主原生提示页，仍停留在列表里。
     */
    private fun skipInPlaylist(
        original: Any,
        route: AiPlaylistRoute,
        environment: HookEnvironment,
        playlistGuard: AiRedirectGuard
    ): Any {
        val messages = InjectedUiLocale.messages()
        val skipped = playlistGuard.tryAcquire() && route.skipToNext()
        val updated = if (skipped) original else rewrite.block(original, messages.aiDeclaredBlockedHint)
        environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.CAPABILITY_DETAIL, FeatureRuntimeStage.APPLIED)
        environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.ID, FeatureRuntimeStage.APPLIED)
        environment.logInfo(
            "ai_declared_playlist",
            "[BIL] 连播中遇到含 AI 生成声明的视频，" + if (skipped) "已切到下一集" else "无下一集，显示提示页"
        )
        ReflectAccess.currentApplication()?.let { context ->
            VersionAdapter.showAdaptToast(
                context,
                if (skipped) messages.aiDeclaredPlaylistSkippedToast else messages.aiDeclaredBlockedHint
            )
        }
        return updated
    }

    private fun intercept(
        original: Any,
        facts: Facts,
        environment: HookEnvironment,
        guard: AiRedirectGuard
    ): Any {
        val candidate = facts.candidates.firstOrNull { candidate ->
            AiDeclaredVideoPolicy.isReplacementCandidate(
                candidate, facts.aid, facts.ownerMid,
                AiDeclaredVideoRegistry::contains, AuthorPickSession::matches
            )
        }
        // 先找到候选再占用额度：没有候选时不该消耗连锁保险的次数。
        val redirect = candidate?.uri?.takeIf { guard.tryAcquire() }
        val messages = InjectedUiLocale.messages()
        val updated = if (redirect != null) {
            rewrite.redirect(original, redirect)
        } else {
            rewrite.block(original, messages.aiDeclaredBlockedHint)
        }
        environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.CAPABILITY_DETAIL, FeatureRuntimeStage.APPLIED)
        environment.reportRuntimeEvidence(AiDeclaredVideoPolicy.ID, FeatureRuntimeStage.APPLIED)
        environment.logInfo(
            "ai_declared_intercepted",
            "[BIL] 已拦截含 AI 生成声明的视频，" + if (redirect != null) "已改为跳转补位视频" else "无可用补位，显示提示页"
        )
        ReflectAccess.currentApplication()?.let { context ->
            VersionAdapter.showAdaptToast(
                context,
                if (redirect != null) messages.aiDeclaredRedirectToast else messages.aiDeclaredBlockedHint
            )
        }
        return updated
    }

    /** 读链：全部是 getter，缺任一环节在安装期就判不可用。 */
    private class Readers(
        val arcPresence: Method,
        val arcGetter: Method,
        val aidGetter: Method,
        val ownerPresence: Method,
        val ownerGetter: Method,
        val ownerMid: Method,
        val ownerTitle: Method,
        val tabPresence: Method,
        val tabGetter: Method,
        val tabModuleList: Method,
        val introPresence: Method,
        val introGetter: Method,
        val modulesList: Method,
        val moduleClass: Class<*>,
        val ugcPresence: Method,
        val ugcGetter: Method,
        val neutralPresence: Method,
        val neutralGetter: Method,
        val neutralTitle: Method,
        val relatesPresence: Method,
        val relatesGetter: Method,
        val cardsList: Method,
        val cardTypeValue: Method,
        val avTypeValue: Int,
        val basicPresence: Method,
        val basicGetter: Method,
        val basicId: Method,
        val basicUri: Method,
        val authorPresence: Method,
        val authorGetter: Method
    ) {
        fun facts(reply: Any): Facts {
            val aid = if (bool(arcPresence, reply)) {
                arcGetter.invoke(reply)?.let { (aidGetter.invoke(it) as? Number)?.toLong() } ?: 0L
            } else 0L
            val owner = if (bool(ownerPresence, reply)) ownerGetter.invoke(reply) else null
            var declared = false
            val candidates = ArrayList<AiDeclaredVideoPolicy.RelateCandidate>()
            forEachModule(reply) { module ->
                if (!declared && bool(ugcPresence, module)) {
                    val ugc = ugcGetter.invoke(module)
                    if (ugc != null && bool(neutralPresence, ugc)) {
                        val title = neutralGetter.invoke(ugc)?.let { neutralTitle.invoke(it) as? String }
                        if (AiDeclaredVideoPolicy.isAiDeclaration(title)) declared = true
                    }
                }
                if (bool(relatesPresence, module)) {
                    val relates = relatesGetter.invoke(module) ?: return@forEachModule
                    (cardsList.invoke(relates) as? List<*>)?.forEach { card ->
                        if (card != null) candidates += candidate(card)
                    }
                }
            }
            return Facts(
                aid = aid,
                ownerName = owner?.let { ownerTitle.invoke(it) as? String },
                ownerMid = owner?.let { (ownerMid.invoke(it) as? Number)?.toLong() } ?: 0L,
                declared = declared,
                candidates = candidates
            )
        }

        fun candidate(card: Any): AiDeclaredVideoPolicy.RelateCandidate {
            val isVideo = (cardTypeValue.invoke(card) as? Int) == avTypeValue
            val basic = if (bool(basicPresence, card)) basicGetter.invoke(card) else null
            val author = basic?.takeIf { bool(authorPresence, it) }?.let { authorGetter.invoke(it) }
            return AiDeclaredVideoPolicy.RelateCandidate(
                isVideo = isVideo,
                aid = basic?.let { (basicId.invoke(it) as? Number)?.toLong() } ?: 0L,
                uri = basic?.let { basicUri.invoke(it) as? String },
                authorName = author?.let { ownerTitle.invoke(it) as? String },
                authorMid = author?.let { (ownerMid.invoke(it) as? Number)?.toLong() } ?: 0L
            )
        }

        fun isKnownAiCard(card: Any): Boolean {
            val fact = candidate(card)
            return fact.isVideo && AiDeclaredVideoRegistry.contains(fact.aid)
        }

        private inline fun forEachModule(reply: Any, block: (Any) -> Unit) {
            if (!bool(tabPresence, reply)) return
            val tab = tabGetter.invoke(reply) ?: return
            (tabModuleList.invoke(tab) as? List<*>)?.forEach { tabModule ->
                if (tabModule == null || !bool(introPresence, tabModule)) return@forEach
                val intro = introGetter.invoke(tabModule) ?: return@forEach
                (modulesList.invoke(intro) as? List<*>)?.forEach { module ->
                    if (module != null && moduleClass.isInstance(module)) block(module)
                }
            }
        }
    }

    /** 只写 `ecode` 与 `ecode_config`，写完回读 `getEcodeValue`。 */
    private class EcodeWriter(
        private val replyPlan: ProtobufBuilderPlan,
        private val setEcodeValue: Method,
        private val setEcodeConfig: Method,
        private val getEcodeValue: Method,
        private val configPlan: ProtobufBuilderPlan,
        private val configDefault: Any,
        private val setRedirectUrl: Method,
        private val setMsg: Method,
        private val notFoundValue: Int,
        private val privacyValue: Int
    ) {
        /** 同一份响应再过一次（或服务端本就报错）时保持幂等：已有非 0 错误码就不再改写。 */
        fun hasHostError(reply: Any): Boolean = (getEcodeValue.invoke(reply) as? Int ?: 0) != 0

        fun redirect(original: Any, url: String): Any = write(original, notFoundValue, url, "")

        fun block(original: Any, message: String): Any = write(original, privacyValue, "", message)

        private fun write(original: Any, code: Int, url: String, message: String): Any {
            val config = configPlan.edit(configDefault) { target ->
                setRedirectUrl.invoke(target, url)
                setMsg.invoke(target, message)
            }
            val updated = replyPlan.edit(original) { target ->
                setEcodeValue.invoke(target, code)
                setEcodeConfig.invoke(target, config)
            }
            check(getEcodeValue.invoke(updated) == code) { "ecode readback failed" }
            return updated
        }
    }

    /**
     * `ViewReply → Tab → TabModule → IntroductionTab → Module → Relates.cards` 的按需复制链。
     * 某一层没有命中就完全不复制那一层；一个都没命中返回 null。
     */
    private class RelateStripChain(
        private val readers: Readers,
        private val replyPlan: ProtobufBuilderPlan,
        private val setTab: Method,
        private val tabPlan: ProtobufBuilderPlan,
        private val clearTabModule: Method,
        private val addAllTabModule: Method,
        private val tabModulePlan: ProtobufBuilderPlan,
        private val setIntroduction: Method,
        private val introPlan: ProtobufBuilderPlan,
        private val clearModules: Method,
        private val addAllModules: Method,
        private val modulePlan: ProtobufBuilderPlan,
        private val setRelates: Method,
        private val relatesPlan: ProtobufBuilderPlan,
        private val clearCards: Method,
        private val addAllCards: Method
    ) {
        fun rebuild(reply: Any, keep: (Any) -> Boolean): Any? = with(readers) {
            if (!bool(tabPresence, reply)) return null
            val tab = tabGetter.invoke(reply) ?: return null
            val tabModules = (tabModuleList.invoke(tab) as? List<*>)?.map { it ?: return null } ?: return null
            var newTabModules: MutableList<Any>? = null
            tabModules.forEachIndexed { tabIndex, tabModule ->
                if (!bool(introPresence, tabModule)) return@forEachIndexed
                val intro = introGetter.invoke(tabModule) ?: return@forEachIndexed
                val modules = (modulesList.invoke(intro) as? List<*>)?.map { it ?: return null } ?: return@forEachIndexed
                var newModules: MutableList<Any>? = null
                modules.forEachIndexed { moduleIndex, module ->
                    if (!moduleClass.isInstance(module) || !bool(relatesPresence, module)) return@forEachIndexed
                    val relates = relatesGetter.invoke(module) ?: return@forEachIndexed
                    val cards = cardsList.invoke(relates) as? List<*> ?: return@forEachIndexed
                    val retained = ProtobufListRetention.retainOrNull(cards, keep) ?: return@forEachIndexed
                    val newRelates = relatesPlan.edit(relates) { target ->
                        clearCards.invoke(target)
                        addAllCards.invoke(target, retained)
                    }
                    val newModule = modulePlan.edit(module) { target -> setRelates.invoke(target, newRelates) }
                    (newModules ?: modules.toMutableList().also { newModules = it })[moduleIndex] = newModule
                }
                val rebuiltModules = newModules ?: return@forEachIndexed
                val newIntro = introPlan.edit(intro) { target ->
                    clearModules.invoke(target)
                    addAllModules.invoke(target, rebuiltModules)
                }
                val newTabModule = tabModulePlan.edit(tabModule) { target -> setIntroduction.invoke(target, newIntro) }
                (newTabModules ?: tabModules.toMutableList().also { newTabModules = it })[tabIndex] = newTabModule
            }
            val rebuiltTabModules = newTabModules ?: return null
            val newTab = tabPlan.edit(tab) { target ->
                clearTabModule.invoke(target)
                addAllTabModule.invoke(target, rebuiltTabModules)
            }
            replyPlan.edit(reply) { target -> setTab.invoke(target, newTab) }
        }
    }

    companion object {
        private const val V1 = "com.bapis.bilibili.app.viewunite.v1."
        private const val COMMON = "com.bapis.bilibili.app.viewunite.common."

        /**
         * @param v1 / [common] 只为单测替身开的口子：共享的 `com.bapis` 替身被 VersionAdapter 的
         *   结构定位测试依赖，往里加 getter 会改变它们的唯一性判定，所以本功能的替身住在独立包里。
         */
        fun resolve(
            loader: ClassLoader,
            v1: String = V1,
            common: String = COMMON
        ): AiDeclaredReplyInterceptor? = runCatching {
            fun cls(name: String) = KavaMemberLookup.classOrNull(loader, name)
            fun getter(owner: Class<*>, name: String): Method? = KavaMemberLookup.methodOrNull(owner, name)
            fun bool(owner: Class<*>, name: String): Method? =
                getter(owner, name)?.takeIf { it.returnType == classOf<Boolean>() }
            fun list(owner: Class<*>, name: String): Method? =
                getter(owner, name)?.takeIf { it.returnType isSubclassOf classOf<List<*>>() }
            fun staticInt(owner: Class<*>, name: String): Int? =
                KavaMemberLookup.fieldOrNull(owner, name)
                    ?.takeIf { it.isStatic && it.type == classOf<Int>() }
                    ?.let { runCatching { it.getInt(null) }.getOrNull() }

            val reply = cls(v1 + "ViewReply") ?: return null
            val arc = cls(v1 + "Arc") ?: return null
            val owner = cls(common + "Owner") ?: return null
            val tab = cls(v1 + "Tab") ?: return null
            val tabModule = cls(v1 + "TabModule") ?: return null
            val intro = cls(v1 + "IntroductionTab") ?: return null
            val module = cls(common + "Module") ?: return null
            val ugc = cls(common + "UgcIntroduction") ?: return null
            val neutral = cls(common + "Neutral") ?: return null
            val relates = cls(common + "Relates") ?: return null
            val card = cls(common + "RelateCard") ?: return null
            val cardType = cls(common + "RelateCardType") ?: return null
            val basic = cls(common + "CardBasicInfo") ?: return null
            val ecode = cls(v1 + "ECode") ?: return null
            val ecodeConfig = cls(v1 + "ECodeConfig") ?: return null

            val readers = Readers(
                arcPresence = bool(reply, "hasArc") ?: return null,
                arcGetter = getter(reply, "getArc")?.takeIf { it.returnType == arc } ?: return null,
                aidGetter = getter(arc, "getAid")?.takeIf { it.returnType == classOf<Long>() } ?: return null,
                ownerPresence = bool(reply, "hasOwner") ?: return null,
                ownerGetter = getter(reply, "getOwner")?.takeIf { it.returnType == owner } ?: return null,
                ownerMid = getter(owner, "getMid")?.takeIf { it.returnType == classOf<Long>() } ?: return null,
                ownerTitle = getter(owner, "getTitle")?.takeIf { it.returnType == classOf<String>() } ?: return null,
                tabPresence = bool(reply, "hasTab") ?: return null,
                tabGetter = getter(reply, "getTab")?.takeIf { it.returnType == tab } ?: return null,
                tabModuleList = list(tab, "getTabModuleList") ?: return null,
                introPresence = bool(tabModule, "hasIntroduction") ?: return null,
                introGetter = getter(tabModule, "getIntroduction")?.takeIf { it.returnType == intro } ?: return null,
                modulesList = list(intro, "getModulesList") ?: return null,
                moduleClass = module,
                ugcPresence = bool(module, "hasUgcIntroduction") ?: return null,
                ugcGetter = getter(module, "getUgcIntroduction")?.takeIf { it.returnType == ugc } ?: return null,
                neutralPresence = bool(ugc, "hasNeutral") ?: return null,
                neutralGetter = getter(ugc, "getNeutral")?.takeIf { it.returnType == neutral } ?: return null,
                neutralTitle = getter(neutral, "getTitle")?.takeIf { it.returnType == classOf<String>() } ?: return null,
                relatesPresence = bool(module, "hasRelates") ?: return null,
                relatesGetter = getter(module, "getRelates")?.takeIf { it.returnType == relates } ?: return null,
                cardsList = list(relates, "getCardsList") ?: return null,
                cardTypeValue = getter(card, "getRelateCardTypeValue")?.takeIf { it.returnType == classOf<Int>() }
                    ?: return null,
                avTypeValue = staticInt(cardType, AiDeclaredVideoPolicy.RELATE_AV_TYPE_CONSTANT) ?: return null,
                basicPresence = bool(card, "hasBasicInfo") ?: return null,
                basicGetter = getter(card, "getBasicInfo")?.takeIf { it.returnType == basic } ?: return null,
                basicId = getter(basic, "getId")?.takeIf { it.returnType == classOf<Long>() } ?: return null,
                basicUri = getter(basic, "getUri")?.takeIf { it.returnType == classOf<String>() } ?: return null,
                authorPresence = bool(basic, "hasAuthor") ?: return null,
                authorGetter = getter(basic, "getAuthor")?.takeIf { it.returnType == owner } ?: return null
            )

            // Builder 类名被混淆（实测 `ViewReply$b`），一律经 newBuilder(...).returnType 取。
            val replyPlan = ProtobufBuilderPlan.resolve(reply) ?: return null
            val configPlan = ProtobufBuilderPlan.resolve(ecodeConfig) ?: return null
            val writer = EcodeWriter(
                replyPlan = replyPlan,
                setEcodeValue = replyPlan.method("setEcodeValue", classOf<Int>()) ?: return null,
                setEcodeConfig = replyPlan.method("setEcodeConfig", ecodeConfig) ?: return null,
                getEcodeValue = getter(reply, "getEcodeValue")?.takeIf { it.returnType == classOf<Int>() }
                    ?: return null,
                configPlan = configPlan,
                configDefault = KavaMemberLookup.methodOrNull(ecodeConfig, "getDefaultInstance")
                    ?.invoke(null) ?: return null,
                setRedirectUrl = configPlan.method("setRedirectUrl", classOf<String>()) ?: return null,
                setMsg = configPlan.method("setMsg", classOf<String>()) ?: return null,
                notFoundValue = staticInt(ecode, "CODE_404_VALUE") ?: return null,
                privacyValue = staticInt(ecode, "CODE_ARC_PRIVACY_VALUE") ?: return null
            )

            // 相关推荐删卡是第二条链：缺任一环节只让它降级，拦截与补位照常。
            val strip = runCatching {
                val tabPlan = ProtobufBuilderPlan.resolve(tab) ?: return@runCatching null
                val tabModulePlan = ProtobufBuilderPlan.resolve(tabModule) ?: return@runCatching null
                val introPlan = ProtobufBuilderPlan.resolve(intro) ?: return@runCatching null
                val modulePlan = ProtobufBuilderPlan.resolve(module) ?: return@runCatching null
                val relatesPlan = ProtobufBuilderPlan.resolve(relates) ?: return@runCatching null
                val iterable = classOf<Iterable<*>>()
                RelateStripChain(
                    readers = readers,
                    replyPlan = replyPlan,
                    setTab = replyPlan.method("setTab", tab) ?: return@runCatching null,
                    tabPlan = tabPlan,
                    clearTabModule = tabPlan.method("clearTabModule") ?: return@runCatching null,
                    addAllTabModule = tabPlan.method("addAllTabModule", iterable) ?: return@runCatching null,
                    tabModulePlan = tabModulePlan,
                    setIntroduction = tabModulePlan.method("setIntroduction", intro) ?: return@runCatching null,
                    introPlan = introPlan,
                    clearModules = introPlan.method("clearModules") ?: return@runCatching null,
                    addAllModules = introPlan.method("addAllModules", iterable) ?: return@runCatching null,
                    modulePlan = modulePlan,
                    setRelates = modulePlan.method("setRelates", relates) ?: return@runCatching null,
                    relatesPlan = relatesPlan,
                    clearCards = relatesPlan.method("clearCards") ?: return@runCatching null,
                    addAllCards = relatesPlan.method("addAllCards", iterable) ?: return@runCatching null
                )
            }.getOrNull()

            val defaultInstance = runCatching {
                KavaMemberLookup.methodOrNull(reply, "getDefaultInstance")?.invoke(null)
            }.getOrNull()
            AiDeclaredReplyInterceptor(reply, replyPlan, defaultInstance, readers, writer, strip)
        }.getOrNull()

        private fun bool(method: Method, target: Any): Boolean = method.invoke(target) as? Boolean == true
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import java.lang.reflect.Method
import java.lang.reflect.Modifier
import java.lang.reflect.ParameterizedType
import java.util.Locale
import java.util.concurrent.atomic.AtomicBoolean

/**
 * 阻止资源组件库清单继续下发。
 *
 * 这个功能故意只在能从返回模型中识别到目标池时改写 builder；池名/模块名尚未被真机
 * 观测确认时保持原响应，避免把基础组件库误扩大为全部资源池。默认关闭，不读宿主文件，
 * 不拉起宿主界面，也不主动发起 IPC。
 */
internal class BlockComponentLibraryFeatureInstaller(
    private val enabled: Boolean,
    private val targetKeywords: Set<String> = ComponentLibraryPoolMatcher.DEFAULT_KEYWORDS
) : FeatureInstaller {
    override val id: String = ID
    override val capabilityIds: List<String> = listOf(CAPABILITY)

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) return skipped(environment, "disabled")
        val loader = environment.classLoader ?: return skipped(environment, "missing-class-loader")
        val resolved = MOSS_CLASSES.asSequence().flatMap { mossName ->
            REQUEST_CLASSES.asSequence().mapNotNull { requestName ->
                val moss = KavaMemberLookup.classOrNull(loader, mossName) ?: return@mapNotNull null
                val request = KavaMemberLookup.classOrNull(loader, requestName) ?: return@mapNotNull null
                val sync = METHOD_NAMES.firstNotNullOfOrNull { name ->
                    KavaMemberLookup.methodOrNull(moss, name, request)?.takeIf {
                        !Modifier.isStatic(it.modifiers) && !it.returnType.isPrimitive
                    }
                } ?: return@mapNotNull null
                Triple(moss, request, sync)
            }
        }.firstOrNull()
            ?: return skipped(environment, "not-applicable-host")
        val moss = resolved.first
        val request = resolved.second
        val method = resolved.third
        val strategy = ComponentLibraryReplyStrategy.resolve(method.returnType, targetKeywords)
            ?: return skipped(environment, "missing-host-structure")
        val observationLogged = AtomicBoolean(false)
        val publisher = ScanSnapshotPublisher(
            environment, MineComponentSnapshotCodec.SURFACE_COMPONENT_POOLS, setOf(CAPABILITY)
        )
        val catalog = ComponentPoolCatalog()

        val observe: (Any) -> Unit = { reply ->
            // **无条件上报候选**（哪怕一个都没勾）：不扫描的话面板永远是空的，
            // 用户就没法勾——四个列表型面共同的纪律，见 AGENTS 勾选面板条目。
            //
            // 这里发布的是 catalog 累积至今的**并集**而不是本次响应的内容：
            // 宿主按需分片下发清单，整份替换会让面板只剩最后一片，见 [ComponentPoolCatalog]。
            catalog.merge(strategy.observePools(reply))
                .takeIf { it.isNotEmpty() }
                ?.let(publisher::publish)
            if (targetKeywords.isEmpty() && observationLogged.compareAndSet(false, true)) {
                strategy.describe(reply)?.let { description ->
                    environment.logInfo(
                        "$ID.observation",
                        "[BIL] 组件库清单观察(仅名称/数量): $description"
                    )
                }
            }
        }
        var installed = 0
        var available = 0
        runCatching {
            environment.registrar.exact("$ID.sync", moss, method.name, request) {
                after {
                    if (hasThrowable) return@after
                    val reply = result ?: return@after
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    observe(reply)
                    strategy.clearMatchedPools(reply)?.let { changed ->
                        result = changed
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                    }
                }
            }
            installed++
        }.onFailure { environment.logError("$ID.sync", "[BIL] 组件库同步清单 Hook 注册失败") }
        available++

        val handlerClass = KavaMemberLookup.classOrNull(loader, MOSS_HANDLER)?.takeIf { it.isInterface }
        if (handlerClass != null) {
            val async = KavaMemberLookup.methods(moss, includeSuperclasses = true, makeAccessible = true) {
                it.name in METHOD_NAMES && it.parameterTypes.contentEquals(arrayOf(request, handlerClass)) &&
                    it.returnType == Void.TYPE && !Modifier.isStatic(it.modifiers)
            }.singleOrNull()
            if (async != null) {
                available++
                if (runCatching {
                    environment.registrar.exact(ID, moss, async.name, request, handlerClass) {
                        before {
                            val delegate = argOrNull(1) ?: return@before
                    val proxy = MossResponseHandlerProxy.wrapTransform(handlerClass, delegate) { reply ->
                                environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                                observe(reply)
                                strategy.clearMatchedPools(reply)?.also {
                                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                                } ?: reply
                            } ?: return@before
                            args[1] = proxy
                        }
                    }
                }.isSuccess) {
                    installed++
                } else {
                    environment.logError("$ID.async", "[BIL] 组件库异步清单 Hook 注册失败")
                }
            }
        }
        if (installed == 0) return skipped(environment, "registration-failed")
        return runCatching {
            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
            val status = if (installed == available) "success" else "partial:$installed/$available"
            // 一个池都没勾时只扫描不过滤——这是**正常终态**，不是缺陷，所以报
            // `success:scan` 而不是 partial：面板要先有候选，用户才能勾。
            val hasSelection = targetKeywords.isNotEmpty()
            val result = FeatureInstallResult.Installed(
                installed,
                complete = installed == available
            )
            environment.reportStatus(
                STATUS,
                if (!hasSelection) "$status:scan" else status
            )
            environment.reportCapability(CAPABILITY, result)
            result
        }.getOrElse {
            environment.logError("$ID.diagnostics", "[BIL] 组件库清单诊断上报失败")
            skipped(environment, "registration-failed")
        }
    }

    private fun skipped(environment: HookEnvironment, reason: String): FeatureInstallResult.Skipped {
        val result = FeatureInstallResult.Skipped(reason)
        environment.reportStatus(STATUS, reason)
        environment.reportCapability(CAPABILITY, result)
        return result
    }

    companion object {
        const val ID = "block_component_library_download"
        const val CAPABILITY = "block_component_library_download"
        private const val STATUS = "block_component_library_status"
        private const val MOSS_HANDLER = "com.bilibili.lib.moss.api.MossResponseHandler"
        private val MOSS_CLASSES = listOf(
            "com.bapis.bilibili.app.resource.v1.ModuleMoss",
            "com.bapis.bilibili.app.resource.v1.KModuleMoss",
            "com.bapis.bilibili.p4218app.resource.p4240v1.ModuleMoss",
            "com.bapis.bilibili.p4218app.resource.p4240v1.KModuleMoss"
        )
        private val REQUEST_CLASSES = listOf(
            "com.bapis.bilibili.app.resource.v1.ListReq",
            "com.bapis.bilibili.app.resource.v1.KListReq",
            "com.bapis.bilibili.p4218app.resource.p4240v1.ListReq",
            "com.bapis.bilibili.p4218app.resource.p4240v1.KListReq"
        )
        private val METHOD_NAMES = listOf("executeList", "list")
    }
}

/** 单次清单响应里看到的一个池；模块名可能取不到，此时只有 [moduleCount] 可用。 */
internal data class ComponentPoolObservation(
    val name: String,
    val moduleNames: List<String>,
    val moduleCount: Int
)

/**
 * 跨请求累积「池名 → 已见模块名」，把分片响应拼成勾选面板的候选全集。
 *
 * **宿主的清单请求是按需分片的，不是全量目录。** 2026-09-15 真机实证：
 * 设备上 `app_mod_resource/manifest/` 有 17 个池（`ad` / `applet` / `appletBasic` /
 * `blink` / `bplus` / `danmaku` / `feOffline` / `game` / `live` / `lynx` / `mainSite` /
 * `mainSiteAndroid` / `mall` / `ogv` / `pink` / `test` / `uper`），其中 `appletBasic`
 * 目录下有 4 个模块；而模块落盘的那份快照只有 `appletBasic（1）` 一条——
 * 因为当时按"整份替换"发布，每个分片都把上一个分片覆盖掉了，
 * 面板里就只剩最后一次请求恰好提到的那个池。
 *
 * 所以这里按池取并集：池名只增不删，模块名去重后计数。
 * 进程重启后的跨场并集由 [MineComponentSnapshotCodec.ACCUMULATING_SURFACES] 接手。
 *
 * 内存有界：池数不超过 [MineComponentSnapshotCodec.MAX_ENTRY_COUNT]，
 * 每池模块名不超过 [MAX_MODULES_PER_POOL]，满了就只丢弃新增、不影响已有计数。
 */
internal class ComponentPoolCatalog {
    private val pools = LinkedHashMap<String, MutableSet<String>>()
    private val floors = HashMap<String, Int>()

    /** 并入一份分片，返回累积至今的全部候选。 */
    @Synchronized fun merge(observed: List<ComponentPoolObservation>): List<MineComponentScanEntry> {
        observed.forEach { observation ->
            val modules = pools.getOrPut(observation.name) {
                if (pools.size >= MineComponentSnapshotCodec.MAX_ENTRY_COUNT) return@forEach
                LinkedHashSet()
            }
            observation.moduleNames.forEach { module ->
                if (modules.size < MAX_MODULES_PER_POOL) modules.add(module)
            }
            // 模块名取不到时退到"单次响应里见过的最大模块数"，好过显示 0。
            floors[observation.name] =
                maxOf(floors[observation.name] ?: 0, observation.moduleCount)
        }
        // 按池名排序：同一组池每次都编码出同样的载荷，下游 LatestValuePublisher
        // 才能按值去重，不会因为 map 迭代顺序变化而空转一次编码 + 落盘。
        return pools.entries.sortedBy { it.key }.mapNotNull { (name, modules) ->
            val count = maxOf(modules.size, floors[name] ?: 0)
            MineComponentScanEntry.create(
                kind = "component_pool",
                title = "$name（$count）",
                id = name,
                uri = null,
                showing = true
            )
        }
    }

    private companion object {
        const val MAX_MODULES_PER_POOL = 512
    }
}

/** 组件库池的保守识别规则；未知/空名称永不命中。 */
internal data class ComponentLibraryMatch(
    val wholePool: Boolean,
    val moduleIndexes: Set<Int> = emptySet()
)

internal object ComponentLibraryPoolMatcher {
    fun match(
        poolName: String?,
        moduleNames: List<String>,
        keywords: Set<String> = DEFAULT_KEYWORDS
    ): ComponentLibraryMatch? {
        val normalizedKeywords = keywords.asSequence()
            .map(::normalize)
            .filterNotNull()
            .toSet()
        if (normalizedKeywords.isEmpty()) return null
        // 全量：清空每一个池的模块列表，不逐个枚举池名。
        // 枚举写法挡不住宿主新增的池——2026-09-15 真机实测当时就有 17 个池，
        // 名单式必然随宿主漂移而漏；而这个功能的语义本来就是"整份不要"。
        if (MATCH_ALL_POOLS in normalizedKeywords) {
            return ComponentLibraryMatch(wholePool = true)
        }
        if (normalize(poolName) in normalizedKeywords) {
            return ComponentLibraryMatch(wholePool = true)
        }
        val moduleIndexes = moduleNames.mapIndexedNotNull { index, name ->
            normalize(name)?.takeIf { it in normalizedKeywords }?.let { index }
        }.toSet()
        return ComponentLibraryMatch(wholePool = false, moduleIndexes = moduleIndexes)
            .takeIf { it.moduleIndexes.isNotEmpty() }
    }

    fun matches(
        poolName: String?,
        moduleNames: List<String>,
        keywords: Set<String> = DEFAULT_KEYWORDS
    ): Boolean = match(poolName, moduleNames, keywords) != null

    private fun normalize(value: String?): String? = value?.trim()
        ?.lowercase(Locale.ROOT)
        ?.takeIf(String::isNotEmpty)

    /**
     * 全量哨兵；出现在关键词集里就命中所有池，见 [match]。
     *
     * 两个入口：手填规则里直接写 `*`；或者扫描没结果时面板给出的「全量禁止」开关，
     * 它写的就是这个值——那种情况下没有候选可勾，只能按"整份都不要"处理。
     */
    const val MATCH_ALL_POOLS = "*"

    /**
     * 勾选（JSON 数组）与手填（逗号/分号/换行分隔）取并集，与其余四个勾选面同规则。
     *
     * 勾选项存的是 `component_pool:<池名>` 形式的 selector 键（见
     * [MineComponentSelector.key]），这里剥掉前缀还原成池名；手填项原样进集合，
     * 所以 `*` 这个哨兵从手填或「全量禁止」开关写进来都认。
     */
    fun selection(selectors: String, rules: String): Set<String> {
        val picked = MineComponentSelectionCodec.decode(selectors)
            .map { it.removePrefix(SELECTOR_PREFIX) }
        val typed = rules.split(',', '，', ';', '；', '\n', '\r')
        return (picked + typed).map(String::trim).filter(String::isNotEmpty).toSet()
    }

    private const val SELECTOR_PREFIX = "component_pool:"

    /**
     * 默认**不拦任何池**——拦谁由用户在勾选面板里决定。
     *
     * 真机取证把口径定死了：哔哩哔哩存储设置里的「App基础组件库」是整棵
     * `app_mod_resource/`，不是某一个池 —— 实测 8549 个文件 / 442.6 MiB，
     * 与 UI 显示的 443 MB 逐字对上（`du` 报 473.8 MiB 是 4K 块对齐，UI 算实际字节）。
     * 当时该设备有 17 个池：`appletBasic`(102MB) / `uper`(97MB) / `live`(74MB,172 模块) /
     * `ogv`(66MB) / `pink`(38MB) / `feOffline`(33MB) / `mall` / `mainSiteAndroid` / …
     *
     * 正因为代价按池而异（拦 `live` 断直播间、拦 `uper` 断创作中心），才做成勾选面板
     * 而不是一个总开关。**空集时只扫描不过滤**，否则面板永远没有候选可勾——
     * 这是四个列表型面共同的纪律，见 AGENTS 勾选面板条目。
     *
     * 另：清单里消失的模块会被宿主当作弃用模块**删除本地文件**（`lib.mod.T#r`，日志
     * `remote config delete abandon mod`，8.84.0–9.13.0 都有），所以拦截不只是"不再下载"。
     */
    val DEFAULT_KEYWORDS: Set<String> = emptySet()
}

/**
 * 安装期解析 protobuf builder；热路径只调用已解析的 Method。
 *
 * ⚠️ **Builder 一律经 [ProtobufBuilderPlan]（`newBuilder(owner)` 静态工厂）取，不要用
 * `toBuilder()`。** 2026-09-15 真机实证：这个功能上线后 `install=SKIPPED,
 * reason=MISSING_HOST_STRUCTURE`，一次都没装上。原因是原实现拿
 * `replyClass.methods` 里的 `toBuilder`——它继承自 `GeneratedMessageLite`，
 * **声明返回类型是基类 `GeneratedMessageLite$Builder`**，于是后面
 * `build().returnType == replyClass` 这条自检必然不成立，整条 resolve 返回 null。
 * 而 `ListReply.newBuilder(ListReply)` 返回的是**具体**的 `ListReply$b`。
 * 这是 AGENTS「内层 Builder 是混淆的，只能经 `newBuilder(...).returnType` 取」
 * 那条红线的另一个入口。
 */
private class ComponentLibraryReplyStrategy private constructor(
    private val replyPlan: ProtobufBuilderPlan,
    private val poolPlan: ProtobufBuilderPlan,
    private val getPools: Method,
    private val clearPools: Method,
    private val addPool: Method,
    private val poolClearModules: Method,
    private val addModule: Method?,
    private val poolName: Method?,
    private val poolModules: Method?,
    private val moduleName: Method?,
    private val targetKeywords: Set<String>
) {
    fun clearMatchedPools(reply: Any): Any? = runCatching {
        if (targetKeywords.isEmpty()) return@runCatching null
        val pools = (getPools.invoke(reply) as? List<*>)?.filterNotNull().orEmpty()
        if (pools.isEmpty()) return@runCatching null
        val rebuiltPools = ArrayList<Any>(pools.size)
        var changed = false
        pools.forEach { pool ->
            val poolText = poolName?.invoke(pool) as? String
            val moduleList = (poolModules?.invoke(pool) as? List<*>)
                .orEmpty()
                .filterNotNull()
            // 匹配器返回的下标是对"传入名单"而言的：名字读不到的模块必须保留原下标
            // （记成 原下标→名字 对），否则过滤后名单的下标套回未过滤的 moduleList
            // 会整体错位，勾掉的模块拦不住、反而删掉别的模块。名字读不到按保守放行。
            val namedModules = moduleList.withIndex().mapNotNull { (index, module) ->
                runCatching { moduleName?.invoke(module) as? String }.getOrNull()
                    ?.let { index to it }
            }
            val match = ComponentLibraryPoolMatcher.match(
                poolText, namedModules.map { it.second }, targetKeywords
            )
            val blockedIndexes = match?.moduleIndexes
                ?.mapTo(HashSet()) { namedModules[it].first }
                .orEmpty()
            val updated = when {
                match == null -> pool
                match.wholePool -> {
                    changed = true
                    rebuildPool(pool, emptyList())
                }
                addModule == null -> return@runCatching null
                else -> {
                    changed = true
                    rebuildPool(pool, moduleList.filterIndexed { index, _ -> index !in blockedIndexes })
                }
            }
            rebuiltPools += updated
        }
        if (!changed) return@runCatching null
        replyPlan.edit(reply) { builder ->
            clearPools.invoke(builder)
            rebuiltPools.forEach { addPool.invoke(builder, it) }
        }
    }.getOrNull()

    private fun rebuildPool(pool: Any, modules: List<Any>): Any = poolPlan.edit(pool) { builder ->
        poolClearModules.invoke(builder)
        if (modules.isNotEmpty()) {
            val addModuleMethod = checkNotNull(addModule)
            modules.forEach { addModuleMethod.invoke(builder, it) }
        }
    }

    /**
     * 读出**这一份**清单里的池。
     *
     * 只取池名、模块名与模块数，不取模块文件路径也不取任何 URL——累积器只需要这些，
     * 也不会把宿主下发的资源清单原样搬进模块存储。
     *
     * ⚠️ 返回的是**分片**而不是全量目录，累积由 [ComponentPoolCatalog] 负责，见那里的注释。
     */
    fun observePools(reply: Any): List<ComponentPoolObservation> = runCatching {
        val pools = (getPools.invoke(reply) as? List<*>)?.filterNotNull().orEmpty()
        pools.mapNotNull { pool ->
            val name = (poolName?.invoke(pool) as? String)?.trim()?.takeIf(String::isNotEmpty)
                ?: return@mapNotNull null
            val moduleList = (poolModules?.invoke(pool) as? List<*>).orEmpty().filterNotNull()
            val moduleNames = moduleList.mapNotNull { module ->
                runCatching { moduleName?.invoke(module) as? String }.getOrNull()
                    ?.trim()?.takeIf(String::isNotEmpty)
            }
            ComponentPoolObservation(name, moduleNames, moduleList.size)
        }
    }.getOrDefault(emptyList())

    fun describe(reply: Any): String? = runCatching {
        val pools = (getPools.invoke(reply) as? List<*>)?.filterNotNull().orEmpty()
        pools.take(8).map { pool ->
            val name = (poolName?.invoke(pool) as? String).orEmpty().take(64)
            val moduleList = (poolModules?.invoke(pool) as? List<*>).orEmpty().filterNotNull()
            val modules = moduleList
                .take(5)
                .mapNotNull { module -> runCatching { moduleName?.invoke(module) as? String }.getOrNull() }
                .map { it.take(64) }
            "$name:${modules.size}/${moduleList.size}[${modules.joinToString(",")}]"
        }.joinToString(" | ")
            .takeIf(String::isNotEmpty)
    }.getOrNull()

    companion object {
        fun resolve(
            replyClass: Class<*>,
            targetKeywords: Set<String>
        ): ComponentLibraryReplyStrategy? = runCatching {
            val replyPlan = ProtobufBuilderPlan.resolve(replyClass) ?: return null
            val getPools = replyClass.methods.firstOrNull { method ->
                method.name == "getPoolsList" && method.parameterCount == 0 &&
                    List::class.java.isAssignableFrom(method.returnType)
            } ?: return null
            val clearPools = replyPlan.method("clearPools") ?: return null
            // 元素类型取**非泛型**的 `getPools(int)` 返回值，不靠 genericReturnType：
            // R8 可能剥掉签名属性，那时泛型实参拿不到，落点会静默降级。
            val poolClass = replyClass.methods.firstOrNull { method ->
                method.name == "getPools" && method.parameterTypes.contentEquals(
                    arrayOf(Int::class.javaPrimitiveType)
                ) && !method.returnType.isPrimitive
            }?.returnType ?: (getPools.genericReturnType as? ParameterizedType)
                ?.actualTypeArguments?.singleOrNull() as? Class<*> ?: return null
            // builder 上 addPools 有 4 个重载（含 int 位置版与 Builder 参数版），
            // 必须按参数类型精确选中"整条 PoolReply"那个。
            val addPool = replyPlan.method("addPools", poolClass) ?: return null
            val poolPlan = ProtobufBuilderPlan.resolve(poolClass) ?: return null
            val poolClearModules = poolPlan.method("clearModules") ?: return null
            val poolName = poolClass.methods.firstOrNull { method ->
                method.name in setOf("getName", "getPoolName") && method.parameterCount == 0 &&
                    method.returnType == String::class.java
            }
            val poolModules = poolClass.methods.firstOrNull { method ->
                method.name == "getModulesList" && method.parameterCount == 0 &&
                    List::class.java.isAssignableFrom(method.returnType)
            }
            val moduleClass = poolClass.methods.firstOrNull { method ->
                method.name == "getModules" && method.parameterTypes.contentEquals(
                    arrayOf(Int::class.javaPrimitiveType)
                ) && !method.returnType.isPrimitive
            }?.returnType ?: (poolModules?.genericReturnType as? ParameterizedType)
                ?.actualTypeArguments?.singleOrNull() as? Class<*>
            val addModule = moduleClass?.let { poolPlan.method("addModules", it) }
            val moduleName = moduleClass?.methods?.firstOrNull { method ->
                method.name in setOf("getName", "getModuleName", "getFilename", "getFileName") &&
                    method.parameterCount == 0 && method.returnType == String::class.java
            }
            ComponentLibraryReplyStrategy(
                replyPlan, poolPlan, getPools, clearPools, addPool,
                poolClearModules, addModule,
                poolName, poolModules, moduleName,
                targetKeywords
            )
        }.getOrNull()
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.HookExceptionPolicy
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.ReflectAccess
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.InjectedUiLocale
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isSubclassOf

/**
 * 屏蔽官方客户端更新：两道**互不知情**的防线。
 *
 * ```
 * 第一道（supplier 层，既有）：同步检查入口抛宿主自己的 LatestVersionException
 *   经 VersionAdapter 定位（25 个混淆 owner 候选 + DexKit 兜底）
 *   拦的是"**怎么做**检查"——宿主换网络实现就会定位落空
 *
 * 第二道（调用方层，新增）：UpdateHelper 的三个检查入口直接空实现
 *   checkUpdateInStartup(Activity, IUpdater)   冷启动自动检查
 *   checkUpdateAndShowDialog(Context, IUpdater) 手动检查
 *   checkInternalUpdateFlag(Context)            内部标记检查
 *   拦的是"**要不要**检查"——产品逻辑比实现稳定得多
 * ```
 *
 * ### 为什么加第二道（"不同版本效果不好"的结构成因）
 *
 * 第一道挂在 supplier 实现上。某版本换了 supplier（owner 类名变）而调用方不变时，
 * 就会出现"定位到了旧 supplier、新链路绕过去了"——静默失效。
 * 第二道打在 `tv.danmaku.bili.update.api.UpdateHelper` 上，
 * **25 个存档宿主（8.84.0 → 9.11.0）逐版核对：四个方法全部存在、
 * 全是 `static`、签名逐字一致、零漂移**。
 *
 * ### 两道必须互不知情
 *
 * 原实现里 `point == null` 会直接 return，等于把两道串联成"与"。
 * 现在各自 try/catch、各自记状态：第一道定位落空时，第二道仍然装得上。
 *
 * ### 刻意不碰的东西
 *
 * - `getExistingForceUpdate(Activity) -> bolts.Task`：语义是"恢复上次未完成的强更"，
 *   拦它可能破坏"已下载未安装"的合法状态机。列为观察项。
 * - 弹窗层（`RuntimeHelper$addUpdateDialog`）：那会连"用户手动点检查更新想看结果"
 *   一起吞掉，粒度太粗；真机发现漏网再单独开开关。
 *
 * ### 异常策略差异
 *
 * 第一道是全仓唯一的 [HookExceptionPolicy.DELIVER_TO_HOST]（必须让异常到宿主）；
 * 第二道是普通 PROTECTIVE——空实现不抛异常，**比第一道更安全**。
 */
internal class BlockUpdateFeatureInstaller(
    private val enabled: Boolean,
    private val point: VersionAdapter.HookPoint?
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            environment.reportStatus(CHANNEL_CALLER, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }

        // 第二道先装：它不依赖 VersionAdapter 定位，也不该被第一道的失败拖下水。
        val callerHooks = installCallerLayer(environment)
        val supplier = installSupplierLayer(environment)

        if (!supplier && callerHooks == 0) {
            return FeatureInstallResult.Skipped("registration-failed")
        }
        environment.reportStatus(
            CHANNEL_STATUS,
            if (supplier) "success" else "caller-only"
        )
        environment.logInfo(
            "block_update_ok",
            "[BIL] 官方客户端更新检查屏蔽已安装，supplier 层=$supplier，调用方层 hooks=$callerHooks"
        )
        return FeatureInstallResult.Installed(
            (if (supplier) 1 else 0) + callerHooks,
            complete = supplier && callerHooks == CALLER_METHODS.size
        )
    }

    /**
     * 第二道：调用方层。三个入口各自独立降级——一个失败不影响其余。
     *
     * 三个方法都是 `static void`，[intercept] 按返回类型给出安全零值（void → 不返回值），
     * 不改任何宿主状态，不存在"改了一半"的中间态。
     * 全是低频入口（冷启动一次 / 用户手动触发），不在帧预算热路径上。
     */
    private fun installCallerLayer(environment: HookEnvironment): Int {
        val loader = environment.classLoader ?: run {
            environment.reportStatus(CHANNEL_CALLER, "missing-class-loader")
            return 0
        }
        val helper = KavaMemberLookup.classOrNull(loader, UPDATE_HELPER_CLASS) ?: run {
            environment.reportStatus(CHANNEL_CALLER, "not-applicable-host")
            environment.logInfo(
                "block_update_caller_absent",
                "[BIL] 更新检查调用方层不可用（本宿主无 $UPDATE_HELPER_CLASS），仅保留 supplier 层"
            )
            return 0
        }
        var installed = 0
        CALLER_METHODS.forEach { name ->
            // 参数类型刻意**不写死**：按名字找唯一候选，签名在 25 版里一致，
            // 但万一某版本加了重载，`methods` 会给出多个，那时宁可跳过也不猜。
            val candidates = KavaMemberLookup.declaredMethods(helper) { it.name == name }
            val method = candidates.singleOrNull()?.takeIf { it.returnType == Void.TYPE }
            if (method == null) {
                environment.logInfo(
                    "block_update_caller_skip",
                    "[BIL] 更新检查调用方入口不唯一或签名不符，已跳过: $name(${candidates.size} 个候选)"
                )
                return@forEach
            }
            runCatching {
                environment.registrar.exact(
                    "update.block.caller.$name",
                    helper,
                    name,
                    *method.parameterTypes
                ) {
                    intercept()
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "block_update_caller_$name",
                    "[BIL] 更新检查调用方层 Hook 注册失败($name): $throwable"
                )
            }
        }
        environment.reportStatus(
            CHANNEL_CALLER,
            if (installed == CALLER_METHODS.size) "success" else "partial:$installed/${CALLER_METHODS.size}"
        )
        return installed
    }

    /** 第一道：supplier 层。定位或注册失败只影响它自己。 */
    private fun installSupplierLayer(environment: HookEnvironment): Boolean {
        val adapted = point ?: run {
            environment.logInfo(
                "block_update_supplier_absent",
                "[BIL] 更新检查 supplier 层未适配（无 VersionAdapter 点位），仅保留调用方层"
            )
            return false
        }
        val exceptionConstructor = environment.hookPoints.resolveConstructor(
            "update.block.latest_exception",
            LATEST_VERSION_EXCEPTION_CLASS,
            listOf(classOf<String>().name)
        )
        if (exceptionConstructor == null ||
            !(exceptionConstructor.declaringClass isSubclassOf classOf<Throwable>())
        ) {
            environment.logError(
                "block_update_missing",
                "[BIL] 更新检查 supplier 层适配不完整：宿主最新版异常类不可用"
            )
            return false
        }

        return runCatching {
            // 唯一使用 DELIVER_TO_HOST 的 Hook：本功能的全部作用就是让宿主的更新检查以
            // 它自己的 LatestVersionException 结束。默认的 PROTECT_HOST
            // （framework `ExceptionMode.PROTECTIVE`）契约是“捕获并按没装 Hook 继续”，
            // 在那个模式下 `throwable` 永远到不了宿主，屏蔽会静默失效。
            //
            // 代价是这里没有框架兜底，所以回调体必须保证**只有**这条刻意的异常会逃逸：
            // 消息解析、构造和失败日志全部收在 runCatching 内，构造失败即放行官方检查。
            environment.registrar.adapted(
                "update.block.check",
                adapted,
                HookExceptionPolicy.DELIVER_TO_HOST
            ) {
                before {
                    val exception = runCatching {
                        val message = InjectedUiLocale.messages(
                            ReflectAccess.currentApplication()
                        ).latestVersionMessage
                        exceptionConstructor.newInstance(message) as Throwable
                    }.getOrElse { failure ->
                        // 日志本身也不能逃逸——它和上面的构造同处 PASSTHROUGH 回调内。
                        runCatching {
                            environment.logError(
                                "block_update_exception_err",
                                "[BIL] 构造宿主最新版状态失败，已放行官方更新检查: $failure"
                            )
                        }
                        null
                    }
                    if (exception != null) throwable = exception
                }
            }
            true
        }.getOrElse { throwable ->
            environment.logError(
                "block_update_install_err",
                "[BIL] 官方客户端更新检查 supplier 层 Hook 注册失败: $throwable"
            )
            false
        }
    }

    companion object {
        const val ID = "block_app_update"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "block_update_status"
        private const val CHANNEL_CALLER = "block_update_caller_status"
        private const val LATEST_VERSION_EXCEPTION_CLASS =
            "tv.danmaku.bili.update.internal.exception.LatestVersionException"

        /**
         * 调用方层入口。`tv.danmaku.bili.update.api` 包在 25 个存档宿主里
         * 全是明文类名，四个方法签名逐字一致：
         *
         * - `checkUpdateInStartup(Activity, IUpdater)` static void
         * - `checkUpdateAndShowDialog(Context, IUpdater)` static void
         * - `checkInternalUpdateFlag(Context)` static void
         * - `getExistingForceUpdate(Activity)` static bolts.Task ← **刻意不在表里**
         */
        private const val UPDATE_HELPER_CLASS = "tv.danmaku.bili.update.api.UpdateHelper"
        internal val CALLER_METHODS = listOf(
            "checkUpdateInStartup",
            "checkUpdateAndShowDialog",
            "checkInternalUpdateFlag"
        )

        /** 观察项：语义是"恢复未完成的强更"，动它可能破坏已下载未安装的状态机。 */
        internal const val EXCLUDED_FORCE_UPDATE = "getExistingForceUpdate"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.view.View
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import java.lang.reflect.Field
import java.lang.reflect.Method
import java.util.concurrent.atomic.AtomicBoolean

/**
 * 底栏自定义隐藏，两层各自独立：
 * - `tabhost`：旧首页框架，在 TabHost 单项绑定完成后隐藏视图，保留宿主页码与索引；
 * - `frame`：新首页框架（平板/宽屏必走，见 [HomeFrameTabLocator]），在 `HomeTabData.bottom`
 *   构造完成后剔除条目。
 * 宿主进程里只会有一套框架在渲染，任一层装上即算就绪；两层都缺才报缺失。
 */
internal class BottomBarFeatureInstaller(
    rules: String,
    selectors: String = "",
    private val points: VersionAdapter.BottomBarPoints?,
    private val frameResolver: (ClassLoader?) -> HomeFrameTabLocator.Resolution = HomeFrameTabLocator::resolve
) : FeatureInstaller {

    override val id: String = ID
    private val tokens = RuleSetCodec.parse(rules)
    private val selectorSet = MineComponentSelectionCodec.decode(selectors)

    private fun hasHiddenConfiguration(): Boolean =
        tokens.isNotEmpty() || selectorSet.isNotEmpty()

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        // 空配置也要装：不扫描就产不出勾选列表（沿用"我的"页 scan / filter+scan 口径）。
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val publisher = ScanSnapshotPublisher(
            environment,
            MineComponentSnapshotCodec.SURFACE_BOTTOM_BAR,
            setOf("bottom_tab_filter")
        )
        val tabHost = installTabHostLayer(environment, publisher)
        val frame = installFrameLayer(environment, publisher)
        environment.reportStatus(CHANNEL_LAYERS, "tabhost=${tabHost.label},frame=${frame.label}")
        val installed = listOf(tabHost, frame).count { it == LayerState.OK }
        if (installed == 0) {
            return missing(environment, tabHost.reason ?: frame.reason ?: "missing-adapter-point")
        }
        val mode = if (hasHiddenConfiguration()) "filter+scan" else "scan"
        environment.reportStatus(CHANNEL_STATUS, "success:$mode")
        environment.logInfo(
            "bottom_bar_ok",
            "[BIL] 底栏自定义隐藏已安装($mode, tabhost=${tabHost.label}, frame=${frame.label})"
        )
        return FeatureInstallResult.Installed(installed)
    }

    private fun installTabHostLayer(
        environment: HookEnvironment,
        publisher: ScanSnapshotPublisher
    ): LayerState {
        val adapted = points ?: return LayerState.absent("missing-adapter-point")
        val itemClass = environment.hookPoints.resolveClass(
            "bottom.item",
            adapted.itemClassName
        ) ?: return LayerState.failed("missing-item-class")
        val fields = adapted.itemStringFields.mapIndexedNotNull { index, name ->
            environment.hookPoints.resolveField("bottom.item.string.$index", itemClass, name)
        }
        if (fields.isEmpty()) return LayerState.failed("missing-item-fields")
        val tabsGetter = environment.hookPoints.resolveAdapted(
            "bottom.tabs",
            adapted.tabsGetter.className,
            adapted.tabsGetter.methodName,
            adapted.tabsGetter.paramClassNames
        ) ?: return LayerState.failed("missing-tabs-getter")
        val firstHit = AtomicBoolean(false)
        return runCatching {
            environment.registrar.adapted("bottom.bind", adapted.bindTabMethod) {
                after {
                    val host = instance ?: return@after
                    val index = (args.getOrNull(0) as? Number)?.toInt() ?: return@after
                    val view = args.getOrNull(1) as? View ?: return@after
                    val tabs = readTabs(tabsGetter, host) ?: return@after
                    publisher.publish(
                        tabs.mapNotNull { candidate ->
                            if (candidate == null || !itemClass.isInstance(candidate)) {
                                return@mapNotNull null
                            }
                            entryOf(values(candidate, fields))
                        }
                    )
                    if (!hasHiddenConfiguration()) return@after
                    val item = tabs.getOrNull(index) ?: return@after
                    if (!itemClass.isInstance(item)) return@after
                    val eligibleCount = tabs.count { candidate ->
                        candidate != null && itemClass.isInstance(candidate)
                    }
                    val matchedCount = tabs.count { candidate ->
                        candidate != null && itemClass.isInstance(candidate) &&
                            matches(values(candidate, fields))
                    }
                    if (!canHide(eligibleCount, matchedCount) ||
                        !matches(values(item, fields))
                    ) {
                        return@after
                    }
                    view.visibility = View.GONE
                    view.isClickable = false
                    view.isEnabled = false
                    view.alpha = 0f
                    if (firstHit.compareAndSet(false, true)) {
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                        environment.logInfo("bottom_bar_tabhost_hit", "[BIL] 底栏自定义隐藏已生效（TabHost 层）")
                    }
                }
            }
            LayerState.OK
        }.getOrElse { throwable ->
            environment.logError("bottom_bar_error", "[BIL] 底栏自定义隐藏失败(TabHost 层): $throwable")
            LayerState.failed("registration-failed")
        }
    }

    private fun installFrameLayer(
        environment: HookEnvironment,
        publisher: ScanSnapshotPublisher
    ): LayerState {
        val model = when (val resolution = frameResolver(environment.classLoader)) {
            is HomeFrameTabLocator.Resolution.Found -> resolution.model
            HomeFrameTabLocator.Resolution.Absent -> return LayerState.absent(null)
            is HomeFrameTabLocator.Resolution.Failed -> {
                environment.logError(
                    "bottom_bar_frame_missing",
                    "[BIL] 底栏自定义隐藏新首页框架层定位失败: ${resolution.reason}"
                )
                return LayerState.failed("frame-${resolution.reason}")
            }
        }
        val slot = model.slot(HomeFrameTabLocator.ELEMENT_BOTTOM)
            ?: return LayerState.failed("frame-missing-bottom-slot")
        val item = model.item
        val firstHit = AtomicBoolean(false)
        val hook = HomeFrameListHook(
            slot = slot,
            item = item,
            onScan = { source ->
                publisher.accumulateAll(
                    source.mapNotNull { candidate ->
                        if (candidate == null || !item.itemClass.isInstance(candidate)) return@mapNotNull null
                        entryOf(frameValues(item, candidate))
                    }
                )
            },
            shouldHide = if (hasHiddenConfiguration()) { candidate ->
                item.itemClass.isInstance(candidate) && matches(frameValues(item, candidate))
            } else null,
            onApplied = { before, after ->
                if (firstHit.compareAndSet(false, true)) {
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                    environment.logInfo(
                        "bottom_bar_frame_hit",
                        "[BIL] 底栏自定义隐藏已生效（新首页框架层，$before → $after）"
                    )
                }
            }
        )
        var registered = 0
        model.constructors.forEachIndexed { index, constructor ->
            runCatching {
                environment.registrar.constructor("bottom.frame.ctor.$index", constructor) {
                    before { hook.enter() }
                    after {
                        runCatching { hook.exit(instance) }.onFailure { throwable ->
                            environment.logError(
                                "bottom_bar_frame_error",
                                "[BIL] 底栏新首页框架层处理失败: $throwable"
                            )
                        }
                    }
                }
                registered += 1
            }.onFailure { throwable ->
                environment.logError(
                    "bottom_bar_frame_ctor_$index",
                    "[BIL] 底栏新首页框架层构造器注册失败: $throwable"
                )
            }
        }
        if (registered == 0) return LayerState.failed("frame-registration-failed")
        // 运行期诊断桥只按旧框架适配点记 ADAPTED；新框架层由安装器自己补上。
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        return LayerState.OK
    }

    private fun readTabs(method: Method, host: Any): List<*>? = runCatching {
        method.invoke(host) as? List<*>
    }.getOrNull()

    /** 旧 TabHost 层：条目只有一串无语义 String 字段，按值形状取两种身份。 */
    private fun values(item: Any, fields: List<Field>): TabValues {
        val strings = fields.mapNotNull { field ->
            runCatching { field.get(item) as? String }.getOrNull()?.trim()?.takeIf(String::isNotEmpty)
        }
        return TabValues(strings, identityFromShape(strings))
    }

    /** 新框架层：按元素名取值，身份与旧层同口径。 */
    private fun frameValues(item: HomeFrameTabLocator.Item, candidate: Any): TabValues {
        fun read(element: String) = item.string(candidate, element)?.trim()?.takeIf(String::isNotEmpty)
        val shape = legacyShapeValues(
            name = read("name"),
            icon = read("icon"),
            iconSelected = read("icon_selected"),
            id = read("id"),
            tabId = read("tab_id"),
            uri = read("uri")
        )
        return TabValues(shape, identityFromFrame(shape, read("uri")))
    }

    private class TabValues(val strings: List<String>, val identity: BottomTabIdentity)

    private fun entryOf(values: TabValues): MineComponentScanEntry? =
        values.identity.scanEntry(showing = !matches(values))

    /** 手填规则（全部 String 值参与）与勾选选择器（主键或旧口径键任一）取并集。 */
    private fun matches(values: TabValues): Boolean {
        if (tokens.isNotEmpty() && RuleSetCodec.matches(tokens, *values.strings.toTypedArray())) return true
        return values.identity.matches(selectorSet)
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("bottom_bar_missing", "[BIL] 底栏自定义隐藏适配不完整: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    private class LayerState private constructor(val label: String, val reason: String?) {
        companion object {
            val OK = LayerState("ok", null)
            fun absent(reason: String?) = LayerState("absent", reason)
            fun failed(reason: String) = LayerState("failed", reason)
        }
    }

    companion object {
        const val ID = "bottom_bar"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "bottom_bar_status"
        /** 两层各自的状态；合并进 [CHANNEL_STATUS] 就分不清是哪套首页框架缺失。 */
        private const val CHANNEL_LAYERS = "bottom_bar_layers"
        private const val MAX_TITLE_CHARS = 12

        internal fun canHide(total: Int, matched: Int): Boolean = matched in 1 until total

        /**
         * 旧口径：宿主的条目类只暴露一串**无语义**的 String 字段，按值的形状分工——
         * 第一个带 `://` 的当"uri"，短且不含 `://` 的当显示名。`TabHost.h` 的字段按 dex 顺序是
         * 名称(`b`) → 图标(`d`) → 选中图标(`e`) → id(`f`) → tab_id(`g`) → 气泡路由(`i`) → 路由(`k`)
         * → 换肤图标(`l/m/y/z`)，所以这里取到的"uri"其实是**图标地址**，换图标/换皮肤就会变。
         * 保留它只为认出存量勾选；新勾选一律写 [canonicalRoute] 口径的主键。
         */
        internal fun shapeKeyParts(values: List<String>): Pair<String?, String?> {
            val uri = values.firstOrNull { it.contains("://") }
            val title = values.firstOrNull { !it.contains("://") && it.length <= MAX_TITLE_CHARS }
            return title to uri
        }

        /**
         * 按旧 TabHost 条目的 String 字段顺序排列新框架条目的同源值，使 [shapeKeyParts]
         * 在两套框架上出同一个旧口径键——两边都来自服务端底栏配置的同名 JSON 字段。
         */
        internal fun legacyShapeValues(
            name: String?,
            icon: String?,
            iconSelected: String?,
            id: String?,
            tabId: String?,
            uri: String?
        ): List<String> = listOfNotNull(name, icon, iconSelected, id, tabId, uri)

        /**
         * 旧层按值形状找路由：排除图标（http/https）与换肤资源（file）后的**最后一个** `://` 值。
         * 取最后一个是因为气泡路由 `h.i` 只在气泡显示期间有值，且排在路由 `h.k` 之前。
         * 路由本身是 H5（https）的底栏项在这一层认不出路由，两层都只用旧口径键，口径仍一致。
         */
        internal fun routeFromShape(values: List<String>): String? =
            values.lastOrNull { value -> canonicalRoute(value) != null }?.let(::canonicalRoute)

        /**
         * 把两套框架拿到的同一路由规范成同一个字符串：
         * - 宿主旧框架对底栏路由做 `Od0.e.b`（trim + 去一个结尾 `/`），新框架拿的是原始值；
         *   宿主自己比路由（`Od0.e.a`）也忽略 query 和结尾 `/`，这里同样去掉；
         * - 旧框架 `MainResourceManager.g` 把 `bilibili://game_center/home`、`bilibili://link/im_home`
         *   改写成 `action://…/menu`，这里还原，否则两层键不同；
         * - scheme、host 小写；http/https/file 不是路由（旧层里它们是图标或换肤资源），返回 null。
         */
        internal fun canonicalRoute(raw: String?): String? {
            val value = raw?.trim().orEmpty()
            val separator = value.indexOf("://")
            if (separator <= 0) return null
            val scheme = value.substring(0, separator).lowercase()
            if (scheme in NON_ROUTE_SCHEMES) return null
            val rest = value.substring(separator + 3).substringBefore('#').substringBefore('?')
            val host = rest.substringBefore('/').lowercase()
            if (host.isEmpty()) return null
            val path = rest.substring(host.length).trimEnd('/')
            val route = "$scheme://$host$path"
            return ACTION_REWRITES[route] ?: route
        }

        internal fun identityFromShape(values: List<String>): BottomTabIdentity {
            val (title, legacyUri) = shapeKeyParts(values)
            return BottomTabIdentity(title, legacyUri, routeFromShape(values))
        }

        internal fun identityFromFrame(shape: List<String>, uri: String?): BottomTabIdentity {
            val (title, legacyUri) = shapeKeyParts(shape)
            return BottomTabIdentity(title, legacyUri, canonicalRoute(uri))
        }

        private val NON_ROUTE_SCHEMES = setOf("http", "https", "file")
        private val ACTION_REWRITES = mapOf(
            "action://game_center/home/menu" to "bilibili://game_center/home",
            "action://link/home/menu" to "bilibili://link/im_home"
        )
    }
}

/**
 * 一个底栏条目的选择器身份。
 *
 * [canonicalKey]（`bottom_tab:uri:<规范路由>`）是新口径主键，两套框架出同一个值、换图标不变；
 * [legacyKey] 是旧 TabHost 层按值形状出的键（通常是图标地址），只用于认出存量勾选。
 * 扫描条目以主键发布、旧键放进 `aliases`，勾选面板下一次确认时把旧键换成主键。
 * 认不出路由（H5 底栏项）时退回只用旧键，与改动前逐字等价。
 */
internal class BottomTabIdentity(
    val title: String?,
    private val legacyUri: String?,
    val route: String?
) {
    val legacyKey: String? = MineComponentSelector.key(KIND, title, null, legacyUri)
    val canonicalKey: String? = route?.let { MineComponentSelector.key(KIND, title, null, it) }

    fun matches(selectors: Set<String>): Boolean =
        (canonicalKey != null && canonicalKey in selectors) ||
            (legacyKey != null && legacyKey in selectors)

    fun scanEntry(showing: Boolean): MineComponentScanEntry? = if (canonicalKey != null) {
        MineComponentScanEntry.create(
            kind = KIND,
            title = title,
            id = null,
            uri = route,
            showing = showing,
            aliases = listOfNotNull(legacyKey?.takeIf { it != canonicalKey })
        )
    } else {
        MineComponentScanEntry.create(kind = KIND, title = title, id = null, uri = legacyUri, showing = showing)
    }

    private companion object {
        const val KIND = "bottom_tab"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import java.lang.reflect.Method

/**
 * 让宿主展示 AV 号而不是 BV 号。
 *
 * 宿主用 `com.bilibili.droid.BVCompat` 里唯一一个 `(String, String) -> String` 的静态方法
 * 在 avid / bvid 之间二选一（等价于 `getVideoId(avid, bvid)`），选哪个由服务端灰度位
 * `bv.enable_bv` 决定。这里只在这一个出口把结果换回 avid。
 *
 * **为什么不改那个静态布尔位**（哔哩漫游的做法）：那个位同时决定文本里识别视频号用的正则
 * 走"AV|BV 全集"还是"仅 AV"，关掉它会顺带让正文里的 BV 链接不再可点，所以上游还得再补一次
 * 正则替换。改这一个返回值出口既不牵连正则，也不用去写 `static final` 字段。
 *
 * 方法名被 R8 混淆（当前是 `a`），因此**不写死名字**：在稳定类上按"静态 + (String, String) ->
 * String + 唯一"结构定位，候选不唯一即按缺失处理。
 *
 * **版本覆盖（2026-09-06 离线核对 9.7.0–9.11.0 五版）**：该结构选择器在每一版都只命中
 * 唯一一个方法（都叫 `a`），且该方法在每一版都有 5 个以上跨 dex 调用方。
 *
 * 改写本身是自证的：只有当返回值确实是 BV 号、而另一个入参不是 BV 号且非空时才替换，
 * 参数顺序万一在未来版本对调也不会把 AV 号换成 BV 号。
 */
internal class BvToAvFeatureInstaller(
    private val enabled: Boolean
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val compat = environment.hookPoints.resolveClass("bv_to_av.compat", BV_COMPAT_CLASS)
            ?: return missing(environment, "missing-bv-compat-class")
        val candidates = KavaMemberLookup.declaredMethods(compat, makeAccessible = true) { method ->
            method.isStatic && method.returnType == classOf<String>() &&
                method.parameterTypes.size == 2 &&
                method.parameterTypes.all { it == classOf<String>() }
        }.distinctBy(Method::toGenericString)
        val chooser = candidates.singleOrNull()
            ?: return missing(
                environment,
                if (candidates.isEmpty()) "missing-video-id-chooser" else "ambiguous-video-id-chooser"
            )

        return runCatching {
            environment.registrar.exact(
                "bv_to_av.video_id",
                chooser.declaringClass,
                chooser.name,
                *chooser.parameterTypes
            ) {
                after {
                    if (hasThrowable) return@after
                    val current = result as? String ?: return@after
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    val alternative = preferredAvId(
                        current,
                        args.getOrNull(0) as? String,
                        args.getOrNull(1) as? String
                    ) ?: return@after
                    result = alternative
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                }
            }
            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
            environment.reportStatus(CHANNEL_STATUS, "success")
            environment.logInfo(
                "bv_to_av_ok",
                "[BIL] AV 号显示已安装(${chooser.declaringClass.name}#${chooser.name})"
            )
            FeatureInstallResult.Installed(1)
        }.getOrElse { throwable ->
            environment.logError(
                "bv_to_av_register",
                "[BIL] AV 号显示 Hook 注册失败: $throwable"
            )
            missing(environment, "registration-failed")
        }
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "bv_to_av_missing",
            "[BIL] AV 号显示适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "bv_to_av"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "bv_to_av_status"
        private const val BV_COMPAT_CLASS = "com.bilibili.droid.BVCompat"

        /** BV 号形如 `BV1` + 9 位受限字母表，总长固定 12。 */
        private const val BV_ID_PREFIX = "BV"
        private const val BV_ID_LENGTH = 12

        internal fun looksLikeBvId(value: String?): Boolean =
            value != null && value.length == BV_ID_LENGTH && value.startsWith(BV_ID_PREFIX)

        /**
         * 在两个候选里挑出该展示的 AV 号。
         *
         * @return 需要改写成的 AV 号；本来就不是 BV 号、或者拿不到可用的 AV 号时返回 null。
         */
        internal fun preferredAvId(current: String, first: String?, second: String?): String? {
            if (!looksLikeBvId(current)) return null
            val alternative = listOfNotNull(first, second)
                .firstOrNull { it != current && it.isNotBlank() && !looksLikeBvId(it) }
            return alternative
        }
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.highcapable.kavaref.extension.isSubclassOf
import com.highcapable.kavaref.extension.classOf
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.isStatic
import java.lang.reflect.Method
import java.util.concurrent.ConcurrentHashMap

/**
 * 在公开 protobuf 评论列表边界按正文关键词、用户等级、@ 整条和发布者过滤。
 *
 * 四条判据共用同一批列表 getter Hook：多开一个判据不会多挂一个 Hook，只是在同一次遍历里
 * 多读几个字段，而且只读当前真的启用的那几个。
 *
 * 覆盖单位口径：
 * - 列表 / 置顶 getter 各算一个单位。
 * - 关键词、等级、@ 整条与发布者分别校验依赖：**用户开了就各算一个单位**，读取路径缺失时计入分母、不计入
 *   分子，让"开了却读不到"表现为 `partial` 而不是悄悄失效。
 */
internal class CommentFilterFeatureInstaller(
    keywordFilterEnabled: Boolean,
    rawKeywords: String,
    minimumLevelFilterEnabled: Boolean,
    minimumLevel: Int,
    removeAtOnlyComments: Boolean = false,
    userFilterEnabled: Boolean = false,
    rawUserRules: String = "",
    private val points: VersionAdapter.CommentFilterPoints?,
    /**
     * 智能过滤评论（JEV）。两层：① `ReplyMoss` 评论列表响应到达时（后台线程）只读正文、提前判定，
     * 开了"首屏等待"就在该回调里等结果，第一屏即生效；② 列表 getter 只查缓存，未命中投后台，
     * 下次加载生效。getter 可能在主线程，所以这一层绝不联网。
     */
    private val semanticJudge: SemanticJudge? = null,
    /** debug 构建的观测日志目录；release 为 null。 */
    private val semanticLogDir: java.io.File? = null,
    /** 主线程上不做同步联网；单测可替换。 */
    private val isMainThread: () -> Boolean = { android.os.Looper.myLooper() == android.os.Looper.getMainLooper() }
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (keywords.isNotEmpty()) add("comments_keyword_filter_enabled")
        if (minimumLevel != null) add("comments_minimum_level_filter_enabled")
        if (removeAtOnly) add("comments_at_only_removed")
        if (!userRules.isEmpty()) add("comments_user_filter_enabled")
        if (semanticJudge != null) add("comments_semantic_filter_enabled")
    }

    private val keywords = if (keywordFilterEnabled) {
        RuleSetCodec.parse(rawKeywords).take(MAX_KEYWORDS).toCollection(linkedSetOf())
    } else {
        emptySet()
    }
    private val minimumLevel = if (minimumLevelFilterEnabled) {
        minimumLevel.coerceIn(MIN_LEVEL, MAX_LEVEL)
    } else {
        null
    }
    private val removeAtOnly = removeAtOnlyComments
    private val userRules = if (userFilterEnabled) {
        AuthorRuleSet.parse(rawUserRules)
    } else {
        AuthorRuleSet.EMPTY
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (keywords.isEmpty() && minimumLevel == null && !removeAtOnly && userRules.isEmpty() &&
            semanticJudge == null
        ) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = points ?: return missing(environment, "missing-adapter-point")
        val accessors = Accessors(
            content = adapted.contentGetter?.let { resolve(environment, "content", it) },
            message = adapted.messageGetter?.let { resolve(environment, "message", it) },
            member = adapted.memberGetter?.let { resolve(environment, "member", it) },
            level = adapted.levelGetter?.let { resolve(environment, "level", it) },
            memberV2 = adapted.memberV2Getter?.let {
                resolve(environment, "member_v2", it)
            },
            memberV2Basic = adapted.memberV2BasicGetter?.let {
                resolve(environment, "member_v2_basic", it)
            },
            memberV2Level = adapted.memberV2LevelGetter?.let {
                resolve(environment, "member_v2_level", it)
            },
            atNameCount = adapted.atNameCountGetter?.let {
                resolve(environment, "at_count", it)
            },
            atNameMap = adapted.atNameMapGetter?.let { resolve(environment, "at_map", it) },
            memberName = adapted.memberNameGetter?.let {
                resolve(environment, "member_name", it)
            },
            memberMid = adapted.memberMidGetter?.let { resolve(environment, "member_mid", it) },
            memberV2Name = adapted.memberV2NameGetter?.let {
                resolve(environment, "member_v2_name", it)
            },
            memberV2Mid = adapted.memberV2MidGetter?.let {
                resolve(environment, "member_v2_mid", it)
            }
        )

        // 判据可用性只算一次：热路径只做布尔判断，不再重复检查 Method 是否为 null。
        val plan = JudgementPlan(
            keywords = if (accessors.hasMessagePath) keywords else emptySet(),
            minimumLevel = minimumLevel?.takeIf { accessors.hasLevelPath },
            removeAtOnly = removeAtOnly && accessors.hasAtPath,
            userRules = userRules.available(accessors.hasAuthorNamePath, accessors.hasAuthorMidPath),
            semanticEnabled = semanticJudge != null && accessors.hasMessagePath
        )
        if (!plan.hasAnyJudgement) return missing(environment, "missing-judgement-getter")

        var installed = 0
        adapted.replyListGetters.forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("comment.filter.list.$index", point) {
                    after {
                        // Kotlin 新通道读原始列表时不过滤，见 [KotlinMossChannel.raw]。
                        if (KotlinMossChannel.isRaw()) return@after
                        val source = result as? List<*> ?: return@after
                        if (source.isEmpty()) return@after
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        val semantic = semanticVerdicts(source, accessors, plan)
                        val filtered = filterComments(source) { reply ->
                            semantic?.get(reply) == SemanticVerdict.BLOCK ||
                                shouldRemove(readSignals(reply, accessors, plan), plan)
                        }
                        if (filtered !== source) {
                            result = filtered
                            environment.reportRuntimeEvidence(
                                ID,
                                FeatureRuntimeStage.APPLIED,
                                source.size - filtered.size
                            )
                        }
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "comment_filter_list_$index",
                    "[BIL] 评论过滤 Hook 注册失败(" +
                        "${point.className}#${point.methodName}): $throwable"
                )
            }
        }

        val defaultReply = adapted.replyDefaultInstanceGetter?.let { point ->
            resolve(environment, "reply_default", point)?.let { getter ->
                runCatching { getter.invoke(null) }.getOrNull()
            }
        }
        if (defaultReply != null) {
            adapted.topReplyGetters.forEachIndexed { index, point ->
                runCatching {
                    environment.registrar.adapted("comment.filter.top.$index", point) {
                        after {
                            if (KotlinMossChannel.isRaw()) return@after
                            val reply = result ?: return@after
                            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                            // 单条置顶：绕过列表 memo（每次都是新包装，缓存它只会挤掉真正的列表条目）。
                            val semanticBlocked = plan.semanticEnabled &&
                                computeSemanticVerdicts(listOf(reply), accessors)?.get(reply) == SemanticVerdict.BLOCK
                            if (semanticBlocked || shouldRemove(readSignals(reply, accessors, plan), plan)) {
                                result = defaultReply
                                environment.reportRuntimeEvidence(
                                    ID,
                                    FeatureRuntimeStage.APPLIED
                                )
                            }
                        }
                    }
                    installed += 1
                }.onFailure { throwable ->
                    environment.logError(
                        "comment_filter_top_$index",
                        "[BIL] 置顶评论过滤 Hook 注册失败(" +
                            "${point.className}#${point.methodName}): $throwable"
                    )
                }
            }
        }
        // KMP 评论页走 Kotlin KReplyMoss：兜底通道，不计入覆盖单位；Java getter 一个都装不上时也照装。
        installKotlinChannel(environment, accessors, plan)
        if (installed == 0) return missing(environment, "registration-failed")
        // 提前判定层是加速通道，不计入覆盖单位：装不上时仍按"下次加载生效"工作。
        if (plan.semanticEnabled) installMossPrefetch(environment, accessors)
        val sharedInstalled = installed
        val sharedExpected = adapted.replyListGetters.size + adapted.topReplyGetters.size
        for (capability in capabilityIds) {
            val usable = when (capability) {
                "comments_minimum_level_filter_enabled" -> accessors.hasLevelPath
                "comments_at_only_removed" -> plan.removeAtOnly
                "comments_user_filter_enabled" -> !plan.userRules.isEmpty()
                "comments_semantic_filter_enabled" -> plan.semanticEnabled
                else -> plan.keywords.isNotEmpty()
            }
            environment.reportCapabilityCoverage(capability, usable, sharedInstalled,
                sharedExpected + if (capability == "comments_user_filter_enabled" && plan.userRules != userRules) 1 else 0)
        }

        // 判据覆盖：用户开了但适配读不到的判据，要在分母里留下痕迹。
        var expected = sharedExpected
        val degraded = ArrayList<String>(4)
        if (keywords.isNotEmpty()) {
            expected += 1
            if (plan.keywords.isNotEmpty()) installed += 1 else degraded += "keyword"
        }
        if (minimumLevel != null) {
            expected += 1
            if (plan.minimumLevel != null) installed += 1 else degraded += "level"
        }
        if (removeAtOnly) {
            expected += 1
            if (plan.removeAtOnly) installed += 1 else degraded += "at-only"
        }
        if (!userRules.isEmpty()) {
            expected += 1
            if (plan.userRules == userRules) installed += 1 else degraded += "author"
        }
        if (semanticJudge != null) {
            expected += 1
            if (plan.semanticEnabled) installed += 1 else degraded += "semantic"
        }
        if (degraded.isNotEmpty()) {
            environment.logError(
                "comment_filter_degraded",
                "[BIL] 评论过滤判据缺少可用读取路径: ${degraded.joinToString(",")}"
            )
        }

        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        val status = if (installed == expected) {
            "success"
        } else {
            "partial:$installed/$expected"
        }
        environment.reportStatus(CHANNEL_STATUS, status)
        if (status == "success") {
            environment.logInfo(
                "comment_filter_ok",
                "[BIL] 评论过滤已安装，hooks=$installed，判据=${plan.describe()}"
            )
        } else {
            environment.logError(
                "comment_filter_partial",
                "[BIL] 评论过滤部分安装，status=$status"
            )
        }
        return FeatureInstallResult.Installed(installed, complete = installed == expected)
    }

    /**
     * getter 层：整批取正文，缓存命中直接给结论，未命中投后台（不阻塞、不联网）。
     * 正文读取与 [readSignals] 同一路径，保证缓存键一致。
     */
    private fun semanticVerdicts(
        source: List<*>,
        accessors: Accessors,
        plan: JudgementPlan
    ): java.util.IdentityHashMap<Any, SemanticVerdict>? {
        if (semanticJudge == null || !plan.semanticEnabled) return null
        return semanticMemo.getOrCompute(source) { computeSemanticVerdicts(source, accessors) }
    }

    private val semanticMemo = SemanticListMemo()

    private fun computeSemanticVerdicts(
        source: List<*>,
        accessors: Accessors
    ): java.util.IdentityHashMap<Any, SemanticVerdict>? {
        val judge = semanticJudge ?: return null
        val replies = source.filterNotNull()
        if (replies.isEmpty()) return null
        val texts = replies.map { messageOf(it, accessors) }
        val verdicts = judge.evaluate(texts, SemanticMode.PREFETCH, onReport = reportTo("comment-getter"))
        return java.util.IdentityHashMap<Any, SemanticVerdict>(replies.size).apply {
            replies.forEachIndexed { index, reply -> put(reply, verdicts[index]) }
        }
    }

    private fun messageOf(reply: Any, accessors: Accessors): String {
        val content = invokeCompatible(accessors.content, reply)
        return invokeCompatible(accessors.message, content)?.toString()?.trim().orEmpty()
    }

    /**
     * 提前判定层：观察 `ReplyMoss` 的评论列表响应（主楼 / 楼中楼 / 对话），只读不改。
     * 回调在后台线程时按设置等待或投后台；在主线程时只投后台。
     */
    private fun installMossPrefetch(environment: HookEnvironment, accessors: Accessors) {
        val judge = semanticJudge ?: return
        val replyInfoClass = accessors.content?.declaringClass ?: return
        val loader = replyInfoClass.classLoader ?: return
        val packageName = replyInfoClass.name.substringBeforeLast('.')
        val moss = KavaMemberLookup.classOrNull(loader, "$packageName.ReplyMoss") ?: run {
            environment.logInfo("comment_semantic_moss_missing", "[BIL] 智能过滤评论：未找到 ReplyMoss，仅用列表缓存层")
            return
        }
        val handlerClass = KavaMemberLookup.classOrNull(loader, MOSS_HANDLER_CLASS)
        val readers = ConcurrentHashMap<Class<*>, List<Method>>()
        fun observe(response: Any) {
            // 收正文必须走原始读取：这里的列表 getter 正是本安装器挂钩的那些，嵌套调用
            // 会让 after 回调抢先以 PREFETCH 认领全部 key，observe 自己的 WAIT 拿到空
            // claimedKeys 直接返回全 UNKNOWN，"首屏等待"永远空转。与 prewarmSemantic 同口径。
            val texts = KotlinMossChannel.raw { collectReplyTexts(response, replyInfoClass, accessors, readers) }
            if (texts.isEmpty()) return
            val mode = if (judge.waitFirstScreen && !isMainThread()) SemanticMode.WAIT else SemanticMode.PREFETCH
            judge.evaluate(texts, mode, onReport = reportTo("comment-moss"))
        }
        var hooks = 0
        PREFETCH_RPCS.forEach { rpc ->
            if (handlerClass != null) {
                KavaMemberLookup.declaredMethods(moss, makeAccessible = true) {
                    !it.isStatic && it.name == rpc && it.parameterCount == 2 &&
                        it.parameterTypes[1] == handlerClass && it.returnType == Void.TYPE
                }.singleOrNull()?.let { method ->
                    runCatching {
                        environment.registrar.exact("comment.semantic.async.$rpc", method.declaringClass,
                            method.name, *method.parameterTypes) {
                            before {
                                val delegate = args.getOrNull(1) ?: return@before
                                // 模块自己发起的请求（回复拓扑翻页等）不判定：那不是用户正在看的评论列表，
                                // 判了既额外计费，开"首屏等待"时还会拖慢拓扑面板。
                                if (isModuleOwnedHandler(delegate)) return@before
                                MossResponseHandlerProxy.wrap(handlerClass, delegate) { response -> observe(response) }
                                    ?.let { args[1] = it }
                            }
                        }
                        hooks += 1
                    }
                }
            }
            val syncName = "execute" + rpc.replaceFirstChar(Char::uppercaseChar)
            KavaMemberLookup.declaredMethods(moss, makeAccessible = true) {
                !it.isStatic && it.name == syncName && it.parameterCount == 1
            }.singleOrNull()?.let { method ->
                runCatching {
                    environment.registrar.exact("comment.semantic.sync.$rpc", method.declaringClass,
                        method.name, *method.parameterTypes) {
                        after {
                            if (hasThrowable) return@after
                            result?.let { observe(it) }
                        }
                    }
                    hooks += 1
                }
            }
        }
        environment.logInfo("comment_semantic_moss", "[BIL] 智能过滤评论：提前判定边界 $hooks 个")
    }

    /**
     * KMP 评论页（`kntr.common.comment.page`，9.14.0 的 `PresetListPageRepo` / `PresetDetailPageRepo`）
     * 直接调 `KReplyMoss.mainList/detailList`，拿到的是 Kotlin 数据类，上面的 Java getter 过滤碰不到。
     * 这里经 [KotlinMossChannel] 往返到 Java `MainListReply` 等，用 [ProtobufReplyTreeRewriter] 删评论
     * （主楼、子回复预览、置顶位），判据与 getter 层完全相同；智能过滤在回调里按"首屏等待"设置判定。
     */
    private fun installKotlinChannel(environment: HookEnvironment, accessors: Accessors, plan: JudgementPlan) {
        // 装不上要留下原因，否则末尾那句"N 个"读起来像"不适用"，而不是"类没找到"（有界：四条）。
        fun skip(reason: String) {
            environment.logInfo("comment_filter_kmoss_skip", "[BIL] 评论过滤新通道未接入: $reason")
        }
        val replyInfoClass = accessors.content?.declaringClass ?: return skip("no-reply-info")
        val loader = replyInfoClass.classLoader ?: return skip("no-class-loader")
        val packageName = replyInfoClass.name.substringBeforeLast('.')
        val members = KotlinMossChannel.prepare(environment, loader, "评论过滤", KMOSS_LOG_KEY) ?: return skip("no-bridge")
        val rewriter = ProtobufReplyTreeRewriter(replyInfoClass) { replies -> kotlinDecide(environment, replies, accessors, plan) }
        val readers = ConcurrentHashMap<Class<*>, List<Method>>()
        var hooks = 0
        KMOSS_RPCS.forEach { (rpc, replyName) ->
            val replyClass = KavaMemberLookup.classOrNull(loader, "$packageName.$replyName")
                ?: return@forEach skip("no-reply-class:$rpc")
            val installed = KotlinMossChannel.install(
                environment, loader, members,
                javaMossClassName = "$packageName.ReplyMoss",
                rpc = rpc,
                javaReplyClass = replyClass,
                hookId = "comment.filter.kmoss.$rpc",
                what = "评论过滤",
                logKey = KMOSS_LOG_KEY,
                shareUnchangedReply = true
            ) { javaReply ->
                prewarmSemantic(javaReply, replyInfoClass, accessors, plan, readers)
                rewriter.rewrite(javaReply).message
            }
            if (installed) hooks += 1
        }
        environment.logInfo("comment_filter_kmoss", "[BIL] 评论过滤：Kotlin 新通道 $hooks 个")
    }

    /**
     * 整份响应的正文一次性送判（与 Java 链路的提前判定层同一批口径），回调在后台线程且开了"首屏等待"时在这里等；
     * 之后 [kotlinDecide] 按层只查缓存，不会每层各发一次阻塞请求。
     */
    private fun prewarmSemantic(
        javaReply: Any,
        replyInfoClass: Class<*>,
        accessors: Accessors,
        plan: JudgementPlan,
        readers: ConcurrentHashMap<Class<*>, List<Method>>
    ) {
        val judge = semanticJudge?.takeIf { plan.semanticEnabled } ?: return
        val texts = KotlinMossChannel.raw { collectReplyTexts(javaReply, replyInfoClass, accessors, readers) }
        if (texts.isEmpty()) return
        val mode = if (judge.waitFirstScreen && !isMainThread()) SemanticMode.WAIT else SemanticMode.PREFETCH
        judge.evaluate(texts, mode, onReport = reportTo("comment-kmoss"))
    }

    /** 同一层的一批评论 → 要删的那些（按引用）。在 moss 回调里，可能是后台线程。 */
    private fun kotlinDecide(
        environment: HookEnvironment,
        replies: List<Any>,
        accessors: Accessors,
        plan: JudgementPlan
    ): Set<Any> {
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
        val judge = semanticJudge?.takeIf { plan.semanticEnabled }
        // 整份响应已在 [prewarmSemantic] 里判过，这里只取缓存结论（未命中投后台，不阻塞）。
        val semantic = judge?.evaluate(replies.map { reply -> messageOf(reply, accessors) }, SemanticMode.PREFETCH)
        val drop = java.util.Collections.newSetFromMap(java.util.IdentityHashMap<Any, Boolean>())
        replies.forEachIndexed { index, reply ->
            if (semantic?.getOrNull(index) == SemanticVerdict.BLOCK ||
                shouldRemove(readSignals(reply, accessors, plan), plan)
            ) drop += reply
        }
        if (drop.isNotEmpty()) environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED, drop.size)
        return drop
    }

    /** 回调是本模块创建的动态代理（`Proxy` 的调用处理器由模块类加载器加载）。 */
    private fun isModuleOwnedHandler(handler: Any): Boolean = runCatching {
        java.lang.reflect.Proxy.isProxyClass(handler.javaClass) &&
            java.lang.reflect.Proxy.getInvocationHandler(handler).javaClass.classLoader ==
            classOf<CommentFilterFeatureInstaller>().classLoader
    }.getOrDefault(false)

    /** 一层反射：响应对象上所有返回 ReplyInfo 或 List<ReplyInfo> 的 getter，外加每条 ReplyInfo 的子回复。 */
    private fun collectReplyTexts(
        response: Any,
        replyInfoClass: Class<*>,
        accessors: Accessors,
        readers: ConcurrentHashMap<Class<*>, List<Method>>
    ): List<String> {
        fun gettersOf(type: Class<*>): List<Method> = readers.getOrPut(type) {
            type.methods.filter { method ->
                !method.isStatic && method.parameterCount == 0 && method.name.startsWith("get") &&
                    (method.returnType == replyInfoClass || method.returnType isSubclassOf classOf<List<*>>())
            }
        }
        val out = LinkedHashSet<String>()
        fun addReply(reply: Any?, depth: Int) {
            if (reply == null || !replyInfoClass.isInstance(reply) || out.size >= MOSS_MAX_TEXTS) return
            messageOf(reply, accessors).takeIf(String::isNotEmpty)?.let(out::add)
            if (depth > 0) return
            gettersOf(replyInfoClass).filter { it.returnType isSubclassOf classOf<List<*>>() }.forEach { getter ->
                (runCatching { getter.invoke(reply) }.getOrNull() as? List<*>)?.forEach { addReply(it, depth + 1) }
            }
        }
        gettersOf(response.javaClass).forEach { getter ->
            when (val value = runCatching { getter.invoke(response) }.getOrNull()) {
                is List<*> -> value.forEach { addReply(it, 0) }
                else -> addReply(value, 0)
            }
        }
        return out.toList()
    }

    private fun reportTo(source: String): ((SemanticBatchReport, List<String>, List<SemanticVerdict>) -> Unit)? {
        val dir = semanticLogDir ?: return null
        return { report, texts, verdicts ->
            val blocked = texts.indices.filter { verdicts[it] == SemanticVerdict.BLOCK }
                .joinToString(" | ") { texts[it].take(24) }
            SemanticDebugLog.append(
                dir,
                "${System.currentTimeMillis()} $source thread=${Thread.currentThread().name} total=${report.total} " +
                    "requested=${report.requested} blocked=${report.blocked} ms=${report.elapsedMs} " +
                    "outcome=${report.outcome}${report.extras()} :: $blocked"
            )
        }
    }

    /** 只读当前启用判据真正需要的字段；未启用的判据一次反射都不做。 */
    private fun readSignals(
        reply: Any,
        accessors: Accessors,
        plan: JudgementPlan
    ): Signals {
        val needContent = plan.needsMessage || plan.removeAtOnly
        val content = if (needContent) invokeCompatible(accessors.content, reply) else null
        val message = if (plan.needsMessage) {
            invokeCompatible(accessors.message, content)?.toString()
        } else {
            null
        }
        val atNames = if (plan.removeAtOnly) readAtNames(content, accessors) else null

        var level: Int? = null
        var authorName: String? = null
        var authorMid: Long? = null
        if (plan.minimumLevel != null || !plan.userRules.isEmpty()) {
            val member = invokeCompatible(accessors.member, reply)
            val memberV2 = invokeCompatible(accessors.memberV2, reply)
            val memberV2Basic = invokeCompatible(accessors.memberV2Basic, memberV2)
            if (plan.minimumLevel != null) {
                level = (invokeCompatible(accessors.level, member) as? Number)?.toInt()
                    ?: (invokeCompatible(accessors.memberV2Level, memberV2Basic) as? Number)
                        ?.toInt()
            }
            if (!plan.userRules.isEmpty()) {
                authorName = (invokeCompatible(accessors.memberName, member) as? String)
                    ?.takeIf(String::isNotBlank)
                    ?: (invokeCompatible(accessors.memberV2Name, memberV2Basic) as? String)
                        ?.takeIf(String::isNotBlank)
                authorMid = (invokeCompatible(accessors.memberMid, member) as? Number)?.toLong()
                    ?.takeIf { it > 0L }
                    ?: (invokeCompatible(accessors.memberV2Mid, memberV2Basic) as? Number)
                        ?.toLong()
                        ?.takeIf { it > 0L }
            }
        }
        return Signals(
            message = message,
            level = level,
            atNames = atNames,
            authorName = authorName,
            authorMid = authorMid
        )
    }

    /** 先读计数：没有 @ 的评论（绝大多数）连 Map 视图都不会构造。 */
    private fun readAtNames(content: Any?, accessors: Accessors): Set<String>? {
        content ?: return null
        val count = (invokeCompatible(accessors.atNameCount, content) as? Number)?.toInt()
            ?: return null
        if (count <= 0) return emptySet()
        val map = invokeCompatible(accessors.atNameMap, content) as? Map<*, *> ?: return null
        return map.keys.asSequence()
            .filterIsInstance<String>()
            .filter(String::isNotBlank)
            .toCollection(linkedSetOf())
    }

    private fun invokeCompatible(method: Method?, target: Any?): Any? {
        if (method == null || target == null || !method.declaringClass.isInstance(target)) {
            return null
        }
        return runCatching { method.invoke(target) }.getOrNull()
    }

    private fun resolve(
        environment: HookEnvironment,
        suffix: String,
        point: VersionAdapter.HookPoint
    ): Method? = environment.hookPoints.resolveAdapted(
        "comment.filter.resolve.$suffix",
        point.className,
        point.methodName,
        point.paramClassNames
    )

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "comment_filter_missing",
            "[BIL] 评论过滤适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    internal data class Signals(
        val message: String? = null,
        val level: Int? = null,
        /** null = 本次没读 @ 名单（判据未启用或读取失败），不能当成"没有 @"。 */
        val atNames: Set<String>? = null,
        val authorName: String? = null,
        val authorMid: Long? = null
    )

    /** 安装期定型的判据集合；热路径只读它，不再回头判断适配是否完整。 */
    internal data class JudgementPlan(
        val keywords: Set<String>,
        val minimumLevel: Int?,
        val removeAtOnly: Boolean,
        val userRules: AuthorRuleSet,
        /** 智能过滤：语义结论由 getter 层单独读正文取得，不走 [needsMessage]。 */
        val semanticEnabled: Boolean = false
    ) {
        val needsMessage: Boolean
            get() = keywords.isNotEmpty() || removeAtOnly

        val hasAnyJudgement: Boolean
            get() = keywords.isNotEmpty() || minimumLevel != null || removeAtOnly ||
                !userRules.isEmpty() || semanticEnabled

        fun describe(): String = buildList {
            if (keywords.isNotEmpty()) add("keyword=${keywords.size}")
            minimumLevel?.let { add("level>=$it") }
            if (removeAtOnly) add("at-only")
            if (!userRules.isEmpty()) {
                add("author=${userRules.mids.size}uid+${userRules.names.size}name")
            }
            if (semanticEnabled) add("semantic")
        }.joinToString("/")
    }

    private data class Accessors(
        val content: Method?,
        val message: Method?,
        val member: Method?,
        val level: Method?,
        val memberV2: Method?,
        val memberV2Basic: Method?,
        val memberV2Level: Method?,
        val atNameCount: Method?,
        val atNameMap: Method?,
        val memberName: Method?,
        val memberMid: Method?,
        val memberV2Name: Method?,
        val memberV2Mid: Method?
    ) {
        val hasMessagePath: Boolean get() = content != null && message != null
        val hasLevelPath: Boolean
            get() = (member != null && level != null) ||
                (memberV2 != null && memberV2Basic != null && memberV2Level != null)

        val hasAtPath: Boolean
            get() = hasMessagePath && atNameCount != null && atNameMap != null

        val hasAuthorNamePath: Boolean get() = (member != null && memberName != null) ||
            (memberV2 != null && memberV2Basic != null && memberV2Name != null)
        val hasAuthorMidPath: Boolean get() = (member != null && memberMid != null) ||
            (memberV2 != null && memberV2Basic != null && memberV2Mid != null)
    }

    companion object {
        const val ID = "comment_filter"
        const val DEFAULT_MIN_LEVEL = 3
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "comment_filter_status"
        private const val MAX_KEYWORDS = 64
        private const val MIN_LEVEL = 1
        private const val MAX_LEVEL = 6
        private const val MOSS_HANDLER_CLASS = "com.bilibili.lib.moss.api.MossResponseHandler"
        /** 评论列表 RPC：主楼、楼中楼、对话。只观察，不改写响应。 */
        private val PREFETCH_RPCS = listOf("mainList", "detailList", "dialogList")
        /** Kotlin 新通道：RPC → 同一 proto 的 Java 响应类简单名（与 `ReplyMoss` 同包）。 */
        private val KMOSS_RPCS = listOf(
            "mainList" to "MainListReply",
            "detailList" to "DetailListReply",
            "dialogList" to "DialogListReply"
        )
        private const val KMOSS_LOG_KEY = "comment_filter_kmoss"
        /** 单次响应最多提取的不同正文数（主楼约 20 条 + 子回复预览）。 */
        private const val MOSS_MAX_TEXTS = 80

        /**
         * 去掉 @ 名字后仍算"空正文"的残留标点。
         *
         * 空白另由 Char.isWhitespace 判断，这里只收分隔性标点；表情、汉字、字母数字一律
         * 留给“有正文”那一侧，宁可漏删也不错删。
         */
        private const val AT_ONLY_RESIDUE_PUNCTUATION = ",，.。、;；:：!！?？~～·|/-—_+&*"

        /** 读取失败时保守放行；只有明确命中某条判据才删除。 */
        internal fun shouldRemove(
            signals: Signals,
            plan: JudgementPlan
        ): Boolean = RuleSetCodec.matches(plan.keywords, signals.message) ||
            (plan.minimumLevel != null && signals.level?.let { it < plan.minimumLevel } == true) ||
            (plan.removeAtOnly && isAtOnlyComment(signals.message, signals.atNames)) ||
            (!plan.userRules.isEmpty() &&
                plan.userRules.matches(signals.authorName, signals.authorMid))

        /** 兼容旧签名的窄入口，供只关心关键词/等级两条判据的单测使用。 */
        internal fun shouldRemove(
            signals: Signals,
            keywords: Set<String>,
            minimumLevel: Int?
        ): Boolean = shouldRemove(
            signals,
            JudgementPlan(keywords, minimumLevel, removeAtOnly = false, userRules = AuthorRuleSet.EMPTY)
        )

        /**
         * 判断整条评论是否只由 @ 组成。
         *
         * [atNames] 为 null 表示这次没能读到 @ 名单——此时一律保留，绝不按"正文很短"猜。
         */
        internal fun isAtOnlyComment(message: String?, atNames: Set<String>?): Boolean {
            if (atNames.isNullOrEmpty()) return false
            val text = message ?: return false
            if (text.isBlank()) return false
            var residue = text
            // 长名字先删，避免"@张三"把"@张三丰"的前缀吃掉后留下孤立的"丰"。
            atNames.sortedByDescending(String::length).forEach { name ->
                residue = residue.replace("@$name", " ")
            }
            return residue.all { it.isWhitespace() || it in AT_ONLY_RESIDUE_PUNCTUATION }
        }

        /** 无命中返回原 List；有命中才创建不可变副本，不改写 protobuf 内部集合。 */
        internal fun filterComments(
            source: List<*>,
            shouldRemove: (Any) -> Boolean
        ): List<*> = ProtobufListRetention.filterOrSame(source, shouldRemove)
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import org.json.JSONObject
import java.lang.reflect.Method
import java.util.concurrent.ConcurrentHashMap

/**
 * 评论净化在 Kotlin 新通道（KMP 评论页）上的协议层实现：在往返得到的 Java 评论响应上直接改，
 * 与 Java 链路的 getter 净化逐项对应。
 *
 * | 子项 | Java 链路 | 这里 |
 * | --- | --- | --- |
 * | 评论里的搜索跳转 | `Content.getUrlsMap` 摘条目 + `Url.getAppUrlSchema` 置空 | 每条评论（含子回复、置顶位）的 `Content.urls` 摘掉搜索条目后重建 |
 * | 空评论区引导 | `SubjectControl.getEmptyPage` 返回默认实例 | `subject_control.empty_page` 清掉 |
 * | 评论反馈（QoE） / 运营推广 | `hasX` 与 `getX` 成对返回"无" | `MainListReply` 上 `clearQoe` / `clearOperation` / `clearOperationV2` |
 *
 * 投票组件、关注按钮、快速回复是旧版 View 层的东西，Compose 评论页没有对应物，这里不做。
 *
 * 所有读取都在 [KotlinMossChannel.raw] 里进行（本功能的 getter 净化会把这些字段读成"无"）。
 * 名字全部是 protobuf 生成代码的固定形状（2026-10-01 dexq 核对 9.14.0）；缺哪一项就跳过那一项。
 */
internal class CommentKotlinPurifier(
    replyInfoClass: Class<*>,
    /** null = 不摘搜索跳转。 */
    private val isSearchUrl: ((Any?) -> Boolean)?,
    private val clearEmptyPage: Boolean,
    /** `MainListReply` 上要清的可选字段名（如 `Qoe`、`Operation`）→ 对应的能力 id。 */
    private val payloads: Map<String, String>,
    /** 形状解析不出来时留一条有界日志（单测不传）。必须排在 [evidence] 之前：Kotlin 的尾随 lambda 绑定到最后一个参数。 */
    private val logSkip: (reason: String) -> Unit = {},
    private val evidence: (capability: String, stage: FeatureRuntimeStage, count: Int) -> Unit
) {
    private val replyLinks = ConcurrentHashMap<Class<*>, Any>()
    private val topShapes = ConcurrentHashMap<Class<*>, Any>()
    private val rewriter = ProtobufReplyTreeRewriter(
        replyInfoClass,
        removableSingles = emptySet(),
        mapReply = { reply -> if (isSearchUrl == null) reply else stripLinks(reply) }
    ) { emptySet() }

    fun purify(message: Any): Any {
        var current = message
        if (isSearchUrl != null) current = rewriter.rewrite(current).message
        val shape = topShapeOf(current.javaClass) ?: return current
        val clears = shape.payloads.filter { field ->
            KotlinMossChannel.raw { field.has.invoke(current) as? Boolean } == true
        }
        val subject = shape.subject?.takeIf { clearEmptyPage }?.let { path ->
            val control = KotlinMossChannel.raw {
                if (path.has.invoke(current) as? Boolean == true) path.getter.invoke(current) else null
            } ?: return@let null
            val hasEmpty = KotlinMossChannel.raw { path.hasEmptyPage.invoke(control) as? Boolean } == true
            if (!hasEmpty) return@let null
            path.controlPlan.edit(control) { builder -> path.clearEmptyPage.invoke(builder) }
        }
        if (clears.isEmpty() && subject == null) return current
        val rebuilt = shape.plan.edit(current) { builder ->
            clears.forEach { it.clear.invoke(builder) }
            if (subject != null) shape.subject?.set?.invoke(builder, subject)
        }
        clears.forEach {
            evidence(it.capability, FeatureRuntimeStage.OBSERVED, 1)
            evidence(it.capability, FeatureRuntimeStage.APPLIED, 1)
        }
        if (subject != null) {
            evidence(EMPTY_GUIDE_CAPABILITY, FeatureRuntimeStage.OBSERVED, 1)
            evidence(EMPTY_GUIDE_CAPABILITY, FeatureRuntimeStage.APPLIED, 1)
        }
        return rebuilt
    }

    // —— 搜索跳转 ——

    private class Links(
        val contentGetter: Method,
        val urlsGetter: Method,
        val contentPlan: ProtobufBuilderPlan,
        val clearUrls: Method,
        val putAllUrls: Method,
        val replyPlan: ProtobufBuilderPlan,
        val setContent: Method
    )

    private fun stripLinks(reply: Any): Any {
        val predicate = isSearchUrl ?: return reply
        val links = linksOf(reply.javaClass) ?: return reply
        val content = KotlinMossChannel.raw { links.contentGetter.invoke(reply) } ?: return reply
        @Suppress("UNCHECKED_CAST")
        val urls = KotlinMossChannel.raw { links.urlsGetter.invoke(content) as? Map<Any?, Any?> } ?: return reply
        if (urls.isEmpty()) return reply
        evidence(SEARCH_LINKS_CAPABILITY, FeatureRuntimeStage.OBSERVED, 1)
        val filtered = CommentPurifyFeatureInstaller.withoutSearchUrls(urls) { value -> predicate(value) }
        if (filtered === urls) return reply
        val newContent = links.contentPlan.edit(content) { builder ->
            links.clearUrls.invoke(builder)
            links.putAllUrls.invoke(builder, filtered)
        }
        evidence(SEARCH_LINKS_CAPABILITY, FeatureRuntimeStage.APPLIED, urls.size - filtered.size)
        return links.replyPlan.edit(reply) { builder -> links.setContent.invoke(builder, newContent) }
    }

    private fun linksOf(type: Class<*>): Links? {
        replyLinks[type]?.let { return it as? Links }
        val resolved = runCatching { resolveLinks(type) }.getOrNull()
        replyLinks[type] = resolved ?: NONE
        // 否定结论会被缓存到进程结束：不留痕迹的话，一次瞬时的反射失败（或宿主换了形状）会让这一层
        // 永远静默空转，而安装器照样报"新通道 3 个"。
        if (resolved == null) logSkip("links-shape:${type.simpleName}")
        return resolved
    }

    private fun resolveLinks(type: Class<*>): Links? {
        val contentGetter = noArg(type, "getContent")?.takeIf { !it.returnType.isPrimitive } ?: return null
        val contentClass = contentGetter.returnType
        val urlsGetter = noArg(contentClass, "getUrlsMap")
            ?.takeIf { it.returnType isSubclassOf classOf<Map<*, *>>() } ?: return null
        val contentPlan = ProtobufBuilderPlan.resolve(contentClass) ?: return null
        val clearUrls = contentPlan.method("clearUrls") ?: return null
        val putAllUrls = contentPlan.method("putAllUrls", classOf<Map<*, *>>()) ?: return null
        val replyPlan = ProtobufBuilderPlan.resolve(type) ?: return null
        val setContent = replyPlan.method("setContent", contentClass) ?: return null
        return Links(contentGetter, urlsGetter, contentPlan, clearUrls, putAllUrls, replyPlan, setContent)
    }

    // —— 顶层可选字段 ——

    private class PayloadField(val capability: String, val has: Method, val clear: Method)

    private class SubjectPath(
        val has: Method,
        val getter: Method,
        val set: Method,
        val hasEmptyPage: Method,
        val controlPlan: ProtobufBuilderPlan,
        val clearEmptyPage: Method
    )

    private class TopShape(val plan: ProtobufBuilderPlan, val payloads: List<PayloadField>, val subject: SubjectPath?)

    private fun topShapeOf(type: Class<*>): TopShape? {
        topShapes[type]?.let { return it as? TopShape }
        val resolved = runCatching { resolveTop(type) }.getOrNull()
        topShapes[type] = resolved ?: NONE
        // 只开着"摘搜索跳转"时，顶层形状根本用不上（摘链接走 rewriter），解析不出形状是正常的，
        // 报出来会是一条假警报。只在顶层确实有事要做时才留痕。
        if (resolved == null && (payloads.isNotEmpty() || clearEmptyPage)) {
            logSkip("top-shape:${type.simpleName}")
        }
        return resolved
    }

    private fun resolveTop(type: Class<*>): TopShape? {
        val plan = ProtobufBuilderPlan.resolve(type) ?: return null
        // 缺失字段先收集、不立即上报：整体解析不出来时由 topShapeOf 报一次 top-shape
        // （有单测钉死"整体失败只报一次"）；只有形状成立但个别字段被丢的部分解析，
        // mapNotNull 时代才是真正的静默黑洞，这里逐字段留痕（每类只解析一次，天然有界）。
        val missing = ArrayList<String>()
        val fields = payloads.map { (name, capability) ->
            val has = noArg(type, "has$name")?.takeIf { it.returnType == classOf<Boolean>() }
            val clear = plan.method("clear$name")
            if (has == null || clear == null) {
                missing += name
                null
            } else {
                PayloadField(capability, has, clear)
            }
        }.filterNotNull()
        val subject = if (!clearEmptyPage) null else run {
            val has = noArg(type, "hasSubjectControl")?.takeIf { it.returnType == classOf<Boolean>() } ?: return@run null
            val getter = noArg(type, "getSubjectControl")?.takeIf { !it.returnType.isPrimitive } ?: return@run null
            val controlClass = getter.returnType
            val set = plan.method("setSubjectControl", controlClass) ?: return@run null
            val hasEmpty = noArg(controlClass, "hasEmptyPage")?.takeIf { it.returnType == classOf<Boolean>() } ?: return@run null
            val controlPlan = ProtobufBuilderPlan.resolve(controlClass) ?: return@run null
            val clearEmpty = controlPlan.method("clearEmptyPage") ?: return@run null
            SubjectPath(has, getter, set, hasEmpty, controlPlan, clearEmpty)
        }
        if (fields.isEmpty() && subject == null) return null
        missing.forEach { logSkip("top-payload:${type.simpleName}#$it") }
        return TopShape(plan, fields, subject)
    }

    private fun noArg(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf { !it.isStatic && it.parameterCount == 0 }

    companion object {
        const val SEARCH_LINKS_CAPABILITY = "comments_search_links_removed"
        const val EMPTY_GUIDE_CAPABILITY = "comments_empty_guide_removed"
        private val NONE = Any()

        /**
         * 请求侧：在 `MainListReq.extra`（JSON）里声明 `disable_underline=true`，与宿主
         * `search_word_disabled` 开关走到的那一步相同（见 [CommentPurifyFeatureInstaller] 的请求侧说明）。
         * 已有这个键就不覆盖；extra 不是 JSON 对象时不动。返回 null 表示不改。
         */
        internal fun withDisableUnderline(extra: String?): String? {
            val json = if (extra.isNullOrBlank()) JSONObject() else runCatching { JSONObject(extra) }.getOrNull() ?: return null
            if (json.has(DISABLE_UNDERLINE)) return null
            return json.put(DISABLE_UNDERLINE, true).toString()
        }

        const val DISABLE_UNDERLINE = "disable_underline"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.view.View
import android.view.ViewGroup
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.highcapable.betterandroid.ui.extension.view.child
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.Field
import java.util.Collections
import java.util.concurrent.ConcurrentHashMap

/** 评论净化：仅接管已由 Adapter 精确确认的 protobuf 与独立组件边界。 */
internal class CommentPurifyFeatureInstaller(
    private val removeSearchLinks: Boolean,
    private val removeEmptyGuide: Boolean,
    private val removeVoteWidgets: Boolean,
    private val removeFollowButtons: Boolean,
    private val removeQoe: Boolean,
    private val removeOperations: Boolean,
    private val blockQuickReply: Boolean = false,
    private val points: VersionAdapter.CommentPurifyPoints?
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (removeSearchLinks) add("comments_search_links_removed")
        if (removeEmptyGuide) add("comments_empty_guide_removed")
        if (removeVoteWidgets) add("comments_vote_widgets_removed")
        if (removeFollowButtons) add("comments_follow_buttons_removed")
        if (removeQoe) add("comments_qoe_removed")
        if (removeOperations) add("comments_operations_removed")
        if (blockQuickReply) add("comments_quick_reply_blocked")
    }

    private val textFields = ConcurrentHashMap<Class<*>, List<Field>>()
    private val quickReplyFields = ConcurrentHashMap<Class<*>, QuickReplyIntentFields>()

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!removeSearchLinks && !removeEmptyGuide && !removeVoteWidgets &&
            !removeFollowButtons && !removeQoe && !removeOperations && !blockQuickReply) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val compose = CommentComposePurifyBridge(removeVoteWidgets, removeFollowButtons, blockQuickReply).install(environment)
        val baseEnvironment = environment
        val environment = environment.copy(capabilityEvidence = { id, result ->
            baseEnvironment.capabilityEvidence?.invoke(id, mergeCommentLayer(result, compose[id]))
        })
        val adapted = points ?: run {
            compose.forEach { (id, result) -> baseEnvironment.capabilityEvidence?.invoke(id, result) }
            installKotlinChannel(environment)
            val active = compose.values.filterIsInstance<FeatureInstallResult.Installed>()
            return if (active.isEmpty()) missing(environment, "missing-adapter-point")
            else FeatureInstallResult.Installed(active.sumOf { it.hookCount }, complete = false)
        }

        var installedCount = compose.values.filterIsInstance<FeatureInstallResult.Installed>().sumOf { it.hookCount }
        var expectedCount = compose.values.sumOf { (it as? FeatureInstallResult.Installed)?.hookCount ?: 1 }
        val missingGroups = compose.filterValues { it !is FeatureInstallResult.Installed || !it.complete }
            .keys.map { "compose:$it" }.toMutableList()
        if (removeSearchLinks) {
            val beforeInstalled = installedCount
            val beforeExpected = expectedCount
            val beforeMissing = missingGroups.size
            expectedCount += 1
            if (installRequestSideOptOut(environment)) installedCount += 1
            else missingGroups += "search-request"
            val urlPoints = adapted.urlMapGetters
            if (urlPoints.isEmpty()) missingGroups += "search"
            expectedCount += urlPoints.size
            urlPoints.forEachIndexed { index, point ->
                runCatching {
                    environment.registrar.adapted("comment.purify.urls.$index", point) {
                        after {
                            if (KotlinMossChannel.isRaw()) return@after
                            val source = result as? Map<*, *> ?: return@after
                            environment.reportRuntimeEvidence("comments_search_links_removed", FeatureRuntimeStage.OBSERVED)
                            val filtered = withoutSearchUrls(source) { value ->
                                isSearchUrlValue(value)
                            }
                            if (filtered !== source) {
                                result = filtered
                                environment.reportRuntimeEvidence("comments_search_links_removed",
                                    FeatureRuntimeStage.APPLIED,
                                    source.size - filtered.size
                                )
                            }
                        }
                    }
                    installedCount += 1
                }.onFailure { throwable ->
                    environment.logError(
                        "comment_purify_search_$index",
                        "[BIL] 评论搜索跳转净化 Hook 注册失败(" +
                            "${point.className}#${point.methodName}): $throwable"
                    )
                }
            }
            // 第二道防线：把跳转目标字段本身置空。
            //
            // **必须与上面那道互不知情**（AGENTS 纵深防御条目）：各自 try/catch、
            // 各自计入分母、各自降级。上面摘不掉 map 条目时，这里仍然能让链接点不动；
            // 这里定位不到时，上面照常工作。两道都失败才是真的失效。
            //
            // 判据是"渲染侧读这个字段才能跳转"，31 个本地宿主逐版实测它每一版都有
            // 跨 dex 消费者，所以不是空 Hook；反过来 `getUrlsOrDefault` /
            // `getUrlsOrThrow` / `getUrlsCount` 31 版全是 0 消费者，故意不挂。
            val schemaPoints = adapted.urlSchemaGetters
            if (schemaPoints.isEmpty()) missingGroups += "search-schema"
            expectedCount += schemaPoints.size
            schemaPoints.forEachIndexed { index, point ->
                runCatching {
                    environment.registrar.adapted("comment.purify.url_schema.$index", point) {
                        after {
                            if (KotlinMossChannel.isRaw()) return@after
                            val current = result as? String ?: return@after
                            environment.reportRuntimeEvidence("comments_search_links_removed", FeatureRuntimeStage.OBSERVED)
                            if (isSearchJumpUri(current)) {
                                // 置空后的实际表现是「**照常显示、点击不跳转**」，不是不显示。
                                // 9.11.0 反汇编实证（classes4.dex）：
                                // ① `Ph.a#e(Content, ReplyControl)` 只是逐字段把 Url 拷进
                                //    `comment2.model.UrlInfo`（title/prefixIcon/appUrl/…），
                                //    建 span 时**不看** appUrl 是否为空；
                                // ② 真正的判空在点击侧 `Dh.v#e(Context, UrlInfo, …)`：
                                //    `if (appUrl == null || appUrl.length() <= 0) return;`
                                //    早退在 `BLRouter.routeTo` **之前**；
                                //    `UrlInfo.isInternalSchema()` 也对空串返回 false。
                                // 所以这道防线的降级形态是"看得见但点不动"，
                                // 而防线①（摘 map 条目）才是"关键词连带搜索小图标一起不显示"。
                                // 两者都不动 title / message，评论文字和表情照旧。
                                result = ""
                                environment.reportRuntimeEvidence("comments_search_links_removed",
                                    FeatureRuntimeStage.APPLIED)
                            }
                        }
                    }
                    installedCount += 1
                }.onFailure { throwable ->
                    environment.logError(
                        "comment_purify_search_schema_$index",
                        "[BIL] 评论搜索跳转目标净化 Hook 注册失败(" +
                            "${point.className}#${point.methodName}): $throwable"
                    )
                }
            }
            val installedPaths = installedCount - beforeInstalled
            val expectedPaths = (expectedCount - beforeExpected).coerceAtLeast(1)
            val missingUncounted = missingGroups.size > beforeMissing && installedPaths == expectedPaths
            environment.reportCapabilityCoverage(
                "comments_search_links_removed",
                installedPaths > 0 || missingGroups.size == beforeMissing,
                installedPaths, expectedPaths + if (missingUncounted) 1 else 0
            )
        }
        if (removeEmptyGuide) {
            val beforeInstalled = installedCount
            val beforeExpected = expectedCount
            val beforeMissing = missingGroups.size
            val emptyPoints = adapted.emptyPageGetters
            if (emptyPoints.isEmpty()) missingGroups += "empty-page"
            expectedCount += emptyPoints.size
            emptyPoints.forEachIndexed { index, point ->
                runCatching {
                    val defaultGetter = environment.hookPoints.resolveAdapted(
                        "comment.purify.empty.default.$index",
                        point.defaultInstanceGetter.className,
                        point.defaultInstanceGetter.methodName,
                        point.defaultInstanceGetter.paramClassNames
                    ) ?: error("missing-default-instance-getter")
                    val defaultInstance = defaultGetter.invoke(null)
                        ?: error("null-default-instance")
                    environment.registrar.adapted(
                        "comment.purify.empty.content.$index",
                        point.contentGetter
                    ) {
                        after {
                            if (KotlinMossChannel.isRaw()) return@after
                            environment.reportRuntimeEvidence("comments_empty_guide_removed", FeatureRuntimeStage.OBSERVED)
                            if (result !== defaultInstance) {
                                result = defaultInstance
                                environment.reportRuntimeEvidence("comments_empty_guide_removed", FeatureRuntimeStage.APPLIED)
                            }
                        }
                    }
                    installedCount += 1
                }.onFailure { throwable ->
                    environment.logError(
                        "comment_purify_empty_$index",
                        "[BIL] 空评论区引导净化 Hook 注册失败(" +
                            "${point.contentGetter.className}#" +
                            "${point.contentGetter.methodName}): $throwable"
                    )
                }
            }
            val installedPaths = installedCount - beforeInstalled
            val expectedPaths = (expectedCount - beforeExpected).coerceAtLeast(1)
            val missingUncounted = missingGroups.size > beforeMissing && installedPaths == expectedPaths
            environment.reportCapabilityCoverage(
                "comments_empty_guide_removed",
                installedPaths > 0 || missingGroups.size == beforeMissing,
                installedPaths, expectedPaths + if (missingUncounted) 1 else 0
            )
        }
        if (removeVoteWidgets) {
            val beforeInstalled = installedCount
            val beforeExpected = expectedCount
            val beforeMissing = missingGroups.size
            val votePoints = adapted.voteWidgetMethods
            if (votePoints.isEmpty()) missingGroups += "vote"
            expectedCount += votePoints.size
            votePoints.forEachIndexed { index, point ->
                runCatching {
                    environment.registrar.adapted("comment.purify.vote.$index", point) {
                        after {
                            val target = instance as? View ?: return@after
                            environment.reportRuntimeEvidence("comments_vote_widgets_removed", FeatureRuntimeStage.OBSERVED)
                            if (target.visibility != View.GONE) {
                                target.visibility = View.GONE
                                environment.reportRuntimeEvidence("comments_vote_widgets_removed", FeatureRuntimeStage.APPLIED)
                            }
                        }
                    }
                    installedCount += 1
                }.onFailure { throwable ->
                    environment.logError(
                        "comment_purify_vote_$index",
                        "[BIL] 评论投票组件净化 Hook 注册失败(" +
                            "${point.className}#${point.methodName}): $throwable"
                    )
                }
            }
            val installedPaths = installedCount - beforeInstalled
            val expectedPaths = (expectedCount - beforeExpected).coerceAtLeast(1)
            val missingUncounted = missingGroups.size > beforeMissing && installedPaths == expectedPaths
            environment.reportCapabilityCoverage(
                "comments_vote_widgets_removed",
                installedPaths > 0 || missingGroups.size == beforeMissing,
                installedPaths, expectedPaths + if (missingUncounted) 1 else 0
            )
        }
        if (removeFollowButtons) {
            val beforeInstalled = installedCount
            val beforeExpected = expectedCount
            val beforeMissing = missingGroups.size
            val followPoints = adapted.follow
            if (followPoints == null) {
                missingGroups += "follow"
            } else {
                val widgetPoints = followPoints.widgetStateMethods
                if (widgetPoints.isEmpty()) missingGroups += "follow-widget"
                expectedCount += widgetPoints.size
                widgetPoints.forEachIndexed { index, point ->
                    runCatching {
                        val outerField = point.viewField?.let { fieldName ->
                            environment.hookPoints.resolveField(
                                "comment.purify.follow.outer.$index",
                                point.className,
                                fieldName
                            ) ?: error("missing-follow-outer-field")
                        }
                        environment.registrar.adapted(
                            "comment.purify.follow.widget.$index",
                            point
                        ) {
                            after {
                                val target = if (outerField == null) {
                                    instance
                                } else {
                                    runCatching { outerField.get(instance) }.getOrNull()
                                }
                                val view = target as? View ?: return@after
                                environment.reportRuntimeEvidence("comments_follow_buttons_removed", FeatureRuntimeStage.OBSERVED)
                                if (view.visibility != View.GONE) {
                                    view.visibility = View.GONE
                                    environment.reportRuntimeEvidence("comments_follow_buttons_removed",
                                        FeatureRuntimeStage.APPLIED
                                    )
                                }
                            }
                        }
                        installedCount += 1
                    }.onFailure { throwable ->
                        environment.logError(
                            "comment_purify_follow_widget_$index",
                            "[BIL] 评论独立关注控件 Hook 注册失败(" +
                                "${point.className}#${point.methodName}): $throwable"
                        )
                    }
                }

                val headerPoints = followPoints.headerBindMethods
                if (headerPoints.isNotEmpty()) {
                    val buttonClassName = followPoints.followButtonClassName
                    val followButtonClass = buttonClassName?.let { className ->
                        environment.hookPoints.resolveClass(
                            "comment.purify.follow.button_class",
                            className
                        )
                    }
                    if (followButtonClass == null) {
                        missingGroups += "follow-header-button"
                    } else {
                        expectedCount += headerPoints.size
                        headerPoints.forEachIndexed { index, point ->
                            runCatching {
                                environment.registrar.adapted(
                                    "comment.purify.follow.header.$index",
                                    point
                                ) {
                                    after {
                                        val root = instance as? ViewGroup ?: return@after
                                        environment.reportRuntimeEvidence("comments_follow_buttons_removed",
                                            FeatureRuntimeStage.OBSERVED
                                        )
                                        val hidden = hideTypedChildren(root, followButtonClass)
                                        environment.reportRuntimeEvidence("comments_follow_buttons_removed",
                                            FeatureRuntimeStage.APPLIED,
                                            hidden
                                        )
                                    }
                                }
                                installedCount += 1
                            }.onFailure { throwable ->
                                environment.logError(
                                    "comment_purify_follow_header_$index",
                                    "[BIL] 评论头部关注按钮 Hook 注册失败(" +
                                        "${point.className}#${point.methodName}): $throwable"
                                )
                            }
                        }
                    }
                }
            }
            val installedPaths = installedCount - beforeInstalled
            val expectedPaths = (expectedCount - beforeExpected).coerceAtLeast(1)
            val missingUncounted = missingGroups.size > beforeMissing && installedPaths == expectedPaths
            environment.reportCapabilityCoverage(
                "comments_follow_buttons_removed",
                installedPaths > 0 || missingGroups.size == beforeMissing,
                installedPaths, expectedPaths + if (missingUncounted) 1 else 0
            )
        }
        if (removeQoe) {
            val beforeInstalled = installedCount
            val beforeExpected = expectedCount
            val beforeMissing = missingGroups.size
            val qoePoint = adapted.qoe
            if (qoePoint == null) {
                missingGroups += "qoe"
            } else {
                expectedCount += 2
                val installed = installAbsentPayload(
                    environment.forCapabilityRuntime("comments_qoe_removed"),
                    "qoe",
                    "评论反馈",
                    qoePoint
                )
                installedCount += installed
                if (installed != 2) missingGroups += "qoe-read-boundary"
            }
            val installedPaths = installedCount - beforeInstalled
            val expectedPaths = (expectedCount - beforeExpected).coerceAtLeast(1)
            val missingUncounted = missingGroups.size > beforeMissing && installedPaths == expectedPaths
            environment.reportCapabilityCoverage(
                "comments_qoe_removed",
                installedPaths > 0 || missingGroups.size == beforeMissing,
                installedPaths, expectedPaths + if (missingUncounted) 1 else 0
            )
        }
        if (removeOperations) {
            val beforeInstalled = installedCount
            val beforeExpected = expectedCount
            val beforeMissing = missingGroups.size
            val operationPoints = adapted.operations
            expectedCount += 4
            var operationInstalled = 0
            operationPoints.forEachIndexed { index, point ->
                operationInstalled += installAbsentPayload(
                    environment.forCapabilityRuntime("comments_operations_removed"),
                    "operation.$index",
                    "评论运营推广",
                    point
                )
            }
            installedCount += operationInstalled
            if (operationPoints.size != 2 || operationInstalled != 4) {
                missingGroups += "operation-read-boundary"
            }
            val installedPaths = installedCount - beforeInstalled
            val expectedPaths = (expectedCount - beforeExpected).coerceAtLeast(1)
            val missingUncounted = missingGroups.size > beforeMissing && installedPaths == expectedPaths
            environment.reportCapabilityCoverage(
                "comments_operations_removed",
                installedPaths > 0 || missingGroups.size == beforeMissing,
                installedPaths, expectedPaths + if (missingUncounted) 1 else 0
            )
        }
        if (blockQuickReply) {
            val beforeInstalled = installedCount
            val beforeExpected = expectedCount
            val beforeMissing = missingGroups.size
            val quickReplyPoints = adapted.quickReplyDialogMethods
            if (quickReplyPoints.isEmpty()) missingGroups += "quick-reply"
            expectedCount += quickReplyPoints.size
            quickReplyPoints.forEachIndexed { index, point ->
                runCatching {
                    environment.registrar.adapted("comment.purify.quick_reply.$index", point) {
                        before {
                            val intent = args.firstOrNull() ?: return@before
                            environment.reportRuntimeEvidence("comments_quick_reply_blocked", FeatureRuntimeStage.OBSERVED)
                            if (shouldBlockQuickReply(intent)) {
                                result = Unit
                                environment.reportRuntimeEvidence("comments_quick_reply_blocked", FeatureRuntimeStage.APPLIED)
                            }
                        }
                    }
                    installedCount += 1
                }.onFailure { throwable ->
                    environment.logError(
                        "comment_purify_quick_reply_$index",
                        "[BIL] 评论快速回复 Hook 注册失败(" +
                            "${point.className}#${point.methodName}): $throwable"
                    )
                }
            }
            val installedPaths = installedCount - beforeInstalled
            val expectedPaths = (expectedCount - beforeExpected).coerceAtLeast(1)
            val missingUncounted = missingGroups.size > beforeMissing && installedPaths == expectedPaths
            environment.reportCapabilityCoverage(
                "comments_quick_reply_blocked",
                installedPaths > 0 || missingGroups.size == beforeMissing,
                installedPaths, expectedPaths + if (missingUncounted) 1 else 0
            )
        }

        // KMP 评论页走 Kotlin KReplyMoss：协议层子项在那条通道上再做一遍；兜底通道不计入覆盖单位，
        // Java 边界一个都装不上时也照装。
        installKotlinChannel(environment)
        if (installedCount == 0) return missing(environment, "registration-failed")
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        val status = if (missingGroups.isEmpty() && installedCount == expectedCount) {
            "success"
        } else {
            "partial:$installedCount/$expectedCount" +
                missingGroups.takeIf { it.isNotEmpty() }
                    ?.joinToString(prefix = ";missing=", separator = ",")
                    .orEmpty()
        }
        environment.reportStatus(CHANNEL_STATUS, status)
        if (status != "success") {
            environment.logError(
                "comment_purify_partial",
                "[BIL] 评论净化部分安装，status=$status"
            )
        } else {
            environment.logInfo(
                "comment_purify_ok",
                "[BIL] 评论净化已安装，hooks=$installedCount"
            )
        }
        return FeatureInstallResult.Installed(installedCount, complete = missingGroups.isEmpty() && installedCount == expectedCount)
    }

    internal fun isSearchUrlValue(value: Any?): Boolean {
        value ?: return false
        val fields = textFields.getOrPut(value.javaClass) {
            KavaMemberLookup.declaredFields(value.javaClass, makeAccessible = true) {
                it.type isSubclassOf classOf<CharSequence>()
            }
        }
        return fields.any { field ->
            runCatching { field.get(value) as? CharSequence }
                .getOrNull()
                ?.let { isSearchJumpUri(it) } == true
        }
    }

    private fun shouldBlockQuickReply(intent: Any): Boolean {
        val fields = quickReplyFields.getOrPut(intent.javaClass) {
            val declared = KavaMemberLookup.declaredFields(
                intent.javaClass,
                makeAccessible = true
            ) { field -> !field.isStatic }
            val booleans = declared.filter { it.type == classOf<Boolean>() }
            QuickReplyIntentFields(
                isReply = booleans.getOrNull(1),
                position = declared.firstOrNull { field ->
                    field.type.isEnum && field.type.simpleName == "Pos"
                }
            )
        }
        val isReply = fields.isReply?.let { field ->
            runCatching { field.getBoolean(intent) }.getOrDefault(false)
        } ?: false
        val position = fields.position?.let { field ->
            runCatching { field.get(intent)?.toString().orEmpty() }.getOrDefault("")
        }.orEmpty()
        return shouldBlockQuickReply(isReply, position)
    }

    /**
     * Kotlin 新通道（KMP 评论页的 `KReplyMoss.mainList/detailList/dialogList`）：见 [CommentKotlinPurifier]。
     * 搜索跳转开着时，`mainList` 的请求也往返一次，在 `extra` 里声明 `disable_underline=true`（第 0 道防线）。
     */
    private fun installKotlinChannel(environment: HookEnvironment) {
        if (!removeSearchLinks && !removeEmptyGuide && !removeQoe && !removeOperations) return
        // 装不上要留下原因（有界：四条）；否则末尾那句"N 个"读起来像"不适用"，而不是"类没找到"。
        fun skip(reason: String) {
            environment.logInfo("comment_purify_kmoss_skip", "[BIL] 评论净化新通道未接入: $reason")
        }
        val loader = environment.classLoader ?: return skip("no-class-loader")
        val replyInfoClass = KavaMemberLookup.classOrNull(loader, "$REPLY_PACKAGE.ReplyInfo")
            ?: return skip("no-reply-info")
        val members = KotlinMossChannel.prepare(environment, loader, "评论净化", KMOSS_LOG_KEY) ?: return skip("no-bridge")
        val payloads = buildMap {
            if (removeQoe) put("Qoe", "comments_qoe_removed")
            if (removeOperations) {
                put("Operation", "comments_operations_removed")
                put("OperationV2", "comments_operations_removed")
            }
        }
        val purifier = CommentKotlinPurifier(
            replyInfoClass,
            isSearchUrl = if (removeSearchLinks) ::isSearchUrlValue else null,
            clearEmptyPage = removeEmptyGuide,
            payloads = payloads,
            // 每个类只解析一次，所以这里天然有界；形状解析不出来时净化是空转，必须留痕。
            logSkip = { reason ->
                environment.logInfo("comment_purify_kmoss_shape", "[BIL] 评论净化新通道：读不到 $reason，对应子项不生效")
            }
        ) { capability, stage, count -> environment.reportRuntimeEvidence(capability, stage, count) }
        val mainListReq = KavaMemberLookup.classOrNull(loader, "$REPLY_PACKAGE.MainListReq")
        // 请求侧那道防线读不到也要说一声，否则"搜索跳转已关"看上去是生效了的。
        if (mainListReq == null && removeSearchLinks) skip("no-main-list-request")
        val requestPlan = mainListReq?.takeIf { removeSearchLinks }?.let(ProtobufBuilderPlan::resolve)
        val getExtra = mainListReq?.let { KavaMemberLookup.methodOrNull(it, "getExtra") }
            ?.takeIf { it.returnType == classOf<String>() }
        val setExtra = requestPlan?.method("setExtra", classOf<String>())
        val requestTransform: ((Any) -> Any)? =
            if (requestPlan != null && getExtra != null && setExtra != null) {
                fun(request: Any): Any {
                    val extra = KotlinMossChannel.raw { getExtra.invoke(request) as? String }
                    val updated = CommentKotlinPurifier.withDisableUnderline(extra) ?: return request
                    return requestPlan.edit(request) { builder -> setExtra.invoke(builder, updated) }
                }
            } else {
                null
            }
        var hooks = 0
        KMOSS_RPCS.forEach { (rpc, replyName) ->
            val replyClass = KavaMemberLookup.classOrNull(loader, "$REPLY_PACKAGE.$replyName")
                ?: return@forEach skip("no-reply-class:$rpc")
            val rewriteRequest = rpc == "mainList" && requestTransform != null
            val installed = KotlinMossChannel.install(
                environment, loader, members,
                javaMossClassName = "$REPLY_PACKAGE.ReplyMoss",
                rpc = rpc,
                javaReplyClass = replyClass,
                hookId = "comment.purify.kmoss.$rpc",
                what = "评论净化",
                logKey = KMOSS_LOG_KEY,
                javaRequestClass = mainListReq?.takeIf { rewriteRequest },
                transformRequest = requestTransform?.takeIf { rewriteRequest },
                shareUnchangedReply = true
            ) { javaReply -> purifier.purify(javaReply) }
            if (installed) hooks += 1
        }
        environment.logInfo("comment_purify_kmoss", "[BIL] 评论净化：Kotlin 新通道 $hooks 个")
    }

    /** 成对替换 protobuf 的 has/get 公开读取结果；默认实例只在安装期解析一次。 */
    private fun installAbsentPayload(
        environment: HookEnvironment,
        groupId: String,
        displayName: String,
        point: VersionAdapter.CommentOptionalPayloadPoint
    ): Int {
        val defaultInstance = runCatching {
            val defaultGetter = environment.hookPoints.resolveAdapted(
                "comment.purify.$groupId.default",
                point.defaultInstanceGetter.className,
                point.defaultInstanceGetter.methodName,
                point.defaultInstanceGetter.paramClassNames
            ) ?: error("missing-default-instance-getter")
            defaultGetter.invoke(null) ?: error("null-default-instance")
        }.onFailure { throwable ->
            environment.logError(
                "comment_purify_${groupId.replace('.', '_')}_default",
                "[BIL] $displayName 默认实例解析失败: $throwable"
            )
        }.getOrNull() ?: return 0

        var installed = 0
        runCatching {
            environment.registrar.adapted(
                "comment.purify.$groupId.presence",
                point.presenceGetter
            ) {
                after {
                    if (KotlinMossChannel.isRaw()) return@after
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    if (result != false) {
                        result = false
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                    }
                }
            }
            installed += 1
        }.onFailure { throwable ->
            environment.logError(
                "comment_purify_${groupId.replace('.', '_')}_presence",
                "[BIL] $displayName presence Hook 注册失败: $throwable"
            )
        }
        runCatching {
            environment.registrar.adapted(
                "comment.purify.$groupId.content",
                point.contentGetter
            ) {
                after {
                    if (KotlinMossChannel.isRaw()) return@after
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    if (result !== defaultInstance) {
                        result = defaultInstance
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                    }
                }
            }
            installed += 1
        }.onFailure { throwable ->
            environment.logError(
                "comment_purify_${groupId.replace('.', '_')}_content",
                "[BIL] $displayName content Hook 注册失败: $throwable"
            )
        }
        return installed
    }


    /**
     * 第 0 道防线：走宿主自己的开关，**让服务端一开始就不下发**。
     *
     * 2026-09-15 反汇编把整条链追通了（9.11.0）：
     * ```
     * CommentViewModel.<init>(Bundle)
     *   Bundle["search_word_disabled"] → toBooleanStrictOrNull
     *     → RemoteContentFilter(searchWordDisabled, weSearchDisabled, filterTagDisabled)
     *       → 评论状态 bl.m.f
     *         → 构建 MainListReq.extra 的那份 JSON：
     *              if (searchWordDisabled) put("disable_underline", true)
     *           → 随请求发出（extra 里同时有 spmid/from_spmid/track_id，与抓包逐字段对得上）
     * ```
     * 名字也对得上：评论里的搜索关键词就是带下划线渲染的（`Url.underline` 是字段 11）。
     * 宿主自己在用这个开关——会员购商品详情页 `com.mall.ui.page.detail.t#run()`
     * 就往 `CommentV3Fragment` 的参数里塞 `search_word_disabled`。
     *
     * 类名未混淆、31 个本地宿主（8.84.0–9.12.0）逐版实测**类与键都零缺失**，
     * 所以按名解析（与 `LegacyFeedbackPanel` 同一套做法），不接 VersionAdapter。
     *
     * **只在 Bundle 里没有这个键时才写**：宿主自己已经设过（会员购那类页面）就不覆盖，
     * 也不去动 `we_search_disabled` / `filter_tag_disabled`——那是另外两件事。
     */
    private fun installRequestSideOptOut(environment: HookEnvironment): Boolean = runCatching {
        val owner = KavaMemberLookup.classOrNull(
            environment.classLoader, COMMENT_VIEW_MODEL_CLASS
        ) ?: error("missing-comment-view-model")
        val constructor = KavaMemberLookup.declaredConstructors(owner) {
            it.parameterTypes.contentEquals(arrayOf(classOf<android.os.Bundle>()))
        }.singleOrNull() ?: error("ambiguous-or-missing-bundle-constructor")
        environment.registrar.constructor("comment.purify.search.request", constructor) {
            before {
                val bundle = args.firstOrNull() as? android.os.Bundle ?: return@before
                environment.reportRuntimeEvidence("comments_search_links_removed", FeatureRuntimeStage.OBSERVED)
                if (bundle.containsKey(SEARCH_WORD_DISABLED_KEY)) return@before
                bundle.putString(SEARCH_WORD_DISABLED_KEY, "true")
                environment.reportRuntimeEvidence("comments_search_links_removed", FeatureRuntimeStage.APPLIED)
                environment.logInfo(
                    "comment_purify_search_request",
                    "[BIL] 评论请求已声明 $SEARCH_WORD_DISABLED_KEY=true"
                )
            }
        }
        true
    }.onFailure { throwable ->
        environment.logError(
            "comment_purify_search_request_missing",
            "[BIL] 评论搜索链接请求侧开关不可用，退回响应侧两道防线: $throwable"
        )
    }.getOrDefault(false)

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "comment_purify_missing",
            "[BIL] 评论净化适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "comment_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "comment_purify_status"

        /** 未混淆；31 个本地宿主（8.84.0–9.12.0）逐版实测零缺失。 */
        internal const val COMMENT_VIEW_MODEL_CLASS =
            "com.bilibili.app.comment3.viewmodel.CommentViewModel"

        /** 宿主自己的启动参数键；同上，31 版零缺失。值按 `toBooleanStrictOrNull` 解析。 */
        internal const val SEARCH_WORD_DISABLED_KEY = "search_word_disabled"
        private const val REPLY_PACKAGE = "com.bapis.bilibili.main.community.reply.v1"
        private const val KMOSS_LOG_KEY = "comment_purify_kmoss"
        /** Kotlin 新通道：RPC → 同一 proto 的 Java 响应类简单名（与 `ReplyMoss` 同包）。 */
        private val KMOSS_RPCS = listOf(
            "mainList" to "MainListReply",
            "detailList" to "DetailListReply",
            "dialogList" to "DialogListReply"
        )

        /**
         * 一次会话里最多记几条"服务端到底还发不发"的观测。
         *
         * 这条日志是**判据不是装饰**：请求侧开关开着时，如果 map 仍然带搜索条目，
         * 说明服务端没吃这个 flag、真正生效的是响应侧那两道；如果 map 恒为空，
         * 才是"服务端不下发"。有界，记满彻底静默。
         */
        // 2026-09-15 曾在这里放过一条"服务端到底还发不发 urls"的取样探针，
        // 第 0 道防线实证通过后已移除：它在每条评论的映射路径上都要做一次
        // AtomicInteger 自增，属于纯诊断开销。退化仍然看得见——`getUrlsMap`
        // 那道钩子本来就按 capability 上报 OBSERVED/APPLIED，服务端要是重新下发
        // 搜索链接，第 1 道会开始报 APPLIED 且带删除条数。取样口径的两条教训
        // 记在 AGENTS 与长期文档 2026-09-15（三）里，别照着第一版重写。

        /**
         * 「这是不是一条跳搜索的链接」——**全仓唯一一份判据**。
         *
         * 直接复用 [DetailUnitedPresentationPurifyPolicy.isSearchJumpLabelUri]（scheme=bilibili
         * ＋ host=search），不再自己留一个 `startsWith("bilibili://search")`：
         * 前缀写法会把 `bilibili://searchxyz` 这种误判成命中，也接不住
         * `bilibili://search/` 这类写法；更重要的是档案红线——同一类判据不许存两份，
         * 复制出来的那份迟早和主份漂移。
         *
         * **不按 `from=appcommentline_search` 这个更精确的标记判**：那是"一个词一个开关"，
         * 宿主换个 from 值就静默失效；类别判据（跳搜索）才是稳的。
         */
        internal fun isSearchJumpUri(value: CharSequence?): Boolean =
            DetailUnitedPresentationPurifyPolicy.isSearchJumpLabelUri(value?.toString())

        /** 只遍历已适配的头部装饰小容器，保留其它徽章、图片与长按监听。 */
        internal fun hideTypedChildren(root: ViewGroup, targetClass: Class<*>): Int {
            var hidden = 0
            for (index in 0 until root.childCount) {
                val child = root.child(index)
                if (targetClass.isInstance(child)) {
                    if (child.visibility != View.GONE) {
                        child.visibility = View.GONE
                        hidden += 1
                    }
                }
                if (child is ViewGroup) hidden += hideTypedChildren(child, targetClass)
            }
            return hidden
        }

        /** 无命中时返回原 Map；命中时返回保持顺序的不可变副本，不修改 protobuf 原数据。 */
        internal fun <K, V> withoutSearchUrls(
            source: Map<K, V>,
            isSearchUrl: (V) -> Boolean
        ): Map<K, V> {
            var filtered: LinkedHashMap<K, V>? = null
            source.forEach { (key, value) ->
                if (isSearchUrl(value)) {
                    val target = filtered ?: LinkedHashMap(source).also { filtered = it }
                    target.remove(key)
                }
            }
            return filtered?.let(Collections::unmodifiableMap) ?: source
        }

        /** 只屏蔽评论卡片/正文短按；显式回复按钮、输入栏和三点菜单必须继续工作。 */
        internal fun shouldBlockQuickReply(isReply: Boolean, positionName: String): Boolean {
            if (!isReply) return false
            val position = positionName.uppercase()
            if (position.isBlank()) return true
            return when {
                "REPLY_BUTTON" in position -> false
                "MORE_MENU" in position -> false
                "BAR" in position -> false
                "INPUT" in position -> false
                "CARD" in position -> true
                "ITEM" in position -> true
                "TEXT" in position -> true
                "REPLY" in position -> true
                else -> true
            }
        }
    }

    private data class QuickReplyIntentFields(
        val isReply: Field?,
        val position: Field?
    )
}

