package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.content.Context
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isAbstract
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import com.highcapable.kavaref.extension.makeAccessible
import java.lang.reflect.Field
import java.lang.reflect.Method
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean

/**
 * 隐藏视频详细页播放器下方的话题、活动等推广卡片。
 *
 * 宿主的 [IAdUnderPlayer] 为接口，真正实现类由广告 SDK 在运行时返回。本安装器挂住
 * GAdBizKt#getGAdVideoDetail 后会立即解析当前 getUnderPlayer 实现并安装三条渲染路由；同时
 * 保留 getter 兜底，以兼容运行中替换实现类的宿主版本。只缓存进程生命周期内稳定的
 * Class/Member 注册状态，不缓存广告对象、Activity、Context 或 View。
 */
internal class DetailAppPromotionFeatureInstaller(
    private val enabled: Boolean,
    private val relateAdEnabled: Boolean = enabled
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (enabled) {
            add("detail_promotion_nest")
            add("detail_promotion_list")
            add("detail_promotion_hd")
        }
        if (relateAdEnabled) {
            add("detail_promotion_related_ad")
            add("detail_promotion_related_game")
        }
    }

    private val attemptedVideoDetailClasses = ConcurrentHashMap.newKeySet<Class<*>>()
    private val attemptedUnderPlayerClasses = ConcurrentHashMap.newKeySet<Class<*>>()
    private val attemptedRelateVideoDetailClasses = ConcurrentHashMap.newKeySet<Class<*>>()
    private val attemptedRelateClasses = ConcurrentHashMap.newKeySet<Class<*>>()
    private val underPlayerGetters = ConcurrentHashMap<Class<*>, Method>()
    private val relateGetters = ConcurrentHashMap<Class<*>, Method>()
    private val facadeHitLogged = AtomicBoolean(false)
    private val hitLogged = AtomicBoolean(false)
    private val relateHitLogged = AtomicBoolean(false)
    private val renderReady = AtomicBoolean(false)
    private val relateRenderReady = AtomicBoolean(false)

    @Volatile
    private var underPlayerRouteSummary: String? = null

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled && !relateAdEnabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }

        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val videoDetailClass = KavaMemberLookup.classOrNull(loader, G_AD_VIDEO_DETAIL)
            ?: return missing(environment, "missing-video-detail-type")
        val types = if (enabled) resolveHostTypes(environment) else null
        val sceneAccess = types?.let(::resolveSceneAccess)
        val relateClass = if (relateAdEnabled) {
            KavaMemberLookup.classOrNull(loader, I_AD_VIDEO_RELATE)
        } else {
            null
        }
        val underPlayerAvailable = enabled && types != null && sceneAccess != null
        val relateAvailable = relateAdEnabled && relateClass != null
        if (enabled && !underPlayerAvailable) {
            listOf("detail_promotion_nest","detail_promotion_list","detail_promotion_hd").forEach {
                environment.reportCapability(it, FeatureInstallResult.Skipped("missing-under-player-dependency"))
            }
        }
        if (relateAdEnabled && !relateAvailable) {
            environment.reportCapability("detail_promotion_related_ad", FeatureInstallResult.Skipped("missing-related-ad-dependency"))
        }
        if (!underPlayerAvailable && !relateAvailable) {
            return missing(environment, "missing-enabled-route")
        }
        if (enabled && !underPlayerAvailable) {
            environment.logError(
                "detail_app_promotion_under_player_dependencies",
                "[BIL] 播放器下方推广依赖不完整，广告推荐渲染拦截仍继续安装"
            )
        }
        if (relateAdEnabled && !relateAvailable) {
            environment.logError(
                "detail_app_promotion_relate_dependencies",
                "[BIL] 广告推荐接口未定位，播放器下方推广拦截仍继续安装"
            )
        }
        val facade = KavaMemberLookup.classOrNull(loader, G_AD_BIZ_FACADE)
            ?: return missing(environment, "missing-ad-biz-facade")
        val videoDetailGetter = KavaMemberLookup.declaredMethods(
            facade,
            makeAccessible = true
        ) {
            it.name == GET_VIDEO_DETAIL && it.parameterCount == 0 &&
                it.isStatic &&
                (it.returnType isSubclassOf videoDetailClass)
        }.singleOrNull() ?: return missing(environment, "ambiguous-video-detail-getter")

        return runCatching {
            environment.registrar.exact(
                "detail_app_promotion.video_detail",
                videoDetailGetter.declaringClass,
                videoDetailGetter.name,
                *videoDetailGetter.parameterTypes
            ) {
                after {
                    val videoDetail = result ?: return@after
                    if (!videoDetailClass.isInstance(videoDetail)) return@after
                    if (facadeHitLogged.compareAndSet(false, true)) {
                        environment.reportStatus(CHANNEL_STATUS, "resolved:video-detail")
                        environment.logInfo(
                            "detail_app_promotion_facade_hit",
                            "[BIL] 视频详细页广告门面已命中，开始解析已启用渲染路径"
                        )
                    }
                    if (underPlayerAvailable) {
                        resolveCurrentUnderPlayer(
                            environment = environment,
                            videoDetail = videoDetail,
                            types = requireNotNull(types),
                            sceneAccess = requireNotNull(sceneAccess)
                        )
                    }
                    if (relateAvailable) {
                        resolveCurrentRelate(
                            environment = environment,
                            videoDetail = videoDetail,
                            relateClass = requireNotNull(relateClass)
                        )
                    }
                }
            }
            environment.postToMain?.invoke {
                if ((underPlayerAvailable && !renderReady.get()) ||
                    (relateAvailable && !relateRenderReady.get())
                ) {
                    runCatching {
                        findInitializedVideoDetail(
                            facade = facade,
                            videoDetailClass = videoDetailClass
                        )
                    }
                        .onSuccess { videoDetail ->
                            if (videoDetail != null) {
                                if (underPlayerAvailable) {
                                    resolveCurrentUnderPlayer(
                                        environment = environment,
                                        videoDetail = videoDetail,
                                        types = requireNotNull(types),
                                        sceneAccess = requireNotNull(sceneAccess)
                                    )
                                }
                                if (relateAvailable) {
                                    resolveCurrentRelate(
                                        environment = environment,
                                        videoDetail = videoDetail,
                                        relateClass = requireNotNull(relateClass)
                                    )
                                }
                            }
                        }
                        .onFailure { throwable ->
                            environment.logError(
                                "detail_app_promotion_warmup",
                                "[BIL] 视频详细页话题推广已初始化实例扫描失败，保留门面惰性兜底: $throwable"
                            )
                        }
                }
            }
            environment.reportStatus(CHANNEL_STATUS, "armed:facade")
            environment.logInfo(
                "detail_app_promotion_armed",
                "[BIL] 视频详细页广告门面拦截器已就绪" +
                    "(underPlayer=$underPlayerAvailable,relate=$relateAvailable)"
            )
            val componentHooks = if (relateAdEnabled) {
                installRelateGameComponentBlock(environment.forCapabilityRuntime("detail_promotion_related_game")).also {
                    environment.reportCapabilityCoverage("detail_promotion_related_game", true, it, 2)
                }
            } else {
                0
            }
            FeatureInstallResult.Installed(1 + componentHooks)
        }.getOrElse { throwable ->
            environment.logError(
                "detail_app_promotion_install",
                "[BIL] 视频详细页话题推广入口注册失败: $throwable"
            )
            environment.reportStatus(CHANNEL_STATUS, "failed:entry")
            FeatureInstallResult.Skipped("entry-registration-failed")
        }
    }

    /**
     * 只读取已完成初始化的 Kotlin Lazy，绝不因适配而提前创建宿主广告服务。
     */
    private fun findInitializedVideoDetail(
        facade: Class<*>,
        videoDetailClass: Class<*>
    ): Any? {
        val lazyCandidates = KavaMemberLookup.fields(
            declaringClass = facade,
            includeSuperclasses = false,
            makeAccessible = true
        ) { field ->
            field.isStatic && field.type == classOf<Lazy<*>>()
        }.mapNotNull { field ->
            field.get(null) as? Lazy<*>
        }
        return initializedLazyValueOfType(lazyCandidates, videoDetailClass)
    }

    private fun installRelateGameComponentBlock(environment: HookEnvironment): Int {
        // 每个解析缺口都要留痕：父层照常上报 ready:relate，只有这里的日志能说明
        // "游戏卡兜底为什么一个都没装"。同文件其余降级路径都有 logError，口径一致。
        fun missing(reason: String): Int {
            environment.logError(
                "detail_promotion_game_missing",
                "[BIL] 详情页游戏推荐组件兜底未安装: $reason"
            )
            return 0
        }
        val loader = environment.classLoader ?: return missing("no-class-loader")
        val viewBindingClass = KavaMemberLookup.classOrNull(loader, ANDROIDX_VIEW_BINDING)
            ?: return missing("no-view-binding")
        val baseComponent = GEMINI_BINDING_COMPONENT_CLASSES.firstNotNullOfOrNull { className ->
            KavaMemberLookup.classOrNull(loader, className)?.takeIf { candidate ->
                // 接口的 isAbstract 同样为 true；gemini 包里的 UIComponent 正是接口，
                // 必须显式排除，否则字母表候选会把它当成基类。
                candidate.isAbstract && !candidate.isInterface &&
                    KavaMemberLookup.methods(
                        candidate,
                        includeSuperclasses = true,
                        makeAccessible = true
                    ) { it.name == CREATE_VIEW_ENTRY && it.parameterCount == 2 }.isNotEmpty() &&
                    KavaMemberLookup.methods(
                        candidate,
                        includeSuperclasses = true,
                        makeAccessible = true
                    ) { it.name == BIND_TO_VIEW && it.parameterCount == 2 }.isNotEmpty()
            }
        } ?: return missing("no-gemini-base-component")
        val gameComponent = RELATE_GAME_COMPONENT_CLASSES.mapNotNull { className ->
            KavaMemberLookup.classOrNull(loader, className)?.takeIf { candidate ->
                candidate isSubclassOf baseComponent &&
                    !candidate.isInterface &&
                    !candidate.isAbstract &&
                    KavaMemberLookup.declaredMethods(candidate, makeAccessible = true) { method ->
                        method.parameterTypes.contentEquals(
                            arrayOf(
                                classOf<Context>(),
                                classOf<LayoutInflater>(),
                                classOf<ViewGroup>()
                            )
                        ) && method.returnType isSubclassOf viewBindingClass
                    }.isNotEmpty() &&
                    KavaMemberLookup.declaredMethods(candidate, makeAccessible = true) { method ->
                        method.parameterCount == 2 &&
                            method.parameterTypes[0] isSubclassOf viewBindingClass &&
                            method.parameterTypes[1].name == KOTLIN_CONTINUATION
                    }.isNotEmpty()
            }
        }.distinctBy { it.name }.singleOrNull() ?: return missing("missing-or-ambiguous-game-component")
        val simpleViewEntry = KavaMemberLookup.classOrNull(loader, GEMINI_SIMPLE_VIEW_ENTRY)
            ?: return missing("no-simple-view-entry")
        val simpleViewEntryConstructor = simpleViewEntry.declaredConstructors
            .filter { it.parameterTypes.contentEquals(arrayOf(classOf<View>())) }
            .singleOrNull()
            ?.apply { makeAccessible() }
            ?: return missing("no-simple-view-constructor")
        val createViewEntry = KavaMemberLookup.methods(
            baseComponent,
            includeSuperclasses = true,
            makeAccessible = true
        ) { method ->
            method.name == CREATE_VIEW_ENTRY && method.parameterTypes.contentEquals(
                arrayOf(classOf<Context>(), classOf<ViewGroup>())
            )
        }.distinctBy(Method::toGenericString).singleOrNull() ?: return missing("no-create-view-entry")
        val bindToView = KavaMemberLookup.methods(
            baseComponent,
            includeSuperclasses = true,
            makeAccessible = true
        ) { method ->
            method.name == BIND_TO_VIEW && method.parameterCount == 2 &&
                method.parameterTypes[1].name == KOTLIN_CONTINUATION
        }.distinctBy(Method::toGenericString).singleOrNull() ?: return missing("no-bind-to-view-entry")

        var installed = 0
        runCatching {
            environment.registrar.exact(
                "detail_app_promotion.relate_game.create",
                createViewEntry.declaringClass,
                createViewEntry.name,
                *createViewEntry.parameterTypes
            ) {
                before {
                    if (!gameComponent.isInstance(thisObject)) return@before
                    val context = args.firstOrNull() as? Context ?: return@before
                    val emptyEntry = runCatching {
                        simpleViewEntryConstructor.newInstance(View(context))
                    }.getOrNull() ?: return@before
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    result = emptyEntry
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                }
            }
            installed += 1
        }.onFailure { throwable ->
            environment.logError(
                "detail_app_promotion_relate_game_create",
                "[BIL] 游戏推荐空视图入口注册失败，已放行该入口: $throwable"
            )
        }
        runCatching {
            environment.registrar.exact(
                "detail_app_promotion.relate_game.bind",
                bindToView.declaringClass,
                bindToView.name,
                *bindToView.parameterTypes
            ) {
                before {
                    if (!gameComponent.isInstance(thisObject)) return@before
                    result = Unit
                }
            }
            installed += 1
        }.onFailure { throwable ->
            environment.logError(
                "detail_app_promotion_relate_game_bind",
                "[BIL] 游戏推荐绑定入口注册失败，已放行该入口: $throwable"
            )
        }
        if (installed > 0) {
            environment.logInfo(
                "detail_app_promotion_relate_game_ready",
                "[BIL] 视频详细页游戏推荐组件兜底已安装(hooks=$installed)"
            )
        }
        return installed
    }

    private fun resolveCurrentUnderPlayer(
        environment: HookEnvironment,
        videoDetail: Any,
        types: HostTypes,
        sceneAccess: SceneAccess
    ) {
        val owner = videoDetail.javaClass
        val getter = underPlayerGetters[owner] ?: locateUnderPlayerGetter(
            owner = owner,
            underPlayerClass = types.underPlayerClass
        )?.also { underPlayerGetters[owner] = it }
        if (getter == null) {
            if (!attemptedVideoDetailClasses.add(owner)) return
            listOf("detail_promotion_nest","detail_promotion_list","detail_promotion_hd").forEach {
                environment.reportCapability(it, FeatureInstallResult.Skipped("missing-under-player-getter"))
            }
            environment.reportStatus(CHANNEL_STATUS, "partial:under-player-getter")
            environment.logError(
                "detail_app_promotion_under_player_missing",
                "[BIL] 无法唯一定位 ${owner.name}#getUnderPlayer，已放行宿主"
            )
            return
        }

        installUnderPlayerGetterFallback(
            environment = environment,
            owner = owner,
            getter = getter,
            types = types,
            sceneAccess = sceneAccess
        )

        runCatching { getter.invoke(videoDetail) }
            .onSuccess { underPlayer ->
                if (underPlayer != null && types.underPlayerClass.isInstance(underPlayer)) {
                    installRenderHooks(
                        environment = environment,
                        owner = underPlayer.javaClass,
                        types = types,
                        sceneAccess = sceneAccess
                    )
                }
            }
            .onFailure { throwable ->
                environment.reportStatus(CHANNEL_STATUS, "partial:under-player-read")
                environment.logError(
                    "detail_app_promotion_under_player_read",
                    "[BIL] 读取播放器下方推广实现失败，保留 getter 兜底: $throwable"
                )
            }
    }

    private fun installUnderPlayerGetterFallback(
        environment: HookEnvironment,
        owner: Class<*>,
        getter: Method,
        types: HostTypes,
        sceneAccess: SceneAccess
    ) {
        if (!attemptedVideoDetailClasses.add(owner)) return
        runCatching {
            environment.registrar.exact(
                "detail_app_promotion.under_player.${owner.name}",
                getter.declaringClass,
                getter.name,
                *getter.parameterTypes
            ) {
                after {
                    val underPlayer = result ?: return@after
                    if (!types.underPlayerClass.isInstance(underPlayer)) return@after
                    installRenderHooks(
                        environment = environment,
                        owner = underPlayer.javaClass,
                        types = types,
                        sceneAccess = sceneAccess
                    )
                }
            }
        }.onFailure { throwable ->
            environment.reportStatus(CHANNEL_STATUS, "partial:under-player-registration")
            environment.logError(
                "detail_app_promotion_under_player_hook",
                "[BIL] getUnderPlayer 兜底注册失败，已保留立即解析结果: $throwable"
            )
        }
    }

    private fun resolveCurrentRelate(
        environment: HookEnvironment,
        videoDetail: Any,
        relateClass: Class<*>
    ) {
        val owner = videoDetail.javaClass
        val getter = relateGetters[owner] ?: locateRelateGetter(owner, relateClass)
            ?.also { relateGetters[owner] = it }
        if (getter == null) {
            if (!attemptedRelateVideoDetailClasses.add(owner)) return
            environment.reportCapability("detail_promotion_related_ad", FeatureInstallResult.Skipped("missing-related-ad-getter"))
            environment.reportStatus(CHANNEL_STATUS, "partial:relate-getter")
            environment.logError(
                "detail_app_promotion_relate_getter_missing",
                "[BIL] 无法唯一定位 ${owner.name}#getRelate，已放行该广告推荐路径"
            )
            return
        }

        installRelateGetterFallback(environment, owner, getter, relateClass)
        runCatching { getter.invoke(videoDetail) }
            .onSuccess { relate ->
                if (relate != null && relateClass.isInstance(relate)) {
                    installRelateRenderHooks(environment, relate.javaClass, relateClass)
                }
            }
            .onFailure { throwable ->
                environment.reportStatus(CHANNEL_STATUS, "partial:relate-read")
                environment.logError(
                    "detail_app_promotion_relate_read",
                    "[BIL] 读取广告推荐实现失败，保留 getRelate 兜底: $throwable"
                )
            }
    }

    private fun installRelateGetterFallback(
        environment: HookEnvironment,
        owner: Class<*>,
        getter: Method,
        relateClass: Class<*>
    ) {
        if (!attemptedRelateVideoDetailClasses.add(owner)) return
        runCatching {
            environment.registrar.exact(
                "detail_app_promotion.relate.${owner.name}",
                getter.declaringClass,
                getter.name,
                *getter.parameterTypes
            ) {
                after {
                    val relate = result ?: return@after
                    if (!relateClass.isInstance(relate)) return@after
                    installRelateRenderHooks(environment, relate.javaClass, relateClass)
                }
            }
        }.onFailure { throwable ->
            environment.reportStatus(CHANNEL_STATUS, "partial:relate-registration")
            environment.logError(
                "detail_app_promotion_relate_hook",
                "[BIL] getRelate 兜底注册失败，已保留立即解析结果: $throwable"
            )
        }
    }

    private fun locateRelateGetter(owner: Class<*>, relateClass: Class<*>): Method? =
        mostSpecificMethods(owner) {
            it.name == GET_RELATE && it.parameterCount == 0 &&
                !it.returnType.isPrimitive &&
                (it.returnType == classOf<Any>() || it.returnType isSubclassOf relateClass)
        }.singleOrNull()

    private fun installRelateRenderHooks(
        environment: HookEnvironment,
        owner: Class<*>,
        relateClass: Class<*>
    ) {
        if (!attemptedRelateClasses.add(owner)) return
        if (!(owner isSubclassOf relateClass)) return
        val methods = mostSpecificMethods(owner) { method ->
            matchesDetailRelateAdRenderMethod(method)
        }
        if (methods.isEmpty()) {
            environment.reportStatus(CHANNEL_STATUS, "partial:ad-relate-method")
            environment.reportCapability("detail_promotion_related_ad", FeatureInstallResult.Skipped("missing-related-ad-method"))
            environment.logError(
                "detail_app_promotion_relate_render_missing",
                "[BIL] ${owner.name} 未找到 getAdRelateView，已放行该实现"
            )
            return
        }
        var installed = 0
        val leafEnvironment = environment.forCapabilityRuntime("detail_promotion_related_ad")
        methods.forEachIndexed { index, method ->
            runCatching {
                environment.registrar.exact(
                    "detail_app_promotion.relate_render.${owner.name}.$index",
                    method.declaringClass,
                    method.name,
                    *method.parameterTypes
                ) {
                    before {
                        leafEnvironment.reportRuntimeEvidence("detail_promotion_related_ad", FeatureRuntimeStage.OBSERVED)
                        result = null
                        leafEnvironment.reportRuntimeEvidence("detail_promotion_related_ad", FeatureRuntimeStage.APPLIED)
                        if (relateHitLogged.compareAndSet(false, true)) {
                            environment.logInfo(
                                "detail_app_promotion_relate_hit",
                                "[BIL] 已隐藏视频详细页广告推荐视图(route=${method.name})"
                            )
                        }
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "detail_app_promotion_relate_render_$index",
                    "[BIL] ${method.name} 注册失败，已放行该广告推荐入口: $throwable"
                )
            }
        }
        environment.reportCapabilityCoverage("detail_promotion_related_ad", true, installed, methods.size)
        if (installed == 0) {
            environment.reportStatus(CHANNEL_STATUS, "failed:ad-relate-registration")
            return
        }
        relateRenderReady.set(true)
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        reportReadyStatus(environment)
        environment.logInfo(
            "detail_app_promotion_relate_ready",
            "[BIL] 视频详细页广告推荐渲染拦截已安装(methods=$installed)"
        )
    }

    private fun locateUnderPlayerGetter(
        owner: Class<*>,
        underPlayerClass: Class<*>
    ): Method? {
        val candidates = mostSpecificMethods(owner) {
            it.name == GET_UNDER_PLAYER && it.parameterCount == 0 &&
                (it.returnType isSubclassOf underPlayerClass)
        }
        return candidates.singleOrNull()
    }

    private fun installRenderHooks(
        environment: HookEnvironment,
        owner: Class<*>,
        types: HostTypes,
        sceneAccess: SceneAccess
    ) {
        if (!attemptedUnderPlayerClasses.add(owner)) return
        val methods = mostSpecificMethods(owner) { method ->
            matchesDetailPromotionRenderMethod(
                method = method,
                callbackClass = types.callbackClass,
                bridgeClass = types.bridgeClass,
                configClass = types.configClass
            )
        }
        if (methods.isEmpty()) {
            listOf("detail_promotion_nest","detail_promotion_list","detail_promotion_hd").forEach {
                environment.reportCapability(it, FeatureInstallResult.Skipped("missing-under-player-render-method"))
            }
            environment.reportStatus(CHANNEL_STATUS, "partial:render-methods")
            environment.logError(
                "detail_app_promotion_render_missing",
                "[BIL] ${owner.name} 未找到受约束的话题推广渲染方法，已放行宿主"
            )
            return
        }

        val installedRoutes = linkedSetOf<String>()
        val registeredByRoute = mutableMapOf<String, Int>()
        fun routeId(name: String): String = when (name) {
            GET_UPPER_NEST_VIEW -> "detail_promotion_nest"
            GET_UPPER_AD_VIEW -> "detail_promotion_list"
            else -> "detail_promotion_hd"
        }
        methods.forEachIndexed { index, method ->
            val capability = routeId(method.name)
            val leafEnvironment = environment.forCapabilityRuntime(capability)
            runCatching {
                environment.registrar.exact(
                    "detail_app_promotion.render.${method.declaringClass.name}.${method.name}.$index",
                    method.declaringClass,
                    method.name,
                    *method.parameterTypes
                ) {
                    before {
                        val config = detailPromotionConfigOrNull(args, types.configClass)
                            ?: return@before
                        if (!sceneAccess.isUniteDetail(config)) return@before
                        leafEnvironment.reportRuntimeEvidence(capability, FeatureRuntimeStage.OBSERVED)
                        result = null
                        leafEnvironment.reportRuntimeEvidence(capability, FeatureRuntimeStage.APPLIED)
                        if (hitLogged.compareAndSet(false, true)) {
                            environment.logInfo(
                                "detail_app_promotion_hit",
                                "[BIL] 已隐藏视频详细页话题推广(route=${method.name})"
                            )
                        }
                    }
                }
                registeredByRoute[method.name] = (registeredByRoute[method.name] ?: 0) + 1
                installedRoutes += when (method.name) {
                    GET_UPPER_NEST_VIEW -> "nest"
                    GET_UPPER_AD_VIEW -> "list"
                    GET_UPPER_HD_VIEW -> "hd"
                    else -> method.name
                }
            }.onFailure { throwable ->
                environment.logError(
                    "detail_app_promotion_render_${method.name}_$index",
                    "[BIL] ${method.name} 注册失败，已放行该入口: $throwable"
                )
            }
        }

        for (name in listOf(GET_UPPER_NEST_VIEW, GET_UPPER_AD_VIEW, GET_UPPER_HD_VIEW)) {
            val required = methods.count { it.name == name }
            if (required == 0) {
                val named = mostSpecificMethods(owner) { it.name == name }.isNotEmpty()
                environment.reportCapability(routeId(name), FeatureInstallResult.Skipped(
                    if (named) "missing-render-signature" else "not-applicable-host"
                ))
            } else environment.reportCapabilityCoverage(routeId(name), true, registeredByRoute[name] ?: 0, required)
        }
        if (installedRoutes.isEmpty()) {
            environment.reportStatus(CHANNEL_STATUS, "failed:render-registration")
            return
        }
        val routeSummary = installedRoutes.sorted().joinToString("+")
        underPlayerRouteSummary = routeSummary
        renderReady.set(true)
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        reportReadyStatus(environment)
        environment.logInfo(
            "detail_app_promotion_ready",
            "[BIL] 视频详细页话题推广渲染拦截已安装(route=$routeSummary)"
        )
    }

    private fun reportReadyStatus(environment: HookEnvironment) {
        val routes = buildList {
            underPlayerRouteSummary?.let { add("under-player:$it") }
            if (relateRenderReady.get()) add("relate")
        }
        if (routes.isNotEmpty()) {
            environment.reportStatus(CHANNEL_STATUS, routes.joinToString(prefix = "ready:", separator = "+"))
        }
    }

    /**
     * 由实际类向父类遍历，按方法名与参数签名保留最靠近实际类的实现，避免同时 Hook override 与 super。
     */
    private fun mostSpecificMethods(
        owner: Class<*>,
        predicate: (Method) -> Boolean
    ): List<Method> {
        val signatures = HashSet<String>()
        return KavaMemberLookup.methods(
            declaringClass = owner,
            includeSuperclasses = true,
            makeAccessible = true,
            predicate = predicate
        ).filter { method ->
            signatures.add(
                method.name + method.parameterTypes.joinToString(
                    prefix = "(",
                    postfix = ")"
                ) { it.name }
            )
        }
    }

    private fun resolveHostTypes(environment: HookEnvironment): HostTypes? {
        val loader = environment.classLoader ?: return null
        return HostTypes(
            videoDetailClass = KavaMemberLookup.classOrNull(loader, G_AD_VIDEO_DETAIL)
                ?: return null,
            underPlayerClass = KavaMemberLookup.classOrNull(loader, I_AD_UNDER_PLAYER) ?: return null,
            callbackClass = KavaMemberLookup.classOrNull(loader, I_AD_UNDER_PLAYER_CALLBACK)
                ?: return null,
            bridgeClass = KavaMemberLookup.classOrNull(loader, AD_UPPER_BRIDGE) ?: return null,
            configClass = KavaMemberLookup.classOrNull(loader, AD_UPPER_CONFIG) ?: return null,
            sceneClass = KavaMemberLookup.classOrNull(loader, AD_UPPER_SCENE) ?: return null
        )
    }

    private fun resolveSceneAccess(types: HostTypes): SceneAccess? {
        val uniteDetail = types.sceneClass.enumConstants
            ?.firstOrNull { (it as? Enum<*>)?.name == UNITE_DETAIL }
            ?: return null
        val getter = KavaMemberLookup.methods(
            declaringClass = types.configClass,
            includeSuperclasses = true,
            makeAccessible = true
        ) {
            it.name == GET_SCENE && it.parameterCount == 0 &&
                (it.returnType isSubclassOf types.sceneClass)
        }.firstOrNull()
        val field = if (getter == null) {
            KavaMemberLookup.fields(
                declaringClass = types.configClass,
                includeSuperclasses = true,
                makeAccessible = true
            ) { it.type isSubclassOf types.sceneClass }.singleOrNull()
        } else {
            null
        }
        if (getter == null && field == null) return null
        return SceneAccess(types.configClass, getter, field, uniteDetail)
    }

    private fun missing(environment: HookEnvironment, reason: String): FeatureInstallResult {
        environment.reportStatus(CHANNEL_STATUS, "missing:$reason")
        environment.logError(
            "detail_app_promotion_$reason",
            "[BIL] 视频详细页话题推广 Hook 不可用，已放行宿主: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    private data class HostTypes(
        val videoDetailClass: Class<*>,
        val underPlayerClass: Class<*>,
        val callbackClass: Class<*>,
        val bridgeClass: Class<*>,
        val configClass: Class<*>,
        val sceneClass: Class<*>
    )

    private class SceneAccess(
        private val configClass: Class<*>,
        private val getter: Method?,
        private val field: Field?,
        private val uniteDetail: Any
    ) {
        fun isUniteDetail(config: Any): Boolean {
            if (!configClass.isInstance(config)) return false
            val scene = runCatching {
                getter?.invoke(config) ?: field?.get(config)
            }.getOrNull()
            return matchesDetailPromotionScene(scene, uniteDetail)
        }
    }

    companion object {
        const val ID = "detail_app_promotion"
        private const val CHANNEL_STATUS = "detail_app_promotion_status"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val G_AD_BIZ_FACADE = "com.bilibili.gripper.api.ad.biz.GAdBizKt"
        private const val G_AD_VIDEO_DETAIL = "com.bilibili.gripper.api.ad.biz.GAdVideoDetail"
        private const val I_AD_UNDER_PLAYER =
            "com.bilibili.gripper.api.ad.biz.videodetail.underplayer.IAdUnderPlayer"
        private const val I_AD_VIDEO_RELATE =
            "com.bilibili.gripper.api.ad.biz.videodetail.relate.IAdVideoRelate"
        private const val I_AD_UNDER_PLAYER_CALLBACK =
            "com.bilibili.gripper.api.ad.biz.videodetail.underplayer.IAdUnderPlayerCallback"
        private const val AD_UPPER_BRIDGE =
            "com.bilibili.gripper.api.ad.biz.videodetail.underplayer.AdUpperBridge"
        private const val AD_UPPER_CONFIG =
            "com.bilibili.gripper.api.ad.biz.videodetail.underplayer.AdUpperConfig"
        private const val AD_UPPER_SCENE =
            "com.bilibili.gripper.api.ad.biz.videodetail.underplayer.AdUpperScene"
        private const val GET_VIDEO_DETAIL = "getGAdVideoDetail"
        private const val GET_UNDER_PLAYER = "getUnderPlayer"
        private const val GET_RELATE = "getRelate"
        private const val GET_UPPER_NEST_VIEW = "getUpperNestView"
        private const val GET_UPPER_AD_VIEW = "getUpperAdView"
        private const val GET_UPPER_HD_VIEW = "getUpperHDView"
        private const val GET_SCENE = "getScene"
        private const val UNITE_DETAIL = "UNITE_DETAIL"
        private const val ANDROIDX_VIEW_BINDING = "androidx.viewbinding.ViewBinding"
        private const val GEMINI_SIMPLE_VIEW_ENTRY = "com.bilibili.app.gemini.ui.UIComponent\$b"
        private const val KOTLIN_CONTINUATION = "kotlin.coroutines.Continuation"
        private const val CREATE_VIEW_ENTRY = "createViewEntry"
        private const val BIND_TO_VIEW = "bindToView"
        private const val RELATE_GAME_PACKAGE =
            "com.bilibili.ship.theseus.united.page.intro.module.relate.game"
        private const val GEMINI_UI_PACKAGE = "com.bilibili.app.gemini.ui"

        /**
         * 相关游戏推广组件的类名随混淆在单字母之间漂移，实测：8.84.0–8.96.0 为未混淆的
         * `RelateGameComponent`、8.97.0=f、8.98.0=g、8.99.0=d、9.1.0/9.1.1=i、
         * 9.2.0/9.3.0/9.5.0/9.9.0=g、9.4.0=f、9.6.0=h、9.7.0/9.10.0=e。
         *
         * 旧的 `e/d/f/RelateGameComponent` 固定名单因此在 8.98.0、9.1.0、9.1.1、9.2.0、9.3.0、
         * 9.5.0、9.6.0、9.9.0 共 8 个宿主上全程未安装，而这些位置在别的版本上又分别是 synthetic
         * lambda 或接口——名单命中与否纯属巧合，且失败完全不可观测。改为在稳定包内按有界字母表
         * 列出候选，判定完全由 [installRelateGameComponentBlock] 的结构过滤承担（继承 gemini 基类
         * + 非接口非抽象 + `(Context, LayoutInflater, ViewGroup) -> ViewBinding` +
         * `(ViewBinding, Continuation)`），并保留 `singleOrNull()`：命中不唯一即按缺失处理。
         */
        private val RELATE_GAME_COMPONENT_CLASSES: List<String> =
            ('a'..'z').map { letter -> "$RELATE_GAME_PACKAGE.$letter" } +
                "$RELATE_GAME_PACKAGE.RelateGameComponent"

        /**
         * gemini 绑定基类同样漂移（8.84.0–8.96.0=k、8.97.0–9.6.0=m、9.7.0–9.10.0=l）。
         * 这里必须保留原有的显式优先顺序：
         * 同一个包里 `UIComponent`（接口）与 `DataBindingComponent` 也满足"两个双参方法"的形状，
         * 只有靠 `isAbstract && !isInterface` 加上先命中已验证候选才不会选错基类。字母表候选只
         * 追加在已验证名单之后，用于覆盖尚未遇到过的新字母。
         */
        private val GEMINI_BINDING_COMPONENT_CLASSES: List<String> = (
            listOf("l", "m", "k", "j", "c", "d", "e") + ('a'..'z').map(Char::toString)
            ).distinct().map { letter -> "$GEMINI_UI_PACKAGE.$letter" }
    }
}

/** 广告推荐接口只允许拦截明确的 View/回调生产方法；基础类型返回值一律不碰。 */
internal fun matchesDetailRelateAdRenderMethod(method: Method): Boolean =
    method.name == "getAdRelateView" &&
        !method.isStatic &&
        !method.isAbstract &&
        method.returnType != Void.TYPE &&
        !method.returnType.isPrimitive

private val DETAIL_PROMOTION_RENDER_METHOD_NAMES = setOf(
    "getUpperNestView",
    "getUpperAdView",
    "getUpperHDView"
)

/** 公开方法名 + 参数角色约束；供安装器与 JVM 多版本契约测试共用。 */
internal fun matchesDetailPromotionRenderMethod(
    method: Method,
    callbackClass: Class<*>,
    bridgeClass: Class<*>,
    configClass: Class<*>
): Boolean =
    method.name in DETAIL_PROMOTION_RENDER_METHOD_NAMES &&
        (method.returnType isSubclassOf callbackClass) &&
        method.parameterTypes.any { it isSubclassOf classOf<ViewGroup>() } &&
        method.parameterTypes.any { it isSubclassOf bridgeClass } &&
        method.parameterTypes.any { it isSubclassOf configClass }

/** 从渲染实参中定位场景配置；调用者类型不是渲染方法的参数，不参与热路径门禁。 */
internal fun detailPromotionConfigOrNull(
    args: Array<out Any?>,
    configClass: Class<*>
): Any? = args.firstOrNull { candidate -> candidate != null && configClass.isInstance(candidate) }

/** 仅统一视频详细页场景允许拦截；读取失败或未知场景均失败开放。 */
internal fun matchesDetailPromotionScene(scene: Any?, uniteDetail: Any): Boolean =
    scene === uniteDetail || scene == uniteDetail

/** 返回首个已初始化且类型匹配的值；未初始化候选不会执行 initializer。 */
internal fun initializedLazyValueOfType(
    candidates: Iterable<Lazy<*>>,
    expectedType: Class<*>
): Any? {
    candidates.forEach { candidate ->
        if (!candidate.isInitialized()) return@forEach
        val value = candidate.value
        if (expectedType.isInstance(value)) return value
    }
    return null
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.Method

/**
 * 详细页组件净化：在 `view.v1.ViewMoss` 的同步/异步响应上按名清掉顶层字段。
 *
 * 字段白名单与硬编码依据见 [DetailModulePurifyPolicy]。
 *
 * 边界纪律：
 * - **副本改写**：全部经 [ProtobufBuilderPlan]，改的是 builder，不动原实例；
 * - **先 `has*` 再 `clear*`**，清完还要回读确认——`clear*` 对空字段静默成功，
 *   不能拿"invoke 没抛"当运行证据；
 * - **排除默认实例**：`getDefaultInstance()` 是进程级单例，绝不改写；
 * - **fail-open 到宿主**：任何异常都交付原响应（异步路径由
 *   [MossResponseHandlerProxy.wrapTransform] 再兜一层），不让详情页白屏；
 * - **子项独立降级**：某个字段在将来版本消失，只把该子项标记未覆盖，其余继续工作。
 */
internal class DetailModulePurifyFeatureInstaller(
    private val enabledKeys: Set<String>
) : FeatureInstaller {

    override val id: String = ID

    override val capabilityIds: List<String>
        get() = DetailModulePurifyPolicy.targetsFor(enabledKeys).map { it.capabilityId } +
            if (DetailModulePurifyPolicy.topicTagsEnabled(enabledKeys)) {
                listOf(DetailModulePurifyPolicy.TopicTags.CAPABILITY_ID)
            } else {
                emptyList()
            }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        val requestedFields = DetailModulePurifyPolicy.targetsFor(enabledKeys)
        val topicTags = DetailModulePurifyPolicy.topicTagsEnabled(enabledKeys)
        if (requestedFields.isEmpty() && !topicTags) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        // 面板上每个勾选项都是一个覆盖单位，列表筛选型也算一项。
        val requestedIds = requestedFields.map { it.capabilityId } +
            if (topicTags) listOf(DetailModulePurifyPolicy.TopicTags.CAPABILITY_ID) else emptyList()
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val cleaner = DetailModuleReplyCleaner.resolve(loader, requestedFields, topicTags)
            ?: return missing(environment, "not-applicable-host")

        // 解析不到访问器的子项单独记未覆盖，不拖垮其余子项。
        requestedIds.filterNot { it in cleaner.capabilityIds }.forEach { id ->
            environment.reportCapability(id, FeatureInstallResult.Skipped("not-applicable-host"))
            environment.logInfo(
                "detail_module_field_absent",
                "[BIL] 详细页组件字段在本宿主不存在，已跳过该项: $id"
            )
        }

        val mossClass = KavaMemberLookup.classOrNull(loader, DetailModulePurifyPolicy.MOSS_CLASS)
            ?: return missing(environment, "not-applicable-host")
        val requestClass = KavaMemberLookup.classOrNull(loader, DetailModulePurifyPolicy.REQUEST_CLASS)
            ?: return missing(environment, "not-applicable-host")
        val handlerClass = KavaMemberLookup.classOrNull(loader, HANDLER_CLASS)

        var routes = 0
        runCatching {
            environment.registrar.exact(
                "detail_module.sync.${DetailModulePurifyPolicy.SYNC_METHOD}",
                mossClass,
                DetailModulePurifyPolicy.SYNC_METHOD,
                requestClass
            ) {
                after {
                    if (hasThrowable) return@after
                    val original = result ?: return@after
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    val updated = cleaner.clean(original, environment)
                    if (updated !== original) result = updated
                }
            }
            routes++
        }.onFailure {
            environment.logError("detail_module_sync", "[BIL] 详细页组件同步响应 Hook 注册失败: $it")
        }

        if (handlerClass != null) {
            runCatching {
                environment.registrar.exact(
                    "detail_module.async.${DetailModulePurifyPolicy.ASYNC_METHOD}",
                    mossClass,
                    DetailModulePurifyPolicy.ASYNC_METHOD,
                    requestClass,
                    handlerClass
                ) {
                    before {
                        val original = argOrNull(1) ?: return@before
                        val proxy = MossResponseHandlerProxy.wrapTransform(handlerClass, original) { reply ->
                            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                            cleaner.clean(reply, environment)
                        } ?: return@before
                        args[1] = proxy
                    }
                }
                routes++
            }.onFailure {
                environment.logError("detail_module_async", "[BIL] 详细页组件异步响应 Hook 注册失败: $it")
            }
        } else {
            environment.logError(
                "detail_module_handler_absent",
                "[BIL] 未找到 MossResponseHandler，详细页组件净化只覆盖同步路径"
            )
        }

        if (routes == 0) return missing(environment, "no-safe-detail-path")

        val covered = requestedIds.filter { it in cleaner.capabilityIds }
        covered.forEach {
            environment.reportCapabilityCoverage(
                it,
                ready = true,
                installedPaths = routes,
                expectedPaths = DetailModulePurifyPolicy.PATHS_PER_TARGET
            )
        }
        val expected = requestedIds.size * DetailModulePurifyPolicy.PATHS_PER_TARGET
        val installed = covered.size * routes
        val complete = installed == expected && expected > 0
        environment.reportStatus(
            CHANNEL_STATUS,
            if (complete) "success" else "partial:$installed/$expected"
        )
        return FeatureInstallResult.Installed(routes, complete = complete)
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("detail_module_missing", "[BIL] 详细页组件净化适配不完整: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "detail_module_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "detail_module_status"
        private const val HANDLER_CLASS = "com.bilibili.lib.moss.api.MossResponseHandler"
    }
}

/**
 * 安装期解析全部反射，回调内只 `invoke`。
 *
 * 与 [PlayerInteractiveReplyCleaner] 同一套做法，但目标是顶层字段，所以不需要
 * carrier/setter 那一层：直接在 `ViewReply` 的 builder 上清。
 */
internal class DetailModuleReplyCleaner private constructor(
    private val reply: Class<*>,
    private val builder: ProtobufBuilderPlan,
    private val fields: List<Field>,
    private val tags: TagFilter?,
    private val defaultInstance: Any?
) {

    internal class Field(val id: String, private val presence: Method, val clear: Method) {
        fun populated(target: Any): Boolean = DetailModulePurifyPolicy.presenceOf(presence, target)
    }

    /**
     * repeated 列表的按特征筛选。
     *
     * 写回方式是 `clear* + addAll*`（builder 上），配合
     * [ProtobufListRetention.retainOrNull]：**全部保留时返回 null**，
     * 调用方据此完全跳过写回——既省一次列表重建，也不会把"本来就没东西可删"
     * 误报成生效。
     */
    internal class TagFilter(
        val id: String,
        private val count: Method,
        private val list: Method,
        private val uri: Method,
        private val clear: Method,
        private val addAll: Method
    ) {
        /** @return 需要写回的保留列表；无命中返回 null。 */
        fun retain(message: Any): List<Any>? {
            if ((count.invoke(message) as? Int ?: 0) <= 0) return null
            val source = list.invoke(message) as? List<*> ?: return null
            return ProtobufListRetention.retainOrNull(source) { !matches(it) }
        }

        fun write(target: Any, retained: List<Any>) {
            clear.invoke(target)
            addAll.invoke(target, retained)
        }

        /** 回读用：改写后列表里不允许再有命中项。 */
        fun remaining(message: Any): Int =
            (list.invoke(message) as? List<*>).orEmpty().count { it != null && matches(it) }

        private fun matches(tag: Any): Boolean =
            DetailModulePurifyPolicy.TopicTags.isTopicTag(uri.invoke(tag) as? String)
    }

    val capabilityIds: Set<String> =
        fields.mapTo(linkedSetOf()) { it.id } + setOfNotNull(tags?.id)

    /** 无命中返回原实例（不分配）；异常保留原响应并记诊断。 */
    fun clean(original: Any, environment: HookEnvironment): Any = runCatching {
        if (!reply.isInstance(original)) return@runCatching original
        // 默认实例是进程级单例，改写它会污染整个宿主进程。
        if (defaultInstance != null && original === defaultInstance) return@runCatching original
        val populated = fields.filter { it.populated(original) }
        // 列表筛选与字段清除**共用同一次副本**：一次响应最多复制一次。
        val retainedTags = tags?.retain(original)
        if (populated.isEmpty() && retainedTags == null) return@runCatching original
        populated.forEach {
            environment.reportRuntimeEvidence(it.id, FeatureRuntimeStage.OBSERVED)
        }
        if (retainedTags != null) {
            environment.reportRuntimeEvidence(tags!!.id, FeatureRuntimeStage.OBSERVED)
        }
        val updated = builder.edit(original) { target ->
            populated.forEach { it.clear.invoke(target) }
            if (retainedTags != null) tags!!.write(target, retainedTags)
        }
        // 回读确认：clear* 对空字段静默成功，不回读就没有"真的清掉了"的证据。
        check(populated.none { it.populated(updated) }) { "Detail module clear readback failed" }
        if (retainedTags != null) {
            check(tags!!.remaining(updated) == 0) { "Detail tag filter readback failed" }
        }
        populated.forEach {
            environment.reportRuntimeEvidence(it.id, FeatureRuntimeStage.APPLIED)
        }
        if (retainedTags != null) {
            environment.reportRuntimeEvidence(tags!!.id, FeatureRuntimeStage.APPLIED)
        }
        environment.reportRuntimeEvidence(
            DetailModulePurifyFeatureInstaller.ID,
            FeatureRuntimeStage.APPLIED
        )
        updated
    }.getOrElse {
        environment.reportRuntimeEvidence(
            DetailModulePurifyFeatureInstaller.ID,
            FeatureRuntimeStage.ERROR
        )
        environment.logError(
            "detail_module_copy_failed",
            "[BIL] 详细页组件副本清理失败，保留原响应: $it"
        )
        original
    }

    companion object {
        fun resolve(
            loader: ClassLoader,
            targets: Collection<DetailModulePurifyPolicy.Target>,
            topicTags: Boolean = false
        ): DetailModuleReplyCleaner? = runCatching {
            val reply = KavaMemberLookup.classOrNull(loader, DetailModulePurifyPolicy.REPLY_CLASS)
                ?: return null
            // Builder 的类名是被混淆的（实测 9.11.0 上是 `ViewReply$b`），
            // 所以只能经 newBuilder(...).returnType 反射拿到，绝不能按名字找。
            val plan = ProtobufBuilderPlan.resolve(reply) ?: return null
            val fields = targets.mapNotNull { target ->
                val presence = KavaMemberLookup.methodOrNull(reply, target.presence)
                    ?.takeIf { it.returnType == classOf<Boolean>() } ?: return@mapNotNull null
                val clear = plan.method(target.clear)
                    ?.takeIf(DetailModulePurifyPolicy::callable) ?: return@mapNotNull null
                Field(target.capabilityId, presence, clear)
            }
            val tagFilter = if (topicTags) resolveTagFilter(loader, reply, plan) else null
            if (fields.isEmpty() && tagFilter == null) return null
            val defaultInstance = runCatching {
                KavaMemberLookup.methodOrNull(reply, "getDefaultInstance")?.invoke(null)
            }.getOrNull()
            DetailModuleReplyCleaner(reply, plan, fields, tagFilter, defaultInstance)
        }.getOrNull()

        /** 任一环节解析不到就返回 null：该子项降级为未覆盖，其余子项照常工作。 */
        private fun resolveTagFilter(
            loader: ClassLoader,
            reply: Class<*>,
            plan: ProtobufBuilderPlan
        ): TagFilter? {
            val spec = DetailModulePurifyPolicy.TopicTags
            val tagClass = KavaMemberLookup.classOrNull(loader, spec.TAG_CLASS) ?: return null
            val count = KavaMemberLookup.methodOrNull(reply, spec.presenceCount)
                ?.takeIf { it.returnType == classOf<Int>() } ?: return null
            val list = KavaMemberLookup.methodOrNull(reply, spec.list)
                ?.takeIf { it.returnType isSubclassOf classOf<List<*>>() } ?: return null
            val uri = KavaMemberLookup.methodOrNull(tagClass, "getUri")
                ?.takeIf { it.returnType == classOf<String>() } ?: return null
            val clear = plan.method(spec.clear)
                ?.takeIf(DetailModulePurifyPolicy::callable) ?: return null
            val addAll = plan.method(spec.addAll, classOf<Iterable<*>>()) ?: return null
            return TagFilter(spec.CAPABILITY_ID, count, list, uri, clear, addAll)
        }
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.Method

/**
 * United 详情页协议层净化：在 `viewunite.v1.ViewMoss` 的响应上按 `ModuleType` 删模块。
 *
 * 判据、链路与"为什么这才是那五项的正确落点"见 [DetailUnitedModulePurifyPolicy]。
 *
 * 边界纪律（与 [DetailModulePurifyFeatureInstaller] 同一套）：
 * - **副本改写**：五层消息全部经 [ProtobufBuilderPlan]，改 builder，不动原实例；
 * - **按需复制**：某一层没有命中就完全不复制那一层，一次响应最多每层复制一次；
 * - **排除默认实例**：`getDefaultInstance()` 是进程级单例，绝不改写；
 * - **改完回读**：`clear*` 对空字段静默成功，不回读就没有"真的删掉了"的证据；
 * - **fail-open 到宿主**：任何异常都交付原响应，不让详情页白屏；
 * - **两条链独立降级**：模块链与 `owner.vip` 链各自解析，一条挂了不拖累另一条。
 */
internal class DetailUnitedModulePurifyFeatureInstaller(
    private val enabledKeys: Set<String>,
    /**
     * 视频提及（游戏推广卡）的协议层总闸。单独一个参数而不是混进 [enabledKeys]：
     * 它沿用的游戏卡开关**默认开**，而 [enabledKeys] 那条路径按"默认关"过滤，
     * 混进去会把老用户的默认行为从"开"改成"关"。
     */
    private val hideVideoMentions: Boolean = false,
    /** 「UP 主分享好物」商品卡。同样沿用默认开的老开关，理由见 [hideVideoMentions]。 */
    private val hideMerchandise: Boolean = false
) : FeatureInstaller {

    override val id: String = DetailUnitedModulePurifyPolicy.ID

    override val capabilityIds: List<String>
        get() = DetailUnitedModulePurifyPolicy.capabilityIdsFor(
            enabledKeys, hideVideoMentions, hideMerchandise
        )

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        val requestedIds = capabilityIds
        if (requestedIds.isEmpty()) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val moduleTargets = DetailUnitedModulePurifyPolicy.moduleTargetsFor(enabledKeys) +
            listOfNotNull(
                DetailUnitedModulePurifyPolicy.VideoMentions.TARGET.takeIf { hideVideoMentions },
                DetailUnitedModulePurifyPolicy.Merchandise.TARGET.takeIf { hideMerchandise }
            )
        val cleaner = UnitedModuleReplyCleaner.resolve(
            loader,
            moduleTargets,
            DetailUnitedModulePurifyPolicy.upVipLabelEnabled(enabledKeys),
            DetailUnitedModulePurifyPolicy.hotBannerEnabled(enabledKeys)
        ) { url ->
            // 只打一次。留给下一次真机确认横条 url 的判据该不该放宽。
            environment.logInfo(
                "detail_united_guidance_bar_url",
                "[BIL] 引导条类型命中但 URL 不是热搜跳转，未改动: $url"
            )
        } ?: return missing(environment, "not-applicable-host")

        // 解析不到的子项单独记未覆盖，不拖垮其余子项。
        requestedIds.filterNot { it in cleaner.capabilityIds }.forEach { capability ->
            environment.reportCapability(capability, FeatureInstallResult.Skipped("not-applicable-host"))
            environment.logInfo(
                "detail_united_module_absent",
                "[BIL] United 详情页模块判据在本宿主不可用，已跳过该项: $capability"
            )
        }

        val mossClass = KavaMemberLookup.classOrNull(loader, DetailUnitedModulePurifyPolicy.MOSS_CLASS)
            ?: return missing(environment, "not-applicable-host")
        val requestClass = KavaMemberLookup.classOrNull(loader, DetailUnitedModulePurifyPolicy.REQUEST_CLASS)
            ?: return missing(environment, "not-applicable-host")
        val handlerClass = KavaMemberLookup.classOrNull(loader, HANDLER_CLASS)

        var routes = 0
        runCatching {
            environment.registrar.exact(
                "detail_united_module.sync.${DetailUnitedModulePurifyPolicy.SYNC_METHOD}",
                mossClass,
                DetailUnitedModulePurifyPolicy.SYNC_METHOD,
                requestClass
            ) {
                after {
                    if (hasThrowable) return@after
                    val original = result ?: return@after
                    environment.reportRuntimeEvidence(
                        DetailUnitedModulePurifyPolicy.ID, FeatureRuntimeStage.OBSERVED
                    )
                    val updated = cleaner.clean(original, environment)
                    if (updated !== original) result = updated
                }
            }
            routes++
        }.onFailure {
            environment.logError(
                "detail_united_module_sync",
                "[BIL] United 详情页模块同步响应 Hook 注册失败: $it"
            )
        }

        if (handlerClass != null) {
            runCatching {
                environment.registrar.exact(
                    "detail_united_module.async.${DetailUnitedModulePurifyPolicy.ASYNC_METHOD}",
                    mossClass,
                    DetailUnitedModulePurifyPolicy.ASYNC_METHOD,
                    requestClass,
                    handlerClass
                ) {
                    before {
                        val original = argOrNull(1) ?: return@before
                        val proxy = MossResponseHandlerProxy.wrapTransform(handlerClass, original) { reply ->
                            environment.reportRuntimeEvidence(
                                DetailUnitedModulePurifyPolicy.ID, FeatureRuntimeStage.OBSERVED
                            )
                            cleaner.clean(reply, environment)
                        } ?: return@before
                        args[1] = proxy
                    }
                }
                routes++
            }.onFailure {
                environment.logError(
                    "detail_united_module_async",
                    "[BIL] United 详情页模块异步响应 Hook 注册失败: $it"
                )
            }
        } else {
            environment.logError(
                "detail_united_module_handler_absent",
                "[BIL] 未找到 MossResponseHandler，United 详情页模块净化只覆盖同步路径"
            )
        }

        if (routes == 0) return missing(environment, "no-safe-united-path")

        val covered = requestedIds.filter { it in cleaner.capabilityIds }
        covered.forEach {
            environment.reportCapabilityCoverage(
                it,
                ready = true,
                installedPaths = routes,
                expectedPaths = DetailUnitedModulePurifyPolicy.PATHS_PER_TARGET
            )
        }
        val expected = requestedIds.size * DetailUnitedModulePurifyPolicy.PATHS_PER_TARGET
        val installed = covered.size * routes
        val complete = installed == expected && expected > 0
        environment.reportStatus(
            CHANNEL_STATUS,
            if (complete) "success" else "partial:$installed/$expected"
        )
        return FeatureInstallResult.Installed(routes, complete = complete)
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "detail_united_module_missing",
            "[BIL] United 详情页模块净化适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    private companion object {
        const val TARGET_PACKAGE = "tv.danmaku.bili"
        const val CHANNEL_STATUS = "detail_united_module_status"
        const val HANDLER_CLASS = "com.bilibili.lib.moss.api.MossResponseHandler"
    }
}

/**
 * `IntroductionTab.modules` 的按类型删除链。
 *
 * 五层里只有**真的有命中**的那几层才会复制：没命中的 tabModule 原样留在列表里，
 * 一个 tabModule 都没命中就连 `Tab` 都不复制。
 */
internal class UnitedModuleChain(
    private val moduleClass: Class<*>,
    private val byType: Map<Int, DetailUnitedModulePurifyPolicy.ModuleTarget>,
    private val typeValue: Method,
    private val tabPresence: Method,
    private val tabGetter: Method,
    private val tabSetter: Method,
    private val tabPlan: ProtobufBuilderPlan,
    private val tabModuleList: Method,
    private val tabModuleClear: Method,
    private val tabModuleAddAll: Method,
    private val tabModulePlan: ProtobufBuilderPlan,
    private val introPresence: Method,
    private val introGetter: Method,
    private val introSetter: Method,
    private val introPlan: ProtobufBuilderPlan,
    private val modulesList: Method,
    private val modulesClear: Method,
    private val modulesAddAll: Method,
    private val guidanceBar: UnitedGuidanceBarMatch? = null
) {

    val capabilityIds: Set<String> = byType.values.mapTo(linkedSetOf()) { it.capabilityId } +
        setOfNotNull(guidanceBar?.target?.capabilityId)

    /**
     * @param hits 命中的子项 capability id，由调用方用来只给真的删掉的项记运行证据。
     * @return 需要写回的新 `Tab`；没有任何命中时返回 null（调用方据此完全跳过复制）。
     */
    fun rebuildTab(reply: Any, hits: MutableSet<String>): Any? {
        if (present(tabPresence, reply) != true) return null
        val tab = tabGetter.invoke(reply) ?: return null
        // protobuf 列表不会含 null；真出现就整条放弃，绝不用错位的下标去写回。
        val tabModules = (tabModuleList.invoke(tab) as? List<*>)?.map { it ?: return null } ?: return null
        var rebuilt: MutableList<Any>? = null
        tabModules.forEachIndexed { index, tabModule ->
            if (present(introPresence, tabModule) != true) return@forEachIndexed
            val intro = introGetter.invoke(tabModule) ?: return@forEachIndexed
            val modules = modulesList.invoke(intro) as? List<*> ?: return@forEachIndexed
            val retained = ProtobufListRetention.retainOrNull(modules) { module ->
                val target = targetOf(module)
                if (target == null) {
                    true
                } else {
                    hits += target.capabilityId
                    false
                }
            } ?: return@forEachIndexed
            val newIntro = introPlan.edit(intro) { target ->
                modulesClear.invoke(target)
                modulesAddAll.invoke(target, retained)
            }
            val newTabModule = tabModulePlan.edit(tabModule) { target ->
                introSetter.invoke(target, newIntro)
            }
            val list = rebuilt ?: tabModules.toMutableList().also { rebuilt = it }
            list[index] = newTabModule
        }
        val list = rebuilt ?: return null
        return tabPlan.edit(tab) { target ->
            tabModuleClear.invoke(target)
            tabModuleAddAll.invoke(target, list)
        }
    }

    fun writeTab(builder: Any, tab: Any) {
        tabSetter.invoke(builder, tab)
    }

    /** 回读用：改写后任何 introduction tab 里都不允许再有命中类型的模块。 */
    fun remaining(reply: Any): Int {
        if (present(tabPresence, reply) != true) return 0
        val tab = tabGetter.invoke(reply) ?: return 0
        val tabModules = tabModuleList.invoke(tab) as? List<*> ?: return 0
        var count = 0
        tabModules.forEach { tabModule ->
            if (tabModule == null || present(introPresence, tabModule) != true) return@forEach
            val intro = introGetter.invoke(tabModule) ?: return@forEach
            val modules = modulesList.invoke(intro) as? List<*> ?: return@forEach
            count += modules.count { it != null && targetOf(it) != null }
        }
        return count
    }

    private fun targetOf(module: Any): DetailUnitedModulePurifyPolicy.ModuleTarget? {
        if (!moduleClass.isInstance(module)) return null
        val type = typeValue.invoke(module) as? Int ?: return null
        byType[type]?.let { return it }
        // 条件型子项：类型对上还不够，载荷里的判据也要成立（见 HotBannerGuidanceBar）。
        val conditional = guidanceBar ?: return null
        if (conditional.typeValue != type) return null
        return if (conditional.matches(module)) conditional.target else null
    }

    private fun present(method: Method, message: Any): Boolean? =
        method.invoke(message) as? Boolean
}

/**
 * 热搜横条的条件判据：类型是 `ACTIVITY_GUIDANCE_BAR` **且** `url` 是热搜跳转。
 *
 * 为什么不能只看类型、以及为什么这一层还没有真机证据，见
 * [DetailUnitedModulePurifyPolicy.HotBannerGuidanceBar]。
 *
 * [unmatchedUrl] 只记**第一条**没匹配上的引导条 URL：下一次真机一眼就能确认
 * 判据该不该放宽，同时不会每条响应都刷日志。
 */
internal class UnitedGuidanceBarMatch(
    val typeValue: Int,
    val target: DetailUnitedModulePurifyPolicy.ModuleTarget,
    private val presence: Method,
    private val getter: Method,
    private val url: Method,
    private val onUnmatched: (String) -> Unit
) {

    @Volatile private var reportedUnmatched = false

    fun matches(module: Any): Boolean {
        if (presence.invoke(module) as? Boolean != true) return false
        val bar = getter.invoke(module) ?: return false
        val value = url.invoke(bar) as? String
        if (DetailUnitedPresentationPurifyPolicy.isSearchJumpLabelUri(value)) return true
        if (!reportedUnmatched) {
            reportedUnmatched = true
            onUnmatched(value.orEmpty())
        }
        return false
    }
}

/** `ViewReply.owner.vip` 的清除链。UP 会员标不是模块，所以单独一条。 */
internal class UnitedVipChain(
    private val ownerPresence: Method,
    private val ownerGetter: Method,
    private val ownerSetter: Method,
    private val ownerPlan: ProtobufBuilderPlan,
    private val vipPresence: Method,
    private val vipClear: Method
) {

    /** @return 需要写回的新 `Owner`；本来就没有会员标时返回 null。 */
    fun rebuildOwner(reply: Any): Any? {
        if (!populated(reply)) return null
        val owner = ownerGetter.invoke(reply) ?: return null
        return ownerPlan.edit(owner) { target -> vipClear.invoke(target) }
    }

    fun writeOwner(builder: Any, owner: Any) {
        ownerSetter.invoke(builder, owner)
    }

    fun populated(reply: Any): Boolean {
        if (ownerPresence.invoke(reply) as? Boolean != true) return false
        val owner = ownerGetter.invoke(reply) ?: return false
        return vipPresence.invoke(owner) as? Boolean == true
    }
}

/** 安装期解析全部反射，回调内只 `invoke`。 */
internal class UnitedModuleReplyCleaner private constructor(
    private val reply: Class<*>,
    private val replyPlan: ProtobufBuilderPlan,
    private val modules: UnitedModuleChain?,
    private val vip: UnitedVipChain?,
    private val defaultInstance: Any?
) {

    val capabilityIds: Set<String> = (modules?.capabilityIds ?: emptySet()) +
        if (vip != null) setOf(DetailUnitedModulePurifyPolicy.UpVipLabel.CAPABILITY_ID) else emptySet()

    /** 无命中返回原实例（不分配）；异常保留原响应并记诊断。 */
    fun clean(original: Any, environment: HookEnvironment): Any = runCatching {
        if (!reply.isInstance(original)) return@runCatching original
        // 默认实例是进程级单例，改写它会污染整个宿主进程。
        if (defaultInstance != null && original === defaultInstance) return@runCatching original
        val hits = linkedSetOf<String>()
        // 把"要写回的新子消息"和"负责写它的那条链"绑在一起，省掉一串 !!。
        val tabWrite = modules?.let { chain -> chain.rebuildTab(original, hits)?.let { chain to it } }
        val ownerWrite = vip?.let { chain -> chain.rebuildOwner(original)?.let { chain to it } }
        if (tabWrite == null && ownerWrite == null) return@runCatching original
        if (ownerWrite != null) hits += DetailUnitedModulePurifyPolicy.UpVipLabel.CAPABILITY_ID
        hits.forEach { environment.reportRuntimeEvidence(it, FeatureRuntimeStage.OBSERVED) }
        val updated = replyPlan.edit(original) { target ->
            tabWrite?.let { (chain, tab) -> chain.writeTab(target, tab) }
            ownerWrite?.let { (chain, owner) -> chain.writeOwner(target, owner) }
        }
        // 回读确认：clear*/addAll* 对空输入静默成功，不回读就没有"真的删掉了"的证据。
        if (tabWrite != null) {
            check(tabWrite.first.remaining(updated) == 0) { "United module removal readback failed" }
        }
        if (ownerWrite != null) {
            check(!ownerWrite.first.populated(updated)) { "United vip clear readback failed" }
        }
        hits.forEach { environment.reportRuntimeEvidence(it, FeatureRuntimeStage.APPLIED) }
        environment.reportRuntimeEvidence(
            DetailUnitedModulePurifyPolicy.ID, FeatureRuntimeStage.APPLIED
        )
        updated
    }.getOrElse {
        environment.reportRuntimeEvidence(
            DetailUnitedModulePurifyPolicy.ID, FeatureRuntimeStage.ERROR
        )
        environment.logError(
            "detail_united_module_copy_failed",
            "[BIL] United 详情页模块副本清理失败，保留原响应: $it"
        )
        original
    }

    companion object {
        fun resolve(
            loader: ClassLoader,
            targets: Collection<DetailUnitedModulePurifyPolicy.ModuleTarget>,
            upVipLabel: Boolean,
            hotBanner: Boolean = false,
            onUnmatchedGuidanceBar: (String) -> Unit = {}
        ): UnitedModuleReplyCleaner? = runCatching {
            val policy = DetailUnitedModulePurifyPolicy
            val reply = KavaMemberLookup.classOrNull(loader, policy.REPLY_CLASS) ?: return null
            // Builder 类名被混淆（实测 `ViewReply$b`），只能经 newBuilder(...).returnType 拿到。
            val replyPlan = ProtobufBuilderPlan.resolve(reply) ?: return null
            val modules = if (targets.isEmpty() && !hotBanner) {
                null
            } else {
                resolveModuleChain(loader, reply, replyPlan, targets, hotBanner, onUnmatchedGuidanceBar)
            }
            val vip = if (upVipLabel) resolveVipChain(loader, reply, replyPlan) else null
            if (modules == null && vip == null) return null
            val defaultInstance = runCatching {
                KavaMemberLookup.methodOrNull(reply, "getDefaultInstance")?.invoke(null)
            }.getOrNull()
            UnitedModuleReplyCleaner(reply, replyPlan, modules, vip, defaultInstance)
        }.getOrNull()

        /** 任一环节缺失就返回 null：整条模块链降级，`owner.vip` 那条不受影响。 */
        private fun resolveModuleChain(
            loader: ClassLoader,
            reply: Class<*>,
            replyPlan: ProtobufBuilderPlan,
            targets: Collection<DetailUnitedModulePurifyPolicy.ModuleTarget>,
            hotBanner: Boolean,
            onUnmatchedGuidanceBar: (String) -> Unit
        ): UnitedModuleChain? {
            val policy = DetailUnitedModulePurifyPolicy
            val tabClass = KavaMemberLookup.classOrNull(loader, policy.TAB_CLASS) ?: return null
            val tabModuleClass = KavaMemberLookup.classOrNull(loader, policy.TAB_MODULE_CLASS)
                ?: return null
            val introClass = KavaMemberLookup.classOrNull(loader, policy.INTRODUCTION_TAB_CLASS)
                ?: return null
            val moduleClass = KavaMemberLookup.classOrNull(loader, policy.MODULE_CLASS) ?: return null
            val moduleTypeClass = KavaMemberLookup.classOrNull(loader, policy.MODULE_TYPE_CLASS)
                ?: return null

            // ModuleType 上的 static final int 常量；缺的子项直接不进表，其余照常。
            val byType = LinkedHashMap<Int, DetailUnitedModulePurifyPolicy.ModuleTarget>()
            targets.forEach { target ->
                val field = KavaMemberLookup.fieldOrNull(moduleTypeClass, target.typeConstant)
                    ?.takeIf { it.isStatic && it.type == classOf<Int>() } ?: return@forEach
                val value = runCatching { field.getInt(null) }.getOrNull() ?: return@forEach
                // 两个子项映射到同一个枚举值就整条放弃：宁可不生效，也不要删错模块。
                if (byType.put(value, target) != null) return null
            }
            val guidance = if (hotBanner) {
                resolveGuidanceBar(loader, moduleClass, moduleTypeClass, onUnmatchedGuidanceBar)
                    // 条件判据与无条件表撞到同一个枚举值就不装它：宁可这一层不生效，
                    // 也不要让"无条件删"覆盖掉"按 URL 才删"。
                    ?.takeIf { it.typeValue !in byType }
            } else {
                null
            }
            if (byType.isEmpty() && guidance == null) return null

            val typeValue = KavaMemberLookup.methodOrNull(moduleClass, policy.MODULE_TYPE_VALUE)
                ?.takeIf { it.returnType == classOf<Int>() } ?: return null
            val tabPresence = boolMethod(reply, policy.TAB_PRESENCE) ?: return null
            val tabGetter = KavaMemberLookup.methodOrNull(reply, policy.TAB_GETTER)
                ?.takeIf { it.returnType == tabClass } ?: return null
            val tabSetter = replyPlan.method(policy.TAB_SETTER, tabClass) ?: return null
            val tabPlan = ProtobufBuilderPlan.resolve(tabClass) ?: return null
            val tabModuleList = listMethod(tabClass, policy.TAB_MODULE_LIST) ?: return null
            val tabModuleClear = tabPlan.method(policy.TAB_MODULE_CLEAR) ?: return null
            val tabModuleAddAll = tabPlan.method(policy.TAB_MODULE_ADD_ALL, classOf<Iterable<*>>())
                ?: return null
            val tabModulePlan = ProtobufBuilderPlan.resolve(tabModuleClass) ?: return null
            val introPresence = boolMethod(tabModuleClass, policy.INTRODUCTION_PRESENCE) ?: return null
            val introGetter = KavaMemberLookup.methodOrNull(tabModuleClass, policy.INTRODUCTION_GETTER)
                ?.takeIf { it.returnType == introClass } ?: return null
            val introSetter = tabModulePlan.method(policy.INTRODUCTION_SETTER, introClass) ?: return null
            val introPlan = ProtobufBuilderPlan.resolve(introClass) ?: return null
            val modulesList = listMethod(introClass, policy.MODULES_LIST) ?: return null
            val modulesClear = introPlan.method(policy.MODULES_CLEAR) ?: return null
            val modulesAddAll = introPlan.method(policy.MODULES_ADD_ALL, classOf<Iterable<*>>())
                ?: return null

            return UnitedModuleChain(
                moduleClass = moduleClass,
                byType = byType,
                typeValue = typeValue,
                tabPresence = tabPresence,
                tabGetter = tabGetter,
                tabSetter = tabSetter,
                tabPlan = tabPlan,
                tabModuleList = tabModuleList,
                tabModuleClear = tabModuleClear,
                tabModuleAddAll = tabModuleAddAll,
                tabModulePlan = tabModulePlan,
                introPresence = introPresence,
                introGetter = introGetter,
                introSetter = introSetter,
                introPlan = introPlan,
                modulesList = modulesList,
                modulesClear = modulesClear,
                modulesAddAll = modulesAddAll,
                guidanceBar = guidance
            )
        }

        /** 缺任一环节就返回 null：热搜横条这一层降级，其余子项照常。 */
        private fun resolveGuidanceBar(
            loader: ClassLoader,
            moduleClass: Class<*>,
            moduleTypeClass: Class<*>,
            onUnmatched: (String) -> Unit
        ): UnitedGuidanceBarMatch? {
            val spec = DetailUnitedModulePurifyPolicy.HotBannerGuidanceBar
            val payloadClass = KavaMemberLookup.classOrNull(loader, spec.PAYLOAD_CLASS) ?: return null
            val field = KavaMemberLookup.fieldOrNull(moduleTypeClass, spec.TYPE_CONSTANT)
                ?.takeIf { it.isStatic && it.type == classOf<Int>() } ?: return null
            val typeValue = runCatching { field.getInt(null) }.getOrNull() ?: return null
            val presence = boolMethod(moduleClass, spec.PAYLOAD_PRESENCE) ?: return null
            val getter = KavaMemberLookup.methodOrNull(moduleClass, spec.PAYLOAD_GETTER)
                ?.takeIf { it.returnType == payloadClass } ?: return null
            val url = KavaMemberLookup.methodOrNull(payloadClass, spec.URL_GETTER)
                ?.takeIf { it.returnType == classOf<String>() } ?: return null
            return UnitedGuidanceBarMatch(typeValue, spec.TARGET, presence, getter, url, onUnmatched)
        }

        private fun resolveVipChain(
            loader: ClassLoader,
            reply: Class<*>,
            replyPlan: ProtobufBuilderPlan
        ): UnitedVipChain? {
            val spec = DetailUnitedModulePurifyPolicy.UpVipLabel
            val ownerClass = KavaMemberLookup.classOrNull(
                loader, DetailUnitedModulePurifyPolicy.OWNER_CLASS
            ) ?: return null
            val ownerPresence = boolMethod(reply, spec.OWNER_PRESENCE) ?: return null
            val ownerGetter = KavaMemberLookup.methodOrNull(reply, spec.OWNER_GETTER)
                ?.takeIf { it.returnType == ownerClass } ?: return null
            val ownerSetter = replyPlan.method(spec.OWNER_SETTER, ownerClass) ?: return null
            val ownerPlan = ProtobufBuilderPlan.resolve(ownerClass) ?: return null
            val vipPresence = boolMethod(ownerClass, spec.VIP_PRESENCE) ?: return null
            val vipClear = ownerPlan.method(spec.VIP_CLEAR) ?: return null
            return UnitedVipChain(
                ownerPresence, ownerGetter, ownerSetter, ownerPlan, vipPresence, vipClear
            )
        }

        private fun boolMethod(owner: Class<*>, name: String): Method? =
            KavaMemberLookup.methodOrNull(owner, name)
                ?.takeIf { it.returnType == classOf<Boolean>() }

        private fun listMethod(owner: Class<*>, name: String): Method? =
            KavaMemberLookup.methodOrNull(owner, name)
                ?.takeIf { it.returnType isSubclassOf classOf<List<*>>() }
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.Constructor
import java.lang.reflect.Field
import java.lang.reflect.Method
import java.util.concurrent.ConcurrentHashMap

/**
 * United 详情页的展示模型净化。
 *
 * 这不是旧 `view.v1.ViewReply` 的协议改写：当前 `UnitedBizDetailsActivity` 已经把 viewunite
 * 数据转成两个短生命周期的渲染模型。这里在模型进入 View 前精确删除：
 *
 * - 标题 `Headline.label` 中 URI 来源为热搜的角标；
 * - `SpecialTag` 映射出的 topic cell。
 *
 * 两者都按 URI 判别，不按可见文字、span 位置或资源图标猜测。
 */
internal class DetailUnitedPresentationPurifyFeatureInstaller(
    private val hideHotSearchBadge: Boolean,
    private val hideSpecialTopicTags: Boolean
) : FeatureInstaller {

    override val id: String = DetailUnitedPresentationPurifyPolicy.ID

    override val capabilityIds: List<String>
        get() = buildList {
            if (hideHotSearchBadge) add(DetailUnitedPresentationPurifyPolicy.HOT_BADGE_CAPABILITY_ID)
            if (hideSpecialTopicTags) add(DetailUnitedPresentationPurifyPolicy.SPECIAL_TOPIC_CAPABILITY_ID)
        }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!hideHotSearchBadge && !hideSpecialTopicTags) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader
            ?: return missing(environment, "missing-class-loader")

        var expected = 0
        var installed = 0
        val failures = mutableListOf<String>()

        if (hideHotSearchBadge) {
            expected += 1
            val plan = HeadlineBadgeHookPlan.resolve(loader)
            val registered = plan != null && registerHeadlineBadgeHook(environment, plan)
            environment.reportCapabilityCoverage(
                DetailUnitedPresentationPurifyPolicy.HOT_BADGE_CAPABILITY_ID,
                ready = plan != null,
                installedPaths = if (registered) 1 else 0,
                expectedPaths = 1
            )
            if (registered) installed += 1 else failures += "headline"
        }

        if (hideSpecialTopicTags) {
            expected += 1
            val plan = SpecialTopicTagHookPlan.resolve(loader)
            val registered = plan != null && registerSpecialTopicHook(environment, plan)
            environment.reportCapabilityCoverage(
                DetailUnitedPresentationPurifyPolicy.SPECIAL_TOPIC_CAPABILITY_ID,
                ready = plan != null,
                installedPaths = if (registered) 1 else 0,
                expectedPaths = 1
            )
            if (registered) installed += 1 else failures += "special-tag"
        }

        val status = if (installed == expected) {
            "success"
        } else {
            "partial:$installed/$expected:${failures.joinToString("+")}"
        }
        environment.reportStatus(CHANNEL_STATUS, status)
        if (installed == 0) {
            environment.logError(
                "detail_united_presentation_missing",
                "[BIL] United 详情页展示模型净化未找到安全挂点: $status"
            )
            return FeatureInstallResult.Skipped("not-applicable-host")
        }
        environment.reportRuntimeEvidence(id, FeatureRuntimeStage.ADAPTED)
        environment.logInfo(
            "detail_united_presentation_ok",
            "[BIL] United 详情页展示模型净化已安装($installed/$expected)"
        )
        return FeatureInstallResult.Installed(installed, complete = installed == expected)
    }

    private fun registerHeadlineBadgeHook(
        environment: HookEnvironment,
        plan: HeadlineBadgeHookPlan
    ): Boolean = runCatching {
        environment.registrar.exact(
            "detail_united_presentation.headline_badge",
            plan.method.declaringClass,
            plan.method.name,
            *plan.method.parameterTypes
        ) {
            before {
                val original = args.getOrNull(0) ?: return@before
                val replacement = runCatching { plan.cleaner.removeHotSearchBadge(original) }
                    .onFailure { throwable ->
                        environment.reportRuntimeEvidence(
                            DetailUnitedPresentationPurifyPolicy.HOT_BADGE_CAPABILITY_ID,
                            FeatureRuntimeStage.ERROR
                        )
                        environment.logError(
                            "detail_united_headline_clean",
                            "[BIL] United 标题热搜角标处理失败: $throwable"
                        )
                    }
                    .getOrNull()
                    ?: return@before
                environment.reportRuntimeEvidence(
                    DetailUnitedPresentationPurifyPolicy.HOT_BADGE_CAPABILITY_ID,
                    FeatureRuntimeStage.OBSERVED
                )
                args[0] = replacement
                environment.reportRuntimeEvidence(
                    DetailUnitedPresentationPurifyPolicy.HOT_BADGE_CAPABILITY_ID,
                    FeatureRuntimeStage.APPLIED
                )
                environment.reportRuntimeEvidence(id, FeatureRuntimeStage.APPLIED)
            }
        }
        true
    }.getOrElse { throwable ->
        environment.logError(
            "detail_united_headline_register",
            "[BIL] United 标题热搜角标 Hook 注册失败: $throwable"
        )
        false
    }

    private fun registerSpecialTopicHook(
        environment: HookEnvironment,
        plan: SpecialTopicTagHookPlan
    ): Boolean = runCatching {
        environment.registrar.exact(
            "detail_united_presentation.special_topic",
            plan.method.declaringClass,
            plan.method.name,
            *plan.method.parameterTypes
        ) {
            after {
                if (hasThrowable) return@after
                val original = result ?: return@after
                val replacement = runCatching { plan.cleaner.removeSpecialTopicCells(original) }
                    .onFailure { throwable ->
                        environment.reportRuntimeEvidence(
                            DetailUnitedPresentationPurifyPolicy.SPECIAL_TOPIC_CAPABILITY_ID,
                            FeatureRuntimeStage.ERROR
                        )
                        environment.logError(
                            "detail_united_special_topic_clean",
                            "[BIL] United 特殊话题单元处理失败: $throwable"
                        )
                    }
                    .getOrNull()
                    ?: return@after
                if (replacement === original) return@after
                environment.reportRuntimeEvidence(
                    DetailUnitedPresentationPurifyPolicy.SPECIAL_TOPIC_CAPABILITY_ID,
                    FeatureRuntimeStage.OBSERVED
                )
                result = replacement
                environment.reportRuntimeEvidence(
                    DetailUnitedPresentationPurifyPolicy.SPECIAL_TOPIC_CAPABILITY_ID,
                    FeatureRuntimeStage.APPLIED
                )
                environment.reportRuntimeEvidence(id, FeatureRuntimeStage.APPLIED)
            }
        }
        true
    }.getOrElse { throwable ->
        environment.logError(
            "detail_united_special_topic_register",
            "[BIL] United 特殊话题单元 Hook 注册失败: $throwable"
        )
        false
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "detail_united_presentation_missing",
            "[BIL] United 详情页展示模型净化适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    private companion object {
        const val ID = "detail_united_presentation_purify"
        const val TARGET_PACKAGE = "tv.danmaku.bili"
        const val CHANNEL_STATUS = "detail_united_presentation_purify_status"
    }
}

/** 标题模型的安全替换：只在经审计 label 形状里的字符串字段具有精确热搜来源 URI 时构造无 label 副本。 */
internal class HeadlineBadgeModelCleaner private constructor(
    private val modelClass: Class<*>,
    private val content: Field,
    private val label: Field,
    private val labelStrings: List<Field>,
    private val constructor: Constructor<*>
) {

    /**
     * 构造"无 label 副本"时把 label 位传 null。
     *
     * 如果某个宿主把该构造参数声明为 Kotlin 非空类型，`newInstance` 会被
     * intrinsic 空检查拒掉——那不是偶发故障，而是**这个宿主上必然每次都失败**。
     * 所以第一次失败就熄火（[degraded]），否则每渲染一个标题刷一条错误日志。
     * 熄火后回到原样交付，热搜角标这一项不生效，其它层不受影响。
     */
    @Volatile private var degraded = false

    val isDegraded: Boolean get() = degraded

    fun removeHotSearchBadge(model: Any): Any? {
        if (degraded) return null
        if (!modelClass.isInstance(model)) return null
        val labelValue = label.get(model) ?: return null
        val isHotSearch = labelStrings.any { field ->
            // 按类别（跳搜索）判，不按某个 from 值——「热搜」「活动」及未来变体同覆盖。
            DetailUnitedPresentationPurifyPolicy.isSearchJumpLabelUri(field.get(labelValue) as? String)
        }
        if (!isHotSearch) return null
        val title = content.get(model) as? String ?: return null
        return try {
            constructor.newInstance(title, null)
        } catch (throwable: Throwable) {
            degraded = true
            throw throwable
        }
    }

    companion object {
        fun resolve(modelClass: Class<*>): HeadlineBadgeModelCleaner? = runCatching {
            val fields = KavaMemberLookup.declaredFields(modelClass, makeAccessible = true) {
                !it.isStatic
            }
            // 只接受当前已核实的 HeadlineData = String + label 形状；未来字段扩张时 fail-open。
            if (fields.size != 2) return null
            val contentFields = fields.filter { it.type == classOf<String>() }
            val labelFields = fields.filter { field ->
                !field.type.isPrimitive && field.type != classOf<String>()
            }
            val candidates = contentFields.flatMap { content ->
                labelFields.mapNotNull { label ->
                    val constructor = KavaMemberLookup.declaredConstructors(
                        modelClass,
                        makeAccessible = true
                    ) { candidate ->
                        candidate.parameterTypes.contentEquals(
                            arrayOf(classOf<String>(), label.type)
                        )
                    }.singleOrNull() ?: return@mapNotNull null
                    val labelFields = KavaMemberLookup.declaredFields(label.type, makeAccessible = true) {
                        !it.isStatic
                    }
                    // 五个已审计宿主的 Label 均为 int + 5 String + 2 long + Map；
                    // 任意扩张或类型漂移都拒绝，以免把未来的非标题 label 当作热搜角标。
                    if (labelFields.size != 9 ||
                        labelFields.count { it.type == classOf<Int>() } != 1 ||
                        labelFields.count { it.type == classOf<Long>() } != 2 ||
                        labelFields.count { it.type isSubclassOf classOf<Map<*, *>>() } != 1
                    ) return@mapNotNull null
                    val uriFields = labelFields.filter {
                        it.type == classOf<String>()
                    }
                    uriFields.takeIf { it.size == 5 }?.let {
                        HeadlineBadgeModelCleaner(modelClass, content, label, it, constructor)
                    }
                }
            }.distinctBy { it.content.name to it.label.name }
            candidates.singleOrNull()
        }.getOrNull()
    }
}

/** SpecialTag 映射结果的安全过滤器；无命中时返回同一实例，避免无意义的模型重建。 */
internal class SpecialTopicTagsModelCleaner private constructor(
    private val modelClass: Class<*>,
    private val cells: Field,
    private val refresh: Field,
    private val constructor: Constructor<*>
) {

    private val cellStringFields = ConcurrentHashMap<Class<*>, List<Field>>()

    fun removeSpecialTopicCells(model: Any): Any {
        if (!modelClass.isInstance(model)) return model
        val source = cells.get(model) as? List<*> ?: return model
        // 正常视频没有话题单元：先扫描，确认命中前不分配过滤列表。
        val firstTopicIndex = source.indexOfFirst(::isSpecialTopicCell)
        if (firstTopicIndex < 0) return model
        val retained = ArrayList<Any?>(source.size - 1)
        for (index in 0 until firstTopicIndex) retained += source[index]
        for (index in (firstTopicIndex + 1) until source.size) {
            if (!isSpecialTopicCell(source[index])) retained += source[index]
        }
        // 空列表必须同时关闭 refresh；否则 TagsService 仍可能创建一个没有 cell 的容器。
        val nextRefresh = if (retained.isEmpty()) false else refresh.getBoolean(model)
        return constructor.newInstance(retained, nextRefresh)
    }

    private fun isSpecialTopicCell(cell: Any?): Boolean {
        if (cell == null) return false
        val fields = cellStringFields.computeIfAbsent(cell.javaClass) { cellClass ->
            KavaMemberLookup.declaredFields(cellClass, makeAccessible = true) { field ->
                !field.isStatic && field.type == classOf<String>()
            }
        }
        return fields.any { field ->
            DetailUnitedPresentationPurifyPolicy.isSpecialTopicUri(field.get(cell) as? String)
        }
    }

    companion object {
        fun resolve(modelClass: Class<*>): SpecialTopicTagsModelCleaner? = runCatching {
            val fields = KavaMemberLookup.declaredFields(modelClass, makeAccessible = true) {
                !it.isStatic
            }
            // TagsData 只有 cells + refresh 两个状态；多出字段时不能靠不完整副本猜测。
            if (fields.size != 2) return null
            val cells = fields.filter { it.type isSubclassOf classOf<List<*>>() }.singleOrNull()
                ?: return null
            val refresh = fields.filter { it.type == classOf<Boolean>() }.singleOrNull()
                ?: return null
            val constructor = KavaMemberLookup.declaredConstructors(modelClass, makeAccessible = true) {
                it.parameterTypes.contentEquals(arrayOf(cells.type, refresh.type))
            }.singleOrNull() ?: return null
            SpecialTopicTagsModelCleaner(modelClass, cells, refresh, constructor)
        }.getOrNull()
    }
}

private data class HeadlineBadgeHookPlan(
    val method: Method,
    val cleaner: HeadlineBadgeModelCleaner
) {
    companion object {
        /**
         * 8.84.0 / 8.89.0 / 9.1.0 / 9.7.0 / 9.11.0 样本都有 UgcHeadlineService，
         * 但入口方法名随版本漂移（r/q/a）。因此只按参数模型形状选择，不写死方法名。
         */
        fun resolve(classLoader: ClassLoader): HeadlineBadgeHookPlan? = runCatching {
            val service = KavaMemberLookup.classOrNull(
                classLoader,
                DetailUnitedPresentationPurifyPolicy.HEADLINE_SERVICE_CLASS
            ) ?: return null
            val runningUiComponent = KavaMemberLookup.classOrNull(
                classLoader,
                DetailUnitedPresentationPurifyPolicy.RUNNING_UI_COMPONENT_CLASS
            ) ?: return null
            KavaMemberLookup.declaredMethods(service, makeAccessible = true) { method ->
                !method.isStatic &&
                    method.returnType == runningUiComponent &&
                    method.parameterTypes.size == 1
            }.mapNotNull { method ->
                HeadlineBadgeModelCleaner.resolve(method.parameterTypes.single())?.let { cleaner ->
                    HeadlineBadgeHookPlan(method, cleaner)
                }
            }.distinctBy { it.method.toGenericString() }.singleOrNull()
        }.getOrNull()
    }
}

private data class SpecialTopicTagHookPlan(
    val method: Method,
    val cleaner: SpecialTopicTagsModelCleaner
) {
    companion object {
        /**
         * 8.84.0 / 8.89.0 的 `tags.f#c(SpecialTag)` 与 9.11.0 的
         * `tags.j#a(SpecialTag)` 都已核对为 TagsData 映射。9.1.0 没有这两个形状，9.7.0
         * 同名 `j` 是另一种 ViewTagInfo 模型；所有不匹配形状一律降级，不能用泛
         * RecyclerView/文字规则冒充兼容。
         */
        fun resolve(classLoader: ClassLoader): SpecialTopicTagHookPlan? = runCatching {
            val specialTag = KavaMemberLookup.classOrNull(
                classLoader,
                DetailUnitedPresentationPurifyPolicy.SPECIAL_TAG_CLASS
            ) ?: return null
            val candidates = DetailUnitedPresentationPurifyPolicy.specialTagMapperClasses.flatMap { className ->
                val mapper = KavaMemberLookup.classOrNull(classLoader, className)
                    ?: return@flatMap emptyList()
                KavaMemberLookup.declaredMethods(mapper, makeAccessible = true) { method ->
                    method.isStatic && method.parameterTypes.contentEquals(arrayOf(specialTag))
                }.mapNotNull { method ->
                    SpecialTopicTagsModelCleaner.resolve(method.returnType)?.let { cleaner ->
                        SpecialTopicTagHookPlan(method, cleaner)
                    }
                }
            }
            candidates.distinctBy { it.method.toGenericString() }.singleOrNull()
        }.getOrNull()
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.view.View
import android.view.ViewGroup
import androidx.core.view.isGone
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.HostThreadGuard
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import java.lang.reflect.InvocationHandler
import java.lang.reflect.Method
import java.lang.reflect.Proxy
import java.util.Collections
import java.util.WeakHashMap

/**
 * 详细页 View 层净化：按结构指纹隐藏指定组件。
 *
 * 规则表与"为什么必须走 View 层"的判据见 [DetailViewPurifyPolicy]。
 *
 * ### Hook 选点与开销
 *
 * 挂 `RecyclerView#setAdapter`——**每个列表配置一次**，不是每帧也不是每次触摸。
 * 在它的 after 里给该 RecyclerView 装**一次**子项挂载监听（按实例弱引用去重），
 * **两条规则共用同一个监听**，不会因为多一个功能就多一层回调。
 *
 * 每次子项挂载的代价，按规则形态分两种：
 * - 有 `itemIdName` 的（关注按钮）：**一次 int 比较**就结束，绝大多数列表在这里被挡掉；
 * - 没有 `itemIdName` 的（热搜横条，item 根无资源名）：先用 `id == NO_ID` 免费挡掉
 *   带 id 的项，再对无 id 项做一次小范围 `findViewById` 找主判据。
 *   量级与 `onBindViewHolder` 相同，项目已有功能就挂在这个量级上。
 *
 * 没有按 Activity 过滤：那要依赖宿主 Activity 类名，多一条失效通道。
 *
 * ### 边界纪律
 *
 * - **不写死宿主类名**：只用 androidx 的类 + 资源名；
 * - 规则要用到的资源名缺任意一个，**该条规则**就不启用（不留白跑查找的路径）；
 * - 监听器不持有 Activity/View 强引用；
 * - 回调里任何异常都吞掉并记诊断，绝不让宿主布局流程崩；
 * - APPLIED 只在**这次真的藏掉了一项**时记：回收复用的视图本来就是折叠状态，不重复记，
 *   所以"报了 APPLIED"才等于"真的藏掉了一个东西"；
 * - 隐藏 **item 根**要连尺寸一起归零，并且必须能在回收复用时**还原**
 *   （见 [ItemCollapseBook]）——只 `GONE` 会留下一格空白，
 *   只归零不还原会把别的内容压成永久空白项。
 */
internal class DetailViewPurifyFeatureInstaller(
    private val enabledKeys: Set<String>
) : FeatureInstaller {

    override val id: String = ID

    override val capabilityIds: List<String>
        get() = DetailViewPurifyPolicy.rulesFor(enabledKeys).map { it.capabilityId }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        val requested = DetailViewPurifyPolicy.rulesFor(enabledKeys)
        if (requested.isEmpty()) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val recyclerView = KavaMemberLookup.classOrNull(
            loader, DetailViewPurifyPolicy.RECYCLER_VIEW_CLASS
        ) ?: return missing(environment, "not-applicable-host")
        val listenerClass = KavaMemberLookup.classOrNull(
            loader, DetailViewPurifyPolicy.CHILD_ATTACH_LISTENER_CLASS
        )?.takeIf { it.isInterface } ?: return missing(environment, "not-applicable-host")
        val addListener = KavaMemberLookup.methodOrNull(
            recyclerView, DetailViewPurifyPolicy.ADD_LISTENER_METHOD, listenerClass
        ) ?: return missing(environment, "not-applicable-host")

        val hider = DetailViewRuleHider(environment, requested, listenerClass, addListener)
        val installed = runCatching {
            environment.registrar.first(
                "detail_view_purify.${DetailViewPurifyPolicy.SET_ADAPTER_METHOD}",
                DetailViewPurifyPolicy.RECYCLER_VIEW_CLASS,
                DetailViewPurifyPolicy.SET_ADAPTER_METHOD
            ) {
                after {
                    val list = instance as? View ?: return@after
                    hider.observe(list)
                }
            }
            true
        }.getOrElse {
            environment.logError(
                "detail_view_purify_register",
                "[BIL] 详细页 View 层净化 Hook 注册失败: $it"
            )
            false
        }
        if (!installed) return missing(environment, "no-safe-detail-view-path")
        requested.forEach {
            environment.reportCapabilityCoverage(
                it.capabilityId, ready = true, installedPaths = 1, expectedPaths = 1
            )
        }
        environment.reportStatus(CHANNEL_STATUS, "success")
        return FeatureInstallResult.Installed(1)
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "detail_view_purify_missing",
            "[BIL] 详细页 View 层净化适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "detail_view_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "detail_view_purify_status"
    }
}

/** 给 RecyclerView 装一次子项挂载监听，命中规则就隐藏目标。资源 id 首次拿到 View 时解析。 */
internal class DetailViewRuleHider(
    private val environment: HookEnvironment,
    private val rules: List<DetailViewPurifyPolicy.Rule>,
    private val listenerClass: Class<*>,
    private val addListener: Method
) {

    private val observed: MutableSet<Any> =
        Collections.newSetFromMap(WeakHashMap<Any, Boolean>())

    private val collapsed = ItemCollapseBook()

    /**
     * 内层（非 item 根）被本安装器设成 GONE 的控件账。[collapsed] 只记 item 根；
     * 这些内层控件走的是纯可见性路径，RecyclerView 复用视图时同一对象会被拿去
     * 承载别的内容，没有这本账就永远停在 GONE。键随宿主视图回收自然清理。
     */
    private val innerHidden = InnerVisibilityBook()

    @Volatile private var ids: Map<String, Int>? = null
    @Volatile private var active: List<DetailViewPurifyPolicy.Rule> = emptyList()

    fun observe(list: View) {
        if (!resolve(list)) return
        synchronized(observed) {
            if (!observed.add(list)) return
        }
        runCatching { addListener.invoke(list, newListener()) }.onFailure {
            synchronized(observed) { observed.remove(list) }
            environment.logError(
                "detail_view_purify_listen",
                "[BIL] 详细页 View 层净化监听安装失败: $it"
            )
        }
    }

    /** @return 是否还有可用规则。资源名解析只做一次，之后不再查 identifier。 */
    @Suppress("DiscouragedApi")
    private fun resolve(view: View): Boolean {
        if (ids == null) {
            val resources = view.resources ?: return false
            val table = rules.flatMap { it.idNames }.distinct().associateWith { name ->
                // DiscouragedApi 的建议（改用 R.foo.bar）不成立：这是**宿主**的资源，
                // 模块自己的 R 类里没有它，按名解析是唯一办法；结果已缓存。
                runCatching { resources.getIdentifier(name, "id", TARGET_PACKAGE) }
                    .getOrDefault(0)
            }
            ids = table
            active = rules.filter { DetailViewPurifyPolicy.usable(it, table) }
            rules.filterNot { it in active }.forEach {
                environment.reportCapability(
                    it.capabilityId, FeatureInstallResult.Skipped("not-applicable-host")
                )
                environment.logError(
                    "detail_view_purify_ids",
                    "[BIL] 详细页组件资源 id 未解析，已跳过该项: ${it.capabilityId} " +
                        "(${it.idNames.joinToString { name -> "$name=${table[name]}" }})"
                )
            }
        }
        return active.isNotEmpty()
    }

    private fun newListener(): Any = Proxy.newProxyInstance(
        listenerClass.classLoader, arrayOf(listenerClass), Handler(this)
    )

    /**
     * 子项挂载回调（**只在主线程**：由 RecyclerView 的布局流程调用），
     * 所以 [collapsed] 不加锁。
     *
     * 折叠过 item 根之后必须管**还原**：RecyclerView 会回收复用视图，
     * 同一个 View 对象可能被拿去承载别的内容。若那次不命中而尺寸还留在 0，
     * 用户看到的就是一条永远空白的项——比原来的问题更糟。
     */
    fun onChildAttached(child: Any?) {
        val view = child as? View ?: return
        val table = ids ?: return
        var keepCollapsed = false
        val hiddenNow = ArrayList<View>()
        active.forEach { rule ->
            if (applyRule(rule, view, table, hiddenNow)) keepCollapsed = true
        }
        restoreManuallyHidden(view, hiddenNow)
        if (!keepCollapsed) restore(view)
    }

    /**
     * 内层 GONE 的还原不走 [collapsed]（那只记 item 根）：凡挂在本子项下、且本轮
     * 没有再次隐藏的已记账控件，一律还原成隐藏前的可见性并摘账。规则仍命中但目标已是
     * GONE 的（上一轮由本规则设的）已在 [keptHidden] 里，不会被误还原。
     */
    private fun restoreManuallyHidden(root: View, keptHidden: Collection<View>) {
        for (key in innerHidden.trackedKeys()) {
            val target = key as? View ?: continue
            if (target in keptHidden) continue
            if (!(target === root || target.isDescendantOf(root))) continue
            innerHidden.restore(ViewVisibilityBox(target))
        }
    }

    private fun View.isDescendantOf(ancestor: View): Boolean {
        var parent = parent
        while (parent != null) {
            if (parent === ancestor) return true
            parent = (parent as? View)?.parent
        }
        return false
    }

    /** @return 这一项的 item 根是否应保持折叠（决定回收复用时要不要还原）。 */
    private fun applyRule(
        rule: DetailViewPurifyPolicy.Rule,
        child: View,
        table: Map<String, Int>,
        hiddenNow: MutableCollection<View>
    ): Boolean {
        // 最便宜的前置判据先走：有 itemIdName 的一次 int 比较；没有的先用 NO_ID 挡。
        val itemId = rule.itemIdName?.let { table[it] }
        if (itemId != null) {
            if (child.id != itemId) return false
        } else if (child.id != View.NO_ID) {
            return false
        }
        return runCatching {
            // 结构指纹必须**全部**命中才动手；任一缺失就原样放行。
            rule.requiredIdNames.forEach { name ->
                child.findViewById<View>(table.getValue(name)) ?: return false
            }
            val target = rule.hideIdName?.let { name ->
                child.findViewById<View>(table.getValue(name)) ?: return false
            } ?: child
            environment.reportRuntimeEvidence(rule.capabilityId, FeatureRuntimeStage.OBSERVED)
            val hidden = if (rule.hidesItemRoot) {
                // 光 GONE 不收缩那一格，要连尺寸一起归零；见 Rule.hidesItemRoot。
                collapsed.collapse(ViewItemBox(target))
            } else if (innerHidden.hide(ViewVisibilityBox(target))) {
                hiddenNow += target
                true
            } else {
                // 规则仍命中且目标已是 GONE（可能上一轮由本规则设的）：也要报给扫除，
                // 否则会被当成"本轮未隐藏"而在回收复用时误还原成 VISIBLE。
                if (innerHidden.tracks(target)) hiddenNow += target
                false
            }
            if (hidden) {
                environment.reportRuntimeEvidence(rule.capabilityId, FeatureRuntimeStage.APPLIED)
                environment.reportRuntimeEvidence(
                    DetailViewPurifyFeatureInstaller.ID, FeatureRuntimeStage.APPLIED
                )
            }
            rule.hidesItemRoot
        }.getOrElse {
            environment.reportRuntimeEvidence(
                DetailViewPurifyFeatureInstaller.ID, FeatureRuntimeStage.ERROR
            )
            environment.logError(
                "detail_view_purify_hide",
                "[BIL] 详细页组件隐藏失败(${rule.capabilityId}): $it"
            )
            false
        }
    }

    /** 没有记录就什么都不做——绝大多数子项走的是这条零成本路径。 */
    private fun restore(child: View) {
        if (!collapsed.tracks(child)) return
        runCatching { collapsed.restore(ViewItemBox(child)) }.onFailure {
            environment.reportRuntimeEvidence(
                DetailViewPurifyFeatureInstaller.ID, FeatureRuntimeStage.ERROR
            )
            environment.logError(
                "detail_view_purify_restore",
                "[BIL] 详细页组件尺寸还原失败: $it"
            )
        }
    }

    /**
     * 代理只处理挂载回调。
     *
     * `equals`/`hashCode`/`toString` 必须自己答——它们也会走到代理上，
     * 交给宿主接口会抛（接口没有这些方法的实现）。
     *
     * 挂载回调由 RecyclerView 在宿主主线程的布局流程里直接调用，不经过 Hook 链，
     * 框架的 PROTECTIVE 兜不住，所以整段走 [HostThreadGuard]；其余未知方法按返回类型给零值。
     */
    private class Handler(private val owner: DetailViewRuleHider) : InvocationHandler {
        override fun invoke(proxy: Any, method: Method, args: Array<out Any?>?): Any? =
            when (method.name) {
                DetailViewPurifyPolicy.ATTACHED_CALLBACK -> {
                    HostThreadGuard.run("detail_view_purify.attached") {
                        owner.onChildAttached(args?.firstOrNull())
                    }
                    null
                }
                "equals" -> proxy === args?.firstOrNull()
                "hashCode" -> System.identityHashCode(proxy)
                "toString" -> "DetailViewRuleHider"
                else -> hostProxyDefaultValue(method.returnType)
            }
    }

    private companion object {
        const val TARGET_PACKAGE = "tv.danmaku.bili"
    }
}

/**
 * 一个 item 根在"占位"这件事上的全部可变状态。
 *
 * 抽成接口只为一件事：把**折叠/还原的簿记**（真正会出 bug 的部分）
 * 从 Android 框架里摘出来，可以直接单测。工程没有 Robolectric，
 * 真 `View` 在单测里是会抛的桩，测不了。
 */
internal interface ItemBox {
    /** 弱引用记录用的身份键。对真 View 就是它自己。 */
    val key: Any
    var height: Int
    var topMargin: Int
    var bottomMargin: Int
    var gone: Boolean
}

/** [ItemBox] 到真 `View` 的适配；只有属性转发，没有判断。 */
private class ViewItemBox(private val view: View) : ItemBox {

    private val params: ViewGroup.LayoutParams? = view.layoutParams
    private val margins: ViewGroup.MarginLayoutParams? =
        params as? ViewGroup.MarginLayoutParams

    override val key: Any get() = view

    override var height: Int
        get() = params?.height ?: 0
        set(value) {
            params?.let {
                it.height = value
                view.layoutParams = it
            }
        }

    override var topMargin: Int
        get() = margins?.topMargin ?: 0
        set(value) {
            margins?.let {
                it.topMargin = value
                view.layoutParams = it
            }
        }

    override var bottomMargin: Int
        get() = margins?.bottomMargin ?: 0
        set(value) {
            margins?.let {
                it.bottomMargin = value
                view.layoutParams = it
            }
        }

    override var gone: Boolean
        get() = view.isGone
        set(value) {
            view.isGone = value
        }
}

/** 一个内层控件在"可见性"这件事上的全部可变状态；抽成接口是为了让簿记可以脱离真 `View` 单测。 */
internal interface VisibilityBox {
    val key: Any
    var visibility: Int
}

/** [VisibilityBox] 到真 `View` 的适配；只有属性转发，没有判断。 */
private class ViewVisibilityBox(private val view: View) : VisibilityBox {
    override val key: Any get() = view
    override var visibility: Int
        get() = view.visibility
        set(value) {
            view.visibility = value
        }
}

/**
 * 内层（非 item 根）被隐藏控件的原始可见性账本。还原回隐藏前的值，而不是一律 VISIBLE：
 * 宿主原本设成 INVISIBLE 的控件不能被顺手变成可见。
 */
internal class InnerVisibilityBook {

    private val saved = WeakHashMap<Any, Int>()

    fun tracks(key: Any): Boolean = saved.containsKey(key)

    /** visibility != GONE 时记下原值并设 GONE，返回 true；已是 GONE 返回 false（不覆盖已记的原值）。 */
    fun hide(box: VisibilityBox): Boolean {
        if (box.visibility == View.GONE) return false
        saved[box.key] = box.visibility
        box.visibility = View.GONE
        return true
    }

    /** 有记录才还原：仍是 GONE 时恢复为记下的原值；无论是否改动都摘账。返回是否有记录。 */
    fun restore(box: VisibilityBox): Boolean {
        val original = saved.remove(box.key) ?: return false
        if (box.visibility == View.GONE) box.visibility = original
        return true
    }

    fun trackedKeys(): List<Any> = saved.keys.toList()
}

/**
 * 折叠过的 item 根的原始尺寸账本。
 *
 * 为什么需要它：`LinearLayoutManager` 自己测量子项，**不跳过 GONE 的孩子**，
 * 所以隐藏 item 根必须把高度和上下 margin 一起归零；
 * 而 RecyclerView 会**回收复用**视图，归零后必须能还原，
 * 否则同一个 View 对象被拿去承载别的内容时会变成一条永久空白项。
 *
 * 用 `WeakHashMap` 持键：账本不该让任何 item 视图活过它的 RecyclerView。
 */
internal class ItemCollapseBook {

    private class Saved(
        val height: Int,
        val topMargin: Int,
        val bottomMargin: Int,
        val gone: Boolean
    )

    private val saved = WeakHashMap<Any, Saved>()

    fun tracks(key: Any): Boolean = saved.containsKey(key)

    /**
     * @return 这次是否**真的**新折叠了一项。已折叠的返回 false，
     *   调用方据此避免把回收复用的视图重复记成 APPLIED——
     *   "报了 APPLIED"必须等于"真的藏掉了一个东西"。
     */
    fun collapse(box: ItemBox): Boolean {
        if (saved.containsKey(box.key)) {
            // 关键：**不能**重新记账，否则原始尺寸会被已经归零的值覆盖，还原就永远回不去。
            // 但 RecyclerView 的绑定过程可能重新写回 LayoutParams；重复挂载时必须重新压平
            // 当前几何，否则只设 GONE 仍会留下旧高度的空位。
            applyCollapsedGeometry(box)
            return false
        }
        saved[box.key] = Saved(box.height, box.topMargin, box.bottomMargin, box.gone)
        applyCollapsedGeometry(box)
        return true
    }

    private fun applyCollapsedGeometry(box: ItemBox) {
        box.height = 0
        box.topMargin = 0
        box.bottomMargin = 0
        box.gone = true
    }

    /**
     * 还原到折叠前的样子，**包括可见性**——宿主自己就把它设成 GONE 的情况下，
     * 不能"顺手"帮它变可见。
     *
     * @return 是否有记录可还原。
     */
    fun restore(box: ItemBox): Boolean {
        val original = saved.remove(box.key) ?: return false
        box.height = original.height
        box.topMargin = original.topMargin
        box.bottomMargin = original.bottomMargin
        box.gone = original.gone
        return true
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import android.os.Looper
import java.io.File
import java.lang.reflect.Method
import java.util.IdentityHashMap

/**
 * 在动态页 protobuf 边界过滤动态卡片，并按需清掉话题栏与顶部 UP 栏中的直播条目。
 *
 * **边界选择的依据**：9.11.0 里业务侧（`classes8.dex`）调用的是
 * `DynamicMossKtxKt.suspendDynAll(...)`，而那个协程包装内部就是
 * `DynamicMoss#dynAll(req, MossResponseHandler)` 的匿名回调；两者同在 `classes25.dex`，
 * 所以"跨 dex 引用为零"在这里**不代表没人调**——判断是否有真实调用点必须连生成的
 * `*MossKtxKt` 包装一起看。同步 `executeDynAll` 一并覆盖，构成双保险。
 *
 * 综合页（`dynAll`）与视频页（`dynVideo`）共用同一套判据：用户配置的关键词和发布者名单在
 * 两个标签页里含义一致，分开配置只会让人困惑。
 *
 * 判据（逐条动态）：
 * - 正文关键词：模块正文 + 转发原动态正文 + 本条正文，**逐段匹配**，命中即停。
 * - 发布者：`Extend.origName` / `Extend.uid`，与评论区共用 [AuthorRuleSet] 的全等语义。
 * - 推广附加卡：任一模块带 `ModuleAdditional`，且类型是带货或 UP 主推荐。
 * - 未解锁的充电专属：`Extend.onlyFansProperty.hasPrivilege == false`。
 *
 * 整份响应级：话题栏 `clearTopicList()`；顶部 UP 栏按 `liveStateValue > 0` 剔除直播中条目，
 * 并**重排 `pos`**（宿主按 pos 排序，不重排会留下空洞）。
 *
 * **版本覆盖（2026-09-06 离线核对 9.7.0–9.11.0 五版）**：四个 Moss 方法各只有一个重载；
 * 综合页容器是 `DynamicList`、视频页是 `CardVideoDynList`，两者元素同为 `DynamicItem`、
 * 读写成员同名，所以按返回类型解析即可；顶部 UP 栏 getter 在综合页叫 `getUpList`、视频页叫
 * `getVideoUpList`，返回类型都是 `CardVideoUpList`。
 *
 * 覆盖单位口径：每个装上的 Moss 边界算一个单位；每条被用户启用、但读取路径缺失的判据计入
 * 分母不计入分子，于是"开了却没生效"表现为 `partial`。
 */
internal class DynamicPurifyFeatureInstaller(
    keywordFilterEnabled: Boolean,
    rawKeywords: String,
    authorFilterEnabled: Boolean,
    rawAuthorRules: String,
    private val removePromotion: Boolean,
    private val removeLockedChargeOnly: Boolean,
    private val hideTopicList: Boolean,
    private val removeLiveUpEntries: Boolean,
    private val hideFrequentVisits: Boolean = false,
    /**
     * 「智能过滤动态」：开关打开且 JEV 配置有效时非空（见 [SemanticJudge.fromSettings]）。
     * 与其它设置一样只在宿主 attach 时确定；缓存只在内存，关闭开关重启后不留任何判定。
     */
    private val semanticJudge: SemanticJudge? = null,
    /** debug 构建的观测日志目录（宿主私有 files）；release 为 null，不写任何文件。 */
    private val semanticLogDir: File? = null,
    /** 主线程上只查缓存、绝不联网；单测可替换。 */
    private val isMainThread: () -> Boolean = { Looper.myLooper() == Looper.getMainLooper() }
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (keywords.isNotEmpty()) add("dynamic_keyword_filter_enabled")
        if (authorRules.isNotEmpty()) add("dynamic_author_filter_enabled")
        if (semanticJudge != null) add("dynamic_semantic_filter_enabled")
        if (removePromotion) add("dynamic_promotions_removed")
        if (removeLockedChargeOnly) add("dynamic_charge_only_removed")
        if (hideTopicList) add("dynamic_topic_list_hidden")
        if (removeLiveUpEntries && !hideFrequentVisits) add("dynamic_up_list_live_removed")
        if (hideFrequentVisits) add("dynamic_frequent_visits_hidden")
    }

    private val keywords = if (keywordFilterEnabled) {
        RuleSetCodec.parse(rawKeywords).take(MAX_KEYWORDS).toCollection(linkedSetOf())
    } else {
        emptySet()
    }
    private val authorRules = if (authorFilterEnabled) {
        AuthorRuleSet.parse(rawAuthorRules)
    } else {
        AuthorRuleSet.EMPTY
    }

    /** 只用于新通道观测的日志：Java 通道是否见过响应（两条通道是否并存）。 */
    private val javaPathObserved = java.util.concurrent.atomic.AtomicBoolean(false)

    private val anyRequested: Boolean
        get() = keywords.isNotEmpty() || authorRules.isNotEmpty() || removePromotion ||
            removeLockedChargeOnly || hideTopicList || removeLiveUpEntries || hideFrequentVisits ||
            semanticJudge != null

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!anyRequested) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val mossClass = environment.hookPoints.resolveClass("dynamic.purify.moss", DYNAMIC_MOSS_CLASS)
            ?: return missing(environment, "missing-moss-class")

        val itemMembers = if (hideFrequentVisits && keywords.isEmpty() && authorRules.isEmpty() &&
            !removePromotion && !removeLockedChargeOnly && semanticJudge == null) null else resolveItemMembers(loader)
        val plan = DynamicPurifyPolicy.Plan(
            keywords = if (itemMembers?.hasTextSource == true) keywords else emptySet(),
            authorRules = authorRules.available(itemMembers?.hasAuthorSource == true && itemMembers.author?.origName != null,
                itemMembers?.hasAuthorSource == true && itemMembers.author?.uid != null),
            removePromotion = removePromotion && itemMembers?.promotion != null,
            removeLockedChargeOnly = removeLockedChargeOnly && itemMembers?.chargeOnly != null,
            semanticEnabled = semanticJudge != null && itemMembers?.hasTextSource == true
        )
        if (semanticJudge != null) {
            val state = if (plan.semanticEnabled) "active rules=${semanticJudge.rules.joinToString(",") { it.id }} " +
                "host=${semanticJudge.endpoint.let { runCatching { java.net.URL(it).host }.getOrNull() }} " +
                "threshold=${semanticJudge.blockThreshold} mode=${if (semanticJudge.waitFirstScreen) "wait" else "pass"}"
            else "missing-text-source"
            environment.logInfo("dynamic_semantic_filter", "[BIL] 智能过滤动态: $state")
            semanticLogDir?.let { SemanticDebugLog.append(it, "${System.currentTimeMillis()} install $state") }
        }

        val feeds = FEED_METHODS.mapNotNull { spec -> resolveFeed(loader, mossClass, spec) }.filter { feed ->
            (plan.hasAnyItemJudgement && feed.listBuilder != null) ||
                (hideTopicList && feed.clearTopicList != null) || (removeLiveUpEntries && feed.upList != null) ||
                (hideFrequentVisits && feed.wholeUpList != null)
        }
        if (feeds.isEmpty()) return missing(environment, "no-dynamic-hook-point")

        val handlerClass = KavaMemberLookup.classOrNull(loader, MOSS_HANDLER_CLASS)
        var installed = 0
        var expected = 0
        val pathsByFeed = hashMapOf<FeedMembers, Int>()

        feeds.forEach { feed ->
            val before = installed
            feed.syncMethod?.let { method ->
                expected += 1
                if (installSync(environment, method, feed, itemMembers, plan)) installed += 1
            }
            val async = feed.asyncMethod
            if (async != null && handlerClass != null) {
                expected += 1
                if (installAsync(environment, async, handlerClass, feed, itemMembers, plan)) {
                    installed += 1
                }
            }
            pathsByFeed[feed] = installed - before
        }
        if (installed == 0) return missing(environment, "registration-failed")
        val sharedExpected = FEED_METHODS.size * 2
        for (capability in capabilityIds) {
            val compatibleFeeds = feeds.filter { feed -> when (capability) {
                "dynamic_frequent_visits_hidden" -> feed.wholeUpList != null
                "dynamic_topic_list_hidden" -> feed.clearTopicList != null
                "dynamic_up_list_live_removed" -> feed.upList != null
                else -> feed.listBuilder != null
            } }
            val usable = when (capability) {
                "dynamic_keyword_filter_enabled" -> plan.keywords.isNotEmpty()
                "dynamic_author_filter_enabled" -> plan.authorRules.isNotEmpty()
                "dynamic_semantic_filter_enabled" -> plan.semanticEnabled
                "dynamic_promotions_removed" -> plan.removePromotion
                "dynamic_charge_only_removed" -> plan.removeLockedChargeOnly
                "dynamic_frequent_visits_hidden" -> feeds.any { it.wholeUpList != null }
                "dynamic_topic_list_hidden" -> feeds.any { it.clearTopicList != null }
                "dynamic_up_list_live_removed" -> feeds.any { it.upList != null }
                else -> false
            }
            val completeData = when (capability) {
                "dynamic_frequent_visits_hidden" -> feeds.size == FEED_METHODS.size && feeds.all { it.wholeUpList != null }
                "dynamic_topic_list_hidden" -> feeds.size == FEED_METHODS.size && feeds.all { it.clearTopicList != null }
                "dynamic_up_list_live_removed" -> feeds.size == FEED_METHODS.size && feeds.all { it.upList != null }
                else -> feeds.size == FEED_METHODS.size && feeds.all { it.listBuilder != null } &&
                    (capability != "dynamic_author_filter_enabled" || plan.authorRules == authorRules)
            }
            environment.reportCapabilityCoverage(capability, usable && compatibleFeeds.isNotEmpty(), compatibleFeeds.sumOf { pathsByFeed[it] ?: 0 },
                sharedExpected + if (completeData) 0 else 1)
        }
        expected = sharedExpected

        // 用户开了但读不到的判据必须留在分母里。
        val degraded = ArrayList<String>(4)
        if (plan.hasAnyItemJudgement && feeds.any { it.listBuilder == null }) {
            expected++; degraded += "item-carrier"
        }
        fun account(requested: Boolean, usable: Boolean, label: String) {
            if (!requested) return
            expected += 1
            if (usable) installed += 1 else degraded += label
        }
        account(keywords.isNotEmpty(), plan.keywords.isNotEmpty(), "keyword")
        account(authorRules.isNotEmpty(), plan.authorRules == authorRules, "author")
        account(semanticJudge != null, plan.semanticEnabled, "semantic")
        account(removePromotion, plan.removePromotion, "promotion")
        account(removeLockedChargeOnly, plan.removeLockedChargeOnly, "charge-only")
        account(hideTopicList, feeds.any { it.clearTopicList != null }, "topic-list")
        account(removeLiveUpEntries && !hideFrequentVisits, feeds.any { it.upList != null }, "up-live")
        account(hideFrequentVisits, feeds.size == FEED_METHODS.size && feeds.all { it.wholeUpList != null }, "frequent-visits")
        if (degraded.isNotEmpty()) {
            environment.logError(
                "dynamic_purify_degraded",
                "[BIL] 动态页净化判据缺少可用读取路径: ${degraded.joinToString(",")}"
            )
        }

        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        // 9.14.0 新增 Compose 动态列表，走 Kotlin KDynamicMoss。优先直接在它的响应上复用同一套过滤
        // （经 protobuf 线格式往返到 Java 响应）；装不上时退回"只观测并留证据"，不再静默失效。
        val covered = installKotlinMoss(environment, loader, feeds, itemMembers, plan)
        // 只接上一部分页签时，剩下的入口仍要观测：否则没覆盖上的那条通道一条错误证据都不会有，
        // 而 status 只按 Java 通道算，照样报 success——正是这里要消灭的静默失效。
        if (covered.size == FEED_METHODS.size) {
            environment.logInfo("dynamic_kmoss_filter", "[BIL] 已接入动态页新通道 KDynamicMoss 过滤，entries=${covered.size}")
        } else {
            val kotlinWatch = KotlinDynamicMossWatch.install(
                environment, loader, capabilityIds + ID, { javaPathObserved.get() }, covered
            )
            if (kotlinWatch > 0) {
                environment.logInfo("dynamic_kmoss_watch", "[BIL] 已观测动态页新通道 KDynamicMoss，entries=$kotlinWatch")
            }
        }
        val status = if (installed == expected) "success" else "partial:$installed/$expected"
        environment.reportStatus(CHANNEL_STATUS, status)
        if (status == "success") {
            environment.logInfo(
                "dynamic_purify_ok",
                "[BIL] 动态页净化已安装，hooks=$installed，判据=${plan.describe()}"
            )
        } else {
            environment.logError(
                "dynamic_purify_partial",
                "[BIL] 动态页净化部分安装，status=$status"
            )
        }
        return FeatureInstallResult.Installed(installed, complete = installed == expected)
    }

    private fun installSync(
        environment: HookEnvironment,
        method: Method,
        feed: FeedMembers,
        itemMembers: ItemMembers?,
        plan: DynamicPurifyPolicy.Plan
    ): Boolean = runCatching {
        environment.registrar.exact(
            "dynamic.purify.sync.${method.name}",
            method.declaringClass,
            method.name,
            *method.parameterTypes
        ) {
            after {
                if (hasThrowable) return@after
                val reply = result ?: return@after
                result = purify(environment, reply, feed, itemMembers, plan)
            }
        }
        true
    }.getOrElse { throwable ->
        environment.logError(
            "dynamic_purify_sync_${method.name}",
            "[BIL] 动态页净化同步边界注册失败(${method.name}): $throwable"
        )
        false
    }

    private fun installAsync(
        environment: HookEnvironment,
        method: Method,
        handlerClass: Class<*>,
        feed: FeedMembers,
        itemMembers: ItemMembers?,
        plan: DynamicPurifyPolicy.Plan
    ): Boolean = runCatching {
        environment.registrar.exact(
            "dynamic.purify.async.${method.name}",
            method.declaringClass,
            method.name,
            *method.parameterTypes
        ) {
            before {
                val delegate = args.getOrNull(1) ?: return@before
                val proxy = MossResponseHandlerProxy.wrapTransform(handlerClass, delegate) {
                    purify(environment, it, feed, itemMembers, plan)
                } ?: return@before
                args[1] = proxy
            }
        }
        true
    }.getOrElse { throwable ->
        environment.logError(
            "dynamic_purify_async_${method.name}",
            "[BIL] 动态页净化异步边界注册失败(${method.name}): $throwable"
        )
        false
    }

    /**
     * 9.14.0 起动态页新列表的数据通道 `KDynamicMoss`：响应是 Kotlin 序列化数据类（字段被混淆），
     * 这里不解析它，而是经 protobuf 线格式往返到同一 proto 的 Java 响应上，**原样复用 [purify]**，
     * 见 [KotlinMossReplyBridge]。Kotlin 版所有请求（suspend / 回调）汇入同一个回调形态泛型入口，
     * 每个页签挂一处即可。任何一步装不上都不进这个集合，调用方据此退回观测措施；运行期任何异常都放行原响应。
     *
     * @return 已经接住过滤的入口名（[KotlinDynamicMossWatch] 据此只观测没接上的那些）。
     */
    private fun installKotlinMoss(
        environment: HookEnvironment,
        loader: ClassLoader,
        feeds: List<FeedMembers>,
        itemMembers: ItemMembers?,
        plan: DynamicPurifyPolicy.Plan
    ): Set<String> {
        val kotlinMoss = KavaMemberLookup.classOrNull(loader, KotlinDynamicMossWatch.K_MOSS_CLASS) ?: return emptySet()
        val members = KotlinMossBridgeMembers.resolve(loader)
        if (members == null) {
            environment.logInfo("dynamic_kmoss_filter_skip", "[BIL] 动态页新通道过滤未安装: kotlinx.serialization 成员缺失")
            return emptySet()
        }
        if (!KotlinMossBridgeSelfTest.allows(environment, loader, members, "动态页")) return emptySet()
        val installed = mutableSetOf<String>()
        FEED_METHODS.forEach { spec ->
            // 装不上不能再静默：每个页签只在缺东西时记一条原因（有界：页签个数）。
            fun skip(reason: String) = environment.logInfo(
                "dynamic_kmoss_filter_skip_${spec.asyncName}",
                "[BIL] 动态页新通道过滤跳过 ${spec.asyncName}: $reason"
            )
            val feed = feeds.firstOrNull { it.replyClass.name == spec.replyClassName } ?: return@forEach skip("no-java-feed")
            val codec = KotlinMossBridgeMembers.JavaReplyCodec.resolve(feed.replyClass) ?: return@forEach skip("no-java-codec")
            val entry = KotlinMossBridgeMembers.callbackEntry(kotlinMoss, spec.asyncName) ?: return@forEach skip("no-callback-entry")
            val handlerClass = entry.parameterTypes[3]
            val reported = java.util.concurrent.atomic.AtomicBoolean(false)
            val called = java.util.concurrent.atomic.AtomicBoolean(false)
            runCatching {
                environment.registrar.exact(
                    "dynamic.purify.kmoss.${spec.asyncName}",
                    entry.declaringClass,
                    entry.name,
                    *entry.parameterTypes
                ) {
                    before {
                        if (called.compareAndSet(false, true)) {
                            environment.logInfo(
                                "dynamic_kmoss_call",
                                "[BIL] 动态页新通道请求已进入 KDynamicMoss#${entry.name}"
                            )
                        }
                        val delegate = args.getOrNull(3) ?: return@before
                        val bridge = members.bridgeFor(args.getOrNull(4), args.getOrNull(2), codec)
                            ?: return@before
                        val proxy = MossResponseHandlerProxy.wrapTransform(handlerClass, delegate) { reply ->
                            if (reported.compareAndSet(false, true)) {
                                environment.logInfo(
                                    "dynamic_kmoss_active",
                                    "[BIL] 动态页新通道 KDynamicMoss#${entry.name} 已收到响应并进入过滤" +
                                        "（javaPathObserved=${javaPathObserved.get()}）"
                                )
                            }
                            runCatching {
                                bridge.transform(reply) { javaReply ->
                                    purify(environment, javaReply, feed, itemMembers, plan)
                                }
                            }.getOrElse { throwable ->
                                environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ERROR)
                                environment.logError(
                                    "dynamic_kmoss_filter_failed",
                                    "[BIL] 动态页新通道过滤失败，已放行原响应(${entry.name}): $throwable"
                                )
                                reply
                            }
                        } ?: return@before
                        args[3] = proxy
                    }
                }
                installed += spec.asyncName
            }.onFailure { throwable ->
                environment.logError(
                    "dynamic_kmoss_filter_${spec.asyncName}",
                    "[BIL] 动态页新通道过滤注册失败(${spec.asyncName}): $throwable"
                )
            }
        }
        return installed
    }

    /** 两条链路共用；未改原响应，成功时返回副本；处理已净化副本时保持幂等。 */
    private fun purify(
        environment: HookEnvironment,
        reply: Any,
        feed: FeedMembers,
        itemMembers: ItemMembers?,
        plan: DynamicPurifyPolicy.Plan
    ): Any {
        if (!feed.replyClass.isInstance(reply)) return reply
        // 字段未设置时宿主拿到的是进程级单例，改它会污染整个进程。
        if (feed.defaultReply != null && reply === feed.defaultReply) return reply
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
        javaPathObserved.set(true)
        var removingWhole = false
        return runCatching {
            val items = purifyItems(reply, feed, itemMembers, plan)
            val clearTopic = hideTopicList && feed.clearTopicList != null &&
                feed.hasTopicList?.let { invoke(it, reply) as? Boolean } == true
            val whole = feed.wholeUpList
            val clearWhole = hideFrequentVisits && whole != null && invoke(whole.has, reply) == true
            removingWhole = clearWhole
            if (clearWhole) environment.reportRuntimeEvidence("dynamic_frequent_visits_hidden", FeatureRuntimeStage.OBSERVED)
            val upList = purifyUpList(reply, feed)
            if (items == null && !clearTopic && !clearWhole && upList == null) return@runCatching reply
            val updated = feed.builder.edit(reply) { builder ->
                if (items != null) feed.setDynamicList!!.invoke(builder, items)
                if (clearTopic) feed.clearTopicList.invoke(builder)
                if (clearWhole) whole!!.clear.invoke(builder)
                if (upList != null) feed.upList!!.setter.invoke(builder, upList)
            }
            if (clearWhole) {
                check(invoke(whole!!.has, updated) == false) { "UP container clear verification failed" }
                environment.reportRuntimeEvidence("dynamic_frequent_visits_hidden", FeatureRuntimeStage.APPLIED)
            }
            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
            updated
        }.getOrElse {
            if (removingWhole) environment.reportRuntimeEvidence("dynamic_frequent_visits_hidden", FeatureRuntimeStage.ERROR)
            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ERROR)
            environment.logError("dynamic_purify_writeback", "[BIL] 动态净化副本构建失败，保留原响应: $it")
            reply
        }
    }

    private fun purifyItems(
        reply: Any,
        feed: FeedMembers,
        itemMembers: ItemMembers?,
        plan: DynamicPurifyPolicy.Plan
    ): Any? {
        if (itemMembers == null || !plan.hasAnyItemJudgement) return null
        val listBuilder = feed.listBuilder ?: return null
        val clearList = feed.clearList ?: return null
        val addAllList = feed.addAllList ?: return null
        val dynamicList = invoke(feed.dynamicListGetter, reply) ?: return null
        val items = invoke(feed.listGetter, dynamicList) as? List<*> ?: return null
        if (items.isEmpty()) return null
        val semantic = if (plan.semanticEnabled) semanticVerdicts(items, itemMembers) else null
        val retained = ProtobufListRetention.retainOrNull(items) { item ->
            val semanticBlocked = semantic?.get(item) == SemanticVerdict.BLOCK
            !DynamicPurifyPolicy.shouldRemove(readSignals(item, itemMembers, plan, semanticBlocked), plan)
        } ?: return null
        val removed = items.size - retained.size
        if (removed <= 0) return null
        return listBuilder.edit(dynamicList) { builder ->
            clearList.invoke(builder)
            addAllList.invoke(builder, retained)
        }
    }

    private fun purifyUpList(reply: Any, feed: FeedMembers): Any? {
        if (!removeLiveUpEntries || hideFrequentVisits) return null
        val up = feed.upList ?: return null
        val container = invoke(up.getter, reply) ?: return null
        // 两个列表必须都读到才动手：只读到一个就写回，会把读不到的那个直接清空。
        val first = invoke(up.listGetter, container) as? List<*> ?: return null
        val second = invoke(up.listSecondGetter, container) as? List<*> ?: return null
        if (first.isEmpty() && second.isEmpty()) return null

        val keep: (Any) -> Boolean = { item ->
            // 读不出直播状态时保留：只删明确在直播的条目。
            val state = (invoke(up.liveStateValue, item) as? Number)?.toInt()
            state == null || state <= 0
        }
        val retainedFirst = ProtobufListRetention.retainOrNull(first, keep)
        val retainedSecond = ProtobufListRetention.retainOrNull(second, keep)
        if (retainedFirst == null && retainedSecond == null) return null

        val newFirst = retainedFirst ?: first.filterNotNull()
        val newSecond = retainedSecond ?: second.filterNotNull()
        val removed = (first.size - newFirst.size) + (second.size - newSecond.size)
        if (removed <= 0) return null
        // 子项也复制：容器 builder 的列表可能共享原始元素，不能直接改原元素的 pos。
        var position = 1L
        fun positioned(items: List<Any>): List<Any> = items.map { item ->
            up.itemBuilder.edit(item) { builder -> up.setPos.invoke(builder, position++) }
        }
        val positionedFirst = positioned(newFirst)
        val positionedSecond = positioned(newSecond)
        return up.builder.edit(container) { builder ->
            up.clearList.invoke(builder)
            up.addAllList.invoke(builder, positionedFirst)
            up.clearListSecond.invoke(builder)
            up.addAllListSecond.invoke(builder, positionedSecond)
        }
    }

    /**
     * 语义判定，三种路径：
     * - 主线程：只查缓存（绝不联网）。
     * - 首屏等待（`waitFirstScreen`）：在当前后台线程（Moss 回调）同步联网，带超时与冷却。
     * - 首屏放行（默认）：先用缓存结果放行，未命中投递到模块后台线程判定，结果进缓存，下次加载生效。
     * 任何失败都是 UNKNOWN（规则照常，fail-open）。
     *
     * 结果按列表 memo：列表 getter 在滚动与绑定时会被反复调用，没有 memo 就会每调一次把整页
     * 动态的正文重新反射一遍再拼一遍。
     */
    private fun semanticVerdicts(items: List<*>, members: ItemMembers): IdentityHashMap<Any, SemanticVerdict>? {
        val judge = semanticJudge ?: return null
        return semanticMemo.getOrCompute(items) { computeSemanticVerdicts(items, members) }
    }

    private val semanticMemo = SemanticListMemo()

    private fun computeSemanticVerdicts(
        items: List<*>,
        members: ItemMembers
    ): IdentityHashMap<Any, SemanticVerdict>? {
        val judge = semanticJudge ?: return null
        val present = items.filterNotNull()
        val texts = present.map { semanticText(it, members) }
        val mode = when {
            isMainThread() -> SemanticMode.CACHE_ONLY
            judge.waitFirstScreen -> SemanticMode.WAIT
            else -> SemanticMode.PREFETCH
        }
        val logDir = semanticLogDir
        val verdicts = judge.evaluate(
            texts,
            mode,
            onReport = logDir?.let { dir -> { report, batch, result -> logSemanticBatch(dir, report, batch, result) } }
        )
        return IdentityHashMap<Any, SemanticVerdict>(present.size).apply {
            present.forEachIndexed { index, item -> put(item, verdicts[index]) }
        }
    }

    /** 送判文本：同一条动态的各段正文按行拼接（这里是给模型读的，不做关键词匹配，拼接无假命中问题）。 */
    private fun semanticText(item: Any, members: ItemMembers): String {
        val extend = members.extendGetter?.let { invoke(it, item) }
        val modules = members.modulesGetter?.let { invoke(it, item) as? List<*> }
        val parts = LinkedHashSet<String>()
        streamText(members, extend, modules) { fragment -> parts += fragment.trim(); false }
        return parts.filter(String::isNotEmpty).joinToString("\n")
    }

    private fun logSemanticBatch(
        directory: File,
        report: SemanticBatchReport,
        texts: List<String>,
        verdicts: List<SemanticVerdict>
    ) {
        val preview = texts.indices.joinToString(" | ") { index ->
            "${verdicts[index].name.first()}:${texts[index].replace('\n', ' ').take(24)}"
        }
        SemanticDebugLog.append(
            directory,
            "${System.currentTimeMillis()} batch thread=${Thread.currentThread().name} total=${report.total} " +
                "hits=${report.cacheHits} requested=${report.requested} blocked=${report.blocked} " +
                "ms=${report.elapsedMs} outcome=${report.outcome}${report.extras()} :: $preview"
        )
    }

    private fun readSignals(
        item: Any,
        members: ItemMembers,
        plan: DynamicPurifyPolicy.Plan,
        semanticBlocked: Boolean = false
    ): DynamicPurifyPolicy.Signals {
        // 语义判定自己读正文（semanticText），这里只在配了关键词时读，避免每条多几次反射。
        val needsKeywordText = plan.keywords.isNotEmpty()
        val extend = if (needsKeywordText || plan.needsAuthor || plan.removeLockedChargeOnly) {
            members.extendGetter?.let { invoke(it, item) }
        } else {
            null
        }
        val modules = if (needsKeywordText || plan.removePromotion) {
            members.modulesGetter?.let { invoke(it, item) as? List<*> }
        } else {
            null
        }

        var authorName: String? = null
        var authorMid: Long? = null
        if (plan.needsAuthor && extend != null) {
            authorName = (invoke(members.author?.origName, extend) as? String)
                ?.takeIf(String::isNotBlank)
            authorMid = (invoke(members.author?.uid, extend) as? Number)?.toLong()
                ?.takeIf { it > 0L }
        }

        val promotion = plan.removePromotion && modules != null &&
            members.promotion?.let { promo -> modules.any { isPromotionModule(it, promo) } } == true

        val lockedChargeOnly = plan.removeLockedChargeOnly && extend != null &&
            members.chargeOnly?.let { isLockedChargeOnly(extend, it) } == true

        return DynamicPurifyPolicy.Signals(
            authorName = authorName,
            authorMid = authorMid,
            promotion = promotion,
            lockedChargeOnly = lockedChargeOnly,
            semanticBlocked = semanticBlocked,
            textFragments = { matches -> streamText(members, extend, modules, matches) }
        )
    }

    /** 逐段回调正文；任一段命中立即返回 true，不再继续读后面的段落。 */
    private fun streamText(
        members: ItemMembers,
        extend: Any?,
        modules: List<*>?,
        matches: (String) -> Boolean
    ): Boolean {
        val text = members.text ?: return false
        if (modules != null && text.moduleDescText != null) {
            modules.forEach { module ->
                module ?: return@forEach
                if (text.hasModuleDesc != null &&
                    invoke(text.hasModuleDesc, module) as? Boolean != true
                ) {
                    return@forEach
                }
                val desc = invoke(text.moduleDescGetter, module) ?: return@forEach
                val value = invoke(text.moduleDescText, desc) as? String
                if (!value.isNullOrEmpty() && matches(value)) return true
            }
        }
        if (extend == null || text.descOrigText == null) return false
        listOfNotNull(text.origDescList, text.descList).forEach { getter ->
            val descriptions = invoke(getter, extend) as? List<*> ?: return@forEach
            descriptions.forEach { description ->
                description ?: return@forEach
                val value = invoke(text.descOrigText, description) as? String
                if (!value.isNullOrEmpty() && matches(value)) return true
            }
        }
        return false
    }

    private fun isPromotionModule(module: Any?, promotion: PromotionMembers): Boolean {
        module ?: return false
        if (invoke(promotion.hasAdditional, module) as? Boolean != true) return false
        val additional = invoke(promotion.additionalGetter, module) ?: return false
        val type = (invoke(promotion.typeValue, additional) as? Number)?.toInt() ?: return false
        return type in promotion.promotedTypes
    }

    private fun isLockedChargeOnly(extend: Any, charge: ChargeOnlyMembers): Boolean {
        if (invoke(charge.hasProperty, extend) as? Boolean != true) return false
        val property = invoke(charge.propertyGetter, extend) ?: return false
        // 只删明确"没有观看权限"的；读不出来时保留。
        return invoke(charge.hasPrivilege, property) as? Boolean == false
    }

    private fun invoke(method: Method?, target: Any?): Any? {
        if (method == null || target == null || !method.declaringClass.isInstance(target)) {
            return null
        }
        return runCatching { method.invoke(target) }.getOrNull()
    }

    // ---- 安装期结构定位 ----------------------------------------------------

    private fun resolveFeed(
        loader: ClassLoader,
        mossClass: Class<*>,
        spec: FeedSpec
    ): FeedMembers? {
        val replyClass = KavaMemberLookup.classOrNull(loader, spec.replyClassName) ?: return null
        val builder = ProtobufBuilderPlan.resolve(replyClass) ?: return null
        val dynamicListGetter = objectGetter(replyClass, "getDynamicList")
        // 容器类名两个页签不同（综合 DynamicList / 视频 CardVideoDynList），所以按返回类型取，
        // 不写死类名。但**必须验证元素类型确实是 DynamicItem**：否则条目判据会因为
        // declaringClass 不匹配而全部读成 null，表现为"装上了却一条都不删"的静默无效。
        val listClass = dynamicListGetter?.returnType
        val listBuilder = listClass?.let(ProtobufBuilderPlan::resolve)
        val setDynamicList = listClass?.let { builder.method("setDynamicList", it) }
        val itemClass = KavaMemberLookup.classOrNull(loader, DYNAMIC_ITEM_CLASS)
        val indexedGetter = listClass?.let { KavaMemberLookup.methodOrNull(it, "getList", classOf<Int>()) }
        val listGetter = listClass?.let { listGetter(it, "getListList") }
        val clearList = listBuilder?.method("clearList")
        val addAllList = listBuilder?.method("addAllList", classOf<Iterable<*>>())
        val itemCarrierReady = itemClass != null && indexedGetter?.returnType == itemClass &&
            setDynamicList != null && listGetter != null && clearList != null && addAllList != null

        val syncMethod = KavaMemberLookup.declaredMethods(mossClass, makeAccessible = true) {
            !it.isStatic && it.name == spec.syncName && it.parameterCount == 1 &&
                it.returnType == replyClass
        }.singleOrNull()
        val asyncMethod = KavaMemberLookup.declaredMethods(mossClass, makeAccessible = true) {
            !it.isStatic && it.name == spec.asyncName && it.parameterCount == 2 &&
                it.returnType == Void.TYPE &&
                it.parameterTypes[1].name == MOSS_HANDLER_CLASS
        }.singleOrNull()
        if (syncMethod == null && asyncMethod == null) return null

        val hasTopic = booleanNoArg(replyClass, "hasTopicList")
        val clearTopic = builder.method("clearTopicList")
        val upList = if (removeLiveUpEntries && !hideFrequentVisits) resolveUpList(loader, replyClass, builder) else null
        val wholeUpList = if (hideFrequentVisits) resolveWholeUpList(replyClass, builder) else null

        return FeedMembers(
            replyClass = replyClass,
            builder = builder,
            listBuilder = listBuilder?.takeIf { itemCarrierReady },
            setDynamicList = setDynamicList,
            dynamicListGetter = dynamicListGetter,
            listGetter = listGetter,
            clearList = clearList,
            addAllList = addAllList,
            defaultReply = defaultInstance(replyClass),
            hasTopicList = hasTopic?.takeIf { clearTopic != null },
            clearTopicList = clearTopic?.takeIf { hasTopic != null },
            upList = upList,
            wholeUpList = wholeUpList,
            syncMethod = syncMethod,
            asyncMethod = asyncMethod
        )
    }

    /** Resolve only the whole carrier; avatar/live/position fields are deliberately not dependencies. */
    private fun resolveWholeUpList(reply: Class<*>, builder: ProtobufBuilderPlan): WholeUpListMembers? =
        UP_LIST_GETTERS.mapNotNull { getterName ->
            val getter = objectGetter(reply, getterName) ?: return@mapNotNull null
            if (getter.returnType.name != "$DYNAMIC_PACKAGE.CardVideoUpList") return@mapNotNull null
            val suffix = getterName.removePrefix("get")
            val has = booleanNoArg(reply, "has$suffix") ?: return@mapNotNull null
            val clear = builder.method("clear$suffix") ?: return@mapNotNull null
            WholeUpListMembers(has, clear)
        }.singleOrNull()

    private class WholeUpListMembers(val has: Method, val clear: Method)

    private fun resolveUpList(loader: ClassLoader, replyClass: Class<*>, replyBuilder: ProtobufBuilderPlan): UpListMembers? {
        // 综合页叫 getUpList、视频页叫 getVideoUpList，但返回的都是同一个 CardVideoUpList。
        // 9.7.0–9.11.0 五个版本都是这两个名字之一，按顺序取第一个能解析到的。
        val containerGetter = UP_LIST_GETTERS.firstNotNullOfOrNull { name ->
            objectGetter(replyClass, name)
        } ?: return null
        val container = containerGetter.returnType
        val builder = ProtobufBuilderPlan.resolve(container) ?: return null
        val setter = replyBuilder.method("set" + containerGetter.name.removePrefix("get"), container) ?: return null
        val primaryList = listGetter(container, "getListList") ?: return null
        val secondaryList = listGetter(container, "getListSecondList") ?: return null
        val clearPrimary = builder.method("clearList") ?: return null
        val clearSecondary = builder.method("clearListSecond") ?: return null
        val addAllPrimary = builder.method("addAllList", classOf<Iterable<*>>()) ?: return null
        val addAllSecondary = builder.method("addAllListSecond", classOf<Iterable<*>>()) ?: return null
        val itemClass = KavaMemberLookup.classOrNull(loader, UP_LIST_ITEM_CLASS) ?: return null
        val itemBuilder = ProtobufBuilderPlan.resolve(itemClass) ?: return null
        val liveState = intNoArg(itemClass, "getLiveStateValue") ?: return null
        val positionSetter = itemBuilder.method("setPos", classOf<Long>()) ?: return null
        return UpListMembers(
            getter = containerGetter,
            setter = setter,
            builder = builder,
            itemBuilder = itemBuilder,
            listGetter = primaryList,
            listSecondGetter = secondaryList,
            clearList = clearPrimary,
            clearListSecond = clearSecondary,
            addAllList = addAllPrimary,
            addAllListSecond = addAllSecondary,
            liveStateValue = liveState,
            setPos = positionSetter
        )
    }

    private fun resolveItemMembers(loader: ClassLoader): ItemMembers? {
        val itemClass = KavaMemberLookup.classOrNull(loader, DYNAMIC_ITEM_CLASS) ?: return null
        val extendGetter = objectGetter(itemClass, "getExtend")
        val modulesGetter = listGetter(itemClass, "getModulesList")
        val moduleClass = KavaMemberLookup.classOrNull(loader, MODULE_CLASS)
        val descriptionClass = KavaMemberLookup.classOrNull(loader, DESCRIPTION_CLASS)

        val text = run {
            val moduleDescGetter = moduleClass?.let { objectGetter(it, "getModuleDesc") }
            val moduleDescText = moduleDescGetter?.returnType?.let { stringNoArg(it, "getText") }
            val descOrigText = descriptionClass?.let { stringNoArg(it, "getOrigText") }
            val origDescList = extendGetter?.returnType?.let { listGetter(it, "getOrigDescList") }
            val descList = extendGetter?.returnType?.let { listGetter(it, "getDescList") }
            val hasModuleSource = modulesGetter != null && moduleDescGetter != null &&
                moduleDescText != null
            val hasExtendSource = descOrigText != null && (origDescList != null || descList != null)
            if (!hasModuleSource && !hasExtendSource) {
                null
            } else {
                TextMembers(
                    hasModuleDesc = moduleClass?.let { booleanNoArg(it, "hasModuleDesc") },
                    moduleDescGetter = moduleDescGetter?.takeIf { hasModuleSource },
                    moduleDescText = moduleDescText?.takeIf { hasModuleSource },
                    origDescList = origDescList?.takeIf { hasExtendSource },
                    descList = descList?.takeIf { hasExtendSource },
                    descOrigText = descOrigText?.takeIf { hasExtendSource }
                )
            }
        }

        val author = extendGetter?.returnType?.let { extendClass ->
            val origName = stringNoArg(extendClass, "getOrigName")
            val uid = longNoArg(extendClass, "getUid")
            if (origName == null && uid == null) null else AuthorMembers(origName, uid)
        }

        val promotion = run {
            val hasAdditional = moduleClass?.let { booleanNoArg(it, "hasModuleAdditional") }
            val additionalGetter = moduleClass?.let { objectGetter(it, "getModuleAdditional") }
            val typeValue = additionalGetter?.returnType?.let { intNoArg(it, "getTypeValue") }
            if (modulesGetter == null || hasAdditional == null || additionalGetter == null ||
                typeValue == null
            ) {
                null
            } else {
                PromotionMembers(
                    hasAdditional = hasAdditional,
                    additionalGetter = additionalGetter,
                    typeValue = typeValue,
                    promotedTypes = resolvePromotedTypes(loader)
                )
            }
        }

        val chargeOnly = extendGetter?.returnType?.let { extendClass ->
            val hasProperty = booleanNoArg(extendClass, "hasOnlyFansProperty")
            val propertyGetter = objectGetter(extendClass, "getOnlyFansProperty")
            val hasPrivilege = propertyGetter?.returnType?.let {
                booleanNoArg(it, "getHasPrivilege")
            }
            if (hasProperty == null || propertyGetter == null || hasPrivilege == null) {
                null
            } else {
                ChargeOnlyMembers(hasProperty, propertyGetter, hasPrivilege)
            }
        }

        return ItemMembers(
            extendGetter = extendGetter,
            modulesGetter = modulesGetter,
            text = text,
            author = author,
            promotion = promotion,
            chargeOnly = chargeOnly
        )
    }

    /** 优先读宿主 `AdditionalType` 上的具名常量，读不到才退回文档值。 */
    private fun resolvePromotedTypes(loader: ClassLoader): Set<Int> {
        val typeClass = KavaMemberLookup.classOrNull(loader, ADDITIONAL_TYPE_CLASS)
            ?: return DynamicPurifyPolicy.FALLBACK_PROMOTION_ADDITIONAL_TYPES
        val resolved = DynamicPurifyPolicy.PROMOTION_ADDITIONAL_TYPE_FIELDS.mapNotNull { name ->
            KavaMemberLookup.fieldOrNull(typeClass, name)
                ?.takeIf { it.isStatic && it.type == classOf<Int>() }
                ?.let { runCatching { it.getInt(null) }.getOrNull() }
        }.toSet()
        return resolved.takeIf {
            it.size == DynamicPurifyPolicy.PROMOTION_ADDITIONAL_TYPE_FIELDS.size
        } ?: DynamicPurifyPolicy.FALLBACK_PROMOTION_ADDITIONAL_TYPES
    }

    private fun defaultInstance(owner: Class<*>): Any? =
        KavaMemberLookup.methodOrNull(owner, "getDefaultInstance")
            ?.takeIf { it.isStatic && it.parameterCount == 0 && it.returnType == owner }
            ?.let { runCatching { it.invoke(null) }.getOrNull() }

    private fun objectGetter(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf {
            !it.isStatic && it.parameterCount == 0 && !it.returnType.isPrimitive
        }

    private fun listGetter(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf {
            !it.isStatic && it.parameterCount == 0 && it.returnType isSubclassOf classOf<List<*>>()
        }

    private fun stringNoArg(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf {
            !it.isStatic && it.parameterCount == 0 && it.returnType == classOf<String>()
        }

    private fun booleanNoArg(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf {
            !it.isStatic && it.parameterCount == 0 && it.returnType == classOf<Boolean>()
        }

    private fun intNoArg(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf {
            !it.isStatic && it.parameterCount == 0 && it.returnType == classOf<Int>()
        }

    private fun longNoArg(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf {
            !it.isStatic && it.parameterCount == 0 && it.returnType == classOf<Long>()
        }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "dynamic_purify_missing",
            "[BIL] 动态页净化适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    // ---- 安装期解析出来的运行期成员（只持有 Class/Method，不持有宿主实例） -------

    private class FeedSpec(
        val replyClassName: String,
        val syncName: String,
        val asyncName: String
    )

    private class FeedMembers(
        val replyClass: Class<*>,
        val builder: ProtobufBuilderPlan,
        val listBuilder: ProtobufBuilderPlan?,
        val setDynamicList: Method?,
        val dynamicListGetter: Method?,
        val listGetter: Method?,
        val clearList: Method?,
        val addAllList: Method?,
        val defaultReply: Any?,
        val hasTopicList: Method?,
        val clearTopicList: Method?,
        val upList: UpListMembers?,
        val wholeUpList: WholeUpListMembers?,
        val syncMethod: Method?,
        val asyncMethod: Method?
    )

    private class UpListMembers(
        val getter: Method,
        val setter: Method,
        val builder: ProtobufBuilderPlan,
        val itemBuilder: ProtobufBuilderPlan,
        val listGetter: Method,
        val listSecondGetter: Method,
        val clearList: Method,
        val clearListSecond: Method,
        val addAllList: Method,
        val addAllListSecond: Method,
        val liveStateValue: Method,
        val setPos: Method
    )

    private class ItemMembers(
        val extendGetter: Method?,
        val modulesGetter: Method?,
        val text: TextMembers?,
        val author: AuthorMembers?,
        val promotion: PromotionMembers?,
        val chargeOnly: ChargeOnlyMembers?
    ) {
        val hasTextSource: Boolean get() = text != null
        val hasAuthorSource: Boolean get() = extendGetter != null && author != null
    }

    private class TextMembers(
        val hasModuleDesc: Method?,
        val moduleDescGetter: Method?,
        val moduleDescText: Method?,
        val origDescList: Method?,
        val descList: Method?,
        val descOrigText: Method?
    )

    private class AuthorMembers(val origName: Method?, val uid: Method?)

    private class PromotionMembers(
        val hasAdditional: Method,
        val additionalGetter: Method,
        val typeValue: Method,
        val promotedTypes: Set<Int>
    )

    private class ChargeOnlyMembers(
        val hasProperty: Method,
        val propertyGetter: Method,
        val hasPrivilege: Method
    )

    companion object {
        const val ID = "dynamic_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "dynamic_purify_status"
        private const val MAX_KEYWORDS = 64
        private const val DYNAMIC_PACKAGE = "com.bapis.bilibili.app.dynamic.v2"
        private const val DYNAMIC_MOSS_CLASS = "$DYNAMIC_PACKAGE.DynamicMoss"
        private const val DYNAMIC_ITEM_CLASS = "$DYNAMIC_PACKAGE.DynamicItem"
        private const val MODULE_CLASS = "$DYNAMIC_PACKAGE.Module"
        private const val DESCRIPTION_CLASS = "$DYNAMIC_PACKAGE.Description"
        private const val ADDITIONAL_TYPE_CLASS = "$DYNAMIC_PACKAGE.AdditionalType"
        private const val UP_LIST_ITEM_CLASS = "$DYNAMIC_PACKAGE.UpListItem"
        private const val MOSS_HANDLER_CLASS = "com.bilibili.lib.moss.api.MossResponseHandler"

        /** 顶部 UP 栏容器的 getter 名：综合页与视频页不同名，返回类型一致。 */
        private val UP_LIST_GETTERS = listOf("getUpList", "getVideoUpList")

        /** 综合页与视频页；两页共用同一套判据。 */
        private val FEED_METHODS = listOf(
            FeedSpec("$DYNAMIC_PACKAGE.DynAllReply", "executeDynAll", "dynAll"),
            FeedSpec("$DYNAMIC_PACKAGE.DynVideoReply", "executeDynVideo", "dynVideo")
        )
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.view.View
import android.view.ViewGroup
import android.widget.TextView
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.highcapable.betterandroid.ui.extension.view.childOrNull
import com.highcapable.betterandroid.ui.extension.view.textToString
import java.util.ArrayDeque
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean

/** 动态页净化：在页签添加与位置映射边界同步移除“同城/校园”。 */
internal class DynamicTabsFeatureInstaller(
    private val hideCity: Boolean,
    private val hideSchool: Boolean,
    private val preferVideo: Boolean,
    private val point: VersionAdapter.DynamicTabsPoint?
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (hideCity) add("dynamic_city_tab_hidden")
        if (hideSchool) add("dynamic_school_tab_hidden")
        if (preferVideo) add("dynamic_video_tab_preferred")
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!hideCity && !hideSchool && !preferVideo) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = point ?: return missing(environment, "missing-adapter-point")
        val titleField = environment.hookPoints.resolveField(
            "dynamic.tabs.item_title",
            adapted.itemClassName,
            adapted.itemTitleField
        ) ?: return missing(environment, "missing-title-field")
        val nameField = environment.hookPoints.resolveField(
            "dynamic.tabs.item_name",
            adapted.itemClassName,
            adapted.itemNameField
        ) ?: return missing(environment, "missing-name-field")
        val customViewGetter = environment.hookPoints.resolveAdapted(
            "dynamic.tabs.custom_view",
            adapted.tabCustomViewGetter.className,
            adapted.tabCustomViewGetter.methodName,
            adapted.tabCustomViewGetter.paramClassNames
        ) ?: return missing(environment, "missing-custom-view-getter")

        val forcedVisibleKinds = ConcurrentHashMap.newKeySet<HiddenKind>()
        val videoAvailable = AtomicBoolean(false)
        val cityLogged = AtomicBoolean(false)
        val schoolLogged = AtomicBoolean(false)
        val videoPreferredLogged = AtomicBoolean(false)
        var installedCount = 0

        val listInstalled = runCatching {
            environment.registrar.adapted("dynamic.tabs.list", adapted.listGetter) {
                after {
                    val source = result as? List<*> ?: return@after
                    var hasVideo = false
                    val filtered = CopyOnFilter.list(source) { item ->
                        val title = runCatching { titleField.get(item) as? String }.getOrNull()
                        val name = runCatching { nameField.get(item) as? String }.getOrNull()
                        if (isVideoTab(title, name)) hasVideo = true
                        val hidden = hiddenKind(title, name, hideCity, hideSchool)
                        hidden != null && hidden !in forcedVisibleKinds
                    }
                    if (preferVideo) videoAvailable.set(hasVideo)
                    if (filtered !== source && filtered.isNotEmpty()) {
                        result = filtered
                    }
                }
            }
            installedCount += 1
        }.isSuccess

        val addInstalled = runCatching {
            environment.registrar.adapted("dynamic.tabs.add", adapted.addTab) {
                before {
                    if (instance?.javaClass?.name != adapted.mediatorTabClassName) return@before
                    val tab = args.firstOrNull() ?: return@before
                    val customView = runCatching {
                        customViewGetter.invoke(tab) as? View
                    }.getOrNull() ?: return@before
                    val label = findTabLabel(customView) ?: return@before
                    val originalSelected = args.getOrNull(1) as? Boolean ?: false
                    val preferredSelected = selectedForVideoPreference(
                        label = label,
                        videoAvailable = videoAvailable.get(),
                        preferVideo = preferVideo,
                        originalSelected = originalSelected
                    )
                    if (preferredSelected != originalSelected) args[1] = preferredSelected
                    if (preferredSelected && preferVideo && isVideoTab(label, null) &&
                        videoPreferredLogged.compareAndSet(false, true)
                    ) {
                        environment.logInfo(
                            "dynamic_tab_preferred_video",
                            "[BIL] 动态页已将“视频”设为初始选中标签"
                        )
                    }
                    val hidden = hiddenKind(label, null, hideCity, hideSchool) ?: return@before
                    val selected = args.getOrNull(1) as? Boolean ?: false
                    if (selected) {
                        // 服务端若把待隐藏标签设为默认项则故障开放，避免无选中页或映射错位。
                        forcedVisibleKinds += hidden
                        environment.logError(
                            "dynamic_tabs_default_visible",
                            "[BIL] 动态页待隐藏标签“$label”是默认项，本次保留以避免页签错位"
                        )
                        return@before
                    }
                    result = null
                    val first = when (hidden) {
                        HiddenKind.CITY -> cityLogged.compareAndSet(false, true)
                        HiddenKind.SCHOOL -> schoolLogged.compareAndSet(false, true)
                    }
                    if (first) {
                        environment.logInfo(
                            "dynamic_tab_hidden_${hidden.name.lowercase()}",
                            "[BIL] 已隐藏动态页标签“$label”"
                        )
                    }
                }
            }
            installedCount += 1
        }.isSuccess

        // Each selected policy requires both list mapping and tab attachment; do not inherit the parent verdict.
        capabilityIds.forEach { environment.reportCapabilityCoverage(it, true, installedCount, 2) }
        if (!listInstalled || !addInstalled) {
            val reason = buildString {
                append("partial:")
                if (!listInstalled) append("list")
                if (!listInstalled && !addInstalled) append(',')
                if (!addInstalled) append("add")
            }
            environment.reportStatus(CHANNEL_STATUS, reason)
            environment.logError(
                "dynamic_tabs_partial",
                "[BIL] 动态页标签净化 Hook 未完整命中: $reason"
            )
            return if (installedCount > 0) FeatureInstallResult.Installed(installedCount, complete = false)
            else FeatureInstallResult.Skipped(reason)
        }
        environment.reportStatus(CHANNEL_STATUS, "success")
        environment.logInfo(
            "dynamic_tabs_ok",
            "[BIL] 动态页标签净化已安装，hooks=$installedCount"
        )
        return FeatureInstallResult.Installed(installedCount, complete = listInstalled && addInstalled)
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("dynamic_tabs_missing", "[BIL] 动态页标签适配不完整: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "dynamic_tabs_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "dynamic_tabs_status"
        private const val MAX_TAB_VIEW_NODES = 24

        internal enum class HiddenKind { CITY, SCHOOL }

        internal fun hiddenKind(
            title: String?,
            name: String?,
            hideCity: Boolean,
            hideSchool: Boolean
        ): HiddenKind? {
            val normalizedTitle = title?.trim()
            val normalizedName = name?.trim()?.lowercase()
            if (hideCity && (normalizedTitle == "同城" || normalizedName in CITY_NAMES)) {
                return HiddenKind.CITY
            }
            if (hideSchool && (normalizedTitle == "校园" || normalizedName in SCHOOL_NAMES)) {
                return HiddenKind.SCHOOL
            }
            return null
        }

        internal fun isVideoTab(title: String?, name: String?): Boolean =
            title?.trim() == "视频" || name?.trim()?.lowercase() == "video"

        internal fun selectedForVideoPreference(
            label: String?,
            videoAvailable: Boolean,
            preferVideo: Boolean,
            originalSelected: Boolean
        ): Boolean = if (preferVideo && videoAvailable) {
            isVideoTab(label, null)
        } else {
            originalSelected
        }

        private fun findTabLabel(root: View): String? {
            val pending = ArrayDeque<View>()
            pending.add(root)
            var visited = 0
            while (pending.isNotEmpty() && visited < MAX_TAB_VIEW_NODES) {
                val view = pending.removeFirst()
                visited += 1
                if (view is TextView) {
                    view.textToString().trim().takeIf { it.isNotEmpty() }?.let { return it }
                }
                if (view is ViewGroup) {
                    for (index in 0 until view.childCount) {
                        view.childOrNull(index)?.let(pending::addLast)
                    }
                }
            }
            return null
        }

        private val CITY_NAMES = setOf("city", "same_city", "nearby")
        private val SCHOOL_NAMES = setOf("school", "campus")
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.app.Instrumentation
import android.content.Context
import android.content.Intent
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.Method

/**
 * 在 Activity 启动边界把宿主内置 WebView 的站外网页改交系统浏览器打开。
 *
 * 复用与 [HomeVerticalDetailFeatureInstaller] 同一个平台边界（`Instrumentation`），但两者
 * 判据完全不相交：那边只认 Story 视频路由，这边只认 `*MWebActivity` + 站外 http(s) 域名，
 * 因此同时启用也不会互相覆盖。
 *
 * 落地前会先用发起方 Context 的 PackageManager 确认真的有应用能接住这个 URL。没有浏览器
 * 时保留宿主原 Intent——宁可继续用内置 WebView，也不能让宿主抛
 * `ActivityNotFoundException`。这次查询只发生在用户真的点开站外链接时，不在任何热路径上。
 */
internal class ExternalBrowserFeatureInstaller(
    private val enabled: Boolean
) : FeatureInstaller {

    override val id: String = ID

    /**
     * "系统没有应用能接住这个链接"只值得记一次。
     *
     * Android 11+ 的软件包可见性会让 `resolveActivity` 在没有 `<queries>` 声明时恒返回 null；
     * 宿主 9.7.0–9.11.0 都声明了 `QUERY_ALL_PACKAGES`，所以当前不受影响。真要遇到宿主收紧
     * 声明的那天，这条日志就是唯一线索，但它绝不能随每次点击刷屏。
     */
    private val noHandlerLogged = java.util.concurrent.atomic.AtomicBoolean(false)

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }

        // 必须同时拿得到 Intent 和发起方 Context：没有 Context 就无法确认有没有浏览器接住，
        // 那种重载宁可不装，也不留一个永远走不到改写分支的空 Hook。
        val candidates = KavaMemberLookup.declaredMethods(
            classOf<Instrumentation>(),
            makeAccessible = true
        ) { method ->
            method.name == "execStartActivity" && !method.isStatic &&
                method.parameterTypes.count { it == classOf<Intent>() } == 1 &&
                method.parameterTypes.any { it isSubclassOf classOf<Context>() }
        }.distinctBy(Method::toGenericString)
        if (candidates.isEmpty()) return missing(environment, "no-safe-activity-launch-hook-point")

        var installed = 0
        candidates.forEachIndexed { index, method ->
            val intentIndex = method.parameterTypes.indexOf(classOf<Intent>())
            val contextIndex = method.parameterTypes.indexOfFirst {
                it isSubclassOf classOf<Context>()
            }
            runCatching {
                environment.registrar.exact(
                    "external.browser.instrumentation.$index",
                    method.declaringClass,
                    method.name,
                    *method.parameterTypes
                ) {
                    before {
                        val intent = args.getOrNull(intentIndex) as? Intent ?: return@before
                        val data = intent.data ?: return@before
                        if (!ExternalBrowserPolicy.shouldOpenExternally(
                                intent.component?.className,
                                data.scheme,
                                data.host
                            )
                        ) {
                            return@before
                        }
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        val caller = args.getOrNull(contextIndex) as? Context
                        val external = buildExternalIntent(intent, data)
                        if (!canBeHandled(caller, external)) {
                            if (noHandlerLogged.compareAndSet(false, true)) {
                                environment.logInfo(
                                    "external_browser_no_handler",
                                    "[BIL] 系统没有可接住该链接的应用，保留宿主内置浏览器"
                                )
                            }
                            return@before
                        }
                        args[intentIndex] = external
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "external_browser_instrumentation_$index",
                    "[BIL] 外部浏览器跳转注册失败(${method.parameterCount} 参数): $throwable"
                )
            }
        }

        if (installed == 0) return missing(environment, "registration-failed")
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        val status = if (installed == candidates.size) {
            "success"
        } else {
            "partial:$installed/${candidates.size}"
        }
        environment.reportStatus(CHANNEL_STATUS, status)
        if (status == "success") {
            environment.logInfo(
                "external_browser_ok",
                "[BIL] 站外链接外部浏览器打开已安装，hooks=$installed"
            )
        } else {
            environment.logError(
                "external_browser_partial",
                "[BIL] 站外链接外部浏览器打开部分安装，status=$status"
            )
        }
        return FeatureInstallResult.Installed(installed, complete = installed == candidates.size)
    }

    /**
     * 只带链接本身出门。
     *
     * 不复制宿主 extra：那些 key 是给内置 WebView 用的，交给第三方浏览器既无意义，也可能
     * 把宿主内部标识泄露出去。`FLAG_ACTIVITY_NEW_TASK` 仅在原 Intent 已经带了它时保留。
     */
    private fun buildExternalIntent(original: Intent, data: android.net.Uri): Intent =
        Intent(Intent.ACTION_VIEW, data).apply {
            addCategory(Intent.CATEGORY_BROWSABLE)
            if (original.flags and Intent.FLAG_ACTIVITY_NEW_TASK != 0) {
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            }
        }

    /** 解析失败一律当作"没人接"，让调用方保留宿主原 Intent。 */
    private fun canBeHandled(caller: Context?, intent: Intent): Boolean {
        val packageManager = caller?.packageManager ?: return false
        return runCatching {
            @Suppress("DEPRECATION")
            packageManager.resolveActivity(intent, 0) != null
        }.getOrDefault(false)
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "external_browser_missing",
            "[BIL] 站外链接外部浏览器打开适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "external_browser"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "external_browser_status"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.HookPointRegistry
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.HookExceptionPolicy
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.ModernMemberHookCreator
import java.lang.reflect.Constructor

internal interface HookRegistrar {
    fun first(
        id: String,
        className: String,
        methodName: String,
        block: ModernMemberHookCreator.() -> Unit
    )

    fun all(
        id: String,
        className: String,
        methodName: String,
        block: ModernMemberHookCreator.() -> Unit
    )

    fun exact(
        id: String,
        owner: Class<*>,
        methodName: String,
        vararg parameterTypes: Class<*>,
        block: ModernMemberHookCreator.() -> Unit
    )

    /**
     * [exceptionPolicy] 保持默认即可；只有“必须让宿主方法以指定异常结束”的 Hook 才改成
     * [HookExceptionPolicy.DELIVER_TO_HOST]，且回调体要自行保证不逃逸其他异常。
     */
    fun adapted(
        id: String,
        point: VersionAdapter.HookPoint,
        exceptionPolicy: HookExceptionPolicy = HookExceptionPolicy.PROTECT_HOST,
        block: ModernMemberHookCreator.() -> Unit
    )

    fun constructor(
        id: String,
        constructor: Constructor<*>,
        block: ModernMemberHookCreator.() -> Unit
    )
}

/** 每个功能安装器的最小边界；安装失败不影响后续功能。 */
internal interface FeatureInstaller {
    val id: String
    /** Enabled leaf capabilities expected to produce independent installation evidence. */
    val capabilityIds: List<String> get() = emptyList()

    fun install(environment: HookEnvironment): FeatureInstallResult
}

internal data class HookEnvironment(
    val processName: String,
    val classLoader: ClassLoader?,
    val hookPoints: HookPointRegistry,
    val registrar: HookRegistrar,
    val logInfo: (String, String) -> Unit,
    val logError: (String, String) -> Unit,
    val reportStatus: (String, String) -> Unit,
    /** 将一次性初始化任务排到 Application.attach 返回后的主线程队列；null = 不主动预解析。 */
    val postToMain: ((() -> Unit) -> Unit)? = null,
    /** 写“我的”页可屏蔽项快照（宿主剪枝时产出，供模块 UI 勾选列表读取）。null = 不启用快照。 */
    /**
     * 面判别位（`MineComponentSnapshotCodec.SURFACE_*`）+ 不可变纯数据；编码和写盘由后台桥承担。
     * 2026-09-04 起由单面扩展为多面：我的页 / 底栏 / 首页 Tab / 首页组件共用这一条通道。
     */
    val writeScanSnapshot: ((String, ScanSnapshotContent) -> Boolean)? = null,
    /**
     * 仅上报功能阶段；宿主桥对每项阶段只保留首次证据，null 时不影响 Hook。禁止传递设置值、
     * 卡片/评论正文、宿主成员名或异常文本。
     */
    val runtimeEvidence: ((String, FeatureRuntimeStage, Int) -> Unit)? = null,
    /** 安装器结束后上报一次结构化结果；诊断异常不能反向影响 Hook 安装链。 */
    val installationEvidence: ((FeatureInstallRecord) -> Unit)? = null,
    val capabilityEvidence: ((String, FeatureInstallResult) -> Unit)? = null,
    val runtimePhase: (() -> Boolean)? = null
)

internal sealed interface FeatureInstallResult {
    data class Installed(val hookCount: Int = 1, val complete: Boolean = true) : FeatureInstallResult
    data object Unverified : FeatureInstallResult
    data class Skipped(val reason: String) : FeatureInstallResult {
        val reasonCode: FeatureSkipReason = FeatureSkipReason.fromRaw(reason)
    }
}

/** 把存量安装器的有界 reason 字符串收敛为稳定诊断码，不改变原日志和安装分支。 */
internal enum class FeatureSkipReason {
    DISABLED,
    NOT_APPLICABLE_PROCESS,
    NOT_APPLICABLE_HOST,
    MISSING_ADAPTER_POINT,
    MISSING_HOST_STRUCTURE,
    AMBIGUOUS_HOST_STRUCTURE,
    REGISTRATION_FAILED,
    NO_SAFE_HOOK_POINT,
    OTHER;

    companion object {
        fun fromRaw(raw: String): FeatureSkipReason {
            val reason = raw.trim().lowercase().replace('_', '-')
            return when {
                reason == "disabled" || reason.startsWith("no-types-enabled") ||
                    reason.startsWith("no-rules") -> DISABLED
                reason == "non-main-process" -> NOT_APPLICABLE_PROCESS
                reason == "not-applicable-host" -> NOT_APPLICABLE_HOST
                reason.contains("ambiguous") -> AMBIGUOUS_HOST_STRUCTURE
                reason.contains("registration-failed") ||
                    reason.contains("register-failed") -> REGISTRATION_FAILED
                reason.contains("missing-adapter") -> MISSING_ADAPTER_POINT
                reason.startsWith("no-legacy") -> MISSING_HOST_STRUCTURE
                reason.contains("missing") -> MISSING_HOST_STRUCTURE
                reason.contains("no-hook") || reason.contains("hook-point") ->
                    NO_SAFE_HOOK_POINT
                reason.contains("failed") -> REGISTRATION_FAILED
                else -> OTHER
            }
        }
    }
}

internal data class FeatureInstallRecord(
    val id: String,
    val result: FeatureInstallResult?,
    val failure: Throwable?
)

/** 保持安装顺序并隔离单功能失败，为 HookEntry 逐步拆分提供稳定骨架。 */
internal class FeatureInstallCoordinator(
    private val environment: HookEnvironment
) {
    fun installAll(installers: Iterable<FeatureInstaller>): List<FeatureInstallRecord> =
        installers.map { installer ->
            val capabilityLock = Any()
            val reported = hashSetOf<String>()
            val installedPhase = java.util.concurrent.atomic.AtomicBoolean(false)
            val planned = runCatching { installer.capabilityIds.toSet() }.getOrDefault(emptySet())
            val scoped = environment.copy(
                runtimePhase = { installedPhase.get() },
                logError = { key, message ->
                    if (installedPhase.get()) environment.reportRuntimeEvidence(installer.id, FeatureRuntimeStage.ERROR)
                    environment.logError(key, message)
                },
                capabilityEvidence = { id, result ->
                if (id in planned) synchronized(capabilityLock) {
                    environment.installationEvidence?.invoke(FeatureInstallRecord(id, result, null))
                    reported += id
                }
            })
            val record = runCatching { installer.install(scoped) }
                .fold(
                    onSuccess = { result ->
                        FeatureInstallRecord(installer.id, result, failure = null)
                    },
                    onFailure = { throwable ->
                        environment.logError(
                            "feature_installer_${installer.id}",
                            "[BIL] 功能安装器 ${installer.id} 失败，已隔离并继续: $throwable"
                        )
                        FeatureInstallRecord(installer.id, result = null, failure = throwable)
                    }
                )
            runCatching { environment.installationEvidence?.invoke(record) }
                .onFailure { throwable ->
                    environment.logError(
                        "feature_diagnostics_${installer.id}",
                        "[BIL] 功能安装诊断上报失败，业务 Hook 状态不受影响: $throwable"
                    )
                }
            for (id in planned) {
                // A group-wide failure before completion blocks its remaining declared paths.
                // A successful parent NEVER supplies success for an unverified leaf.
                synchronized(capabilityLock) {
                    if (id !in reported) {
                        val outcome = when (val result = record.result) {
                            is FeatureInstallResult.Skipped -> result
                            else -> FeatureInstallResult.Unverified
                        }
                        runCatching {
                            environment.installationEvidence?.invoke(
                                if (record.failure != null) FeatureInstallRecord(id, null, record.failure)
                                else FeatureInstallRecord(id, outcome, null)
                            )
                        }
                    }
                }
            }
            installedPhase.set(true)
            record
        }
}

/** Installation-time only; evidence collection failures must not affect business hooks. */
internal fun HookEnvironment.reportCapability(id: String, result: FeatureInstallResult) {
    runCatching { capabilityEvidence?.invoke(id, result) }
}

/** Call with the leaf's own prerequisites, not the overall parent's success flag. */
internal fun HookEnvironment.reportCapabilityCoverage(
    id: String,
    ready: Boolean,
    installedPaths: Int,
    expectedPaths: Int
) {
    reportCapability(id, when {
        !ready -> FeatureInstallResult.Skipped("missing-capability-dependency")
        installedPaths <= 0 -> FeatureInstallResult.Skipped("registration-failed")
        else -> FeatureInstallResult.Installed(installedPaths, installedPaths >= expectedPaths && expectedPaths > 0)
    })
}

/** Bound once during installation; maps shared helper evidence to its actual leaf. */
internal fun HookEnvironment.forCapabilityRuntime(id: String): HookEnvironment {
    val sink = runtimeEvidence ?: return this
    return copy(
        runtimeEvidence = { _, stage, count -> sink(id, stage, count) },
        logError = { key, message ->
            if (runtimePhase?.invoke() == true) reportRuntimeEvidence(id, FeatureRuntimeStage.ERROR)
            logError(key, message)
        }
    )
}

internal class FunctionalFeatureInstaller(
    override val id: String,
    private val action: (HookEnvironment) -> FeatureInstallResult
) : FeatureInstaller {
    override fun install(environment: HookEnvironment): FeatureInstallResult = action(environment)
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter

/** 完整数字显示：在宿主统一数字格式化边界返回原始非负整数，避免“万/亿”缩写。 */
internal class FullNumberFeatureInstaller(
    private val enabled: Boolean,
    private val points: VersionAdapter.FullNumberPoints?
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = points?.formatterMethods?.takeIf { it.isNotEmpty() }
            ?: return missing(environment, "missing-adapter-point")

        var installedCount = 0
        adapted.forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("number.full.format.$index", point) {
                    before {
                        rawNumberText(args.firstOrNull())?.let { result = it }
                    }
                }
                installedCount += 1
            }.onFailure { throwable ->
                environment.logError(
                    "full_number_method_$index",
                    "[BIL] 完整数字格式化 Hook 注册失败(" +
                        "${point.className}#${point.methodName}): $throwable"
                )
            }
        }

        if (installedCount == 0) return missing(environment, "registration-failed")
        val status = if (installedCount == adapted.size) {
            "success"
        } else {
            "partial:$installedCount/${adapted.size}"
        }
        environment.reportStatus(CHANNEL_STATUS, status)
        if (installedCount != adapted.size) {
            environment.logError(
                "full_number_partial",
                "[BIL] 完整数字显示部分安装，hooks=$installedCount/${adapted.size}"
            )
        } else {
            environment.logInfo(
                "full_number_ok",
                "[BIL] 完整数字显示已安装，hooks=$installedCount"
            )
        }
        return FeatureInstallResult.Installed(installedCount, complete = installedCount == adapted.size)
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("full_number_missing", "[BIL] 完整数字显示适配不完整: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "full_number_display"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "full_number_status"

        /** 只接管非负整数；负数、空值和非纯数字字符串故障开放给宿主。 */
        internal fun rawNumberText(value: Any?): String? = when (value) {
            is Byte -> value.toLong().takeIf { it >= 0L }?.toString()
            is Short -> value.toLong().takeIf { it >= 0L }?.toString()
            is Int -> value.takeIf { it >= 0 }?.toString()
            is Long -> value.takeIf { it >= 0L }?.toString()
            is String -> value.takeIf { text ->
                text.isNotEmpty() && text.all { it in '0'..'9' }
            }
            else -> null
        }
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.content.Context
import android.view.View
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.ModernMemberHookCreator
import com.highcapable.kavaref.extension.classOf
import java.lang.reflect.Constructor
import java.util.Collections

/** 视频详情页“视频提及”游戏推广的数据层与渲染层安装器。 */
internal class GamePromotionFeatureInstaller(
    private val enabled: Boolean
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }

        val results = LinkedHashMap<String, Boolean>()
        fun hookMethod(
            key: String,
            className: String,
            methodName: String,
            block: ModernMemberHookCreator.() -> Unit
        ) {
            runCatching {
                environment.registrar.first("game_mentioned.$key", className, methodName, block)
            }.fold(
                onSuccess = { results[key] = true },
                onFailure = { results[key] = false }
            )
        }

        hookMethod("video_mentions_title", VIDEO_MENTIONS_CLASS, GET_TITLE) { replaceTo("") }
        hookMethod("mention_title", MENTION_CLASS, GET_TITLE) { replaceTo("") }
        hookMethod("mention_cards", MENTION_CLASS, GET_CARDS_LIST) {
            replaceTo(Collections.emptyList<Any>())
        }

        if (KavaMemberLookup.classOrNull(environment.classLoader, MENTION_FACTORY_CLASS) != null) {
            runCatching {
                environment.registrar.first(
                    "game_mentioned.section_factory",
                    MENTION_FACTORY_CLASS,
                    MENTION_FACTORY_METHOD
                ) {
                    replaceAny {
                        try {
                            val constructor = mentionedSectionConstructor(environment)
                            environment.logInfo(
                                "factory",
                                "[BIL] 已拦截视频提及 section 工厂方法 yx3.a.c"
                            )
                            constructor.newInstance()
                        } catch (throwable: Throwable) {
                            environment.logError(
                                "factory_err",
                                "[BIL] 空 section 构造失败: $throwable"
                            )
                            null
                        }
                    }
                }
                results["sectionFactory"] = true
            }.onFailure { throwable ->
                results["sectionFactory"] = false
                environment.logError(
                    "factory_hook_err",
                    "[BIL] 工厂方法 hook 失败: $throwable"
                )
            }
        } else {
            results["sectionFactory"] = false
        }

        hookMethod("hidden", GAME_CARD_DATA_CLASS, "hidden") { replaceToTrue() }
        hookMethod("benefit_group", GAME_FEED_ITEM_CLASS, "getBottomBenefitTipGroup") {
            replaceTo(0)
        }
        hookMethod("show_benefit_widget", GAME_FEED_ITEM_CLASS, "getShowBenefitWidget") {
            replaceToFalse()
        }

        runCatching {
            environment.registrar.first(
                "game_mentioned.component_view_entry",
                MENTIONED_COMPONENT_CLASS,
                CREATE_VIEW_ENTRY
            ) {
                before {
                    val context = args.firstOrNull() as? Context ?: return@before
                    try {
                        result = uiComponentConstructor(context).newInstance(View(context))
                        environment.logInfo(
                            "createViewEntry",
                            "[BIL] 已拦截视频提及游戏卡 createViewEntry"
                        )
                    } catch (throwable: Throwable) {
                        result = null
                        environment.logError(
                            "createViewEntry_err",
                            "[BIL] createViewEntry 拦截失败: $throwable"
                        )
                    }
                }
            }
            results["createViewEntry"] = true
        }.onFailure {
            results["createViewEntry"] = false
        }

        runCatching {
            val headerClass = KavaMemberLookup.classOrNull(
                environment.classLoader,
                MENTIONED_HEADER_COMPONENT_CLASS
            ) ?: throw ClassNotFoundException(MENTIONED_HEADER_COMPONENT_CLASS)
            val headerConstructor = KavaMemberLookup.declaredConstructors(
                headerClass,
                makeAccessible = true
            ) { it.parameterCount == 1 }.firstOrNull()
                ?: throw NoSuchMethodException("$MENTIONED_HEADER_COMPONENT_CLASS#<init>(1)")
            environment.registrar.constructor(
                "game_mentioned.header_constructor",
                headerConstructor
            ) {
                before {
                    args[0] = ""
                    environment.logInfo("header_ctor", "[BIL] 已清空视频提及 header 标题")
                }
            }
            environment.registrar.all(
                "game_mentioned.header_view_entry",
                MENTIONED_HEADER_COMPONENT_CLASS,
                CREATE_VIEW_ENTRY
            ) {
                before {
                    val context = args.firstOrNull() as? Context ?: return@before
                    try {
                        result = uiComponentConstructor(context).newInstance(View(context))
                        environment.logInfo(
                            "header_cve",
                            "[BIL] 已拦截视频提及 header createViewEntry"
                        )
                    } catch (throwable: Throwable) {
                        result = null
                        environment.logError(
                            "header_cve_err",
                            "[BIL] header createViewEntry 拦截失败: $throwable"
                        )
                    }
                }
            }
            results["headerComponent"] = true
        }.onFailure { throwable ->
            results["headerComponent"] = false
            environment.logError("header_err", "[BIL] header 组件 hook 失败: $throwable")
        }

        hookMethod("benefit_tip", BENEFIT_WIDGET_CLASS, "I") { intercept() }
        hookMethod("section_cards", MENTIONED_SECTION_CLASS, "getCards") { intercept() }
        hookMethod("section_height", MENTIONED_SECTION_CLASS, "getHeight") { intercept() }
        hookMethod("section_header", MENTIONED_SECTION_CLASS, "getHeader") { intercept() }
        hookMethod("section_fold_count", MENTIONED_SECTION_CLASS, "getFoldCount") { intercept() }

        val bodyBlocked = listOf(
            "mention_cards",
            "hidden",
            "createViewEntry",
            "section_cards"
        ).any { results[it] == true }
        val headerBlocked = listOf(
            "video_mentions_title",
            "mention_title",
            "headerComponent",
            "section_header"
        ).any { results[it] == true }
        val ready = bodyBlocked && headerBlocked
        val summary = if (ready) {
            "success"
        } else {
            buildString {
                append("partial:")
                if (!bodyBlocked) append("body")
                if (!bodyBlocked && !headerBlocked) append(',')
                if (!headerBlocked) append("header")
            }
        }
        environment.reportStatus(CHANNEL_STATUS, summary)
        if (ready) {
            environment.logInfo("gamecard_ok", "[BIL] gamecard summary: success")
            return FeatureInstallResult.Installed(results.count { it.value })
        }
        environment.logError("gamecard_partial", "[BIL] gamecard 部分 hook 未命中: $summary")
        val available = results.count { it.value }
        return if (available > 0) FeatureInstallResult.Installed(available, complete = false)
        else FeatureInstallResult.Skipped(summary)
    }

    private fun mentionedSectionConstructor(environment: HookEnvironment): Constructor<*> =
        mentionedSectionConstructor ?: synchronized(classOf<GamePromotionFeatureInstaller>()) {
            mentionedSectionConstructor ?: run {
                val owner = KavaMemberLookup.classOrNull(
                    environment.classLoader,
                    MENTIONED_SECTION_CLASS
                ) ?: throw ClassNotFoundException(MENTIONED_SECTION_CLASS)
                KavaMemberLookup.constructorOrNull(owner)
                    ?.also { mentionedSectionConstructor = it }
                    ?: throw NoSuchMethodException("$MENTIONED_SECTION_CLASS()")
            }
        }

    private fun uiComponentConstructor(context: Context): Constructor<*> =
        uiComponentConstructor ?: synchronized(classOf<GamePromotionFeatureInstaller>()) {
            uiComponentConstructor ?: run {
                val owner = KavaMemberLookup.classOrNull(context.classLoader, UI_COMPONENT_CLASS)
                    ?: throw ClassNotFoundException(UI_COMPONENT_CLASS)
                KavaMemberLookup.constructorOrNull(owner, classOf<View>())
                    ?.also { uiComponentConstructor = it }
                    ?: throw NoSuchMethodException("$UI_COMPONENT_CLASS(android.view.View)")
            }
        }

    companion object {
        const val ID = "game_mentioned_promotion"
        private const val CHANNEL_STATUS = "gamecard_ad_status"
        private const val MENTIONED_COMPONENT_CLASS =
            "com.bilibili.biligame.videocard.GameVideoMentionedComponent"
        private const val UI_COMPONENT_CLASS = "com.bilibili.app.gemini.ui.UIComponent\$b"
        private const val MENTIONED_HEADER_COMPONENT_CLASS =
            "com.bilibili.biligame.videocard.GameVideoMentionedHeaderComponent"
        private const val MENTION_FACTORY_CLASS = "yx3.a"
        private const val MENTION_FACTORY_METHOD = "c"
        private const val MENTION_CLASS = "com.bapis.bilibili.app.viewunite.common.Mention"
        private const val VIDEO_MENTIONS_CLASS =
            "com.bapis.bilibili.app.viewunite.common.VideoMentions"
        private const val GET_TITLE = "getTitle"
        private const val GET_CARDS_LIST = "getCardsList"
        private const val GAME_CARD_DATA_CLASS =
            "com.bilibili.biligame.videocard.GameVideoMentionCardData"
        private const val GAME_FEED_ITEM_CLASS =
            "com.bilibili.biligame.ui.feed.bean.GameFeedItem"
        private const val BENEFIT_WIDGET_CLASS =
            "com.bilibili.biligame.ui.feed.widget.bottomtip.BottomGameBenefitWidgetKt"
        private const val MENTIONED_SECTION_CLASS =
            "com.bilibili.playerbizcommonv2.videomentioned.MentionedSectionItem"
        private const val CREATE_VIEW_ENTRY = "createViewEntry"

        @Volatile
        private var uiComponentConstructor: Constructor<*>? = null

        @Volatile
        private var mentionedSectionConstructor: Constructor<*>? = null
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.view.View
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import java.util.Collections

/** 收起首页 V8Banner 以及极旧版本的容器数据入口。 */
internal class HomeBannerFeatureInstaller(
    private val enabled: Boolean,
    private val point: VersionAdapter.BannerPoint?,
    /** 返回 true 表示轮播专用父壳已完整收起；false 表示只安全收起了目标 Banner。 */
    private val collapseBanner: (View) -> Boolean
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = if (enabled) listOf("home_banner_view") else emptyList()

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }

        val viewEnvironment = environment.forCapabilityRuntime("home_banner_view")
        val results = LinkedHashMap<String, Boolean>()
        val bannerPoint = point
        if (bannerPoint != null) {
            val bannerClass = KavaMemberLookup.classOrNull(
                environment.classLoader,
                bannerPoint.bannerClassName
            )
            bannerPoint.lifecycleMethods.forEachIndexed { index, lifecyclePoint ->
                val key = "${lifecyclePoint.className}#${lifecyclePoint.methodName}"
                runCatching {
                    environment.registrar.adapted("home_banner.lifecycle.$index", lifecyclePoint) {
                        after {
                            val banner = instance as? View ?: return@after
                            if (bannerClass?.isInstance(banner) != true) return@after
                            if (
                                lifecyclePoint.methodName == "onVisibilityChanged" &&
                                (args.getOrNull(1) as? Int) != View.VISIBLE
                            ) return@after
                            viewEnvironment.reportRuntimeEvidence("home_banner_view", FeatureRuntimeStage.OBSERVED)
                            if (collapseBanner(banner)) {
                                viewEnvironment.reportRuntimeEvidence("home_banner_view", FeatureRuntimeStage.APPLIED)
                            } else {
                                environment.logInfo(
                                    "banner_parent_unsafe",
                                    "[BIL] Banner 已隐藏，但父容器结构未知，已停止向上收起"
                                )
                            }
                        }
                    }
                    results[key] = true
                }.onFailure { throwable ->
                    results[key] = false
                    environment.logInfo(
                        "banner_adapter_${lifecyclePoint.methodName}_err",
                        "[BIL] Banner Adapter 入口失败: $throwable"
                    )
                }
            }
        } else {
            runCatching {
                environment.registrar.first(
                    "home_banner.legacy_container",
                    LEGACY_CONTAINER_CLASS,
                    LEGACY_ITEMS_METHOD
                ) { replaceTo(Collections.emptyList<Any>()) }
                results["legacyContainer"] = true
            }.onFailure {
                results["legacyContainer"] = false
            }
        }

        val ready = results.any { (key, registered) ->
            registered && (key.endsWith("#onAttachedToWindow") || key == "legacyContainer")
        }
        val successfulPaths = results.count { it.value }
        val complete = ready && results.values.all { it }
        environment.reportCapability("home_banner_view",
            if (successfulPaths > 0) FeatureInstallResult.Installed(successfulPaths,
                complete = complete)
            else FeatureInstallResult.Skipped("no_required_hook_point"))
        environment.reportStatus(CHANNEL_STATUS, if (complete) "success" else if (ready) "partial:$successfulPaths/${results.size}" else "failed")
        if (ready) {
            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
            environment.logInfo("banner_ok", "[BIL] Banner Adapter 已注册 V8Banner 收起入口")
            return FeatureInstallResult.Installed(successfulPaths, complete)
        }
        environment.logError("banner_failed", "[BIL] Banner Adapter 未找到可用入口")
        return FeatureInstallResult.Skipped("no_required_hook_point")
    }

    companion object {
        const val ID = "home_banner"
        private const val CHANNEL_STATUS = "banner_ad_status"
        private const val LEGACY_CONTAINER_CLASS = "xm3.d"
        private const val LEGACY_ITEMS_METHOD = "l"
        private const val DEDICATED_CONTAINER_CLASS =
            "com.bilibili.pegasus.holders.bannerv8.BannerV8Container"
        private const val INDICATOR_CLASS =
            "com.bilibili.app.comm.list.widget.swiper.CircleIndicator"

        /**
         * 通用父布局只有在子节点全部属于目标 Banner/轮播指示器时才视为专用壳；
         * 精确的 BannerV8Container 本身即是专用壳，可以兼容其内部装饰节点扩展。
         */
        internal fun isDedicatedBannerShell(
            parentClassName: String,
            childClassNames: List<String>,
            bannerClassName: String
        ): Boolean {
            if (parentClassName == DEDICATED_CONTAINER_CLASS) return true
            if (childClassNames.size !in 1..MAX_GENERIC_SHELL_CHILDREN) return false
            if (bannerClassName !in childClassNames) return false
            return childClassNames.all { name ->
                name == bannerClassName || name == INDICATOR_CLASS
            }
        }

        private const val MAX_GENERIC_SHELL_CHILDREN = 3
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.view.View
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import java.lang.reflect.Method

/** 仅对父 Fragment 链属于首页容器的子 Fragment 按类名规则隐藏根 View。 */
internal class HomeComponentFilterFeatureInstaller(
    rules: String,
    selectors: String = "",
    private val points: VersionAdapter.HomeComponentPoints?
) : FeatureInstaller {

    override val id: String = ID
    private val tokens = RuleSetCodec.parse(rules)
    private val selectorSet = MineComponentSelectionCodec.decode(selectors)

    private fun hasHiddenConfiguration(): Boolean =
        tokens.isNotEmpty() || selectorSet.isNotEmpty()

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        // 空配置也要装：不扫描就产不出勾选列表。
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = points ?: return missing(environment, "missing-adapter-point")
        val parentGetter = environment.hookPoints.resolveAdapted(
            "home.components.parent",
            adapted.parentFragmentGetter.className,
            adapted.parentFragmentGetter.methodName,
            adapted.parentFragmentGetter.paramClassNames
        ) ?: return missing(environment, "missing-parent-getter")

        val publisher = ScanSnapshotPublisher(
            environment,
            MineComponentSnapshotCodec.SURFACE_HOME_COMPONENTS,
            setOf("home_component_filter")
        )
        return runCatching {
            environment.registrar.adapted("home.components.view", adapted.onViewCreated) {
                after {
                    val fragment = instance ?: return@after
                    val root = args.firstOrNull() as? View ?: return@after
                    val className = fragment.javaClass.name
                    if (!isCandidate(className) || !isHomeChild(fragment, parentGetter)) {
                        return@after
                    }
                    val hide = matches(className)
                    // 标识只有混淆类名，另外摸一个可读标题当副标题；摸不到就只显示类名。
                    publisher.accumulate(
                        MineComponentScanEntry.create(
                            kind = "home_component",
                            title = firstText(root, 0),
                            id = className,
                            uri = null,
                            showing = !hide
                        )
                    )
                    if (hide) root.visibility = View.GONE
                }
            }
            val mode = if (hasHiddenConfiguration()) "filter+scan" else "scan"
            environment.reportStatus(CHANNEL_STATUS, "success:$mode")
            environment.logInfo("home_components_ok", "[BIL] 首页组件自定义隐藏已安装($mode)")
            FeatureInstallResult.Installed()
        }.getOrElse { throwable ->
            environment.logError(
                "home_components_error",
                "[BIL] 首页组件自定义隐藏 Hook 注册失败: $throwable"
            )
            missing(environment, "registration-failed")
        }
    }

    private fun isHomeChild(fragment: Any, parentGetter: Method): Boolean {
        var current: Any? = invokeParent(parentGetter, fragment)
        repeat(MAX_PARENT_DEPTH) {
            val parent = current ?: return false
            if (isHomeContainer(parent.javaClass)) return true
            current = invokeParent(parentGetter, parent)
        }
        return false
    }

    private fun invokeParent(method: Method, target: Any): Any? = runCatching {
        method.invoke(target)
    }.getOrNull()

    /** 手填规则与勾选选择器取并集。 */
    private fun matches(className: String): Boolean {
        if (tokens.isNotEmpty() &&
            RuleSetCodec.matches(tokens, className, className.substringAfterLast('.'))
        ) return true
        if (selectorSet.isEmpty()) return false
        val key = MineComponentSelector.key("home_component", null, className, null)
        return key != null && key in selectorSet
    }

    /** 一次性、深度受限地摸一个可读标题；只在扫描时走，不进任何逐帧路径。 */
    private fun firstText(view: View, depth: Int): String? {
        if (depth > MAX_TITLE_DEPTH) return null
        if (view is android.widget.TextView) {
            val text = view.text?.toString()?.trim()
            if (!text.isNullOrEmpty() && text.length <= MAX_TITLE_CHARS) return text
        }
        if (view is android.view.ViewGroup) {
            for (index in 0 until view.childCount) {
                val child = view.getChildAt(index) ?: continue
                firstText(child, depth + 1)?.let { return it }
            }
        }
        return null
    }

    private fun isCandidate(className: String): Boolean {
        val lower = className.lowercase()
        if (!lower.startsWith("com.bilibili") && !lower.startsWith("tv.danmaku")) return false
        return EXCLUDED_MARKERS.none(lower::contains)
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "home_components_missing",
            "[BIL] 首页组件自定义隐藏适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "home_component_filter"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "home_component_filter_status"
        private const val MAX_TITLE_DEPTH = 6
        private const val MAX_TITLE_CHARS = 24
        private const val MAX_PARENT_DEPTH = 12
        private val HOME_CONTAINER_MARKERS = listOf(
            "basehomefragment",
            "homefragmentv2",
            "main2.homefragment",
            "pagebuildcomponent"
        )
        private val EXCLUDED_MARKERS = listOf(
            "search",
            "dynamic",
            "following",
            "history",
            "favorite",
            "detail",
            "mine",
            "mainfragment"
        )

        /**
         * 父 Fragment 的**类继承链**里任一类名命中容器标记即算首页容器。
         *
         * 只看运行时类名会漏掉新首页框架：那边首页页面的运行时类是
         * `tv.danmaku.bili.home.tab.page.HomeFragment`，标记 `basehomefragment` 对应的是它的
         * 父类 `BaseHomeFragment`（8.92.1–9.12.0 全宿主里唯一名字含它的类）。
         * 旧框架的 `HomeFragmentV2` 父链上没有别的类名会因此新命中。
         */
        internal fun isHomeContainer(type: Class<*>): Boolean =
            generateSequence(type) { it.superclass }
                .take(MAX_CONTAINER_HIERARCHY)
                .any { owner ->
                    val name = owner.name.lowercase()
                    HOME_CONTAINER_MARKERS.any(name::contains)
                }

        private const val MAX_CONTAINER_HIERARCHY = 8

        internal fun isClassMatched(rules: String, className: String): Boolean =
            isStaticCandidate(className) && RuleSetCodec.matches(
                RuleSetCodec.parse(rules),
                className,
                className.substringAfterLast('.')
            )

        private fun isStaticCandidate(className: String): Boolean {
            val lower = className.lowercase()
            return (lower.startsWith("com.bilibili") || lower.startsWith("tv.danmaku")) &&
                EXCLUDED_MARKERS.none(lower::contains)
        }
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import java.lang.reflect.Field
import java.lang.reflect.Method

/** 在首页推荐响应的公开 List 边界过滤广告、图文和游戏推广。 */
internal class HomeRecommendPurifyFeatureInstaller(
    private val removeAds: Boolean,
    private val removeCmV2: Boolean,
    private val removeBanner: Boolean,
    private val removePictures: Boolean,
    private val removeGamePromotions: Boolean,
    titleFilterEnabled: Boolean,
    rawTitleKeywords: String,
    private val removeLive: Boolean,
    private val removeCourses: Boolean,
    private val removeVertical: Boolean,
    private val removeLarge: Boolean,
    minDurationSeconds: Int,
    maxDurationSeconds: Int,
    private val points: VersionAdapter.HomeRecommendFeedPoints?,
    private val removePgc: Boolean = false,
    private val removeSpecialCards: Boolean = false,
    /**
     * 标签黑名单的原始存储串；空串就是整个维度关闭。
     *
     * 同一条串里数字按标签 id 比、非数字按标签名整串比，见 [TidBlocklistCodec]。
     */
    rawBlockedTids: String = "",
    /**
     * UP 主黑名单的原始存储串；空串就是整个维度关闭。
     *
     * 判据与详情页那档一致：整串相等，同时承认 UP 名与 mid。
     */
    rawBlockedAuthors: String = "",
    /**
     * 三点面板劫持是否开着。
     *
     * 开着时即使黑名单为空也要解析 tid / UP 读取链——用户可能这一场才从面板点第一个，
     * 那些选择只活在 [SectionPickSession] / [AuthorPickSession] 的内存里，
     * 没有 accessor 就当场失效。
     */
    private val sectionPickEnabled: Boolean = false,
    minPlayCount: Int = 0,
    maxPlayCount: Int = 0,
    /**
     * 「屏蔽 AI 生成声明视频」的首页一档：`uri` 里 `creation_tags` 含 `aigc`，
     * 或 aid 已被详情页确认过（[AiDeclaredVideoRegistry]）。判据见 [AiDeclaredVideoPolicy]。
     */
    private val removeAiDeclared: Boolean = false,
    /**
     * 强力模式开着时，详情页记下的发布者只写进 [AuthorPickSession]；
     * 这里必须据此打开 UP 维度的读取链，否则"本进程立即生效"那半句不成立。
     */
    aiDeclaredStrongMode: Boolean = false,
    /**
     * 智能过滤推荐视频（JEV，按标题）。列表 getter 可能在主线程：主线程只查缓存并投后台；
     * 后台线程且开了"首屏等待"时在当前线程等结果。
     */
    semanticJudge: SemanticJudge? = null,
    /** debug 构建的观测日志目录；release 为 null。 */
    semanticLogDir: java.io.File? = null,
    isMainThread: () -> Boolean = { android.os.Looper.myLooper() == android.os.Looper.getMainLooper() }
) : FeatureInstaller {

    private val semantic = SemanticTitleFilter(semanticJudge, semanticLogDir, isMainThread, "home")

    private val titleKeywords = if (titleFilterEnabled) {
        RuleSetCodec.parse(rawTitleKeywords)
    } else {
        emptySet()
    }
    private val durationRange = VideoDurationRange(minDurationSeconds, maxDurationSeconds)
    private val playCountRange = VideoPlayCountRange(minPlayCount, maxPlayCount)

    /** 没有开关，名单非空即启用——与标题关键词同模式，避免"开着但名单为空"的无意义状态。 */
    private val blockedTids = TidBlocklistCodec.parse(rawBlockedTids)

    /** 同一条串里的非数字项按标签名整串比，判据与详情页那档共用 [ExactRuleSetCodec]。 */
    private val blockedTagNames = TidBlocklistCodec.parseNames(rawBlockedTids)

    /** 这个维度是否需要解析读取链；名字和 id 任一非空都要。 */
    private val tagDimensionEnabled =
        blockedTids.isNotEmpty() || blockedTagNames.isNotEmpty() || sectionPickEnabled

    /** UP 主名单：整串相等，名字与 mid 共用一份，见 [ExactRuleSetCodec]。 */
    private val blockedAuthors = ExactRuleSetCodec.parse(rawBlockedAuthors)

    /** UP 维度是否需要解析读取链；面板劫持开着时即使名单为空也要。 */
    private val authorDimensionEnabled = blockedAuthors.isNotEmpty() || sectionPickEnabled ||
        (removeAiDeclared && aiDeclaredStrongMode)

    /** 只有这些开关才需要把卡片公开字段交给语义分类器；Banner 单独走精确 token 判定。 */
    private val semanticClassificationEnabled =
        removeCmV2 || removeAds || removePictures || removeGamePromotions ||
            removeLive || removeCourses || removeVertical || removeLarge

    /** `shouldRemove` 的其余判定也全部关闭时，直接跳过整段分类/规则工作。 */
    private val itemRemovalEnabled = semanticClassificationEnabled ||
        titleKeywords.isNotEmpty() || durationRange.isEnabled ||
        playCountRange.isEnabled || tagDimensionEnabled || authorDimensionEnabled ||
        removeAiDeclared || semantic.enabled

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (removeBanner) add("home_banner_feed")
        if (removeAds) add("home_recommend_ads_removed")
        if (removeCmV2) add("home_recommend_cm_v2_removed")
        if (removePictures) add("home_recommend_pictures_removed")
        if (removeGamePromotions) add("home_recommend_game_promotions_removed")
        if (titleKeywords.isNotEmpty()) add("home_recommend_title_filter_enabled")
        if (removeLive) add("home_recommend_live_removed")
        if (removeCourses) add("home_recommend_courses_removed")
        if (removeVertical) add("home_recommend_vertical_removed")
        if (removeLarge) add("home_recommend_large_removed")
        if (removePgc) add("home_recommend_pgc_removed")
        if (removeSpecialCards) add("home_recommend_special_cards_removed")
        if (durationRange.isEnabled) add("home_recommend_duration_filter")
        if (playCountRange.isEnabled) add("home_recommend_play_count_filter")
        if (tagDimensionEnabled) add("home_recommend_tid_block")
        if (authorDimensionEnabled) add("home_recommend_author_block")
        if (removeAiDeclared) add(AiDeclaredVideoPolicy.CAPABILITY_HOME)
        if (semantic.enabled) add(CAPABILITY_SEMANTIC)
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        val hasContentFilter = removeAds || removeCmV2 || removeBanner || removePictures || removeGamePromotions ||
            titleKeywords.isNotEmpty() || removeLive || removeCourses || removeVertical ||
            removeLarge || removePgc || removeSpecialCards || tagDimensionEnabled ||
            authorDimensionEnabled || removeAiDeclared || semantic.enabled
        if (durationRange.isConfigured && !durationRange.isValid) {
            environment.logError(
                "home_recommend_duration_invalid",
                "[BIL] 推荐视频时长范围无效，已保守放行: " +
                    "min=${durationRange.minSeconds},max=${durationRange.maxSeconds}"
            )
        }
        if (playCountRange.isConfigured && !playCountRange.isValid) {
            environment.logError(
                "home_recommend_play_count_invalid",
                "[BIL] 推荐视频播放量范围无效，已保守放行: " +
                    "min=${playCountRange.minimum},max=${playCountRange.maximum}"
            )
        }
        if (!hasContentFilter && !durationRange.isEnabled && !playCountRange.isEnabled) {
            val reason = when {
                durationRange.isConfigured && !durationRange.isValid -> "invalid-duration-range"
                playCountRange.isConfigured && !playCountRange.isValid -> "invalid-play-count-range"
                else -> "disabled"
            }
            environment.reportStatus(CHANNEL_STATUS, reason)
            return FeatureInstallResult.Skipped(reason)
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = points ?: return missing(environment, "missing-adapter-point")
        val accessors = Accessors(
            holderType = resolve(environment, "holder", adapted.holderTypeGetter)
                ?: return missing(environment, "missing-holder-getter"),
            bizType = resolveOptional(environment, "biz", adapted.bizTypeGetter),
            adInfo = resolveOptional(environment, "ad_info", adapted.adInfoGetter),
            cardType = resolveOptional(environment, "card_type", adapted.cardTypeGetter),
            cardGoto = resolveOptional(environment, "card_goto", adapted.cardGotoGetter),
            goTo = resolveOptional(environment, "goto", adapted.goToGetter),
            uri = resolveOptional(environment, "uri", adapted.uriGetter),
            param = resolveOptional(environment, "param", adapted.paramGetter),
            title = resolveOptional(environment, "title", adapted.titleGetter),
            subtitle = resolveOptional(environment, "subtitle", adapted.subtitleGetter),
            desc = resolveOptional(environment, "desc", adapted.descGetter),
            duration = resolveDuration(environment, adapted),
            playCountGate = resolvePlayCountGate(environment, adapted),
            tid = resolveTid(environment, adapted),
            author = resolveAuthor(environment, adapted)
        )
        var partialReason: String? = null
        val extraTypesReadable = accessors.cardType != null || accessors.cardGoto != null || accessors.goTo != null
        if (removePgc && !extraTypesReadable && accessors.uri == null) partialReason = "missing-pgc-readers"
        if (removeSpecialCards && !extraTypesReadable) partialReason = "missing-special-card-readers"
        if (durationRange.isEnabled && accessors.duration == null) {
            if (!hasContentFilter && !playCountRange.isEnabled) {
                return missing(environment, "missing-duration-accessor")
            }
            partialReason = "missing-duration-accessor"
            environment.logError(
                "home_recommend_duration_missing",
                "[BIL] 首页推荐时长读取适配不完整，其他推荐过滤继续生效"
            )
        }
        val playCountGate = accessors.playCountGate ?: accessors.duration?.playerArgsGetter
        if (playCountRange.isEnabled && playCountGate == null) {
            if (!hasContentFilter && !durationRange.isEnabled) {
                return missing(environment, "missing-play-count-gate")
            }
            partialReason = if (partialReason == null) {
                "missing-play-count-gate"
            } else {
                "$partialReason+missing-play-count-gate"
            }
            environment.logError(
                "home_recommend_play_count_missing",
                "[BIL] 首页推荐播放量读取门禁适配不完整，其他推荐过滤继续生效"
            )
        }
        // 名单非空却读不到 tid：必须报 partial。否则每张卡都拿 null、静默变成"从不命中"，
        // 用户只会看到"设了标签但没生效"，而状态通道一路 success。
        if (tagDimensionEnabled && accessors.tid == null) {
            partialReason = if (partialReason == null) "missing-tid-accessor"
            else "$partialReason+missing-tid-accessor"
            environment.logError(
                "home_recommend_tid_missing",
                "[BIL] 首页推荐标签读取适配不完整（args/tid 链缺失），" +
                    "标签维度不生效，其他推荐过滤继续"
            )
        }
        // UP 名单非空却读不到读取链：同理必须报 partial，不能静默变成"从不命中"。
        if (authorDimensionEnabled && accessors.author == null) {
            partialReason = if (partialReason == null) "missing-author-accessor"
            else "$partialReason+missing-author-accessor"
            environment.logError(
                "home_recommend_author_missing",
                "[BIL] 首页推荐 UP 读取适配不完整（args/up 链缺失），" +
                    "UP 维度不生效，其他推荐过滤继续"
            )
        }
        // AI 声明这一档两条输入各自独立：uri 读不到只丢标签那半边，param 读不到只丢已知 aid 那半边；
        // 两条都没有才是整档失效，必须报 partial，不能静默变成"从不命中"。
        if (removeAiDeclared && accessors.uri == null && accessors.param == null) {
            partialReason = if (partialReason == null) "missing-ai-declared-readers"
            else "$partialReason+missing-ai-declared-readers"
            environment.logError(
                "home_recommend_ai_declared_missing",
                "[BIL] 首页推荐 uri/param 读取适配不完整，AI 声明这一档不生效，其他推荐过滤继续"
            )
        }
        // 只填了标签名却读不到 tname：同理，名字那半边会静默失效。
        if (blockedTagNames.isNotEmpty() && accessors.tid?.tnameGetter == null) {
            partialReason = if (partialReason == null) "missing-tname-accessor"
            else "$partialReason+missing-tname-accessor"
            environment.logError(
                "home_recommend_tname_missing",
                "[BIL] 首页推荐标签名读取适配不完整（args/tname 链缺失），" +
                    "按名字那半边不生效，按 id 那半边继续"
            )
        }

        var installed = 0
        adapted.responseItemGetters.forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("home.recommend.purify.$index", point) {
                    after {
                        if (hasThrowable) return@after
                        val source = result as? List<*> ?: return@after
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        var removedBanners = 0
                        var removedPgc = 0
                        var removedSpecial = 0
                        val semanticVerdicts = semantic.verdicts(source) { item -> invokeString(accessors.title, item) }
                        val filtered = CopyOnFilter.list(source) { item ->
                            if (semanticVerdicts?.get(item) == SemanticVerdict.BLOCK) return@list true
                            val signals = signals(item, accessors)
                            probeTag(signals, environment)
                            val isBanner = removeBanner && isHomeBanner(signals)
                            if (isBanner) removedBanners += 1
                            val kind = if (removePgc || removeSpecialCards) HomeExtraCardPolicy.classify(
                                signals.cardType, signals.cardGoto, signals.goTo, signals.uri
                            ) else HomeExtraCardPolicy.Kind.UNKNOWN
                            val pgc = removePgc && kind == HomeExtraCardPolicy.Kind.PGC
                            val special = removeSpecialCards && kind == HomeExtraCardPolicy.Kind.SPECIAL
                            if (pgc) { removedPgc++; environment.reportRuntimeEvidence("home_recommend_pgc_removed", FeatureRuntimeStage.OBSERVED) }
                            if (special) { removedSpecial++; environment.reportRuntimeEvidence("home_recommend_special_cards_removed", FeatureRuntimeStage.OBSERVED) }
                            pgc || special || isBanner || shouldRemove(signals)
                        }
                        if (filtered !== source) {
                            result = filtered
                            if (removedPgc > 0) environment.reportRuntimeEvidence("home_recommend_pgc_removed", FeatureRuntimeStage.APPLIED)
                            if (removedSpecial > 0) environment.reportRuntimeEvidence("home_recommend_special_cards_removed", FeatureRuntimeStage.APPLIED)
                            environment.reportRuntimeEvidence(
                                ID,
                                FeatureRuntimeStage.APPLIED,
                                source.size - filtered.size
                            )
                            environment.logInfo(
                                "home_recommend_removed",
                                "[BIL] 首页推荐服务端数据已过滤 ${source.size - filtered.size} 项"
                            )
                        }
                        if (removedBanners > 0) {
                            environment.reportRuntimeEvidence(
                                "home_banner_feed",
                                FeatureRuntimeStage.OBSERVED
                            )
                            environment.reportRuntimeEvidence(
                                "home_banner_feed",
                                FeatureRuntimeStage.APPLIED,
                                removedBanners
                            )
                        }
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "home_recommend_purify_$index",
                    "[BIL] 首页推荐服务端过滤 Hook 注册失败(" +
                        "${point.className}#${point.methodName}): $throwable"
                )
            }
        }
        if (installed == 0) return missing(environment, "registration-failed")
        val routeReadable = accessors.cardType != null || accessors.cardGoto != null ||
            accessors.goTo != null || accessors.uri != null
        for (capability in capabilityIds) {
            val readable = when (capability) {
                "home_recommend_duration_filter" -> accessors.duration != null
                "home_recommend_play_count_filter" ->
                    (accessors.playCountGate ?: accessors.duration?.playerArgsGetter) != null
                "home_recommend_title_filter_enabled" -> accessors.title != null
                "home_recommend_ads_removed" -> true // required holderType is a valid advertisement-token source
                "home_recommend_cm_v2_removed" -> accessors.cardType != null // this predicate reads cardType only
                "home_banner_feed" -> true
                "home_recommend_large_removed" -> true // required holderType is resolved above
                "home_recommend_pgc_removed" -> extraTypesReadable || accessors.uri != null
                "home_recommend_special_cards_removed" -> extraTypesReadable
                "home_recommend_tid_block" -> accessors.tid != null
                // UP 屏蔽的真实前提是 args/up 读取链；落进 else 的 routeReadable 会在
                // "链缺失但路由字段可读"的宿主上把这一维度报成可用，与实际相反。
                "home_recommend_author_block" -> accessors.author != null
                AiDeclaredVideoPolicy.CAPABILITY_HOME -> accessors.uri != null || accessors.param != null
                CAPABILITY_SEMANTIC -> accessors.title != null
                else -> routeReadable
            }
            environment.reportCapabilityCoverage(capability, readable, installed, adapted.responseItemGetters.size)
        }
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        environment.reportStatus(
            CHANNEL_STATUS,
            partialReason?.let { "partial:$it" } ?:
                if (installed == adapted.responseItemGetters.size) "success" else "partial:$installed/${adapted.responseItemGetters.size}"
        )
        environment.logInfo(
            "home_recommend_purify_ok",
            "[BIL] 首页推荐服务端过滤已安装，hooks=$installed," +
                "duration=${durationRange.isEnabled}," +
                "playCount=${playCountRange.isEnabled}," +
                // 只记条数不记内容；用来区分"名单没传到宿主"和"传到了但不命中"。
                "tagIds=${blockedTids.size},tagNames=${blockedTagNames.size}," +
                "tnameReadable=${accessors.tid?.tnameGetter != null}"
        )
        return FeatureInstallResult.Installed(installed, complete = partialReason == null && installed == adapted.responseItemGetters.size)
    }

    /** 已经记过的 `tid:tname`，每种只记一条。 */
    private val probedTags = java.util.Collections.synchronizedSet(HashSet<String>())

    /**
     * 把首页卡片实际带的 `tid` / `tname` 记进日志，**只在这个维度开着时**才做。
     *
     * 为什么需要：一个视频有很多标签，`args.tname` 只是其中**某一个**，未必是用户在
     * 卡片上看到、或者心里想的那个。没有这条日志，用户填了名字不生效时无从下手——
     * 只能反复猜。有了它，照着日志里的值填就一定命中。
     *
     * `tname` 本来就会经观测快照通道呈现给用户（`SURFACE_SECTION_PICKS` 的条目标题），
     * 记进日志不越界。有界：只记 [MAX_PROBED_TAGS] 种，之后彻底静默。
     */
    private fun probeTag(signals: Signals, environment: HookEnvironment) {
        if (!tagDimensionEnabled || probedTags.size >= MAX_PROBED_TAGS) return
        val tid = signals.tid ?: return
        if (tid <= 0L) return
        val key = "$tid:${signals.tname}"
        if (!probedTags.add(key)) return
        // 日志 key 必须带上这条观测的身份，宿主桥按 key 全局去重。
        environment.logInfo(
            "home_recommend_tag_seen:$key",
            "[BIL] 首页卡片标签 tid=$tid, tname=${signals.tname}, rid=${signals.rid}"
        )
    }

    private fun shouldRemove(signals: Signals): Boolean {
        if (!itemRemovalEnabled) return false
        val hostSignals = signals.toHostSignals()
        val kinds = if (semanticClassificationEnabled) {
            HostContentSemanticClassifier.classify(hostSignals)
        } else {
            emptySet()
        }
        return (removeCmV2 && HostContentSemanticClassifier.isCmV2(hostSignals)) ||
            (removeAds && HostContentKind.ADVERTISEMENT in kinds) ||
            (removePictures && HostContentKind.PICTURE in kinds) ||
            (removeGamePromotions && HostContentKind.GAME in kinds) ||
            RuleSetCodec.matches(titleKeywords, signals.title) ||
            (removeLive && HostContentKind.LIVE in kinds) ||
            (removeCourses && HostContentKind.COURSE in kinds) ||
            (removeVertical && HostContentKind.VERTICAL in kinds) ||
            (removeLarge && HostContentKind.LARGE in kinds) ||
            durationRange.shouldRemove(signals.durationSeconds) ||
            playCountRange.shouldRemove(signals.playCount) ||
            // 标签是独立维度：精确相等，读不到 tid 放行。
            // **只比 tid**。2026-09-12 实测：宿主把 `args.tid` 写进不感兴趣请求时用的键是
            // `tag_id`，`args.rid` 才是分区——两者不是同一个 id 空间。拿分区 id 去比这份
            // 标签名单会误删：分区 id 都是两三位数，撞上一个小标签 id 是迟早的事。
            // 持久名单与本场会话选择是两个来源，任一命中即删；
            // 会话那份不落盘，见 SectionPickSession。
            TidBlocklistCodec.matches(blockedTids, signals.tid) ||
            SectionPickSession.contains(signals.tid) ||
            // 标签名走整串相等，和详情页那档同一个 codec：contains 语义会让"科技"
            // 命中"科技美学"，用在标签上一定误伤。
            ExactRuleSetCodec.matches(blockedTagNames, signals.tname) ||
            // UP 是独立维度：名字与 mid 任一整串相等即删，读不到一律放行。
            // 持久名单与本场会话选择是两个来源，见 AuthorPickSession。
            ExactRuleSetCodec.matches(blockedAuthors, signals.upName, signals.upId) ||
            AuthorPickSession.matches(signals.upName, signals.upId) ||
            signals.aiDeclared
    }

    private fun signals(item: Any, accessors: Accessors): Signals {
        val needsRoute = removePictures || removeGamePromotions || removeLive ||
            removeCourses || removeVertical || removeLarge || removePgc || removeSpecialCards
        val needsClassification = removeAds || removeCmV2 || needsRoute
        val tidAccessor = accessors.tid
        val tidArgs = tidAccessor?.let { accessor ->
            invokeCompatible(accessor.argsGetter, item)
        }
        val authorAccessor = accessors.author
        val authorArgs = authorAccessor?.let { accessor ->
            // 9.11.0 的 tid/up 链共享同一个 ArgsData getter；只有 Method 签名相同
            // 才复用，避免把跨版本可能不同的两个容器误当成同一个对象。
            if (tidAccessor != null && tidAccessor.argsGetter == accessor.argsGetter) {
                tidArgs
            } else {
                invokeCompatible(accessor.argsGetter, item)
            }
        }
        return Signals(
            holderType = if (removeAds || removeBanner || removeLarge) {
                invokeString(accessors.holderType, item)
            } else {
                null
            },
            bizType = if (removeAds || removeBanner) {
                invokeString(accessors.bizType, item)
            } else {
                null
            },
            cardType = if (needsClassification || removeBanner) {
                invokeString(accessors.cardType, item)
            } else null,
            cardGoto = if (removeAds || removeBanner || needsRoute) {
                invokeString(accessors.cardGoto, item)
            } else {
                null
            },
            goTo = if (needsRoute || removeBanner) {
                invokeString(accessors.goTo, item)
            } else {
                null
            },
            uri = if (needsRoute) invokeString(accessors.uri, item) else null,
            param = if (removeGamePromotions) invokeString(accessors.param, item) else null,
            aiDeclared = removeAiDeclared && aiDeclared(item, accessors),
            title = if (titleKeywords.isNotEmpty() || removeGamePromotions) {
                invokeString(accessors.title, item)
            } else {
                null
            },
            subtitle = if (removeGamePromotions) invokeString(accessors.subtitle, item) else null,
            desc = if (removeGamePromotions) invokeString(accessors.desc, item) else null,
            hasAdInfo = (removeAds || removeGamePromotions) &&
                invokeCompatible(accessors.adInfo, item) != null,
            durationSeconds = if (durationRange.isEnabled) {
                accessors.duration?.let { duration ->
                    VideoDurationReader.fromContainer(
                        item,
                        duration.playerArgsGetter,
                        duration.durationGetter,
                        duration.durationField
                    )
                }
            } else {
                null
            },
            playCount = if (playCountRange.isEnabled) {
                (accessors.playCountGate ?: accessors.duration?.playerArgsGetter)?.let { gate ->
                    VideoPlayCountReader.fromHomeCover(item, gate)
                }
            } else {
                null
            },
            // 名单为空且没开面板劫持时 accessors.tid/author 是 null，这里不产生反射调用。
            // 同一张卡的 tid/tname/rid 与 upName/upId 各自共用一次 getArgs()；若两条
            // 适配链确实指向同一个 Method，再额外跨维度复用一次容器读取。
            tid = tidAccessor?.let { accessor ->
                tidArgs?.let { args ->
                    (invokeCompatible(accessor.tidGetter, args) as? Number)?.toLong()
                }
            },
            tname = tidAccessor?.tnameGetter?.let { getter ->
                tidArgs?.let { args -> invokeCompatible(getter, args) as? String }
            },
            // 只喂探针。探针记满就静默，之后这里的反射也随之停掉。
            rid = tidAccessor?.ridGetter?.takeIf { probedTags.size < MAX_PROBED_TAGS }
                ?.let { getter ->
                    tidArgs?.let { args ->
                        (invokeCompatible(getter, args) as? Number)?.toLong()
                    }
                },
            // UP 维度关着时 authorAccessor 是 null，这里不产生任何反射调用。
            upName = authorAccessor?.let { accessor ->
                authorArgs?.let { args -> invokeCompatible(accessor.upNameGetter, args) as? String }
            },
            // mid 以十进制串参与比对，这样用户填名字或填 mid 都能命中。
            upId = authorAccessor?.upIdGetter?.let { getter ->
                authorArgs?.let { args ->
                    (invokeCompatible(getter, args) as? Number)?.takeIf { it.toLong() > 0L }
                        ?.toLong()?.toString()
                }
            }
        )
    }

    /**
     * 先比已知 aid（一次 `toLongOrNull` + 集合查找），再看 uri 标签（原串预判不分配）。
     * 标签命中的 aid 也记进 [AiDeclaredVideoRegistry]，让相关推荐与补位候选同样避开它。
     */
    private fun aiDeclared(item: Any, accessors: Accessors): Boolean {
        val aid = AiDeclaredVideoPolicy.aidFromParam(invokeString(accessors.param, item))
        if (AiDeclaredVideoRegistry.contains(aid)) return true
        if (!AiDeclaredVideoPolicy.feedUriDeclaresAigc(invokeString(accessors.uri, item))) return false
        AiDeclaredVideoRegistry.add(aid)
        return true
    }

    /** 名单为空时**不解析**，免得在热路径上白做两次反射查找。 */
    private fun resolveTid(
        environment: HookEnvironment,
        points: VersionAdapter.HomeRecommendFeedPoints
    ): TidAccessor? {
        if (!tagDimensionEnabled) return null
        val argsPoint = points.argsGetter ?: return null
        val tidPoint = points.argsTidGetter ?: return null
        val argsGetter = resolve(environment, "args", argsPoint) ?: return null
        val tidGetter = environment.hookPoints.resolveAdapted(
            "home.recommend.resolve.args_tid",
            tidPoint.className,
            tidPoint.methodName,
            tidPoint.paramClassNames
        ) ?: return null
        // 这个维度开着就解析：除了按名字比，探针也要用它把卡片实际的标签名记进日志
        // ——没有那条日志，用户填了名字不生效时只能反复猜。
        val tnameGetter = points.argsTnameGetter
            ?.let { point ->
                environment.hookPoints.resolveAdapted(
                    "home.recommend.resolve.args_tname",
                    point.className,
                    point.methodName,
                    point.paramClassNames
                )
            }
        // 分区 id 只喂探针，不参与判定；缺了什么都不影响。
        val ridGetter = points.argsRidGetter?.let { point ->
            environment.hookPoints.resolveAdapted(
                "home.recommend.resolve.args_rid",
                point.className,
                point.methodName,
                point.paramClassNames
            )
        }
        return TidAccessor(argsGetter, tidGetter, tnameGetter, ridGetter)
    }

    /** 名单为空且没开面板劫持时**不解析**，免得在热路径上白做反射查找。 */
    private fun resolveAuthor(
        environment: HookEnvironment,
        points: VersionAdapter.HomeRecommendFeedPoints
    ): AuthorAccessor? {
        if (!authorDimensionEnabled) return null
        val argsPoint = points.argsGetter ?: return null
        val namePoint = points.argsUpNameGetter ?: return null
        val argsGetter = resolve(environment, "args", argsPoint) ?: return null
        val upNameGetter = environment.hookPoints.resolveAdapted(
            "home.recommend.resolve.args_up_name",
            namePoint.className,
            namePoint.methodName,
            namePoint.paramClassNames
        ) ?: return null
        val upIdGetter = points.argsUpIdGetter?.let { point ->
            environment.hookPoints.resolveAdapted(
                "home.recommend.resolve.args_up_id",
                point.className,
                point.methodName,
                point.paramClassNames
            )
        }
        return AuthorAccessor(argsGetter, upNameGetter, upIdGetter)
    }

    private fun resolveDuration(
        environment: HookEnvironment,
        points: VersionAdapter.HomeRecommendFeedPoints
    ): DurationAccessor? {
        if (!durationRange.isEnabled) return null
        val getterPoint = points.playerArgsGetter ?: return null
        val getter = resolve(environment, "player_args", getterPoint) ?: return null
        val durationGetter = points.playerArgsDurationGetter?.let { point ->
            resolve(environment, "player_args_duration", point)
        }
        val durationField = points.playerArgsDurationField?.let { fieldName ->
            environment.hookPoints.resolveField(
                "home.recommend.resolve.player_args_duration_field",
                getter.returnType,
                fieldName
            )
        }
        if (durationGetter == null && durationField == null) return null
        return DurationAccessor(getter, durationGetter, durationField)
    }

    private fun resolvePlayCountGate(
        environment: HookEnvironment,
        points: VersionAdapter.HomeRecommendFeedPoints
    ): Method? {
        if (!playCountRange.isEnabled) return null
        val getterPoint = points.playerArgsGetter ?: return null
        return resolve(environment, "player_args_play_count", getterPoint)
    }

    private fun resolveOptional(
        environment: HookEnvironment,
        suffix: String,
        point: VersionAdapter.HookPoint?
    ): Method? = point?.let { resolve(environment, suffix, it) }

    private fun resolve(
        environment: HookEnvironment,
        suffix: String,
        point: VersionAdapter.HookPoint
    ): Method? = environment.hookPoints.resolveAdapted(
        "home.recommend.resolve.$suffix",
        point.className,
        point.methodName,
        point.paramClassNames
    )

    private fun invokeString(method: Method?, target: Any): String? =
        invokeCompatible(method, target)?.toString()

    private fun invokeCompatible(method: Method?, target: Any): Any? {
        if (method == null || !method.declaringClass.isInstance(target)) return null
        return runCatching { method.invoke(target) }.getOrNull()
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "home_recommend_purify_missing",
            "[BIL] 首页推荐服务端过滤适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    internal data class Signals(
        val holderType: String? = null,
        val bizType: String? = null,
        val cardType: String? = null,
        val cardGoto: String? = null,
        val goTo: String? = null,
        val uri: String? = null,
        val param: String? = null,
        val title: String? = null,
        val subtitle: String? = null,
        val desc: String? = null,
        val hasAdInfo: Boolean = false,
        val durationSeconds: Long? = null,
        val playCount: Long? = null,
        /**
         * `args.tid`——**标签 id**（宿主自己按 `tag_id` 上报），不是分区。
         *
         * 读不到就是 null，**null 一律放行**（番剧/广告卡本来就没有标签）。
         */
        val tid: Long? = null,
        /** `args.tname`——标签名；同上，读不到放行。 */
        val tname: String? = null,
        /** `args.upName`——UP 主名；读不到放行。 */
        val upName: String? = null,
        /** `args.upId`——UP 主 mid 的十进制串；读不到放行。 */
        val upId: String? = null,
        /**
         * `args.rid`——**分区 id**（宿主按 `rid` 上报），**只进探针日志、不参与任何判定**。
         *
         * 2026-09-12 实测 30 张卡：**27 张是 0**，非 0 的三个（3/3/11）与卡片内容也对不上
         * 标准分区表。**结论：新版 feed 协议的卡片 args 里没有可用的分区，"按分区过滤"
         * 这条路不通。** 留着这条探针是为了宿主哪天把它填上时能第一时间发现，
         * 不是留着给判定用的。
         */
        val rid: Long? = null,
        /** AI 生成声明一档的结论；开关关着时恒为 false，不产生任何读取。 */
        val aiDeclared: Boolean = false
    )

    private data class Accessors(
        val holderType: Method,
        val bizType: Method?,
        val adInfo: Method?,
        val cardType: Method?,
        val cardGoto: Method?,
        val goTo: Method?,
        val uri: Method?,
        val param: Method?,
        val title: Method?,
        val subtitle: Method?,
        val desc: Method?,
        val duration: DurationAccessor?,
        val playCountGate: Method?,
        val tid: TidAccessor?,
        val author: AuthorAccessor?
    )

    /**
     * UP 读取链：容器 getter + 名字 getter，缺任一级整个维度不可用。
     *
     * [upIdGetter] 可缺——缺了只是不能按 mid 命中，按名字那半边照常。
     */
    private data class AuthorAccessor(
        val argsGetter: Method,
        val upNameGetter: Method,
        val upIdGetter: Method? = null
    )

    /**
     * 两级链：容器 getter + 数值 getter，缺任一级整个维度不可用。
     *
     * [tnameGetter] 是按名字比那半边，可缺——缺了只影响名字，id 那半边照常。
     * [ridGetter] 只喂探针，缺了什么都不影响。
     */
    private data class TidAccessor(
        val argsGetter: Method,
        val tidGetter: Method,
        val tnameGetter: Method? = null,
        val ridGetter: Method? = null
    )

    private data class DurationAccessor(
        val playerArgsGetter: Method,
        val durationGetter: Method?,
        val durationField: Field?
    )

    companion object {
        const val CAPABILITY_SEMANTIC = "home_recommend_semantic_filter_enabled"
        const val ID = "home_recommend_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "home_recommend_purify_status"

        /** 标签探针上限：记满这么多种就彻底静默，不会随刷新无限增长。 */
        private const val MAX_PROBED_TAGS = 30

        internal fun isAdvertisement(value: Signals): Boolean {
            return HostContentKind.ADVERTISEMENT in
                HostContentSemanticClassifier.classify(value.toHostSignals())
        }

        internal fun isHomeBanner(value: Signals): Boolean =
            HostContentSemanticClassifier.isHomeBanner(value.toHostSignals())

        internal fun isCmV2(value: Signals): Boolean =
            HostContentSemanticClassifier.isCmV2(value.toHostSignals())

        internal fun isPicture(value: Signals): Boolean =
            HostContentKind.PICTURE in HostContentSemanticClassifier.classify(
                value.toHostSignals()
            )

        internal fun isGamePromotion(value: Signals): Boolean =
            HostContentKind.GAME in HostContentSemanticClassifier.classify(value.toHostSignals())

        internal fun isLive(value: Signals): Boolean =
            HostContentKind.LIVE in HostContentSemanticClassifier.classify(value.toHostSignals())

        internal fun isCourse(value: Signals): Boolean =
            HostContentKind.COURSE in HostContentSemanticClassifier.classify(value.toHostSignals())

        internal fun isVertical(value: Signals): Boolean =
            HostContentKind.VERTICAL in HostContentSemanticClassifier.classify(value.toHostSignals())

        internal fun isLarge(value: Signals): Boolean =
            HostContentKind.LARGE in HostContentSemanticClassifier.classify(value.toHostSignals())

        private fun Signals.toHostSignals(): HostContentSignals = HostContentSignals(
            holderType = holderType,
            bizType = bizType,
            cardType = cardType,
            cardGoto = cardGoto,
            goTo = goTo,
            uri = uri,
            param = param,
            title = title,
            subtitle = subtitle,
            desc = desc,
            hasAdInfo = hasAdInfo
        )
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import java.lang.reflect.Field
import java.util.concurrent.atomic.AtomicBoolean

/**
 * 首页顶栏 Tab 自定义隐藏，两层各自独立：
 * - `legacy`：旧首页框架，在 `HomeFragmentV2` 的 Tab 构建参数进入宿主前过滤；
 * - `frame`：新首页框架（平板/宽屏必走，见 [HomeFrameTabLocator]），在 `HomeTabData.tab`
 *   构造完成后剔除条目。
 * 两层条目都来自服务端同一份 Tab 配置（JSON `id/name/uri/tab_id`），选择器键完全相同，
 * 已勾选项跨框架通用。任一层装上即算就绪。
 */
internal class HomeTabFilterFeatureInstaller(
    rules: String,
    selectors: String = "",
    private val points: VersionAdapter.HomeTabPoints?,
    private val frameResolver: (ClassLoader?) -> HomeFrameTabLocator.Resolution = HomeFrameTabLocator::resolve
) : FeatureInstaller {

    override val id: String = ID
    private val tokens = RuleSetCodec.parse(rules)
    private val selectorSet = MineComponentSelectionCodec.decode(selectors)

    private fun hasHiddenConfiguration(): Boolean =
        tokens.isNotEmpty() || selectorSet.isNotEmpty()

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        // 即使一项都没勾也要装：不扫描就永远产不出勾选列表（沿用"我的"页的 scan / filter+scan 口径）。
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val publisher = ScanSnapshotPublisher(
            environment,
            MineComponentSnapshotCodec.SURFACE_HOME_TABS,
            setOf("home_tab_filter")
        )
        val legacy = installLegacyLayer(environment, publisher)
        val frame = installFrameLayer(environment, publisher)
        environment.reportStatus(CHANNEL_LAYERS, "legacy=${legacy.label},frame=${frame.label}")
        val installed = listOf(legacy, frame).count { it == LayerState.OK }
        if (installed == 0) {
            return missing(environment, legacy.reason ?: frame.reason ?: "missing-adapter-point")
        }
        val mode = if (hasHiddenConfiguration()) "filter+scan" else "scan"
        environment.reportStatus(CHANNEL_STATUS, "success:$mode")
        environment.logInfo(
            "home_tabs_ok",
            "[BIL] 首页 Tab 自定义隐藏已安装(legacy=${legacy.label}, frame=${frame.label})"
        )
        return FeatureInstallResult.Installed(installed)
    }

    private fun installLegacyLayer(
        environment: HookEnvironment,
        publisher: ScanSnapshotPublisher
    ): LayerState {
        val adapted = points ?: return LayerState.absent("missing-adapter-point")
        val resource = environment.hookPoints.resolveClass(
            "home.tabs.resource",
            adapted.resourceClassName
        ) ?: return LayerState.failed("missing-resource-class")
        val fields = Fields(
            id = resolveField(environment, resource, adapted.idField, "id"),
            title = resolveField(environment, resource, adapted.titleField, "title"),
            uri = resolveField(environment, resource, adapted.uriField, "uri"),
            reporter = adapted.reporterIdField?.let {
                resolveField(environment, resource, it, "reporter")
            }
        )
        if (fields.id == null || fields.title == null || fields.uri == null) {
            return LayerState.failed("missing-resource-fields")
        }
        val firstHit = AtomicBoolean(false)
        return runCatching {
            environment.registrar.adapted("home.tabs.build", adapted.buildMethod) {
                before {
                    val source = args.firstOrNull() as? List<*> ?: return@before
                    if (source.isEmpty()) return@before
                    // 先按未过滤的完整列表出快照，勾选面板才看得到"当前被隐藏的那几项"。
                    publisher.publish(
                        source.mapNotNull { item ->
                            if (!resource.isInstance(item) || item == null) return@mapNotNull null
                            entryOf(legacyValues(item, fields))
                        }
                    )
                    if (!hasHiddenConfiguration()) return@before
                    val filtered = CopyOnFilter.list(source) { item ->
                        resource.isInstance(item) && matches(legacyValues(item, fields))
                    }
                    if (filtered !== source && filtered.isNotEmpty()) {
                        args[0] = filtered
                        if (firstHit.compareAndSet(false, true)) {
                            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                            environment.logInfo(
                                "home_tabs_legacy_hit",
                                "[BIL] 首页 Tab 自定义隐藏已生效（旧首页框架层，${source.size} → ${filtered.size}）"
                            )
                        }
                    }
                }
            }
            LayerState.OK
        }.getOrElse { throwable ->
            environment.logError("home_tabs_error", "[BIL] 首页 Tab 自定义隐藏失败(旧首页框架层): $throwable")
            LayerState.failed("registration-failed")
        }
    }

    private fun installFrameLayer(
        environment: HookEnvironment,
        publisher: ScanSnapshotPublisher
    ): LayerState {
        val model = when (val resolution = frameResolver(environment.classLoader)) {
            is HomeFrameTabLocator.Resolution.Found -> resolution.model
            HomeFrameTabLocator.Resolution.Absent -> return LayerState.absent(null)
            is HomeFrameTabLocator.Resolution.Failed -> {
                environment.logError(
                    "home_tabs_frame_missing",
                    "[BIL] 首页 Tab 自定义隐藏新首页框架层定位失败: ${resolution.reason}"
                )
                return LayerState.failed("frame-${resolution.reason}")
            }
        }
        val slot = model.slot(HomeFrameTabLocator.ELEMENT_TAB)
            ?: return LayerState.failed("frame-missing-tab-slot")
        val item = model.item
        val firstHit = AtomicBoolean(false)
        val hook = HomeFrameListHook(
            slot = slot,
            item = item,
            onScan = { source ->
                publisher.accumulateAll(
                    source.mapNotNull { candidate ->
                        if (candidate == null || !item.itemClass.isInstance(candidate)) return@mapNotNull null
                        entryOf(frameValues(item, candidate))
                    }
                )
            },
            shouldHide = if (hasHiddenConfiguration()) { candidate ->
                item.itemClass.isInstance(candidate) && matches(frameValues(item, candidate))
            } else null,
            onApplied = { before, after ->
                if (firstHit.compareAndSet(false, true)) {
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                    environment.logInfo(
                        "home_tabs_frame_hit",
                        "[BIL] 首页 Tab 自定义隐藏已生效（新首页框架层，$before → $after）"
                    )
                }
            }
        )
        var registered = 0
        model.constructors.forEachIndexed { index, constructor ->
            runCatching {
                environment.registrar.constructor("home.tabs.frame.ctor.$index", constructor) {
                    before { hook.enter() }
                    after {
                        runCatching { hook.exit(instance) }.onFailure { throwable ->
                            environment.logError(
                                "home_tabs_frame_error",
                                "[BIL] 首页 Tab 新首页框架层处理失败: $throwable"
                            )
                        }
                    }
                }
                registered += 1
            }.onFailure { throwable ->
                environment.logError(
                    "home_tabs_frame_ctor_$index",
                    "[BIL] 首页 Tab 新首页框架层构造器注册失败: $throwable"
                )
            }
        }
        if (registered == 0) return LayerState.failed("frame-registration-failed")
        // 运行期诊断桥只按旧框架适配点记 ADAPTED；新框架层由安装器自己补上。
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        return LayerState.OK
    }

    private fun resolveField(
        environment: HookEnvironment,
        owner: Class<*>,
        name: String,
        suffix: String
    ): Field? = environment.hookPoints.resolveField("home.tabs.$suffix", owner, name)

    private fun legacyValues(item: Any, fields: Fields) = TabValues(
        id = readString(fields.id, item),
        title = readString(fields.title, item),
        uri = readString(fields.uri, item),
        reporter = readString(fields.reporter, item)
    )

    /**
     * 旧框架 `MainResourceManager` 把 JSON `id` 放进第一个 String 字段、`tab_id` 放进
     * reporter 字段；新框架按元素名直接取同名值，两边出的键完全相同。
     */
    private fun frameValues(item: HomeFrameTabLocator.Item, candidate: Any) = TabValues(
        id = item.string(candidate, "id"),
        title = item.string(candidate, "name"),
        uri = item.string(candidate, "uri"),
        reporter = item.string(candidate, "tab_id")
    )

    private fun entryOf(values: TabValues): MineComponentScanEntry? = MineComponentScanEntry.create(
        kind = "home_tab",
        title = values.title,
        id = values.id,
        uri = values.uri,
        showing = !matches(values)
    )

    /** 手填规则与勾选选择器取并集；两条来源互不依赖，任一命中即隐藏。 */
    private fun matches(values: TabValues): Boolean {
        if (tokens.isNotEmpty() && RuleSetCodec.matches(
                tokens,
                values.id,
                values.title,
                values.uri,
                values.reporter
            )
        ) return true
        if (selectorSet.isEmpty()) return false
        val key = MineComponentSelector.key("home_tab", values.title, values.id, values.uri)
        return key != null && key in selectorSet
    }

    private fun readString(field: Field?, target: Any): String? = runCatching {
        field?.get(target) as? String
    }.getOrNull()

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("home_tabs_missing", "[BIL] 首页 Tab 自定义隐藏适配不完整: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    private class TabValues(val id: String?, val title: String?, val uri: String?, val reporter: String?)

    private data class Fields(
        val id: Field?,
        val title: Field?,
        val uri: Field?,
        val reporter: Field?
    )

    private class LayerState private constructor(val label: String, val reason: String?) {
        companion object {
            val OK = LayerState("ok", null)
            fun absent(reason: String?) = LayerState("absent", reason)
            fun failed(reason: String) = LayerState("failed", reason)
        }
    }

    companion object {
        const val ID = "home_tab_filter"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "home_tab_filter_status"
        private const val CHANNEL_LAYERS = "home_tab_filter_layers"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.widget.TextView
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import java.lang.reflect.Method

/**
 * Compose 顶栏右上角项列表的过滤器。
 *
 * 独立成类是为了让"失败一次就整层停手"这个状态**跟着安装器实例走**，而不是挂在
 * companion 上——静态可变状态会让单测互相污染，也会让两个宿主进程里的降级串在一起。
 * 菜单层有自己的状态，不受这里影响。
 */
internal class ComposeTopRightFilter(
    /**
     * 判据默认就是两层共用的那一个；做成参数只为让"失败一次就停手"这条契约可测——
     * 生产路径上真正会抛的是字段枚举，单测里没法用普通类触发。
     */
    private val isGameEntry: (Any) -> Boolean = HomeTopBarFeatureInstaller::isGameMenuItem
) {
    @Volatile
    private var degraded = false

    val isDegraded: Boolean get() = degraded

    /**
     * 剔掉游戏中心项；没有要剔的（或整层已降级）返回 null，让调用方**不要**替换参数
     * ——避免无谓分配，也避免把原列表换成一个等价副本。
     *
     * 这条路径每次列表变化都会走，所以失败必须停手：反复抛会刷满宿主日志，而且
     * 失败说明元素结构变了、继续试没有意义。失败时一律不改参数（对宿主 fail-open），
     * 漏掉的那次由菜单层兜。
     */
    fun filter(items: List<*>, environment: HookEnvironment): List<*>? {
        if (degraded || items.isEmpty()) return null
        return try {
            val kept = items.filter { item -> item == null || !isGameEntry(item) }
            if (kept.size == items.size) null else kept
        } catch (throwable: Throwable) {
            degraded = true
            environment.logError(
                "home_game_menu_compose_err",
                "[BIL] Compose 顶栏层过滤失败，该层停用（菜单层不受影响）: $throwable"
            )
            null
        }
    }
}

/** 首页顶部栏净化：游戏中心入口与搜索框默认推荐词。 */
internal class HomeTopBarFeatureInstaller(
    private val hideGameMenu: Boolean,
    private val hideSearchDefaultWord: Boolean,
    private val points: VersionAdapter.HomeTopBarPoints?
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (hideGameMenu) add("home_top_bar_game_menu_hidden")
        if (hideSearchDefaultWord) add("home_top_bar_search_word_hidden")
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!hideGameMenu && !hideSearchDefaultWord) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }

        var installedCount = 0
        var gameReady = !hideGameMenu
        var searchViewReady = !hideSearchDefaultWord
        var searchWordReady = !hideSearchDefaultWord

        // 游戏中心入口两条互为保底的路径，**必须各自独立**：老 options menu 路径
        // （`menu.a#b`）与新 Compose 顶栏路径（`TopRightComponent$initTopRight$1$1`）
        // 在 9.11.0 上并存，哪条真正生效取决于宿主放量。两者各自 runCatching、
        // 各自计入安装数、各自上报，任一缺失都不拖累另一条——把它们串成 AND
        // 会让可用性变成两者之积，比单层更差。
        var menuLayerInstalled = false
        var composeLayerInstalled = false
        if (hideGameMenu) {
            val point = points?.gameMenu
            if (point != null) {
                menuLayerInstalled = runCatching {
                    environment.registrar.adapted("home.top_bar.game_menu", point) {
                        before {
                            val target = instance ?: return@before
                            if (hasGameMenuAction(target, point.viewField)) {
                                result = null
                                environment.logInfo(
                                    "home_game_menu",
                                    "[BIL] 已隐藏首页顶部游戏中心入口（菜单层）"
                                )
                            }
                        }
                    }
                    installedCount += 1
                }.isSuccess
            }

            val composePoint = points?.composeGameMenu
            if (composePoint != null) {
                val filter = ComposeTopRightFilter()
                composeLayerInstalled = runCatching {
                    environment.registrar.adapted("home.top_bar.game_compose", composePoint) {
                        before {
                            val items = argOrNull(0) as? List<*> ?: return@before
                            val kept = filter.filter(items, environment) ?: return@before
                            args[0] = kept
                            environment.logInfo(
                                "home_game_menu_compose",
                                "[BIL] 已隐藏首页顶部游戏中心入口（Compose 列表层，" +
                                    "${items.size} → ${kept.size}）"
                            )
                        }
                    }
                    installedCount += 1
                }.isSuccess
            }

            // 两条路径只要有一条装上就算就绪：老宿主没有 Compose 层、
            // 将来老菜单路径下线后也只会剩 Compose 层，要求"全装上"会永久报 partial。
            gameReady = menuLayerInstalled || composeLayerInstalled
            environment.reportStatus(
                CHANNEL_GAME_LAYERS,
                "menu=${layerState(points?.gameMenu != null, menuLayerInstalled)}," +
                    "compose=${layerState(composePoint != null, composeLayerInstalled)}"
            )
        }

        if (hideSearchDefaultWord) {
            val viewPoint = points?.baseOnViewCreated
            searchViewReady = viewPoint != null && runCatching {
                environment.registrar.adapted("home.top_bar.search_view", viewPoint) {
                    after {
                        if (hasThrowable) return@after
                        clearSearchText(instance, viewPoint.viewField, environment)
                    }
                }
                installedCount += 1
            }.isSuccess

            val wordPoints = points?.defaultWordMethods.orEmpty()
            var installedWordMethods = 0
            wordPoints.forEachIndexed { index, point ->
                if (runCatching {
                        environment.registrar.adapted(
                            "home.top_bar.search_word.$index",
                            point
                        ) {
                            before {
                                clearSearchText(
                                    instance,
                                    viewPoint?.viewField,
                                    environment
                                )
                                result = null
                            }
                        }
                    }.isSuccess
                ) {
                    installedWordMethods += 1
                    installedCount += 1
                }
            }
            searchWordReady = wordPoints.isNotEmpty() && installedWordMethods == wordPoints.size
        }

        // View 和协议层相互独立；同步/异步响应都清理文案，任一缺失必须报告 partial。
        // 初值必须是"开关开启时不就绪"：SearchMoss 解析不出来时 if 块整段跳过，
        // 若初值为 true，协议层静默缺席却一路 success，partial:search-protocol 永远出不来。
        var searchProtocolReady = !hideSearchDefaultWord
        val searchMoss = if (hideSearchDefaultWord) environment.classLoader?.let {
            KavaMemberLookup.classOrNull(it, SEARCH_MOSS_CLASS)
        } else null
        if (searchMoss != null) {
            val protocol = resolveDefaultWordsBoundary(environment, searchMoss)
            var registered = 0
            if (protocol != null) {
                listOfNotNull(protocol.sync?.let { it to false }, protocol.async?.let { it to true }).forEach { (method, async) ->
                    if (runCatching {
                        environment.registrar.exact("home.top_bar.search_default_words.$async",
                            method.declaringClass, method.name, *method.parameterTypes) {
                            if (async) before {
                                val delegate = argOrNull(1) ?: return@before
                                val proxy = MossResponseHandlerProxy.wrapTransform(protocol.handler!!, delegate) {
                                    protocol.cleaner.clean(it, environment)
                                } ?: return@before
                                args[1] = proxy
                            } else after {
                                if (hasThrowable) return@after
                                val original = result ?: return@after
                                val updated = protocol.cleaner.clean(original, environment)
                                if (updated !== original) result = updated
                            }
                        }
                    }.isSuccess) { registered++; installedCount++ }
                }
            }
            searchProtocolReady = registered == 2 && protocol?.cleaner?.complete == true
        }

        val ready = gameReady && searchViewReady && searchWordReady && searchProtocolReady
        // 分母按"这个宿主上确实存在的落点数"算，而不是固定 1：老宿主只有菜单层、
        // 放量后可能只有 Compose 层，固定分母会把正常情况报成缺失。
        val gameLayerTotal =
            (if (points?.gameMenu != null) 1 else 0) + (if (points?.composeGameMenu != null) 1 else 0)
        val gameLayerInstalled =
            (if (menuLayerInstalled) 1 else 0) + (if (composeLayerInstalled) 1 else 0)
        if (hideGameMenu) environment.reportCapabilityCoverage(
            "home_top_bar_game_menu_hidden",
            points?.gameMenu != null || points?.composeGameMenu != null,
            gameLayerInstalled,
            gameLayerTotal.coerceAtLeast(1)
        )
        if (hideSearchDefaultWord) environment.reportCapabilityCoverage(
            "home_top_bar_search_word_hidden", true,
            installedCount - gameLayerInstalled,
            1 + points?.defaultWordMethods.orEmpty().size.coerceAtLeast(1) + if (searchMoss != null) 2 else 0
        )
        val summary = if (ready) {
            "success"
        } else {
            buildString {
                append("partial:")
                val missing = ArrayList<String>(4)
                if (!gameReady) missing += "game"
                if (!searchViewReady) missing += "search-view"
                if (!searchWordReady) missing += "search-word"
                if (!searchProtocolReady) missing += "search-protocol"
                append(missing.joinToString(","))
            }
        }
        environment.reportStatus(CHANNEL_STATUS, summary)
        if (!ready) {
            environment.logError(
                "home_top_bar_partial",
                "[BIL] 首页顶部栏净化 Hook 未完整命中: $summary"
            )
            return if (installedCount > 0) FeatureInstallResult.Installed(installedCount, complete = false)
            else FeatureInstallResult.Skipped(summary)
        }
        environment.logInfo(
            "home_top_bar_ok",
            "[BIL] 首页顶部栏净化已安装，hooks=$installedCount"
        )
        return FeatureInstallResult.Installed(installedCount)
    }

    /**
     * 定位搜索默认词的协议边界。
     *
     * `SearchMoss.executeDefaultWords` 是同步调用且被业务侧跨 dex 引用（9.7.0–9.11.0 实测
     * 均只有一个重载、且都有跨 dex 调用方）。一个可清的文案字段都找不到时返回 null，
     * 由调用方计为 `search-protocol` 降级。
     */
    private fun resolveDefaultWordsBoundary(environment: HookEnvironment, moss: Class<*>): DefaultWordsBoundary? {
        val loader = environment.classLoader ?: return null
        val reply = KavaMemberLookup.classOrNull(loader, "com.bapis.bilibili.app.interfaces.v1.DefaultWordsReply") ?: return null
        val cleaner = SearchDefaultWordsCleaner.resolve(reply) ?: return null
        val methods = KavaMemberLookup.declaredMethods(moss, makeAccessible = true)
        val sync = methods.filter { !it.isStatic && it.name == DEFAULT_WORDS_METHOD &&
            it.parameterCount == 1 && it.returnType == reply }.singleOrNull()
        val handler = KavaMemberLookup.classOrNull(loader, "com.bilibili.lib.moss.api.MossResponseHandler")
            ?.takeIf { it.isInterface }
        val async = methods.filter { !it.isStatic && it.name == "defaultWords" && it.parameterCount == 2 &&
            it.returnType == Void.TYPE && it.parameterTypes[1] == handler }.singleOrNull()
        return DefaultWordsBoundary(sync, async, handler, cleaner)
    }

    private class DefaultWordsBoundary(
        val sync: Method?, val async: Method?, val handler: Class<*>?,
        val cleaner: SearchDefaultWordsCleaner
    )

    private fun clearSearchText(
        target: Any?,
        fieldName: String?,
        environment: HookEnvironment
    ) {
        if (target == null || fieldName.isNullOrBlank()) return
        runCatching {
            val field = KavaMemberLookup.fieldOrNull(
                target.javaClass,
                fieldName,
                includeSuperclasses = true
            ) ?: return
            val searchText = field.get(target) as? TextView ?: return
            searchText.clearAnimation()
            searchText.text = ""
        }.onFailure { throwable ->
            environment.logError(
                "home_search_text_err",
                "[BIL] 清理首页搜索默认词失败: $throwable"
            )
        }
    }

    companion object {
        const val ID = "home_top_bar_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "home_top_bar_status"

        /** 游戏中心两层各自的状态；合并进 [CHANNEL_STATUS] 就无法分因。 */
        private const val CHANNEL_GAME_LAYERS = "home_game_menu_layers"
        private const val GAME_MENU_ACTION = "action://game_center/home/menu"

        internal fun layerState(present: Boolean, installed: Boolean): String = when {
            installed -> "ok"
            present -> "failed"
            else -> "absent"
        }

        /** 项自身的 String 字段里带游戏中心 action 即判定命中（9110400 实测是 `Nm1.o.c`）。 */
        internal fun isGameMenuItem(item: Any): Boolean = containsGameMenuAction(item)

        /**
         * 两层共用的**纯判据**——"什么算游戏中心入口"只能有一个定义，否则一层改了
         * 另一层跟不上。共用判据不等于串联：注册、降级、状态三者仍各自独立。
         */
        private fun containsGameMenuAction(holder: Any): Boolean = KavaMemberLookup.fields(
            holder.javaClass,
            includeSuperclasses = true,
            makeAccessible = true
        ).any { field ->
            if (field.type != classOf<String>()) return@any false
            val action = runCatching { field.get(holder) as? String }.getOrNull()
                ?: return@any false
            action == GAME_MENU_ACTION || action.startsWith("$GAME_MENU_ACTION?")
        }
        private const val SEARCH_MOSS_CLASS = "com.bapis.bilibili.app.interfaces.v1.SearchMoss"
        private const val DEFAULT_WORDS_METHOD = "executeDefaultWords"

        /** 顶部菜单基类共用同一构建方法，只对配置对象中含游戏 action 的实例放行拦截。 */
        internal fun hasGameMenuAction(target: Any, configFieldName: String?): Boolean {
            if (configFieldName.isNullOrBlank()) return false
            val configField = KavaMemberLookup.fieldOrNull(
                target.javaClass,
                configFieldName,
                includeSuperclasses = true
            ) ?: return false
            val config = runCatching { configField.get(target) }.getOrNull() ?: return false
            return containsGameMenuAction(config)
        }
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.app.Activity
import android.app.Instrumentation
import android.content.ComponentName
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.Method
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong

/**
 * 在最终 Activity 启动边界把明确的 Story 视频转换为普通详情页。
 *
 * 这里只保留一个路由写入点：不再提前修改卡片、RouteRequest 或 Builder，避免宿主继续沿用
 * Story 路由创建的业务状态。新版宿主写入完整 United 契约，旧版宿主使用 Legacy Activity。
 */
internal class HomeVerticalDetailFeatureInstaller(
    private val enabled: Boolean,
    private val points: VersionAdapter.HomeRecommendFeedPoints?
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val backends = resolveBackends(environment)
        if (backends.isEmpty()) return missing(environment, "missing-detail-activity")
        val instrumentationCount = installActivityLaunchBoundary(environment, backends)
        if (instrumentationCount == 0) {
            return missing(environment, "no-safe-activity-launch-hook-point")
        }
        val playConfig = installPlayConfigStorySuppression(environment)
        val intentSanitizer = installIntentHandlerSanitizer(environment)
        val layered = playConfig.installed + intentSanitizer.installed
        val installed = instrumentationCount + layered
        // 分母只算这个宿主上确实存在的落点：PlayConfig/KPlayConfig 类或 Intent 入口
        // 不存在的老宿主不算缺；存在却注册失败必须让 complete 掉成 false 并报 partial。
        val expected = playConfig.expected + intentSanitizer.expected
        val complete = layered == expected
        val status = layerStatus(layered, expected)

        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        environment.reportStatus(CHANNEL_STATUS, status)
        environment.logInfo(
            "home_vertical_ok",
            "[BIL] 竖屏视频普通详情路由已安装，backend=" +
                backends.joinToString("+") { it.name.lowercase() } +
                ",instrumentation=$instrumentationCount,playConfig=${playConfig.installed}/${playConfig.expected}," +
                "intentSanitizer=${intentSanitizer.installed}/${intentSanitizer.expected},status=$status"
        )
        return FeatureInstallResult.Installed(installed, complete = complete)
    }

    /**
     * 按偏好顺序返回宿主实际存在的后端。
     *
     * 之前只取第一个匹配并固化到整个进程：United 的任一前置条件不满足就直接放行，即使宿主
     * 同时具备旧详情页也没有第二次机会。现在保留完整列表，由每个 Intent 自行降级。
     */
    private fun resolveBackends(environment: HookEnvironment): List<HomeVerticalDetailBackend> {
        val loader = environment.classLoader ?: return emptyList()
        return HomeVerticalDetailBackend.entries.filter { backend ->
            val activityClass = KavaMemberLookup.classOrNull(loader, backend.activityClassName)
            activityClass != null && activityClass isSubclassOf classOf<Activity>() &&
                (!backend.requiresOnCreate || declaresOnCreate(activityClass))
        }
    }

    /**
     * 禁止宿主把横屏普通播放自动提升为 Story，不改变用户主动进入 Story 页的其它开关。
     *
     * 宿主读这两个开关的类**随版本换了**：≤9.12 的消费端调 Java protobuf `PlayConfig`，9.13 起
     * 全部改调 Kotlin 序列化版 `KPlayConfig`（2026-09-30 用 dexq 对 8.84–9.14 六个宿主做调用点
     * 矩阵：Java getter 的非 Builder 调用点 9.10.0 还有 3 个、9.13.0 / 9.14.0 是 0，`KPlayConfig`
     * 反之）。只 Hook Java 版在 9.13+ 上会"注册成功、永不触发"，所以两套都装，各自按类名判存。
     */
    private fun installPlayConfigStorySuppression(environment: HookEnvironment): PlayConfigLayer {
        val loader = environment.classLoader ?: return PlayConfigLayer(0, 0)
        val java = installPlayConfigGetters(
            environment, loader, "play_config", PLAY_CONFIG_CLASS, BOOL_VALUE_CLASS
        ) { boolValueClass ->
            KavaMemberLookup.methodOrNull(boolValueClass, "getDefaultInstance")
                ?.takeIf { it.isStatic && it.returnType == boolValueClass }
                ?.let { runCatching { it.invoke(null) }.getOrNull() }
        }
        val kotlin = installPlayConfigGetters(
            environment, loader, "k_play_config", K_PLAY_CONFIG_CLASS, K_BOOL_VALUE_CLASS
        ) { boolValueClass ->
            // kotlinx.serialization 数据类：全默认值的公开无参构造应得到 value=false；不假设，实测为 false 才用。
            runCatching { boolValueClass.getDeclaredConstructor().newInstance() }
                .getOrNull()
                ?.takeIf { instance ->
                    KavaMemberLookup.methodOrNull(boolValueClass, "getValue")
                        ?.let { runCatching { it.invoke(instance) }.getOrNull() } == false
                }
        }
        return PlayConfigLayer(java.installed + kotlin.installed, java.expected + kotlin.expected)
    }

    /** [defaultValueOf] 返回"开关关闭"的默认实例，返回 null 表示这套类在当前宿主上不可用。 */
    private fun installPlayConfigGetters(
        environment: HookEnvironment,
        loader: ClassLoader,
        tag: String,
        configClassName: String,
        boolValueClassName: String,
        defaultValueOf: (Class<*>) -> Any?
    ): PlayConfigLayer {
        val boolValueClass = KavaMemberLookup.classOrNull(loader, boolValueClassName) ?: return PlayConfigLayer(0, 0)
        val configClass = KavaMemberLookup.classOrNull(loader, configClassName) ?: return PlayConfigLayer(0, 0)
        val defaultValue = defaultValueOf(boolValueClass)
            ?.takeIf(boolValueClass::isInstance)
            ?: return PlayConfigLayer(0, 0)
        var installed = 0
        PLAY_CONFIG_STORY_GETTERS.forEach { methodName ->
            val method = KavaMemberLookup.methodOrNull(configClass, methodName)
                ?.takeIf {
                    !it.isStatic && it.parameterCount == 0 &&
                        it.returnType == boolValueClass
                } ?: return@forEach
            runCatching {
                environment.registrar.exact(
                    "home.vertical.$tag.$methodName",
                    method.declaringClass,
                    method.name
                ) {
                    before {
                        result = defaultValue
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "home_vertical_${tag}_$methodName",
                    "[BIL] ${configClass.simpleName} 自动 Story 抑制注册失败($methodName): $throwable"
                )
            }
        }
        return PlayConfigLayer(installed, PLAY_CONFIG_STORY_GETTERS.size)
    }

    /** 该层的"已装上"与"本宿主确实存在的落点数"；后者为 0 表示这一层在此宿主不适用。 */
    private data class PlayConfigLayer(val installed: Int, val expected: Int)

    /**
     * 唯一路由写入边界。动态查找 Intent 参数，先复制再构造并校验完整契约，任何异常均保留
     * 宿主原 Intent。
     */
    private fun installActivityLaunchBoundary(
        environment: HookEnvironment,
        backends: List<HomeVerticalDetailBackend>
    ): Int {
        val candidates = KavaMemberLookup.declaredMethods(
            classOf<Instrumentation>(),
            makeAccessible = true
        ) { method ->
            method.name == "execStartActivity" && !method.isStatic &&
                method.parameterTypes.count { it == classOf<Intent>() } == 1
        }.distinctBy(Method::toGenericString)
        var installed = 0
        candidates.forEachIndexed { index, method ->
            val intentIndex = method.parameterTypes.indexOf(classOf<Intent>())
            if (intentIndex < 0) return@forEachIndexed
            runCatching {
                environment.registrar.exact(
                    "home.vertical.instrumentation.$index",
                    method.declaringClass,
                    method.name,
                    *method.parameterTypes
                ) {
                    before {
                        val intent = args.getOrNull(intentIndex) as? Intent ?: return@before
                        if (!HomeVerticalDetailRoutePolicy.isStrictStoryVideoRoute(
                                intent.data?.toString()
                            )
                        ) {
                            return@before
                        }
                        val outcome = rewriteIntentSafely(intent, backends, environment)
                        // 用户在普通详情页里主动点了播放器右下角"竖屏"（issue #9）：策略层已判定放行，
                        // 让宿主进 Story。这是预期行为而不是"该改没改"，所以不计 OBSERVED，避免诊断里
                        // 出现"观察到却从未应用"；仍走 logSkipOnce 留一条脱敏的 Intent 结构日志。
                        if (outcome is LaunchRewrite.Skipped &&
                            outcome.reason == HomeVerticalLaunchSkip.DETAIL_PAGE_VERTICAL_SWITCH
                        ) {
                            logSkipOnce(environment, intent, outcome.reason)
                            return@before
                        }
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        val applied = when (outcome) {
                            is LaunchRewrite.Applied -> outcome
                            is LaunchRewrite.Skipped -> {
                                logSkipOnce(environment, intent, outcome.reason)
                                return@before
                            }
                        }
                        args[intentIndex] = applied.intent
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                        environment.logInfo(
                            "home_vertical_activity_launch",
                            "[BIL] Story 视频已在 Activity 启动边界按 " +
                                "${applied.backend.name} 完整契约改为普通详情页"
                        )
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "home_vertical_instrumentation_$index",
                    "[BIL] Activity 启动边界注册失败(${method.parameterCount} 参数): $throwable"
                )
            }
        }
        return installed
    }

    /** IntentHandler 只清理强制 Story 参数，不再承担目标页面改写。 */
    private fun installIntentHandlerSanitizer(environment: HookEnvironment): PlayConfigLayer {
        val point = points?.intentHandlerOnCreate ?: return PlayConfigLayer(0, 0)
        return runCatching {
            environment.registrar.adapted("home.vertical.intent_handler_sanitizer", point) {
                before {
                    val activity = instance as? Activity ?: return@before
                    val original = activity.intent ?: return@before
                    val sanitizedUri = original.data?.toString()
                        ?.let(HomeVerticalDetailRoutePolicy::sanitizeIntentHandlerUri)
                        ?: return@before
                    val sanitized = Intent(original).apply { data = Uri.parse(sanitizedUri) }
                    activity.intent = sanitized
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                    environment.logInfo(
                        "home_vertical_intent_handler_sanitized",
                        "[BIL] 已清理宿主 Intent 入口的强制 Story 参数"
                    )
                }
            }
            PlayConfigLayer(1, 1)
        }.getOrElse { throwable ->
            environment.logError(
                "home_vertical_intent_handler_failed",
                "[BIL] 宿主 Intent 入口参数清理注册失败: $throwable"
            )
            PlayConfigLayer(0, 1)
        }
    }

    private fun rewriteIntentSafely(
        intent: Intent,
        backends: List<HomeVerticalDetailBackend>,
        environment: HookEnvironment
    ): LaunchRewrite = runCatching {
        val component = intent.component
        // cid 解析要对 player_preload 做 JSON 解析，而宿主内联的 DASH manifest 实测可达
        // 28 KB。先用不含 cid 的快照判定；只有策略层明确说"就差 cid"时才付这笔开销，
        // 跨包、超长、身份冲突等注定放行的 Intent 完全不会触发解析。
        var snapshot = HomeVerticalActivityLaunchSnapshot(
            dataUri = intent.data?.toString(),
            componentPackage = component?.packageName,
            targetPackage = intent.`package`,
            aid = intent.extraToken(AID_EXTRA),
            avid = intent.extraToken(AVID_EXTRA),
            bvid = intent.extraToken(BVID_EXTRA),
            preloadCid = null,
            fromSpmid = launchOriginSpmid(intent)
        )
        var cidResolved = false
        var firstReason: HomeVerticalLaunchSkip? = null
        // 按偏好顺序逐个尝试：United 缺 cid 或身份不是 aid 时，仍可能由 Legacy 详情页承接。
        backends.forEach { backend ->
            var outcome = HomeVerticalDetailRoutePolicy.planActivityLaunch(snapshot, backend)
            if (
                outcome is HomeVerticalActivityLaunchOutcome.Skipped &&
                outcome.reason == HomeVerticalLaunchSkip.MISSING_PRELOAD_CID &&
                !cidResolved
            ) {
                cidResolved = true
                snapshot = snapshot.copy(preloadCid = resolvePreloadCid(intent))
                if (snapshot.preloadCid != null) {
                    outcome = HomeVerticalDetailRoutePolicy.planActivityLaunch(snapshot, backend)
                }
            }
            when (outcome) {
                is HomeVerticalActivityLaunchOutcome.Skipped -> {
                    if (firstReason == null) firstReason = outcome.reason
                }

                is HomeVerticalActivityLaunchOutcome.Planned -> {
                    // 构造或完整契约校验失败时不记原因，交由 null 表示"非策略层主动放行"。
                    val built = buildIntent(intent, outcome.plan, backend)
                    if (built != null) return@runCatching LaunchRewrite.Applied(built, backend)
                }
            }
        }
        LaunchRewrite.Skipped(firstReason)
    }.getOrElse { throwable ->
        environment.logError(
            "home_vertical_intent_rewrite_failed",
            "[BIL] Story 启动 Intent 构造异常，已保留宿主原 Intent: $throwable"
        )
        LaunchRewrite.Skipped(null)
    }

    /**
     * 多来源解析 United 契约必需的 cid。
     *
     * 原实现只读 URI 查询参数 `player_preload`，而模块自己写回时用的是 Intent extra——读写
     * 方向不对称，且"宿主一定把它放在查询串里"这个前提从未被设备实测确认。这里按 URI 查询、
     * extra JSON、extra 数字 cid、URI 查询 cid 的顺序依次尝试，任一命中即可。
     */
    private fun resolvePreloadCid(intent: Intent): Long? {
        val uri = intent.data
        HomeVerticalDetailRoutePolicy.parsePlayerPreloadCid(
            runCatching { uri?.getQueryParameter(PLAYER_PRELOAD_EXTRA) }.getOrNull()
        )?.let { return it }
        HomeVerticalDetailRoutePolicy.parsePlayerPreloadCid(
            intent.extraToken(PLAYER_PRELOAD_EXTRA)
        )?.let { return it }
        intent.extraToken(CID_EXTRA)?.toLongOrNull()?.takeIf { it > 0L }?.let { return it }
        return runCatching { uri?.getQueryParameter(CID_EXTRA) }
            .getOrNull()
            ?.toLongOrNull()
            ?.takeIf { it > 0L }
    }

    private fun buildIntent(
        intent: Intent,
        plan: HomeVerticalActivityLaunchPlan,
        backend: HomeVerticalDetailBackend
    ): Intent? {
        val rewritten = Intent(intent)
        return when (plan) {
            is HomeVerticalActivityLaunchPlan.Legacy -> {
                rewritten.data = Uri.parse(plan.detailUri)
                rewritten.component = ComponentName(TARGET_PACKAGE, backend.activityClassName)
                rewritten.takeIf { validateLegacyIntent(it, plan, backend) }
            }

            is HomeVerticalActivityLaunchPlan.United -> {
                val preloadToken = nextPlayerPreloadToken()
                UNITED_REPLACED_EXTRAS.forEach(rewritten::removeExtra)
                rewritten.data = Uri.parse(plan.detailUri)
                rewritten.component = ComponentName(TARGET_PACKAGE, backend.activityClassName)
                rewritten.putExtra(PLAYER_PRELOAD_EXTRA, preloadToken)
                rewritten.putExtra(BLROUTER_TARGET_URL_EXTRA, plan.targetUrl)
                rewritten.putExtra(BLROUTER_PAGE_NAME_EXTRA, UNITED_VIDEO_PAGE)
                rewritten.putExtra(BLROUTER_MATCH_RULE_EXTRA, UNITED_VIDEO_PAGE)
                rewritten.putExtra(JUMP_FROM_EXTRA, DETAIL_SOURCE)
                rewritten.putExtra(AID_EXTRA, plan.aid)
                rewritten.putExtra(CID_EXTRA, plan.cid)
                rewritten.putExtra(BVID_EXTRA, "")
                rewritten.putExtra(FROM_EXTRA, DETAIL_SOURCE)
                rewritten.takeIf {
                    validateUnitedIntent(it, plan, backend, preloadToken)
                }
            }
        }
    }

    /**
     * 每个放行原因在本进程只记一条，附带脱敏的 Intent 结构。
     *
     * 只输出路由根、是否有路径身份、查询串 key 列表与 extra 的 key/类型；不输出任何取值、
     * 标题、完整 URI 或跟踪参数。这足以回答"`player_preload` 到底在查询串还是 extra 里"
     * 这类问题，而不必再猜宿主行为。
     */
    private fun logSkipOnce(
        environment: HookEnvironment,
        intent: Intent,
        reason: HomeVerticalLaunchSkip?
    ) {
        val label = reason?.name?.lowercase() ?: "build-or-validate-failed"
        if (!loggedSkipReasons.add(label)) return
        val shape = runCatching { describeIntentShape(intent) }.getOrElse { "shape-unavailable" }
        environment.logInfo(
            "home_vertical_skip_$label",
            "[BIL] Story 视频未改写，reason=$label $shape"
        )
    }

    /**
     * 启动来源埋点：先看 Intent extra（BLRouter 会把 `RouteRequest.extras` 原样 `putExtras` 成顶层
     * extra，9.14.0 `DefaultGlobalLauncher.createIntent` 反汇编实证），缺失再取 URI 查询。
     * 只在已确认是 Story 路由的 Intent 上调用；`Uri.getQueryParameter` 按子串定位、只解码命中的值。
     */
    private fun launchOriginSpmid(intent: Intent): String? =
        intent.extraToken(FROM_SPMID_EXTRA)
            ?: runCatching { intent.data?.getQueryParameter(FROM_SPMID_EXTRA) }
                .getOrNull()
                ?.trim()
                ?.takeIf(String::isNotEmpty)

    private fun describeIntentShape(intent: Intent): String {
        val uri = intent.data
        val root = uri?.let { "${it.scheme}://${it.host}" } ?: "none"
        val hasPath = uri?.path?.trim('/')?.isNotEmpty() == true
        val queryKeys = runCatching {
            uri?.queryParameterNames.orEmpty()
                .take(MAX_LOGGED_KEYS)
                .joinToString(",") { it.take(MAX_LOGGED_KEY_LENGTH) }
        }.getOrDefault("")
        val extraKeys = runCatching {
            intent.extras?.keySet().orEmpty()
                .take(MAX_LOGGED_KEYS)
                .joinToString(",") { key ->
                    @Suppress("DEPRECATION")
                    val type = runCatching { intent.extras?.get(key) }
                        .getOrNull()
                        ?.javaClass
                        ?.simpleName
                        ?: "null"
                    "${key.take(MAX_LOGGED_KEY_LENGTH)}:$type"
                }
        }.getOrDefault("")
        return "root=$root hasPath=$hasPath queryKeys=[$queryKeys] extraKeys=[$extraKeys]"
    }

    private fun validateLegacyIntent(
        intent: Intent,
        plan: HomeVerticalActivityLaunchPlan.Legacy,
        backend: HomeVerticalDetailBackend
    ): Boolean = intent.data?.toString() == plan.detailUri &&
        intent.component?.packageName == TARGET_PACKAGE &&
        intent.component?.className == backend.activityClassName

    private fun validateUnitedIntent(
        intent: Intent,
        plan: HomeVerticalActivityLaunchPlan.United,
        backend: HomeVerticalDetailBackend,
        preloadToken: String
    ): Boolean = intent.data?.toString() == plan.detailUri &&
        intent.component?.packageName == TARGET_PACKAGE &&
        intent.component?.className == backend.activityClassName &&
        intent.getStringExtra(PLAYER_PRELOAD_EXTRA) == preloadToken &&
        preloadToken.all(Char::isDigit) &&
        intent.getStringExtra(BLROUTER_TARGET_URL_EXTRA) == plan.targetUrl &&
        intent.getStringExtra(BLROUTER_PAGE_NAME_EXTRA) == UNITED_VIDEO_PAGE &&
        intent.getStringExtra(BLROUTER_MATCH_RULE_EXTRA) == UNITED_VIDEO_PAGE &&
        intent.getLongExtra(AID_EXTRA, -1L) == plan.aid &&
        intent.getLongExtra(CID_EXTRA, -1L) == plan.cid &&
        intent.getStringExtra(BVID_EXTRA) == "" &&
        intent.getIntExtra(JUMP_FROM_EXTRA, -1) == DETAIL_SOURCE &&
        intent.getIntExtra(FROM_EXTRA, -1) == DETAIL_SOURCE

    @Suppress("DEPRECATION")
    private fun Intent.extraToken(key: String): String? = runCatching {
        when (val value = extras?.get(key)) {
            is Number -> value.toLong().takeIf { it > 0L }?.toString()
            is String -> value.trim().takeIf(String::isNotEmpty)
            else -> null
        }
    }.getOrNull()

    private fun nextPlayerPreloadToken(): String = playerPreloadSequence.updateAndGet { current ->
        if (current >= MAX_PLAYER_PRELOAD_TOKEN) 1L else current + 1L
    }.toString()

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "home_vertical_missing",
            "[BIL] 首页竖屏视频详情路由适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    private sealed interface LaunchRewrite {
        data class Applied(
            val intent: Intent,
            val backend: HomeVerticalDetailBackend
        ) : LaunchRewrite

        /** [reason] 为 null 表示 Intent 构造或完整契约校验失败，而非策略层主动放行。 */
        data class Skipped(val reason: HomeVerticalLaunchSkip?) : LaunchRewrite
    }

    companion object {
        const val ID = "home_vertical_detail"

        internal fun layerStatus(installed: Int, expected: Int): String =
            if (installed == expected) "success" else "partial:$installed/$expected"

        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "home_vertical_detail_status"
        private const val BOOL_VALUE_CLASS = "com.bapis.bilibili.app.distribution.BoolValue"
        private const val PLAY_CONFIG_CLASS =
            "com.bapis.bilibili.app.distribution.setting.play.PlayConfig"
        private const val K_BOOL_VALUE_CLASS = "com.bapis.bilibili.app.distribution.KBoolValue"
        private const val K_PLAY_CONFIG_CLASS =
            "com.bapis.bilibili.app.distribution.setting.play.KPlayConfig"
        private const val PLAYER_PRELOAD_EXTRA = "player_preload"
        private const val BLROUTER_TARGET_URL_EXTRA = "blrouter.targeturl"
        private const val BLROUTER_PAGE_NAME_EXTRA = "blrouter.pagename"
        private const val BLROUTER_MATCH_RULE_EXTRA = "blrouter.matchrule"
        private const val JUMP_FROM_EXTRA = "jumpFrom"
        private const val AID_EXTRA = "aid"
        private const val AVID_EXTRA = "avid"
        private const val CID_EXTRA = "cid"
        private const val BVID_EXTRA = "bvid"
        private const val FROM_EXTRA = "from"
        private const val FROM_SPMID_EXTRA = "from_spmid"
        private const val UNITED_VIDEO_PAGE = "bilibili://united_video/"
        private const val DETAIL_SOURCE = 7
        private const val MAX_PLAYER_PRELOAD_TOKEN = 999_999_998L
        private const val MAX_LOGGED_KEYS = 24
        private const val MAX_LOGGED_KEY_LENGTH = 40

        /** 有界：至多 HomeVerticalLaunchSkip 枚举项数 + 1 条构造失败记录。 */
        private val loggedSkipReasons = ConcurrentHashMap.newKeySet<String>()
        private val playerPreloadSequence = AtomicLong(
            (System.nanoTime() and 0x3fff_ffffL).coerceAtLeast(1L)
        )
        private val PLAY_CONFIG_STORY_GETTERS = listOf(
            "getLandscapeAutoStory",
            "getShouldAutoStory"
        )
        private val UNITED_REPLACED_EXTRAS = listOf(
            PLAYER_PRELOAD_EXTRA,
            BLROUTER_TARGET_URL_EXTRA,
            BLROUTER_PAGE_NAME_EXTRA,
            BLROUTER_MATCH_RULE_EXTRA,
            JUMP_FROM_EXTRA,
            AID_EXTRA,
            AVID_EXTRA,
            CID_EXTRA,
            BVID_EXTRA,
            FROM_EXTRA
        )

        internal fun normalizeVideoRouteUri(uri: String): String? =
            HomeVerticalDetailRoutePolicy.normalizeVideoDetailUri(uri)

        /** 只看类自己声明的 `onCreate(Bundle)`；反射失败一律视为没有，宁可少用一个后端。 */
        internal fun declaresOnCreate(activityClass: Class<*>): Boolean =
            runCatching { activityClass.getDeclaredMethod("onCreate", classOf<Bundle>()) }.isSuccess
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isAbstract
import com.highcapable.kavaref.extension.isFinal
import com.highcapable.kavaref.extension.isStatic
import java.lang.reflect.Field
import java.lang.reflect.Method
import java.net.URLDecoder
import java.net.URLEncoder
import java.util.concurrent.ConcurrentHashMap
import org.json.JSONObject

/** 首页竖屏卡片进入普通详情页所需的最小、脱敏路由快照。 */
internal data class HomeVerticalRouteSnapshot(
    val holderType: String? = null,
    val bizType: String? = null,
    val cardType: String? = null,
    val cardGoto: String? = null,
    val goTo: String? = null,
    val uri: String? = null,
    val param: String? = null,
    val playerAid: Long? = null,
    /** PlayerArgs 已明确指向直播、番剧等非普通投稿时禁止改写。 */
    val playerNonUgc: Boolean = false,
    val hasAdInfo: Boolean = false
)

/** 规范视频身份，不保存标题、完整 URI 或跟踪参数。 */
internal data class CanonicalHomeVideoId(
    val kind: Kind,
    val value: String
) {
    enum class Kind { BV, AID }
}

internal data class HomeVerticalRoutePlan(
    val identity: CanonicalHomeVideoId,
    /** 同一卡片中不同命名空间（BV/aid）的身份别名。 */
    val aliases: Set<CanonicalHomeVideoId> = setOf(identity),
    val detailUri: String,
    val rewriteCardGoto: Boolean,
    val rewriteGoTo: Boolean,
    val rewriteUri: Boolean
)

/**
 * 纯路由策略：只在结构化证据确认是普通投稿型竖屏卡片、且 BV/aid 可验证时生成改写计划。
 * 未知、冲突或特殊业务卡片全部 fail-open。
 */
internal object HomeVerticalDetailRoutePolicy {
    private const val STORY_URI_ROOT = "bilibili://story"
    private const val STORY_TRANSLUCENT_URI_ROOT = "bilibili://story_translucent"
    private const val VIDEO_URI_ROOT = "bilibili://video"
    private const val VIDEO_URI_PREFIX = "$VIDEO_URI_ROOT/"
    private const val AV_GOTO = "av"
    /**
     * 真实 Story 路由长度上限。
     *
     * 2026-09-02 在宿主 9.9.0 实测：首页竖屏卡片的 Intent data URI 长 **35,657** 字符——
     * `player_preload` 里内联了完整 DASH manifest（每个清晰度的 CDN 直链）。原值 4096 会把
     * 每一条带预加载的 Story URI 在第一道长度检查就丢弃，这正是"有概率不生效"的真实成因：
     * 未预加载的短 URI 能通过，预加载过的长 URI 一律失败。
     *
     * 现值留足量级余量。Intent 受 Binder 事务上限约束（实践中数百 KB），256 KB 之外属于
     * 病态输入。
     */
    private const val MAX_ROUTE_LENGTH = 262_144

    /**
     * 普通详情页播放器的页面级 spmid。
     *
     * 2026-09-30 对 9.13.0 / 9.14.0 反汇编实证：详情页右下角"竖屏"按钮（GeminiPlayerFullStoryWidget
     * → `StoryEntranceService`）用 `RouteRequest(bilibili://story/{aid}).requestCode(1101)` 启动 Story，
     * **两种形态（共享播放器 / 不共享播放器）的 extras 里都带 `from_spmid = united.player-video-detail.0.0`**。
     * 8.84.0 / 8.91.0 / 9.5.0 / 9.10.0 / 9.13.0 / 9.14.0 六个样本里，把它写进 Story 启动 extras 的
     * 都是 `StoryEntranceService`（8.x 是其 `o/t` 方法，9.x 是 `story/a`、`story/b` 两个 lambda）；
     * 其余引用者是广告上报的 `IReportExtraHandler.put`，不启动页面。
     *
     * 注意这是按**来源**放行，不是按"按钮"：同一个 `StoryEntranceService` 还承载"横屏/自动进 Story"
     * 与"返回 Story"两条宿主自发路径，它们也带这个值。前者由 PlayConfig 的两个自动 Story 开关抑制
     * （见 [HomeVerticalDetailFeatureInstaller]，注意 9.13+ 必须挂 `KPlayConfig`），不靠这里兜底。
     *
     * **必须精确相等，不能用前缀**：`united.player-video-detail.` 是宿主埋点事件的命名空间，下面有几百条
     * （`banner.0.click`、`caching.button.click`、`bp.button.click`……），前缀匹配会把这些事件名下发起的
     * 其它启动也一并放行，等于给"替换成普通详情页"开了个洞。
     */
    private const val DETAIL_PLAYER_SPMID = "united.player-video-detail.0.0"
    private val BV_PATTERN = Regex("BV[0-9A-Za-z]{6,30}", RegexOption.IGNORE_CASE)
    private val AID_PATTERN = Regex("(?:av)?[0-9]{1,19}", RegexOption.IGNORE_CASE)

    /**
     * 这次 Story 启动是不是用户在**普通详情页里主动点了"竖屏"**发起的。
     *
     * 是就必须放行：用户明确要进竖屏，宿主随后会把当前播放器交给 Story 页；再把它改回"打开普通
     * 详情页"，就是 issue #9 的"闪回当前视频详情页、进不了竖屏"。判据只认来源埋点，不认 URI 形态
     * ——首页卡片、搜索、动态等入口的 from_spmid 都不是详情页播放器的，替换逻辑不受影响。
     */
    fun isDetailPageVerticalSwitch(fromSpmid: String?): Boolean =
        fromSpmid == DETAIL_PLAYER_SPMID

    /**
     * 在宿主统一路由边界将具有明确视频身份的 Story 路由规范化为普通详情路由。
     * 无 aid/BV 的 Story 根页、身份冲突或非哔哩哔哩路由均 fail-open。
     */
    fun normalizeVideoDetailUri(uri: String): String? {
        STORY_URI_ROOTS.forEach { root ->
            parseUnambiguousRoute(uri, root)?.let { route ->
                return rewriteStoryRoute(uri, route, root)
            }
        }
        parseUnambiguousRoute(uri, VIDEO_URI_ROOT) ?: return null
        return sanitizeStoryRoutingHints(uri).takeUnless { it == uri }
    }


    /**
     * 在最终 Activity 启动边界生成完整的普通详情页契约。新版宿主优先使用 United 详情页，
     * 旧版宿主退回 Legacy 详情页；无法证明身份或缺少 United 必需 cid 时保持原 Intent。
     */
    fun planActivityLaunch(
        snapshot: HomeVerticalActivityLaunchSnapshot,
        backend: HomeVerticalDetailBackend
    ): HomeVerticalActivityLaunchOutcome {
        fun skip(reason: HomeVerticalLaunchSkip) =
            HomeVerticalActivityLaunchOutcome.Skipped(reason)
        if (snapshot.componentPackage != null && snapshot.componentPackage != TARGET_PACKAGE) {
            return skip(HomeVerticalLaunchSkip.CROSS_PACKAGE)
        }
        if (snapshot.targetPackage != null && snapshot.targetPackage != TARGET_PACKAGE) {
            return skip(HomeVerticalLaunchSkip.CROSS_PACKAGE)
        }
        val original = snapshot.dataUri ?: return skip(HomeVerticalLaunchSkip.NO_DATA_URI)
        // story 与 story_translucent 都是宿主注册的竖屏路由；两者只有根不同，身份契约一致。
        val storyRoot = storyRootFor(original) ?: return skip(HomeVerticalLaunchSkip.NOT_STORY_ROUTE)
        // 先于长度/身份判断：来源明确时无需解析 35 KB 的 player_preload，也不该有任何改写。
        if (isDetailPageVerticalSwitch(snapshot.fromSpmid)) {
            return skip(HomeVerticalLaunchSkip.DETAIL_PAGE_VERTICAL_SWITCH)
        }
        // 长度拒绝必须落在这里而不是入口门禁：门禁静默，这里才有原因可上报。
        if (original.length > MAX_ROUTE_LENGTH) {
            return skip(HomeVerticalLaunchSkip.ROUTE_TOO_LONG)
        }

        val extraIdentities = parseIntentIdentities(
            HomeVerticalIntentRouteSnapshot(
                dataUri = original,
                componentPackage = snapshot.componentPackage,
                targetPackage = snapshot.targetPackage,
                aid = snapshot.aid,
                avid = snapshot.avid,
                bvid = snapshot.bvid
            )
        ) ?: return skip(HomeVerticalLaunchSkip.MALFORMED_INTENT_IDENTITY)

        // 路径身份缺失时不再整体放弃：查询串身份由 parseUnambiguousRoute 直接给出，两者都
        // 没有的裸根路由再退回 Intent 结构化字段，与卡片层 decide() 的既有语义对齐。
        val route = parseUnambiguousRoute(original, storyRoot)
            ?: run {
                if (!permitsFallbackIdentity(original, storyRoot)) {
                    return skip(HomeVerticalLaunchSkip.MALFORMED_ROUTE)
                }
                val fallback = extraIdentities
                    .singleOrNull { it.kind == CanonicalHomeVideoId.Kind.AID }
                    ?: extraIdentities.singleOrNull()
                    ?: return skip(HomeVerticalLaunchSkip.NO_IDENTITY)
                ParsedRoute(fallback, setOf(fallback), rawToken = null)
            }

        val identities = linkedSetOf<CanonicalHomeVideoId>().apply {
            addAll(route.identities)
            addAll(extraIdentities)
        }
        if (identities.groupBy(CanonicalHomeVideoId::kind).any { it.value.size > 1 }) {
            return skip(HomeVerticalLaunchSkip.IDENTITY_CONFLICT)
        }

        val plan = when (backend) {
            HomeVerticalDetailBackend.LEGACY -> HomeVerticalActivityLaunchPlan.Legacy(
                detailUri = rewriteStoryRoute(original, route, storyRoot)
            )

            HomeVerticalDetailBackend.UNITED -> {
                val identity = route.primaryIdentity
                if (identity.kind != CanonicalHomeVideoId.Kind.AID) {
                    return skip(HomeVerticalLaunchSkip.BV_ONLY_UNITED)
                }
                val aid = identity.value.toLongOrNull()?.takeIf { it > 0L }
                    ?: return skip(HomeVerticalLaunchSkip.NO_IDENTITY)
                val cid = snapshot.preloadCid?.takeIf { it > 0L }
                    ?: return skip(HomeVerticalLaunchSkip.MISSING_PRELOAD_CID)
                val targetUrl = "$UNITED_VIDEO_URI_ROOT/$aid"
                val fromSpmid = uniqueQueryValue(original, FROM_SPMID_QUERY)
                    ?.takeIf { it.length <= MAX_FROM_SPMID_LENGTH }
                val detailUri = buildString {
                    append(targetUrl).append('?')
                    if (fromSpmid != null) {
                        append(FROM_SPMID_QUERY)
                            .append('=')
                            .append(encodeQueryComponent(fromSpmid))
                            .append('&')
                    }
                    append("aid=").append(aid).append("&bvid=")
                }
                HomeVerticalActivityLaunchPlan.United(
                    detailUri = detailUri,
                    targetUrl = targetUrl,
                    aid = aid,
                    cid = cid
                )
            }
        }
        return HomeVerticalActivityLaunchOutcome.Planned(plan)
    }

    /** 仅清理 IntentHandler 中强制回到 Story 的参数，不在该层改写目标页面。 */
    fun sanitizeIntentHandlerUri(uri: String): String? {
        if (uri.length > MAX_ROUTE_LENGTH || storyRootFor(uri) == null) return null
        return sanitizeStoryRoutingHints(uri).takeUnless { it == uri }
    }

    /**
     * 启动边界的廉价前置门禁：只判断是不是宿主的竖屏路由根。
     *
     * 这里**刻意不设长度上限**。门禁返回 false 是完全静默的（否则每次 Activity 启动都会打
     * 日志），所以任何在此处被拒绝的情况都不可归因。实测教训：原实现在门禁上叠了
     * `length <= 4096`，而真实 Story URI 长 35,657 字符，于是每一次失败都既无 OBSERVED
     * 也无放行原因，排查时表现为"功能像是没装"。
     *
     * 现在门禁只回答"这条路由是不是我们的"（`startsWith` 与 URI 长度无关），长度、身份、
     * cid 等一切拒绝理由都由 [planActivityLaunch] 给出有界原因。
     */
    fun isStrictStoryVideoRoute(uri: String?): Boolean =
        uri != null && storyRootFor(uri) != null

    fun parsePlayerPreloadCid(raw: String?): Long? {
        val json = raw?.takeIf { it.length in 2..MAX_PLAYER_PRELOAD_LENGTH } ?: return null
        return runCatching { JSONObject(json).optLong("cid", -1L).takeIf { it > 0L } }
            .getOrNull()
    }

    internal fun canonicalIdentity(raw: String?): CanonicalHomeVideoId? {
        val token = raw?.trim()?.takeIf { it.isNotEmpty() } ?: return null
        if (BV_PATTERN.matches(token)) {
            return CanonicalHomeVideoId(
                CanonicalHomeVideoId.Kind.BV,
                "BV" + token.substring(2)
            )
        }
        if (!AID_PATTERN.matches(token)) return null
        val digits = if (token.startsWith("av", ignoreCase = true)) token.substring(2) else token
        val value = digits.toLongOrNull()?.takeIf { it > 0L } ?: return null
        return CanonicalHomeVideoId(CanonicalHomeVideoId.Kind.AID, value.toString())
    }

    private fun CanonicalHomeVideoId.routeToken(): String = when (kind) {
        CanonicalHomeVideoId.Kind.BV -> value
        CanonicalHomeVideoId.Kind.AID -> value
    }

    private fun parseRoute(raw: String?, root: String): ParsedRoute? {
        val route = raw?.takeIf { it.length <= MAX_ROUTE_LENGTH && isRouteFor(it, root) }
            ?: return null
        val suffixStart = route.indexOfFirstFrom(root.length) { it == '?' || it == '#' }
        val pathEnd = suffixStart.takeIf { it >= 0 } ?: route.length
        val path = route.substring(root.length, pathEnd)
        val rawToken = when {
            path.isEmpty() -> null
            !path.startsWith('/') || path.length == 1 || '/' in path.substring(1) -> return null
            else -> path.substring(1)
        }
        val pathIdentity = rawToken?.let(::canonicalIdentity) ?: if (rawToken == null) null else return null
        val query = parseQueryIdentities(route) ?: return null
        val identities = linkedSetOf<CanonicalHomeVideoId>().apply {
            pathIdentity?.let(::add)
            addAll(query)
        }
        val primary = pathIdentity
            ?: identities.firstOrNull { it.kind == CanonicalHomeVideoId.Kind.BV }
            ?: identities.firstOrNull()
            ?: return null
        return ParsedRoute(primary, identities, rawToken)
    }

    private fun parseUnambiguousRoute(raw: String?, root: String): ParsedRoute? {
        val route = parseRoute(raw, root) ?: return null
        if (route.identities.groupBy(CanonicalHomeVideoId::kind).any { it.value.size > 1 }) {
            return null
        }
        return route
    }

    private fun storyRootFor(raw: String?): String? =
        STORY_URI_ROOTS.firstOrNull { isRouteFor(raw, it) }

    private fun parseIntentIdentities(
        snapshot: HomeVerticalIntentRouteSnapshot
    ): Set<CanonicalHomeVideoId>? {
        val identities = linkedSetOf<CanonicalHomeVideoId>()
        listOf(
            snapshot.bvid to CanonicalHomeVideoId.Kind.BV,
            snapshot.aid to CanonicalHomeVideoId.Kind.AID,
            snapshot.avid to CanonicalHomeVideoId.Kind.AID
        ).forEach { (raw, expectedKind) ->
            if (raw == null) return@forEach
            val identity = canonicalIdentity(raw) ?: return null
            if (identity.kind != expectedKind) return null
            identities += identity
        }
        return identities
    }

    /** 只允许“无路径、且没有显式非法视频身份”的 Story 根路由从外部结构化字段补身份。 */
    private fun permitsFallbackIdentity(raw: String?, root: String): Boolean {
        val route = raw?.takeIf { it.length <= MAX_ROUTE_LENGTH && isRouteFor(it, root) }
            ?: return false
        val suffixStart = route.indexOfFirstFrom(root.length) { it == '?' || it == '#' }
        val pathEnd = suffixStart.takeIf { it >= 0 } ?: route.length
        if (route.substring(root.length, pathEnd).isNotEmpty()) return false
        return parseQueryIdentities(route)?.isEmpty() == true
    }

    private data class ParsedRoute(
        val primaryIdentity: CanonicalHomeVideoId,
        val identities: Set<CanonicalHomeVideoId>,
        val rawToken: String?
    )

    private fun isRouteFor(raw: String?, root: String): Boolean {
        if (raw == null || raw.length < root.length || !raw.startsWith(root, ignoreCase = true)) {
            return false
        }
        return raw.length == root.length || raw[root.length] in charArrayOf('/', '?', '#')
    }

    private fun rewriteStoryRoute(raw: String, route: ParsedRoute, storyRoot: String): String {
        val sanitized = sanitizeStoryRoutingHints(raw)
        if (route.rawToken != null) {
            return VIDEO_URI_ROOT + sanitized.substring(storyRoot.length)
        }
        val suffixStart = sanitized.indexOfFirstFrom(storyRoot.length) {
            it == '?' || it == '#'
        }
        val suffix = if (suffixStart >= 0) sanitized.substring(suffixStart) else ""
        return VIDEO_URI_PREFIX + route.primaryIdentity.routeToken() + suffix
    }

    /** 去掉宿主用于强制进入 Story 的控制参数，保留其余参数的原始编码、顺序和 fragment。 */
    private fun sanitizeStoryRoutingHints(raw: String): String {
        val queryStart = raw.indexOf('?')
        if (queryStart < 0) return raw
        val fragmentStart = raw.indexOf('#', queryStart + 1).takeIf { it >= 0 } ?: raw.length
        val components = raw.substring(queryStart + 1, fragmentStart).split('&')
        val retained = components.filterNot(::isStoryRoutingHint)
        if (retained.size == components.size) return raw
        return buildString(raw.length) {
            append(raw, 0, queryStart)
            if (retained.isNotEmpty()) append('?').append(retained.joinToString("&"))
            if (fragmentStart < raw.length) append(raw.substring(fragmentStart))
        }
    }

    private fun isStoryRoutingHint(component: String): Boolean {
        val delimiter = component.indexOf('=')
        val encodedName = if (delimiter >= 0) component.substring(0, delimiter) else component
        val name = decodeQueryComponent(encodedName)?.lowercase() ?: return false
        // 先判名再解值：宿主把整个 DASH manifest 内联进 player_preload（实测解码后 28 KB），
        // 无条件解码每个组件的值只为查白名单，纯属浪费。名字不在白名单里就没必要解码。
        if (name !in STORY_ROUTING_QUERY_KEYS) return false
        val encodedValue = if (delimiter >= 0) component.substring(delimiter + 1) else ""
        val value = decodeQueryComponent(encodedValue) ?: return false
        return value.equals("story", ignoreCase = true)
    }

    /** 返回 null 表示出现了显式但无效的 aid/BV 查询身份，调用方据此 fail-open。 */
    private fun parseQueryIdentities(raw: String): Set<CanonicalHomeVideoId>? {
        val queryStart = raw.indexOf('?')
        if (queryStart < 0) return emptySet()
        val fragmentStart = raw.indexOf('#', queryStart + 1).takeIf { it >= 0 } ?: raw.length
        val identities = linkedSetOf<CanonicalHomeVideoId>()
        raw.substring(queryStart + 1, fragmentStart).split('&').forEach { component ->
            val delimiter = component.indexOf('=')
            if (delimiter <= 0) return@forEach
            val name = decodeQueryComponent(component.substring(0, delimiter))
                ?.lowercase() ?: return@forEach
            if (name !in VIDEO_ID_QUERY_KEYS) return@forEach
            val value = decodeQueryComponent(component.substring(delimiter + 1)) ?: return null
            val identity = canonicalIdentity(value) ?: return null
            if (name == "bvid" && identity.kind != CanonicalHomeVideoId.Kind.BV) return null
            if (name != "bvid" && identity.kind != CanonicalHomeVideoId.Kind.AID) return null
            identities += identity
        }
        return identities
    }

    private fun decodeQueryComponent(raw: String): String? =
        runCatching { URLDecoder.decode(raw, Charsets.UTF_8.name()) }.getOrNull()

    private fun encodeQueryComponent(raw: String): String =
        URLEncoder.encode(raw, Charsets.UTF_8.name()).replace("+", "%20")

    private fun uniqueQueryValue(raw: String, expectedName: String): String? {
        val queryStart = raw.indexOf('?')
        if (queryStart < 0) return null
        val fragmentStart = raw.indexOf('#', queryStart + 1).takeIf { it >= 0 } ?: raw.length
        val values = raw.substring(queryStart + 1, fragmentStart)
            .split('&')
            .mapNotNull { component ->
                val delimiter = component.indexOf('=')
                if (delimiter <= 0) return@mapNotNull null
                val name = decodeQueryComponent(component.substring(0, delimiter)) ?: return null
                if (!name.equals(expectedName, ignoreCase = true)) return@mapNotNull null
                decodeQueryComponent(component.substring(delimiter + 1)) ?: return null
            }
            .distinct()
        return values.singleOrNull()
    }

    private inline fun String.indexOfFirstFrom(
        startIndex: Int,
        predicate: (Char) -> Boolean
    ): Int {
        for (index in startIndex until length) if (predicate(this[index])) return index
        return -1
    }

    private val STORY_ROUTING_QUERY_KEYS = setOf("-arouter", "-atype")
    private val VIDEO_ID_QUERY_KEYS = setOf("aid", "avid", "bvid")
    private val STORY_URI_ROOTS = listOf(STORY_TRANSLUCENT_URI_ROOT, STORY_URI_ROOT)
    private val STORY_ACTIVITY_CLASSES = setOf(
        "com.bilibili.video.story.StoryVideoActivity",
        "com.bilibili.video.story.StoryTransparentActivity"
    )
    private const val UNITED_VIDEO_URI_ROOT = "bilibili://united_video"
    private const val FROM_SPMID_QUERY = "from_spmid"
    private const val MAX_FROM_SPMID_LENGTH = 512
    /**
     * 实测同一条 URI 的 `player_preload` 解码后为 **28,449** 字符。原值 8192 与
     * [MAX_ROUTE_LENGTH] 的旧值 4096 还自相矛盾——preload 是 URI 的子串，8192 的载荷永远
     * 装不进 4096 的 URI。必须小于 [MAX_ROUTE_LENGTH]。
     */
    private const val MAX_PLAYER_PRELOAD_LENGTH = 131_072
    private const val TARGET_PACKAGE = "tv.danmaku.bili"

    internal const val NORMAL_AV_GOTO: String = AV_GOTO
}

