internal data class HomeVerticalReadAccessors(
    val cardGoto: Method?,
    val goTo: Method?,
    val uri: Method?
)

internal enum class HomeVerticalMutationResult {
    APPLIED,
    NO_SAFE_ACCESSOR,
    ROLLED_BACK,
    ROLLBACK_INCOMPLETE
}

/**
 * 按具体卡片类缓存 setter/稳定序列化字段；一次事务中全部写入并读回，失败则恢复原值。
 * 缓存只持有 Class/Method/Field，不持有宿主卡片实例。
 */
internal class ConcreteHomeVerticalRouteMutator {
    private val accessors = ConcurrentHashMap<Class<*>, ConcreteAccessors>()

    fun apply(
        item: Any,
        snapshot: HomeVerticalRouteSnapshot,
        plan: HomeVerticalRoutePlan,
        readers: HomeVerticalReadAccessors
    ): HomeVerticalMutationResult = synchronized(item) {
        val resolved = accessors.computeIfAbsent(item.javaClass, ::resolveAccessors)
        val changes = buildList {
            if (plan.rewriteCardGoto) {
                add(
                    PropertyChange(
                        resolved.cardGoto,
                        snapshot.cardGoto,
                        HomeVerticalDetailRoutePolicy.NORMAL_AV_GOTO,
                        readers.cardGoto
                    )
                )
            }
            if (plan.rewriteGoTo) {
                add(
                    PropertyChange(
                        resolved.goTo,
                        snapshot.goTo,
                        HomeVerticalDetailRoutePolicy.NORMAL_AV_GOTO,
                        readers.goTo
                    )
                )
            }
            if (plan.rewriteUri) {
                add(PropertyChange(resolved.uri, snapshot.uri, plan.detailUri, readers.uri))
            }
        }
        if (changes.isEmpty() || changes.any { it.writer == null || it.reader == null }) {
            return@synchronized HomeVerticalMutationResult.NO_SAFE_ACCESSOR
        }

        val cacheSnapshot = resolved.cacheFields.mapNotNull { field ->
            runCatching { field to field.get(item) }.getOrNull()
        }
        val applied = ArrayList<PropertyChange>(changes.size)
        for (change in changes) {
            if (change.writer?.write(item, change.expected) != true) {
                return@synchronized rollback(item, applied, cacheSnapshot)
            }
            applied += change
        }
        if (!clearCaches(item, resolved.cacheFields) ||
            changes.any { change -> invokeString(change.reader, item) != change.expected }
        ) {
            return@synchronized rollback(item, applied, cacheSnapshot)
        }
        HomeVerticalMutationResult.APPLIED
    }

    internal fun cachedClassCount(): Int = accessors.size

    private fun rollback(
        item: Any,
        applied: List<PropertyChange>,
        cacheSnapshot: List<Pair<Field, Any?>>
    ): HomeVerticalMutationResult {
        var complete = true
        applied.asReversed().forEach { change ->
            if (change.writer?.write(item, change.original) != true) complete = false
        }
        cacheSnapshot.forEach { (field, value) ->
            if (runCatching { field.set(item, value) }.isFailure) complete = false
        }
        return if (complete) {
            HomeVerticalMutationResult.ROLLED_BACK
        } else {
            HomeVerticalMutationResult.ROLLBACK_INCOMPLETE
        }
    }

    private fun clearCaches(item: Any, fields: List<Field>): Boolean = fields.all { field ->
        runCatching { field.set(item, null) }.isSuccess
    }

    private fun resolveAccessors(type: Class<*>): ConcreteAccessors = ConcreteAccessors(
        cardGoto = propertyWriter(type, "setCardGoto", "cardGoto", "card_goto"),
        goTo = propertyWriter(type, "setGoTo", "goTo", "goto"),
        uri = propertyWriter(type, "setUri", "uri", "uri"),
        cacheFields = KavaMemberLookup.fields(
            type,
            includeSuperclasses = true,
            makeAccessible = true
        ) { field ->
            !field.isStatic &&
                !field.isFinal &&
                !field.type.isPrimitive &&
                field.name in ROUTE_CACHE_FIELD_NAMES
        }.distinctBy(Field::toGenericString)
    )

    private fun propertyWriter(
        type: Class<*>,
        setterName: String,
        fieldName: String,
        serializedName: String
    ): PropertyWriter? {
        val setter = mostSpecific(
            type,
            KavaMemberLookup.methods(
                type,
                includeSuperclasses = true,
                makeAccessible = true
            ) { method ->
                method.name == setterName && method.parameterCount == 1 &&
                    method.parameterTypes[0] == classOf<String>() &&
                    !method.isStatic &&
                    !method.isAbstract
            }.distinctBy(Method::toGenericString)
        )
        val stringFields = KavaMemberLookup.fields(
            type,
            includeSuperclasses = true,
            makeAccessible = true
        ) { field ->
            field.type == classOf<String>() && !field.isStatic &&
                !field.isFinal
        }.distinctBy(Field::toGenericString)
        val annotated = mostSpecific(
            type,
            stringFields.filter { it.serializedNameValue() == serializedName }
        )
        val field = annotated ?: mostSpecific(type, stringFields.filter { it.name == fieldName })
        if (setter == null && field == null) return null
        return PropertyWriter(setter, field)
    }

    private fun <T> mostSpecific(type: Class<*>, candidates: List<T>): T? where T : java.lang.reflect.Member {
        if (candidates.isEmpty()) return null
        val scored = candidates.map { it to inheritanceDistance(type, it.declaringClass) }
        val nearest = scored.minOf { it.second }
        return scored.filter { it.second == nearest }.map { it.first }.singleOrNull()
    }

    private fun inheritanceDistance(type: Class<*>, owner: Class<*>): Int {
        var current: Class<*>? = type
        var distance = 0
        while (current != null) {
            if (current == owner) return distance
            current = current.superclass
            distance += 1
        }
        return Int.MAX_VALUE
    }

    private fun Field.serializedNameValue(): String? =
        declaredAnnotations.firstNotNullOfOrNull { annotation ->
            val annotationType = annotation.annotationClass.java
            val attribute = when (annotationType.name) {
                GSON_SERIALIZED_NAME -> "value"
                FASTJSON_JSON_FIELD -> "name"
                else -> null
            } ?: return@firstNotNullOfOrNull null
            runCatching { annotationType.getMethod(attribute).invoke(annotation) as? String }.getOrNull()
        }

    private fun invokeString(method: Method?, target: Any): String? {
        if (method == null || !method.declaringClass.isInstance(target)) return null
        return runCatching { method.invoke(target) as? String }.getOrNull()
    }

    private data class ConcreteAccessors(
        val cardGoto: PropertyWriter?,
        val goTo: PropertyWriter?,
        val uri: PropertyWriter?,
        val cacheFields: List<Field>
    )

    private data class PropertyChange(
        val writer: PropertyWriter?,
        val original: String?,
        val expected: String,
        val reader: Method?
    )

    private data class PropertyWriter(
        val setter: Method?,
        val field: Field?
    ) {
        fun write(target: Any, value: String?): Boolean {
            val writableField = field
            if (value == null && writableField != null) {
                return runCatching { writableField.set(target, null) }.isSuccess
            }
            val writableSetter = setter
            if (writableSetter != null && runCatching { writableSetter.invoke(target, value) }.isSuccess) return true
            return writableField != null && runCatching { writableField.set(target, value) }.isSuccess
        }
    }

    private companion object {
        private const val GSON_SERIALIZED_NAME = "com.google.gson.annotations.SerializedName"
        private const val FASTJSON_JSON_FIELD = "com.alibaba.fastjson.annotation.JSONField"
        private val ROUTE_CACHE_FIELD_NAMES = setOf("stringUriCache", "uriCache")
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import java.util.concurrent.atomic.AtomicBoolean

/**
 * 把一条 Java moss RPC 的过滤"搬"到它的 Kotlin 孪生通道上（`…Moss` → `…KMoss`）的通用安装器。
 *
 * 宿主正把页面逐个迁到 KMP（`kntr.*`），迁过去的页面直接调 `K*Moss`、拿 Kotlin 序列化数据类，
 * 挂在 Java 响应 getter 上的过滤对它无声失效（2026-10-01 研判：9.14.0 的 KMP 评论页、新版搜索都是这样）。
 * 这里沿用 [KotlinMossReplyBridge] 的线格式往返：Kotlin 响应 → 同一 proto 的 Java 响应 → 调用方给的
 * [install] `transformJava` → 有改动才回写成新的 Kotlin 响应。Kotlin 版 suspend / 回调两种调用最终都汇入
 * 回调形态泛型入口（[KotlinMossBridgeMembers.callbackEntry]），挂一处即可。
 *
 * **原始读取**：同一进程里 Java getter 上通常还挂着本功能的 getter 过滤，`transformJava` 里读列表若经过它，
 * 读到的是已过滤结果，就判断不出"有没有删东西"。所以 `transformJava` 要在 [raw] 里读，getter 过滤开头用
 * [isRaw] 放行。
 *
 * 任何一步装不上返回 false（调用方照常走 Java 链路）；运行期任何异常都放行原响应。
 */
internal object KotlinMossChannel {

    private val rawDepth = ThreadLocal<IntArray>()

    /** 在"原始读取"作用域里执行：本线程上的 getter 过滤一律放行。可重入。 */
    fun <T> raw(block: () -> T): T {
        val depth = rawDepth.get() ?: IntArray(1).also(rawDepth::set)
        depth[0]++
        try {
            return block()
        } finally {
            depth[0]--
        }
    }

    /** getter 过滤开头调用：处于 [raw] 作用域时不过滤。 */
    fun isRaw(): Boolean = (rawDepth.get()?.get(0) ?: 0) > 0

    /** 解析 kotlinx.serialization 成员并跑一次真实往返自检；不可用返回 null。 */
    fun prepare(environment: HookEnvironment, loader: ClassLoader, what: String, logKey: String): KotlinMossBridgeMembers? {
        val members = KotlinMossBridgeMembers.resolve(loader)
        if (members == null) {
            environment.logInfo("${logKey}_skip", "[BIL] $what 新通道未安装: kotlinx.serialization 成员缺失")
            return null
        }
        return members.takeIf { KotlinMossBridgeSelfTest.allows(environment, loader, it, what) }
    }

    /**
     * 在 Kotlin 孪生 moss 的 [rpc] 回调入口上装过滤。
     *
     * @param javaMossClassName Java moss 全名；Kotlin 版按 `K` + 简单名推出。
     * @param javaReplyClass 与 Kotlin 响应同一 proto 的 Java 响应类。
     * @param transformJava 在 Java 响应上做过滤；返回同一个对象表示没改动。
     */
    fun install(
        environment: HookEnvironment,
        loader: ClassLoader,
        members: KotlinMossBridgeMembers,
        javaMossClassName: String,
        rpc: String,
        javaReplyClass: Class<*>,
        hookId: String,
        what: String,
        logKey: String,
        /** 可选：请求也走同样的往返（例如在请求里声明宿主自己的开关）；返回同一对象表示不改。 */
        javaRequestClass: Class<*>? = null,
        transformRequest: ((Any) -> Any)? = null,
        /** 评论管线显式启用；其他 RPC 保持原代理与变换行为。 */
        shareUnchangedReply: Boolean = false,
        transformJava: (Any) -> Any
    ): Boolean {
        fun skip(reason: String): Boolean {
            environment.logInfo("${logKey}_skip_$rpc", "[BIL] $what 新通道跳过 $rpc: $reason")
            return false
        }
        val kotlinName = KotlinMossBridgeMembers.kotlinMossClassName(javaMossClassName) ?: return skip("no-kotlin-name")
        val kotlinMoss = KavaMemberLookup.classOrNull(loader, kotlinName) ?: return skip("no-kotlin-moss")
        val codec = KotlinMossBridgeMembers.JavaReplyCodec.resolve(javaReplyClass) ?: return skip("no-java-codec")
        val entry = KotlinMossBridgeMembers.callbackEntry(kotlinMoss, rpc) ?: return skip("no-callback-entry")
        val handlerClass = entry.parameterTypes[3]
        val requestCodec = javaRequestClass?.takeIf { transformRequest != null }
            ?.let { KotlinMossBridgeMembers.JavaReplyCodec.resolve(it) ?: return skip("no-java-request-codec") }
        val called = AtomicBoolean(false)
        val failedLogged = AtomicBoolean(false)
        val requestFailedLogged = AtomicBoolean(false)
        return runCatching {
            environment.registrar.exact(hookId, entry.declaringClass, entry.name, *entry.parameterTypes) {
                before {
                    if (called.compareAndSet(false, true)) {
                        environment.logInfo("${logKey}_call", "[BIL] $what 新通道请求已进入 ${kotlinMoss.simpleName}#${entry.name}")
                    }
                    if (requestCodec != null && transformRequest != null) {
                        val request = args.getOrNull(0)
                        // 请求的生成 `$serializer` 同时是序列化与反序列化策略，可以原样往返。
                        val requestBridge = members.bridgeFor(args.getOrNull(4), args.getOrNull(1), requestCodec)
                        if (request != null && requestBridge != null) {
                            runCatching { requestBridge.transform(request, transformRequest) }
                                .onSuccess { updated -> if (updated !== request) args[0] = updated }
                                .onFailure { throwable ->
                                    if (requestFailedLogged.compareAndSet(false, true)) {
                                        environment.logError(
                                            "${logKey}_request_failed",
                                            "[BIL] $what 新通道请求改写失败，已放行原请求(${entry.name}): $throwable"
                                        )
                                    }
                                }
                        }
                    }
                    val delegate = args.getOrNull(3) ?: return@before
                    val bridge = members.bridgeFor(args.getOrNull(4), args.getOrNull(2), codec) ?: return@before
                    val failed: (Throwable) -> Unit = { throwable ->
                        if (failedLogged.compareAndSet(false, true)) {
                            environment.logError("${logKey}_failed",
                                "[BIL] $what 新通道过滤失败，已放行原响应(${entry.name}): $throwable")
                        }
                    }
                    val proxy = if (shareUnchangedReply) {
                        val key = KotlinMossResponseHandlerProxy.Key(entry, javaReplyClass, args[4]!!, args[2]!!)
                        KotlinMossResponseHandlerProxy.wrap(handlerClass, delegate, key, bridge, failed, transformJava)
                    } else MossResponseHandlerProxy.wrapTransform(handlerClass, delegate) { reply ->
                        runCatching { bridge.transform(reply, transformJava) }.getOrElse { throwable ->
                            failed(throwable)
                            reply
                        }
                    } ?: return@before
                    args[3] = proxy
                }
            }
            true
        }.getOrElse { throwable ->
            environment.logError("${logKey}_register_$rpc", "[BIL] $what 新通道注册失败($rpc): $throwable")
            false
        }
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.InvocationTargetException
import java.lang.reflect.Method

/**
 * Kotlin 序列化版 moss 响应 ↔ Java protobuf 响应的往返桥。
 *
 * 9.14.0 起动态页新列表走 `KDynamicMoss`，响应是 kotlinx.serialization 数据类，且 R8 把字段名混淆成
 * `a`/`b`/`c`……（getter 也被内联掉），既没法按名字读、也没法按名字写。但**同一个 proto 的 Java 版
 * 响应类（`DynAllReply` / `DynVideoReply`）仍在宿主里**，动态过滤的全部判据都已经建立在它上面。
 * 所以这里不去解析 Kotlin 数据类，而是走 protobuf 线格式：
 *
 *     Kotlin 响应 --ProtoBuf.encodeToByteArray--> 字节 --Java parseFrom--> Java 响应
 *         --（既有的动态过滤，原样复用）--> 过滤后的 Java 响应
 *         --toByteArray--> 字节 --ProtoBuf.decodeFromByteArray--> 新的 Kotlin 响应
 *
 * 好处：判据（关键词/发布者/带货卡/充电专属/智能过滤/话题栏/UP 栏）一条都不用重写；字段混淆无关；
 * 线格式两边生成自同一份 proto，往返无损。**过滤没有改动任何东西时直接返回原 Kotlin 对象，不做回写**，
 * 所以最常见的路径只多一次序列化 + 解析。
 *
 * 任何一步抛异常都由调用方回退到原响应；这里不吞异常，也不缓存任何宿主实例。
 */
internal class KotlinMossReplyBridge(
    private val encode: (Any) -> ByteArray,
    private val parseJava: (ByteArray) -> Any,
    private val toBytes: (Any) -> ByteArray,
    private val decode: (ByteArray) -> Any
) {
    internal fun read(kotlinReply: Any): Any = parseJava(encode(kotlinReply))
    internal fun write(javaReply: Any): Any = decode(toBytes(javaReply))

    /** @return 过滤后的 Kotlin 响应；[purifyJava] 返回同一个对象表示没有改动，此时返回 [kotlinReply] 本身。 */
    fun transform(kotlinReply: Any, purifyJava: (Any) -> Any): Any {
        val javaReply = read(kotlinReply)
        val updated = purifyJava(javaReply)
        return if (updated === javaReply) kotlinReply else write(updated)
    }
}

/**
 * 安装期解析出的 kotlinx.serialization 与 Java protobuf 成员；只持有 Class/Method，不持有宿主实例。
 * 这些名字（`ProtoBuf#encodeToByteArray` / `decodeFromByteArray`、`parseFrom([B)` / `toByteArray`）在宿主里
 * 都没有被混淆（2026-09-30 dexq 对 9.14.0 核对）；任何一个缺失就整体不可用（返回 null），
 * 由调用方退回观测措施，而不是装一个半截的桥。
 */
internal class KotlinMossBridgeMembers private constructor(
    private val strategyClass: Class<*>,
    private val deserializationClass: Class<*>,
    private val protoBufClass: Class<*>,
    private val encodeMethod: Method,
    private val decodeMethod: Method
) {
    /** Java 响应类的解析/序列化入口。 */
    class JavaReplyCodec(private val parseFrom: Method, private val toByteArray: Method) {
        fun parse(bytes: ByteArray): Any = unwrap { parseFrom.invoke(null, bytes) }
            ?: error("parseFrom returned null")

        fun serialize(reply: Any): ByteArray = unwrap { toByteArray.invoke(reply) } as? ByteArray
            ?: error("toByteArray returned non-bytes")

        companion object {
            /**
             * 用 [Class.getMethod]（含继承的公开方法）而不是"只看本类声明"的查找：Java protobuf 消息的
             * `toByteArray()` 声明在父类 `AbstractMessageLite` 里，本类只声明静态 `parseFrom(byte[])`。
             * 2026-10-01 真机上因为只查本类，两处 Kotlin 通道都静默没装上；单测夹具把两个方法声明在同一个类里，没能暴露。
             */
            fun resolve(javaReplyClass: Class<*>): JavaReplyCodec? {
                val parse = runCatching { javaReplyClass.getMethod("parseFrom", classOf<ByteArray>()) }.getOrNull()
                    ?.takeIf { it.isStatic && it.returnType isSubclassOf javaReplyClass }
                val bytes = runCatching { javaReplyClass.getMethod("toByteArray") }.getOrNull()
                    ?.takeIf { !it.isStatic && it.returnType == classOf<ByteArray>() }
                return if (parse != null && bytes != null) JavaReplyCodec(parse, bytes) else null
            }
        }
    }

    /** 宿主的默认 `ProtoBuf` 实例（`ProtoBuf.Default`）；自检用，取不到返回 null。 */
    fun defaultProtoBuf(): Any? = runCatching { protoBufClass.getField("Default").get(null) }.getOrNull()
        ?.takeIf(protoBufClass::isInstance)

    fun encodeKotlin(protoBuf: Any, serializer: Any, value: Any): ByteArray =
        unwrap { encodeMethod.invoke(protoBuf, serializer, value) } as? ByteArray
            ?: error("encodeToByteArray returned non-bytes")

    fun decodeKotlin(protoBuf: Any, serializer: Any, bytes: ByteArray): Any =
        unwrap { decodeMethod.invoke(protoBuf, serializer, bytes) } ?: error("decodeFromByteArray returned null")

    /**
     * 为一次响应回调构造桥。[serializer] 是宿主传给 `dynAll/dynVideo` 的响应反序列化器
     * （生成的 `$serializer`，同时实现序列化与反序列化两个接口），[protoBuf] 是它用的 `ProtoBuf` 实例。
     * 类型对不上就返回 null，调用方原样放行。
     */
    fun bridgeFor(protoBuf: Any?, serializer: Any?, codec: JavaReplyCodec): KotlinMossReplyBridge? {
        if (protoBuf == null || serializer == null) return null
        if (!protoBufClass.isInstance(protoBuf)) return null
        if (!strategyClass.isInstance(serializer) || !deserializationClass.isInstance(serializer)) return null
        return KotlinMossReplyBridge(
            encode = { reply -> unwrap { encodeMethod.invoke(protoBuf, serializer, reply) } as? ByteArray
                ?: error("encodeToByteArray returned non-bytes") },
            parseJava = codec::parse,
            toBytes = codec::serialize,
            decode = { bytes -> unwrap { decodeMethod.invoke(protoBuf, serializer, bytes) }
                ?: error("decodeFromByteArray returned null") }
        )
    }

    companion object {
        const val SERIALIZATION_STRATEGY = "kotlinx.serialization.SerializationStrategy"
        const val DESERIALIZATION_STRATEGY = "kotlinx.serialization.DeserializationStrategy"
        const val PROTO_BUF = "kotlinx.serialization.protobuf.ProtoBuf"

        fun resolve(loader: ClassLoader): KotlinMossBridgeMembers? {
            val strategy = KavaMemberLookup.classOrNull(loader, SERIALIZATION_STRATEGY) ?: return null
            val deserialization = KavaMemberLookup.classOrNull(loader, DESERIALIZATION_STRATEGY) ?: return null
            val protoBuf = KavaMemberLookup.classOrNull(loader, PROTO_BUF) ?: return null
            val encode = KavaMemberLookup.methodOrNull(protoBuf, "encodeToByteArray", strategy, classOf<Any>())
                ?.takeIf { !it.isStatic && it.returnType == classOf<ByteArray>() } ?: return null
            val decode = KavaMemberLookup.methodOrNull(protoBuf, "decodeFromByteArray", deserialization, classOf<ByteArray>())
                ?.takeIf { !it.isStatic } ?: return null
            return KotlinMossBridgeMembers(strategy, deserialization, protoBuf, encode, decode)
        }

        /**
         * Java moss 类名 → 同包的 Kotlin 版类名：`…v1.ViewMoss` → `…v1.KViewMoss`（宿主里 K 版一律是 `K` + 原类名，
         * 且 `K*Moss` 类名没有被混淆）。类名里带 `$` 或最后一段为空时返回 null。
         */
        fun kotlinMossClassName(javaMossClassName: String): String? {
            val dot = javaMossClassName.lastIndexOf('.')
            val simple = javaMossClassName.substring(dot + 1)
            if (simple.isEmpty() || '$' in simple) return null
            return javaMossClassName.substring(0, dot + 1) + "K" + simple
        }

        /** 同步入口 `executeViewProgress` 与异步入口 `viewProgress` 对应同一个 RPC：统一成 `viewProgress`。 */
        fun rpcName(methodName: String): String =
            if (methodName.startsWith("execute") && methodName.length > "execute".length &&
                methodName["execute".length].isUpperCase()
            ) {
                methodName.substring("execute".length).replaceFirstChar { it.lowercaseChar() }
            } else methodName

        /**
         * `KDynamicMoss` 里所有 Kotlin 版请求最终汇入的**回调形态泛型入口**：
         * `(Object req, SerializationStrategy, DeserializationStrategy, Handler, ProtoBuf)V`。
         * suspend 形态的 `dynAll/dynVideo` 也是转成它（内联的 `suspendCall` 匿名回调）再发请求，
         * 所以挂它一处就覆盖 suspend / 回调两种调用方式。Handler 类型被混淆，只认"接口"，
         * 响应回调方法名（`onNext`）没有被混淆，由 [MossResponseHandlerProxy] 处理。
         */
        fun callbackEntry(mossClass: Class<*>, name: String): Method? =
            KavaMemberLookup.declaredMethods(mossClass, makeAccessible = true) { method ->
                val types = method.parameterTypes
                method.name == name && !method.isStatic && method.returnType == Void.TYPE &&
                    types.size == 5 && types[0] == classOf<Any>() &&
                    types[1].name == SERIALIZATION_STRATEGY &&
                    types[2].name == DESERIALIZATION_STRATEGY &&
                    types[3].isInterface && types[4].name == PROTO_BUF
            }.singleOrNull()
    }
}

/** 反射调用的异常统一还原成宿主/库自己抛出的那个。 */
private inline fun unwrap(block: () -> Any?): Any? = try {
    block()
} catch (invocation: InvocationTargetException) {
    throw invocation.targetException ?: invocation
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.view.MotionEvent
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.Method

/**
 * 直播间的两个交互小件：禁止上下滑动换房、双击改为暂停/继续。
 *
 * 两项互相独立，各算一个覆盖单位；一项定位失败不影响另一项。
 *
 * **翻页器类名是混淆的，禁止写死**：这里从稳定类
 * `LiveVerticalPagerView` 出发，取它声明的、类型是宿主 RecyclerView 子类的字段，用那个字段
 * 的类型当翻页器实现类。候选不唯一就按缺失处理，不猜。
 *
 * **版本覆盖（2026-09-06 离线核对 9.7.0–9.11.0 五版）**：翻页器候选每一版都恰好一个，
 * 但实现类名逐版漂移（`IM.h` → `KM.h` → `LM.g` → `LM.h` → `MM.g`），字段名也从 `a` 变过 `b`，
 * 这正是不能写死名字、只能按结构定位的直接证据；播放桥返回类型同样漂移
 * （`p5.b` → `q5.b`），但 `isPlaying`/`pause`/`resume` 三个方法五版齐全。
 *
 * 双击暂停走 `LiveRoomPlayerContainerView#onDoubleTap`：`before` 里通过宿主自己的播放桥
 * （`getPlayerCommonBridge`，私有但名字未混淆）切换播放状态，然后消费掉这次双击，避免同时
 * 触发原本的点赞。桥或其方法解析不到时**不注册**这一项，绝不让双击变成空操作。
 */
internal class LiveRoomWidgetFeatureInstaller(
    private val blockRoomSwitch: Boolean,
    private val doubleTapPause: Boolean
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (blockRoomSwitch) add("live_room_switch_blocked")
        if (doubleTapPause) add("live_double_tap_pause")
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!blockRoomSwitch && !doubleTapPause) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")

        var installed = 0
        var expected = 0

        if (blockRoomSwitch) {
            expected += 1
            val success = installRoomSwitchBlock(environment.forCapabilityRuntime("live_room_switch_blocked"), loader)
            if (success) installed += 1
            environment.reportCapabilityCoverage("live_room_switch_blocked", true, if (success) 1 else 0, 1)
        }
        if (doubleTapPause) {
            expected += 1
            val success = installDoubleTapPause(environment.forCapabilityRuntime("live_double_tap_pause"), loader)
            if (success) installed += 1
            environment.reportCapabilityCoverage("live_double_tap_pause", true, if (success) 1 else 0, 1)
        }

        if (installed == 0) return missing(environment, "no-live-room-hook-point")
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        val status = if (installed == expected) "success" else "partial:$installed/$expected"
        environment.reportStatus(CHANNEL_STATUS, status)
        if (status == "success") {
            environment.logInfo(
                "live_room_widgets_ok",
                "[BIL] 直播间小件已安装，switch=$blockRoomSwitch，doubleTap=$doubleTapPause"
            )
        } else {
            environment.logError(
                "live_room_widgets_partial",
                "[BIL] 直播间小件部分安装，status=$status"
            )
        }
        return FeatureInstallResult.Installed(installed, complete = installed == expected)
    }

    /** 翻页器拦不到触摸就换不了房；直接让 `onInterceptTouchEvent` 恒返回 false。 */
    private fun installRoomSwitchBlock(
        environment: HookEnvironment,
        loader: ClassLoader
    ): Boolean {
        val pagerHost = KavaMemberLookup.classOrNull(loader, LIVE_VERTICAL_PAGER_CLASS)
            ?: run {
                environment.logError(
                    "live_room_pager_host_missing",
                    "[BIL] 直播间翻页容器类缺失，禁止换房未安装"
                )
                return false
            }
        val recyclerView = KavaMemberLookup.classOrNull(loader, HOST_RECYCLER_VIEW_CLASS)
            ?: run {
                environment.logError(
                    "live_room_recycler_missing",
                    "[BIL] 宿主 RecyclerView 类缺失，禁止换房未安装"
                )
                return false
            }
        // 刻意排除字段类型正好是 RecyclerView 本身的情况：那会让我们去 Hook 平台基类的
        // onInterceptTouchEvent，全应用每个列表都被波及。只接受宿主自己的子类实现。
        val candidates = KavaMemberLookup.declaredFields(pagerHost) { field ->
            !field.isStatic && field.type isSubclassOf recyclerView &&
                field.type != recyclerView
        }.map { it.type }.distinct()
        val pagerClass = candidates.singleOrNull() ?: run {
            environment.logError(
                "live_room_pager_ambiguous",
                "[BIL] 直播间翻页器候选不唯一(${candidates.size})，禁止换房未安装"
            )
            return false
        }
        val intercept = KavaMemberLookup.methodOrNull(
            pagerClass,
            "onInterceptTouchEvent",
            classOf<MotionEvent>()
        )?.takeIf { !it.isStatic && it.returnType == classOf<Boolean>() } ?: run {
            environment.logError(
                "live_room_intercept_missing",
                "[BIL] 直播间翻页器缺少 onInterceptTouchEvent，禁止换房未安装"
            )
            return false
        }

        // onInterceptTouchEvent 每个 MOVE 事件都会进来，是货真价实的触摸热路径：
        // 运行证据只在第一次上报，之后每次回调只剩一次 volatile 读。
        val evidenceReported = java.util.concurrent.atomic.AtomicBoolean(false)
        return runCatching {
            environment.registrar.exact(
                "live.room.block_switch",
                intercept.declaringClass,
                intercept.name,
                *intercept.parameterTypes
            ) {
                before {
                    // 只拦截"是否把手势收走"这一个判断；触摸事件本身仍交给子视图正常分发。
                    result = false
                    if (evidenceReported.compareAndSet(false, true)) {
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                    }
                }
            }
            true
        }.getOrElse { throwable ->
            environment.logError(
                "live_room_block_switch_register",
                "[BIL] 直播间禁止换房 Hook 注册失败: $throwable"
            )
            false
        }
    }

    private fun installDoubleTapPause(
        environment: HookEnvironment,
        loader: ClassLoader
    ): Boolean {
        val container = KavaMemberLookup.classOrNull(loader, LIVE_PLAYER_CONTAINER_CLASS)
            ?: run {
                environment.logError(
                    "live_room_container_missing",
                    "[BIL] 直播间播放容器类缺失，双击暂停未安装"
                )
                return false
            }
        val onDoubleTap = KavaMemberLookup.declaredMethods(container, makeAccessible = true) {
            !it.isStatic && it.name == "onDoubleTap" && it.parameterCount == 1 &&
                it.parameterTypes[0] == classOf<MotionEvent>() &&
                it.returnType == classOf<Boolean>()
        }.singleOrNull() ?: run {
            environment.logError(
                "live_room_double_tap_missing",
                "[BIL] 直播间播放容器缺少 onDoubleTap，双击暂停未安装"
            )
            return false
        }
        val bridgeGetter = KavaMemberLookup.methodOrNull(container, PLAYER_BRIDGE_GETTER)
            ?.takeIf { !it.isStatic && it.parameterCount == 0 && !it.returnType.isPrimitive }
            ?: run {
                environment.logError(
                    "live_room_bridge_missing",
                    "[BIL] 直播间播放桥缺失，双击暂停未安装"
                )
                return false
            }
        // 三个控制方法都声明在播放桥的接口类型上，直接按返回类型解析，不依赖运行期实现类。
        val bridgeType = bridgeGetter.returnType
        val isPlaying = KavaMemberLookup.methodOrNull(bridgeType, "isPlaying")
            ?.takeIf { it.parameterCount == 0 && it.returnType == classOf<Boolean>() }
        val pause = voidNoArg(bridgeType, "pause")
        val resume = voidNoArg(bridgeType, "resume")
        if (isPlaying == null || pause == null || resume == null) {
            environment.logError(
                "live_room_bridge_members_missing",
                "[BIL] 直播间播放桥缺少播放控制方法，双击暂停未安装"
            )
            return false
        }

        return runCatching {
            environment.registrar.exact(
                "live.room.double_tap_pause",
                onDoubleTap.declaringClass,
                onDoubleTap.name,
                *onDoubleTap.parameterTypes
            ) {
                before {
                    val target = instance ?: return@before
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    val bridge = runCatching { bridgeGetter.invoke(target) }.getOrNull()
                        ?: return@before
                    val playing = runCatching { isPlaying.invoke(bridge) }.getOrNull() as? Boolean
                        ?: return@before
                    val toggled = runCatching {
                        if (playing) pause.invoke(bridge) else resume.invoke(bridge)
                        true
                    }.getOrDefault(false)
                    // 切换失败就放行原逻辑，保持宿主原有的双击行为，不制造"点了没反应"。
                    if (!toggled) return@before
                    result = true
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                }
            }
            true
        }.getOrElse { throwable ->
            environment.logError(
                "live_room_double_tap_register",
                "[BIL] 直播间双击暂停 Hook 注册失败: $throwable"
            )
            false
        }
    }

    private fun voidNoArg(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf { method ->
            method.parameterCount == 0 && method.returnType == Void.TYPE
        }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "live_room_widgets_missing",
            "[BIL] 直播间小件适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "live_room_widgets"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "live_room_widgets_status"
        private const val LIVE_VERTICAL_PAGER_CLASS =
            "com.bilibili.bililive.room.ui.roomv3.vertical.widget.LiveVerticalPagerView"
        private const val LIVE_PLAYER_CONTAINER_CLASS =
            "com.bilibili.bililive.room.ui.roomv3.player.container.LiveRoomPlayerContainerView"
        private const val HOST_RECYCLER_VIEW_CLASS =
            "androidx.recyclerview.widget.RecyclerView"
        private const val PLAYER_BRIDGE_GETTER = "getPlayerCommonBridge"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.content.Context
import android.view.View
import android.view.ViewGroup
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.ReflectAccess

/** 隐藏视频简介区的“UP 主分享好物”商品模块。 */
internal class MerchandiseFeatureInstaller(
    private val enabled: Boolean
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) return FeatureInstallResult.Skipped("disabled")
        val owner = KavaMemberLookup.classOrNull(environment.classLoader, COMPONENT_CLASS)
            ?: return FeatureInstallResult.Skipped("missing:$COMPONENT_CLASS")

        environment.registrar.exact(
            HOOK_CREATE_VIEW_ENTRY,
            owner,
            "createViewEntry",
            classOf<Context>(),
            classOf<ViewGroup>()
        ) {
            after {
                val viewEntry = result ?: return@after
                val root = runCatching {
                    ReflectAccess.callMethod(viewEntry, "getRoot") as? View
                }.getOrNull() ?: return@after
                runCatching {
                    collapse(root)
                    var parent = root.parent as? View
                    var depth = 0
                    while (parent != null && depth < 2) {
                        collapse(parent)
                        parent = parent.parent as? View
                        depth++
                    }
                }
                environment.logInfo(
                    "merch_blocked",
                    "[BIL] 已隐藏UP主分享好物 createViewEntry"
                )
            }
        }
        return FeatureInstallResult.Installed()
    }

    private fun collapse(view: View) {
        view.visibility = View.GONE
        view.layoutParams?.let { params ->
            if (params.height != 0) {
                params.height = 0
                view.requestLayout()
            }
        }
    }

    companion object {
        const val ID = "merchandise"
        const val HOOK_CREATE_VIEW_ENTRY = "merchandise.create_view_entry"
        private const val COMPONENT_CLASS =
            "com.bilibili.ship.theseus.united.page.intro.module.merchandise.MerchandiseComponent"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import java.lang.reflect.Field
import java.lang.reflect.Method

/**
 * “我的”页组件扫描与隐藏。
 *
 * 9.9.x 在 HomeUserCenterFragment 消费 AccountMine 之前剪枝 sectionListV2；其他版本
 * 同时注册 MenuGroup(V2)#getItemList 返回边界和旧字段边界。所有链路都在空配置时保留
 * 扫描能力，配置仅决定是否过滤。运行期只保存字符串快照，不缓存宿主模型实例。
 */
internal class MineComponentFilterFeatureInstaller(
    rules: String,
    hiddenIds: Collection<String>,
    selectors: String,
    private val points: VersionAdapter.MineComponentPoints?,
    private val accountMinePoints: VersionAdapter.MineAccountMinePoints?
) : FeatureInstaller {

    override val id: String = ID
    private val ruleTokens = RuleSetCodec.parse(rules)
    private val hiddenIdSet = hiddenIds.asSequence()
        .map(String::trim)
        .filter(String::isNotEmpty)
        .toSet()
    private val hiddenSelectorSet = MineComponentSelectionCodec.decode(selectors)

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val snapshots = SnapshotAccumulator(environment)
        val accountInstalled = installMineAccountMinePath(environment, snapshots)
        val getterInstalled = installGetterPath(environment, snapshots)
        var installed = accountInstalled + getterInstalled
        if (installed == 0) {
            val legacy = installLegacyFieldPath(environment, snapshots, points)
            if (legacy is FeatureInstallResult.Installed) installed += legacy.hookCount
        }
        if (installed == 0) return missing(environment, "registration-failed")
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        val mode = if (hasHiddenConfiguration()) "filter+scan" else "scan"
        environment.reportStatus(CHANNEL_STATUS, "success:$mode")
        return FeatureInstallResult.Installed(installed)
    }

    private fun installMineAccountMinePath(
        environment: HookEnvironment,
        snapshots: SnapshotAccumulator
    ): Int {
        val adapted = accountMinePoints ?: return 0
        if (adapted.buildMethods.isEmpty()) return 0
        val accountMineClass = KavaMemberLookup.classOrNull(
            environment.classLoader,
            adapted.accountMineClass
        ) ?: return 0
        val groupClass = KavaMemberLookup.classOrNull(environment.classLoader, adapted.groupClass)
            ?: return 0
        val itemClass = KavaMemberLookup.classOrNull(environment.classLoader, adapted.itemClass)
            ?: return 0
        val sectionsField = KavaMemberLookup.fieldOrNull(
            accountMineClass,
            adapted.sectionListV2Field
        ) ?: return 0
        val groupItemsField = KavaMemberLookup.fieldOrNull(
            groupClass,
            adapted.groupItemListField
        ) ?: return 0
        val itemTitleField = KavaMemberLookup.fieldOrNull(itemClass, adapted.itemTitleField)
            ?: return 0
        val groupTitleField = adapted.groupTitleField?.let {
            KavaMemberLookup.fieldOrNull(groupClass, it)
        }
        val itemIdField = adapted.itemIdField?.let {
            KavaMemberLookup.fieldOrNull(itemClass, it)
        }
        val itemUriField = adapted.itemUriField?.let {
            KavaMemberLookup.fieldOrNull(itemClass, it)
        }
        val itemVisibleField = adapted.itemVisibleField?.let {
            KavaMemberLookup.fieldOrNull(itemClass, it)
        }
        val itemLocalShowField = adapted.itemLocalShowField?.let {
            KavaMemberLookup.fieldOrNull(itemClass, it)
        }
        val liveTipField = adapted.liveTipField?.let {
            KavaMemberLookup.fieldOrNull(accountMineClass, it)
        }
        val sectionButtonField = adapted.sectionButtonField?.let {
            KavaMemberLookup.fieldOrNull(groupClass, it)
        }

        var installed = 0
        adapted.buildMethods.forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("mine.account_mine.$index", point) {
                    before {
                        val accountMine = args.getOrNull(1) ?: return@before
                        if (!accountMineClass.isInstance(accountMine)) return@before
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        pruneAccountMine(
                            accountMine = accountMine,
                            sectionsField = sectionsField,
                            groupClass = groupClass,
                            groupTitleField = groupTitleField,
                            groupItemsField = groupItemsField,
                            itemClass = itemClass,
                            itemTitleField = itemTitleField,
                            itemIdField = itemIdField,
                            itemUriField = itemUriField,
                            itemVisibleField = itemVisibleField,
                            itemLocalShowField = itemLocalShowField,
                            sectionButtonField = sectionButtonField,
                            liveTipField = liveTipField,
                            snapshots = snapshots,
                            environment = environment
                        )
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "mine_account_mine_$index",
                    "[BIL] “我的”页 AccountMine Hook 注册失败: $throwable"
                )
            }
        }
        return installed
    }

    private fun pruneAccountMine(
        accountMine: Any,
        sectionsField: Field,
        groupClass: Class<*>,
        groupTitleField: Field?,
        groupItemsField: Field,
        itemClass: Class<*>,
        itemTitleField: Field,
        itemIdField: Field?,
        itemUriField: Field?,
        itemVisibleField: Field?,
        itemLocalShowField: Field?,
        sectionButtonField: Field?,
        liveTipField: Field?,
        snapshots: SnapshotAccumulator,
        environment: HookEnvironment
    ) {
        runCatching {
            val sourceSections = sectionsField.get(accountMine) as? List<*> ?: return
            val entries = ArrayList<MineComponentScanEntry>()
            var itemHidden = 0
            var groupHidden = 0
            var changed = false

            sourceSections.forEach { group ->
                if (group == null || !groupClass.isInstance(group)) return@forEach
                val groupTitle = readString(group, groupTitleField)
                val sourceItems = runCatching { groupItemsField.get(group) as? List<*> }
                    .getOrNull()
                if (sourceItems != null) {
                    val filtered = CopyOnFilter.list(sourceItems) { item ->
                        if (!itemClass.isInstance(item)) return@list false
                        val title = readString(item, itemTitleField)
                        val itemId = readValue(item, itemIdField)
                        val uri = readString(item, itemUriField)
                        val protected = MineSettingsEntryGuard.isSettingsEntry(uri)
                        val hidden = !protected && matchesHidden("item", title, itemId, uri)
                        MineComponentScanEntry.create(
                            kind = "item",
                            title = title,
                            id = itemId,
                            uri = uri,
                            showing = !hidden,
                            selectable = !protected
                        )?.let(entries::add)
                        if (hidden) {
                            itemHidden += 1
                            setHiddenFlags(item, itemVisibleField, itemLocalShowField)
                        }
                        hidden
                    }
                    if (filtered !== sourceItems && runCatching {
                            groupItemsField.set(group, filtered)
                        }.isSuccess
                    ) changed = true
                }

                sectionButtonField?.let { field ->
                    val button = runCatching { field.get(group) }.getOrNull()
                    if (button != null) {
                        val title = readNamedString(button, "text") ?: readNamedString(button, "title")
                        val id = readNamedValue(button, "id")
                        val uri = readNamedString(button, "uri")
                        val hidden = matchesHidden("button", title, id, uri)
                        MineComponentScanEntry.create(
                            "button",
                            title,
                            id,
                            uri,
                            showing = !hidden
                        )?.let(entries::add)
                        if (hidden && runCatching { field.set(group, null) }.isSuccess) changed = true
                    }
                }

                if (groupTitle != null) {
                    val hidden = matchesHidden("group", groupTitle, null, null)
                    MineComponentScanEntry.create(
                        "group",
                        groupTitle,
                        null,
                        null,
                        showing = !hidden
                    )?.let(entries::add)
                }
            }

            val filteredSections = CopyOnFilter.list(sourceSections) { group ->
                if (!groupClass.isInstance(group)) return@list false
                val title = readString(group, groupTitleField)
                val hidden = matchesHidden("group", title, null, null)
                if (!hidden) return@list false
                // 整组隐藏但组里有「设置」：保留这一组、只留「设置」。整组删掉会让宿主
                // 找不到设置入口，而它补回设置时取的是"最后一个分组"——一个分组都不剩就崩。
                val items = runCatching { groupItemsField.get(group) as? List<*> }.getOrNull()
                val kept = items?.let {
                    MineSettingsEntryGuard.settingsOnly(it) { item ->
                        item?.takeIf(itemClass::isInstance)?.let { entry -> readString(entry, itemUriField) }
                    }
                }
                if (kept != null && runCatching { groupItemsField.set(group, kept) }.isSuccess) {
                    changed = true
                    groupHidden += 1
                    return@list false
                }
                groupHidden += 1
                true
            }
            if (filteredSections !== sourceSections && runCatching {
                    sectionsField.set(accountMine, filteredSections)
                }.isSuccess
            ) changed = true

            liveTipField?.let { field ->
                val tip = runCatching { field.get(accountMine) }.getOrNull()
                if (tip != null) {
                    val title = readNamedString(tip, "text") ?: readNamedString(tip, "title")
                    val id = readNamedValue(tip, "id")
                    val hidden = matchesHidden("live_tip", title, id, null)
                    MineComponentScanEntry.create(
                        "live_tip",
                        title,
                        id,
                        null,
                        showing = !hidden
                    )?.let(entries::add)
                    if (hidden && runCatching { field.set(accountMine, null) }.isSuccess) changed = true
                }
            }

            snapshots.replace(
                capabilities = setOf("item_filter", "group_filter", "button_filter", "live_tip_filter"),
                entries = entries
            )
            if (changed) {
                environment.reportRuntimeEvidence(
                    ID,
                    FeatureRuntimeStage.APPLIED,
                    (itemHidden + groupHidden).coerceAtLeast(1)
                )
                environment.logInfo(
                    "mine_account_mine_hit",
                    "[BIL] 已按数据层剪枝隐藏“我的”页组件 item=$itemHidden group=$groupHidden"
                )
            }
        }.onFailure { throwable ->
            environment.logError("mine_account_mine_runtime", "[BIL] “我的”页数据剪枝失败，已放行: $throwable")
        }
    }

    /** MenuGroup(V2)#getItemList 返回边界：兼容新动态页面，并产出项目级扫描快照。 */
    private fun installGetterPath(
        environment: HookEnvironment,
        snapshots: SnapshotAccumulator
    ): Int {
        val adapted = points ?: return 0
        if (adapted.itemListGetters.isEmpty()) return 0
        val titleMethods = resolveMethods(environment, "title", adapted.itemTitleGetters)
        if (titleMethods.isEmpty()) return 0
        val idMethods = resolveMethods(environment, "id", adapted.itemIdGetters)
        val uriMethods = resolveMethods(environment, "uri", adapted.itemUriGetters)
        val groupTitleMethods = resolveMethods(environment, "group_title", adapted.groupTitleGetters)

        var installed = 0
        adapted.itemListGetters.forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("mine.components.list.$index", point) {
                    after {
                        val source = result as? List<*> ?: return@after
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        val scanned = ArrayList<MineComponentScanEntry>()
                        val filtered = CopyOnFilter.list(source) { item ->
                            val title = invokeString(item, titleMethods)
                            val id = invokeValue(item, idMethods) ?: readNamedValue(item, "id")
                            val uri = invokeString(item, uriMethods) ?: readNamedString(item, "uri")
                            val protected = MineSettingsEntryGuard.isSettingsEntry(uri)
                            val hidden = !protected && matchesHidden("item", title, id, uri)
                            MineComponentScanEntry.create(
                                "item",
                                title,
                                id,
                                uri,
                                showing = !hidden,
                                selectable = !protected
                            )?.let(scanned::add)
                            hidden
                        }
                        val groupTitle = instance?.let { invokeString(it, groupTitleMethods) }
                        MineComponentScanEntry.create(
                            "group",
                            groupTitle,
                            null,
                            null,
                            showing = true,
                            selectable = false
                        )?.let(scanned::add)
                        snapshots.merge(setOf("item_filter"), scanned)
                        if (filtered !== source) {
                            result = filtered
                            environment.reportRuntimeEvidence(
                                ID,
                                FeatureRuntimeStage.APPLIED,
                                source.size - filtered.size
                            )
                        }
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "mine_components_$index",
                    "[BIL] “我的”页 getter 过滤 Hook 注册失败(${point.className}#${point.methodName}): $throwable"
                )
            }
        }
        return installed
    }

    /** 8.84.0–8.91.0 旧字段模型。 */
    private fun installLegacyFieldPath(
        environment: HookEnvironment,
        snapshots: SnapshotAccumulator,
        adapted: VersionAdapter.MineComponentPoints?
    ): FeatureInstallResult {
        val points = adapted ?: return FeatureInstallResult.Skipped("missing-adapter-point")
        if (points.legacyBuildMethods.isEmpty()) return FeatureInstallResult.Skipped("no-legacy-build")
        val groupClassName = points.legacyGroupClassName
            ?: return FeatureInstallResult.Skipped("missing-legacy-group-class")
        val itemClassName = points.legacyItemClassName
            ?: return FeatureInstallResult.Skipped("missing-legacy-item-class")
        val itemListName = points.legacyItemListField
            ?: return FeatureInstallResult.Skipped("missing-legacy-item-list")
        val titleName = points.legacyItemTitleField
            ?: return FeatureInstallResult.Skipped("missing-legacy-title")
        val groupListName = points.legacyGroupListField
            ?: return FeatureInstallResult.Skipped("missing-legacy-group-list")
        val groupClass = KavaMemberLookup.classOrNull(environment.classLoader, groupClassName)
            ?: return FeatureInstallResult.Skipped("missing-legacy-group-class")
        val itemClass = KavaMemberLookup.classOrNull(environment.classLoader, itemClassName)
            ?: return FeatureInstallResult.Skipped("missing-legacy-item-class")
        val itemListField = KavaMemberLookup.fieldOrNull(groupClass, itemListName)
            ?: return FeatureInstallResult.Skipped("missing-legacy-item-list")
        val titleField = KavaMemberLookup.fieldOrNull(itemClass, titleName)
            ?: return FeatureInstallResult.Skipped("missing-legacy-title")

        var installed = 0
        points.legacyBuildMethods.forEachIndexed { index, point ->
            val owner = KavaMemberLookup.classOrNull(environment.classLoader, point.className)
                ?: return@forEachIndexed
            val groupListField = KavaMemberLookup.fieldOrNull(owner, groupListName)
                ?: return@forEachIndexed
            val adapterField = points.legacyAdapterField?.let { KavaMemberLookup.fieldOrNull(owner, it) }
            val notifyChanged = adapterField?.type?.let {
                KavaMemberLookup.inheritedMethodOrNull(it, "notifyDataSetChanged")
            }
            runCatching {
                environment.registrar.adapted("mine.components.legacy.$index", point) {
                    after {
                        val fragment = instance ?: return@after
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        val groups = runCatching { groupListField.get(fragment) as? List<*> }
                            .getOrNull() ?: return@after
                        val scanned = ArrayList<MineComponentScanEntry>()
                        var changed = false
                        groups.forEach { group ->
                            if (group == null || !groupClass.isInstance(group)) return@forEach
                            val source = runCatching { itemListField.get(group) as? List<*> }
                                .getOrNull() ?: return@forEach
                            val filtered = CopyOnFilter.list(source) { item ->
                                if (!itemClass.isInstance(item)) return@list false
                                val title = readString(item, titleField)
                                val id = readNamedValue(item, "id")
                                val uri = readNamedString(item, "uri")
                                val protected = MineSettingsEntryGuard.isSettingsEntry(uri)
                                val hidden = !protected && matchesHidden("item", title, id, uri)
                                MineComponentScanEntry.create(
                                    "item",
                                    title,
                                    id,
                                    uri,
                                    showing = !hidden,
                                    selectable = !protected
                                )?.let(scanned::add)
                                hidden
                            }
                            if (filtered !== source && runCatching {
                                    itemListField.set(group, filtered)
                                }.isSuccess
                            ) changed = true
                        }
                        snapshots.merge(setOf("item_filter"), scanned)
                        if (changed) runCatching {
                            adapterField?.get(fragment)?.let { notifyChanged?.invoke(it) }
                        }
                        if (changed) environment.reportRuntimeEvidence(
                            ID,
                            FeatureRuntimeStage.APPLIED
                        )
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "mine_components_legacy_$index",
                    "[BIL] 旧版“我的”页组件过滤 Hook 注册失败: $throwable"
                )
            }
        }
        return if (installed == 0) {
            FeatureInstallResult.Skipped("legacy-registration-failed")
        } else {
            FeatureInstallResult.Installed(installed)
        }
    }

    private fun matchesHidden(kind: String, title: String?, id: String?, uri: String?): Boolean {
        val selector = MineComponentSelector.key(kind, title, id, uri)
        if (selector != null && selector in hiddenSelectorSet) return true
        if (id != null && id in hiddenIdSet) return true
        return title != null && ruleTokens.isNotEmpty() && RuleSetCodec.matches(ruleTokens, title)
    }

    private fun hasHiddenConfiguration(): Boolean =
        ruleTokens.isNotEmpty() || hiddenIdSet.isNotEmpty() || hiddenSelectorSet.isNotEmpty()

    private fun resolveMethods(
        environment: HookEnvironment,
        suffix: String,
        points: List<VersionAdapter.HookPoint>
    ): List<Method> = points.mapIndexedNotNull { index, point ->
        environment.hookPoints.resolveAdapted(
            "mine.components.$suffix.$index",
            point.className,
            point.methodName,
            point.paramClassNames
        )
    }.distinctBy(Method::toGenericString)

    private fun invokeString(instance: Any, methods: List<Method>): String? =
        methods.firstNotNullOfOrNull { method ->
            if (!method.declaringClass.isInstance(instance)) null
            else runCatching { method.invoke(instance) as? String }.getOrNull()
        }

    private fun invokeValue(instance: Any, methods: List<Method>): String? =
        methods.firstNotNullOfOrNull { method ->
            if (!method.declaringClass.isInstance(instance)) null
            else runCatching { method.invoke(instance)?.toString() }.getOrNull()
        }

    private fun readString(instance: Any, field: Field?): String? =
        field?.let { runCatching { it.get(instance) as? String }.getOrNull() }

    private fun readValue(instance: Any, field: Field?): String? =
        field?.let { runCatching { it.get(instance)?.toString() }.getOrNull() }

    private fun readNamedString(instance: Any, name: String): String? =
        readNamedField(instance, name) as? String

    private fun readNamedValue(instance: Any, name: String): String? =
        readNamedField(instance, name)?.toString()

    private fun readNamedField(instance: Any, name: String): Any? {
        var owner: Class<*>? = instance.javaClass
        while (owner != null) {
            val field = KavaMemberLookup.fieldOrNull(owner, name)
            if (field != null) return runCatching { field.get(instance) }.getOrNull()
            owner = owner.superclass
        }
        return null
    }

    private fun setHiddenFlags(instance: Any, visible: Field?, localShow: Field?) {
        MineComponentHiddenFlagWriter.apply(instance, visible)
        MineComponentHiddenFlagWriter.apply(instance, localShow)
    }

    private fun missing(environment: HookEnvironment, reason: String): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "mine_components_missing",
            "[BIL] “我的”页组件扫描/隐藏适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    private class SnapshotAccumulator(private val environment: HookEnvironment) {
        private val entries = LinkedHashMap<String, MineComponentScanEntry>()
        private val capabilities = linkedSetOf<String>()

        @Synchronized
        fun replace(capabilities: Set<String>, entries: Collection<MineComponentScanEntry>) {
            publishIfChanged(
                capabilities,
                entries.associateByTo(LinkedHashMap(), MineComponentScanEntry::key)
            )
        }

        @Synchronized
        fun merge(capabilities: Set<String>, newEntries: Collection<MineComponentScanEntry>) {
            if (newEntries.isEmpty()) return
            val mergedEntries = LinkedHashMap(entries)
            newEntries.forEach { entry ->
                val previous = mergedEntries[entry.key]
                mergedEntries[entry.key] = if (previous?.selectable == true && !entry.selectable) {
                    entry.copy(selectable = true)
                } else {
                    entry
                }
            }
            publishIfChanged(this.capabilities + capabilities, mergedEntries)
        }

        private fun publishIfChanged(
            newCapabilities: Set<String>,
            newEntries: Map<String, MineComponentScanEntry>
        ) {
            entries.clear()
            newEntries.entries.take(MineComponentSnapshotCodec.MAX_ENTRY_COUNT).forEach {
                entries[it.key] = it.value
            }
            capabilities.clear()
            capabilities.addAll(newCapabilities)
            environment.writeScanSnapshot?.invoke(
                MineComponentSnapshotCodec.SURFACE_MINE,
                ScanSnapshotContent(
                    processName = environment.processName,
                    capabilities = capabilities.toSet(),
                    entries = entries.values.toList()
                )
            )
        }
    }

    companion object {
        const val ID = "mine_component_filter"
        private const val TARGET_PACKAGE = MineComponentSnapshotCodec.TARGET_PACKAGE
        private const val CHANNEL_STATUS = "mine_component_filter_status"
    }
}

/**
 * 按字段实际类型写入「隐藏」值。
 *
 * 宿主的 `visible` / `localShow` 可能声明为 `boolean`/`int`，也可能是对应的装箱形式
 * （FastJSON 反序列化出的可空字段常为后者）。Kotlin 的 `Boolean::class.java` 只表示
 * **原始** 类型，与 `javaPrimitiveType` 完全相同——旧实现把这两者并列，看似覆盖了原始与
 * 装箱，实际两个分支条件重复，装箱字段一个都匹配不上，隐藏操作被静默跳过。
 *
 * 因此装箱形式必须显式用 `classOf<T>(primitiveType = false)` 列出。写入值仍用 Kotlin 的
 * `false`/`0`，Java 反射会按目标字段自动装箱或拆箱，两种形式共用同一个值。
 */
internal object MineComponentHiddenFlagWriter {

    /** 返回该字段类型对应的隐藏值；无法表达「隐藏」语义的类型返回 null，不写入。 */
    fun hiddenValueFor(type: Class<*>): Any? = when (type) {
        classOf<Boolean>(), classOf<Boolean>(primitiveType = false) -> false
        classOf<Int>(), classOf<Int>(primitiveType = false) -> 0
        else -> null
    }

    /** 写入成功返回 true；字段缺失、类型不支持或宿主拒绝写入均返回 false 且不抛出。 */
    fun apply(instance: Any, field: Field?): Boolean {
        val target = field ?: return false
        val value = hiddenValueFor(target.type) ?: return false
        return runCatching {
            target.set(instance, value)
            true
        }.getOrDefault(false)
    }
}

/**
 * 「我的」页的「设置」入口不许被隐藏。
 *
 * 宿主构建菜单时（9.12.0 `MineUserCenterViewModelV2$1$1`）若在各分组的 `getItemList` 里找不到
 * `activity://main/preference`，会自己补一个「设置」项并挂到**最后一个分组**上；菜单项全部不显示的
 * 分组会被它先删掉。于是"隐藏了设置 + 其余分组也都被隐藏/清空"时，它对空列表取第 -1 项，进程崩溃
 * （2026-09-21 用户诊断包实证）。隐藏「设置」本来也无效——宿主总会补回来——所以直接保护它。
 * 漫游入口（`RoamingCompatHook`）也挂在含「设置」的那个分组上，一并受益。
 */
internal object MineSettingsEntryGuard {
    const val SETTINGS_URI = "activity://main/preference"

    fun isSettingsEntry(uri: String?): Boolean =
        uri?.trim()?.substringBefore('?')?.substringBefore('#') == SETTINGS_URI

    /** 组内的「设置」项；没有时返回 null（调用方按原逻辑整组隐藏）。 */
    fun settingsOnly(items: List<*>, uriOf: (Any?) -> String?): List<Any?>? =
        items.filter { isSettingsEntry(uriOf(it)) }.takeIf { it.isNotEmpty() }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.view.View
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter

/** “我的”页净化：隐藏会员卡片，不修改 AccountMine 数据或其它菜单项。 */
internal class MineVipFeatureInstaller(
    private val enabled: Boolean,
    private val keepSpace: Boolean = false,
    private val point: VersionAdapter.MineVipPoint?
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (enabled) add("mine_vip_hidden")
        if (enabled && keepSpace) add("mine_vip_space_kept")
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = point ?: return missing(environment, "missing-adapter-point")
        val managerFieldName = adapted.onResume.viewField
            ?: return missing(environment, "missing-manager-field-name")

        // 安装期一次性解析完整成员链；回调只执行已缓存 Member，不重复扫描宿主结构。
        val managerField = environment.hookPoints.resolveField(
            "mine.vip.manager_field",
            adapted.onResume.className,
            managerFieldName
        ) ?: return missing(environment, "missing-manager-field")
        val bindingField = environment.hookPoints.resolveField(
            "mine.vip.binding_field",
            managerField.type,
            adapted.bindingField
        ) ?: return missing(environment, "missing-binding-field")
        val rootGetter = environment.hookPoints.resolveAdapted(
            "mine.vip.root_getter",
            adapted.rootGetter.className,
            adapted.rootGetter.methodName,
            adapted.rootGetter.paramClassNames
        ) ?: return missing(environment, "missing-root-getter")

        return runCatching {
            environment.registrar.adapted("mine.vip.on_resume", adapted.onResume) {
                before {
                    runCatching {
                        val fragment = instance
                        val manager = managerField.get(fragment) ?: return@runCatching
                        val binding = bindingField.get(manager) ?: return@runCatching
                        val root = rootGetter.invoke(binding) as? View ?: return@runCatching
                        root.visibility = if (keepSpace) View.INVISIBLE else View.GONE
                    }.onFailure { throwable ->
                        environment.logError(
                            "mine_vip_hide_err",
                            "[BIL] 隐藏“我的”页会员卡片失败: $throwable"
                        )
                    }
                }
            }
            environment.reportStatus(CHANNEL_STATUS, "success")
            environment.logInfo(
                "mine_vip_ok",
                "[BIL] “我的”页会员卡片净化已安装，keepSpace=$keepSpace"
            )
            // Both selected visibility modes use this fully resolved root chain and the registered callback.
            capabilityIds.forEach { environment.reportCapabilityCoverage(it, true, 1, 1) }
            FeatureInstallResult.Installed()
        }.getOrElse { throwable ->
            environment.reportStatus(CHANNEL_STATUS, "failed:${throwable.javaClass.simpleName}")
            environment.logError(
                "mine_vip_install_err",
                "[BIL] “我的”页会员卡片净化 Hook 注册失败: $throwable"
            )
            FeatureInstallResult.Skipped("registration-failed")
        }
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("mine_vip_missing", "[BIL] “我的”页会员卡片适配不完整: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "mine_vip_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "mine_vip_status"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.ReflectAccess
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.InjectedUiLocale
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import java.lang.ref.WeakReference
import java.lang.reflect.Method
import java.lang.reflect.Modifier

/** 共用 Compose 入口：兼容首页 Fragment 和详情页 Nf 弹窗，无宿主网络请求。 */
internal class NativeFeedbackPanel(
    private val injector: FeedbackPanelInjector,
    private val groupItems: Method,
    private val groupStyle: Method,
    private val groupTitle: Method,
    private val groupCopy: Method,
    private val itemClick: Method,
    private val cardMatches: (Any) -> Boolean,
    private val entries: (Any) -> List<Any>,
    private val onSkip: (String) -> Unit = {}
) {
    data class LegacyEntry(val title: String, val click: () -> Unit)

    fun legacyEntries(items: List<Any>): List<LegacyEntry> {
        val card = FeedbackCardGraph.findUnique(items, cardMatches) ?: run {
            onSkip("legacy-missing-current-card")
            return emptyList()
        }
        return entries(card).map { entry ->
            LegacyEntry(injector.titleOf(entry)) { injector.click(entry) }
        }.also { if (it.isEmpty()) onSkip("legacy-missing-tag-metadata") }
    }

    private var original = WeakReference<List<*>>(null)
    private var replacement = WeakReference<List<*>>(null)

    /** 重组复用同一列表；缓存只持弱引用，关闭面板后不保留卡片、回调或 Activity。 */
    fun merge(groups: List<*>): List<*>? {
        if (original.get() === groups) return replacement.get()
        original = WeakReference(groups)
        replacement = WeakReference(null)
        if (groups.isEmpty() || groups.size > 16) return null
        val itemLists = groups.map { group ->
            if (group == null || !groupItems.declaringClass.isInstance(group)) return null
            @Suppress("UNCHECKED_CAST")
            (groupItems.invoke(group) as? List<Any>) ?: return null
        }
        if (itemLists.any { list -> list.any(injector::isOurs) }) return null
        val allItems = itemLists.flatten()
        if (allItems.size > 64 || !injector.accepts(allItems)) return null
        val callbacks = allItems.mapNotNull { itemClick.invoke(it) }
        val card = FeedbackCardGraph.findUnique(callbacks, cardMatches) ?: run {
            onSkip("missing-current-card")
            return null
        }
        val extra = entries(card)
        if (extra.isEmpty()) {
            onSkip("missing-tag-metadata")
            return null
        }
        val targetIndex = itemLists.indexOfLast { it.isNotEmpty() }
        if (targetIndex < 0) return null
        val target = groups[targetIndex]
        val copied = groupCopy.invoke(target, groupStyle.invoke(target), groupTitle.invoke(target),
            itemLists[targetIndex] + extra) ?: return null
        val result = groups.toMutableList().also { it[targetIndex] = copied }
        original = WeakReference(groups)
        replacement = WeakReference(result)
        return result
    }

    companion object {
        private const val MODEL = "kntr.app.pegasus.feedbackdialog.model."
        private const val CONTENT = "kntr.app.pegasus.feedbackdialog.FeedbackDialogKt"
        private const val HOME_CARD = "com.bilibili.pegasus.data.base.BasePegasusData"

        fun install(
            environment: HookEnvironment,
            home: VersionAdapter.HomeRecommendFeedPoints?,
            related: VersionAdapter.VideoRelatePoints?
        ): FeatureInstallResult = runCatching {
            val loader = environment.classLoader
            fun owner(name: String) = checkNotNull(KavaMemberLookup.classOrNull(loader, name)) { name }
            fun getter(type: Class<*>, name: String): Method? = KavaMemberLookup.methods(
                type, includeSuperclasses = true, makeAccessible = true
            ) { it.name == name && it.parameterCount == 0 && !Modifier.isStatic(it.modifiers) }
                .distinctBy(Method::toGenericString).singleOrNull()
            val content = KavaMemberLookup.declaredMethods(owner(CONTENT), makeAccessible = true) {
                it.name == "BottomSheetContent" && Modifier.isStatic(it.modifiers) &&
                    it.returnType == Void.TYPE &&
                    FeedbackContentSignature.changedIndex(it.parameterTypes.map(Class<*>::getName)) != null
            }.single()
            val changedIndex = checkNotNull(FeedbackContentSignature.changedIndex(content.parameterTypes.map(Class<*>::getName)))
            val item = owner(MODEL + "FeedbackItem")
            val ctor = KavaMemberLookup.declaredConstructors(item) {
                it.parameterTypes.none { type -> type.name == "kotlin.jvm.internal.DefaultConstructorMarker" }
            }.maxByOrNull { it.parameterCount } ?: error("item-constructor")
            val typeGetter = checkNotNull(getter(item, "getType"))
            val clickGetter = checkNotNull(getter(item, "getOnClick"))
            val injector = FeedbackPanelInjector(ctor, checkNotNull(getter(item, "getTitle")),
                typeGetter, clickGetter, item, owner("kotlin.jvm.functions.Function1"),
                checkNotNull(FeedbackPanelInjector.defaultTypeOf(typeGetter.returnType)))
            check(injector.isUsable) { "item-calibration" }
            val group = owner(MODEL + "Feedback")
            val itemsGetter = checkNotNull(getter(group, "getItems"))
            val styleGetter = checkNotNull(getter(group, "getStyle"))
            val titleGetter = checkNotNull(getter(group, "getTitle"))
            val copy = KavaMemberLookup.declaredMethods(group, makeAccessible = true) {
                it.name == "copy" && !Modifier.isStatic(it.modifiers) && it.returnType == group &&
                    it.parameterTypes.contentEquals(arrayOf(styleGetter.returnType, String::class.java, List::class.java))
            }.single()

            val homeCard = KavaMemberLookup.classOrNull(loader, HOME_CARD)
            val cardArgs = home?.argsGetter?.let { point ->
                environment.hookPoints.resolveAdapted("feedback.home.args", point.className,
                    point.methodName, point.paramClassNames)
            } ?: homeCard?.let { getter(it, "getArgs") }
            val tid = cardArgs?.returnType?.let { getter(it, "getTid") }
            val tname = cardArgs?.returnType?.let { getter(it, "getTname") }
            val up = cardArgs?.returnType?.let { getter(it, "getUpName") }
            val mid = cardArgs?.returnType?.let { getter(it, "getUpId") }
            val detail = related?.detailRelateService?.componentFactory?.let { point ->
                environment.hookPoints.resolveAdapted("feedback.detail.factory", point.className,
                    point.methodName, point.paramClassNames)?.parameterTypes
                    ?.mapNotNull(RelatedFeedbackTags::resolve)?.singleOrNull()
            }
            val homeReady = homeCard != null && cardArgs != null && tid != null
            check(homeReady || detail != null) { "missing-card-readers" }
            val publisher = ScanSnapshotPublisher(environment,
                MineComponentSnapshotCodec.SURFACE_SECTION_PICKS, setOf("home_recommend_tid_block"))
            val authors = ScanSnapshotPublisher(environment,
                MineComponentSnapshotCodec.SURFACE_AUTHOR_PICKS, setOf("home_recommend_author_block"))
            /**
             * 点过之后给一次即时回执。
             *
             * 宿主对我们注入的这一行只会关掉面板：它既不弹自己的 toast（那是不感兴趣流程
             * 里发请求之后才有的），也不会撤掉当前这张卡（过滤只作用于之后加载的推荐）。
             * 没有这一条，用户看到的就是"点了什么都没发生"。
             *
             * Application 在 `attach.before` 还没建好，所以在点击时才取，不在安装期缓存。
             */
            fun announce(name: String) {
                val context = ReflectAccess.currentApplication() ?: return
                VersionAdapter.showAdaptToast(context,
                    String.format(InjectedUiLocale.messages().panelBlockRecordedToast, name))
            }
            fun picked(tag: FeedbackTag) {
                val added = SectionPickSession.add(tag.id)
                if (!added && !SectionPickSession.contains(tag.id)) return
                publisher.accumulate(MineComponentScanEntry(SectionPickPolicy.snapshotKey(tag.id),
                    SectionPickPolicy.SNAPSHOT_KIND, tag.name, tag.id.toString(), null, true,
                    selectionToken = java.util.UUID.randomUUID().toString()))
                announce(tag.name)
                if (!added) return
                environment.reportRuntimeEvidence(SectionPickFeatureInstaller.ID, FeatureRuntimeStage.APPLIED)
                environment.logInfo("section_pick_hit:${tag.id}", "[BIL] 已选择标签 id=${tag.id}，本次会话生效，长期保存需在模块中确认")
            }
            val panel = NativeFeedbackPanel(injector, itemsGetter, styleGetter, titleGetter, copy,
                clickGetter, { card ->
                    homeReady && homeCard!!.isInstance(card) || detail?.cardClass?.isInstance(card) == true
                }, { card ->
                    val messages = InjectedUiLocale.messages()
                    val data = if (homeReady && homeCard!!.isInstance(card)) cardArgs!!.invoke(card) else null
                    val tags = if (data != null) {
                        val id = (tid!!.invoke(data) as? Number)?.toLong() ?: 0L
                        val name = tname?.invoke(data) as? String
                        if (id > 0) listOf(FeedbackTag(id, name?.takeIf(String::isNotBlank) ?: id.toString()))
                        else emptyList()
                    } else detail?.read(card).orEmpty()
                    buildList {
                        tags.forEach { tag ->
                            injector.newEntry(String.format(messages.panelBlockTagLabel, tag.name)) { picked(tag) }
                                ?.let(::add)
                        }
                        val upName = data?.let { up?.invoke(it) as? String }?.takeIf(String::isNotBlank)
                        if (upName != null) {
                            val upId = (mid?.invoke(data) as? Number)?.toLong()?.takeIf { it > 0 }
                            injector.newEntry(String.format(messages.panelBlockAuthorLabel, upName)) {
                                if (AuthorPickSession.add(upName)) {
                                    authors.accumulate(MineComponentScanEntry.create("author", upName, upName, null, true)
                                        ?.copy(selectionToken = java.util.UUID.randomUUID().toString()))
                                }
                                // 重复点同一个 UP 也回执：用户看到的应当是"这次点击被收到了"。
                                announce(upName)
                            }?.let(::add)
                        }
                    }
                }, { reason ->
                    environment.logInfo("section_pick_panel_skip:$reason", "[BIL] 原生面板本次不追加模块选项: $reason")
                })
            environment.registrar.exact("feedback.native.content", content.declaringClass,
                content.name, *content.parameterTypes) {
                before {
                    val groups = args[0] as? List<*> ?: return@before
                    runCatching { panel.merge(groups) }.onSuccess { merged ->
                        if (merged != null) {
                            args[0] = merged
                            // 第一个参数被替换，清掉调用方针对原列表预计算的 Compose changed 位。
                            args[changedIndex] = (args[changedIndex] as Int) and 0b1110.inv()
                            environment.reportRuntimeEvidence(SectionPickFeatureInstaller.ID, FeatureRuntimeStage.OBSERVED)
                        }
                    }.onFailure {
                        environment.logError("section_pick_inject_error", "[BIL] 面板注入失败，本次保留原面板: ${it.javaClass.simpleName}")
                    }
                }
            }
            val legacyReady = LegacyFeedbackPanel.install(environment, panel)
            val complete = homeReady && detail != null && legacyReady
            environment.reportStatus("section_pick_status", if (complete) "success" else "partial:card-reader")
            environment.logInfo("section_pick_installed", "[BIL] 原生面板注入已注册，home=$homeReady, related=${detail != null}, legacy=$legacyReady")
            FeatureInstallResult.Installed(if (legacyReady) 2 else 1, complete = complete)
        }.getOrElse {
            environment.reportStatus("section_pick_status", "missing-panel-structure")
            environment.logError("section_pick_missing", "[BIL] 原生面板注入不可用: ${it.message}")
            FeatureInstallResult.Skipped("missing-panel-structure")
        }
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.ReflectAccess

/** 暂停页广告 P1 请求层 + P2 面板层 + P3 倒计时层安装器。 */
internal class PausedAdFeatureInstaller(
    private val enabled: Boolean,
    private val points: VersionAdapter.PausePoints?
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }

        var hookCount = 0
        var primaryCount = 0
        points?.requestMethods.orEmpty().forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("paused.request.$index", point) {
                    before { result = null }
                }
                primaryCount++
                hookCount++
                environment.logInfo(
                    "paused_request_$index",
                    "[BIL] 已注册暂停页请求拦截 ${point.className}#${point.methodName}"
                )
            }.onFailure { throwable ->
                environment.logInfo(
                    "paused_request_${index}_err",
                    "[BIL] 暂停页请求入口注册失败: $throwable"
                )
            }
        }

        points?.legacyCallback?.let { point ->
            runCatching {
                environment.registrar.adapted("paused.legacy_callback", point) {
                    before { result = null }
                }
                primaryCount++
                hookCount++
                environment.logInfo("paused_legacy", "[BIL] 已注册旧版暂停页 Function0 拦截")
            }.onFailure { throwable ->
                environment.logInfo(
                    "paused_legacy_err",
                    "[BIL] 旧版暂停页入口注册失败: $throwable"
                )
            }
        }

        if (points == null) {
            listOf(REQUEST_CLASS_V2, REQUEST_CLASS_V3).forEachIndexed { index, className ->
                if (KavaMemberLookup.classOrNull(environment.classLoader, className) != null) {
                    runCatching {
                        environment.registrar.first(
                            "paused.request_fallback.$index",
                            className,
                            INVOKE_SUSPEND
                        ) { before { result = null } }
                        primaryCount++
                        hookCount++
                        environment.logInfo(
                            "paused_fallback_$index",
                            "[BIL] 已注册暂停页请求兜底 $className"
                        )
                    }
                }
            }
        }

        var panelRegistered = false
        runCatching {
            val panelPoint = points?.panelShow
            if (panelPoint != null) {
                environment.registrar.adapted("paused.panel_show", panelPoint) {
                    after {
                        val data = args.firstOrNull {
                            it?.javaClass?.name?.contains(PANEL_DATA_NAME) == true
                        }
                        if (data != null) {
                            runCatching { ReflectAccess.callMethod(instance, "dismissPanel") }
                                .onSuccess {
                                    environment.logInfo(
                                        "paused_p2_dismiss",
                                        "[BIL] 已丢弃暂停页广告面板（P2 兜底）"
                                    )
                                }
                        }
                    }
                }
            } else {
                environment.registrar.all(
                    "paused.panel_show_fallback",
                    PANEL_REPOSITORY_CLASS,
                    "showPanel"
                ) {
                    after {
                        val data = args.firstOrNull {
                            it?.javaClass?.name?.contains(PANEL_DATA_NAME) == true
                        }
                        if (data != null) runCatching {
                            ReflectAccess.callMethod(instance, "dismissPanel")
                        }
                    }
                }
            }
            panelRegistered = true
            hookCount++
            environment.logInfo(
                "paused_p2",
                "[BIL] 已注册暂停页广告面板拦截兜底（AdPanelRepository.showPanel）"
            )
        }.onFailure { throwable ->
            environment.logInfo(
                "paused_p2_reg_err",
                "[BIL] 暂停页广告 P2 兜底注册失败: $throwable"
            )
        }

        runCatching {
            val countdownPoint = points?.countdown
            if (countdownPoint != null) {
                environment.registrar.adapted("paused.countdown", countdownPoint) {
                    before { result = null }
                }
            } else {
                environment.registrar.first(
                    "paused.countdown_fallback",
                    COUNTDOWN_CLASS,
                    INVOKE_SUSPEND
                ) { before { result = null } }
            }
            hookCount++
            environment.logInfo("paused_p3", "[BIL] 已屏蔽暂停页「3 秒后展示广告」倒计时 toast")
        }.onFailure { throwable ->
            environment.logInfo(
                "paused_p3_reg_err",
                "[BIL] 暂停页倒计时 toast 屏蔽注册失败: $throwable"
            )
        }

        // P4：协议响应层。与 P1/P2/P3 互不知情——它们全是"按宿主实现定位"
        // （混淆类名一漂移就落空），这一层打在未混淆的 protobuf 生成类上。
        if (installResponseLayer(environment)) hookCount++

        environment.reportStatus(
            CHANNEL_STATUS,
            if (primaryCount > 0 || panelRegistered) "success" else "failed"
        )
        return if (hookCount > 0) {
            FeatureInstallResult.Installed(hookCount)
        } else {
            FeatureInstallResult.Skipped("no_hook_point")
        }
    }

    /**
     * P4：在 `ViewMoss#executePlayPause` 的响应上清掉广告载荷。
     *
     * `PlayPauseReply` 是 oneof（`dataCase_` + `data_`）承载 `ads_`，
     * 而**暂停进度条 `bar_` 是独立声明字段**——25 版逐版核对确认，
     * 所以 `clearAds()` 在结构上就碰不到进度条，不存在"顺手删掉正常功能"的风险。
     *
     * 定位面只有两个未混淆的 protobuf 类名，不依赖任何混淆实现类，
     * 这是它比 P1/P2/P3 稳的原因。
     *
     * ⚠️ `PlayPauseReply` **从 8.91.0 才有**（8.84.0–8.89.0 那 5 版没有），
     * 缺失时哨兵降级记 info 不记 error，P1/P2/P3 照常工作。
     */
    private fun installResponseLayer(environment: HookEnvironment): Boolean {
        val loader = environment.classLoader ?: return false
        val reply = KavaMemberLookup.classOrNull(loader, PLAY_PAUSE_REPLY_CLASS)
        val moss = KavaMemberLookup.classOrNull(loader, VIEW_MOSS_CLASS)
        val request = KavaMemberLookup.classOrNull(loader, PLAY_PAUSE_REQ_CLASS)
        if (reply == null || moss == null || request == null) {
            environment.reportStatus(CHANNEL_RESPONSE, "not-applicable-host")
            environment.logInfo(
                "paused_p4_absent",
                "[BIL] 暂停页响应层不可用（本宿主无 $PLAY_PAUSE_REPLY_CLASS），仅保留 P1/P2/P3"
            )
            return false
        }
        val cleaner = PausePayloadCleaner.resolve(reply) ?: run {
            environment.reportStatus(CHANNEL_RESPONSE, "not-applicable-host")
            environment.logInfo(
                "paused_p4_shape",
                "[BIL] 暂停页响应层形状不符（缺 hasAds/clearAds），仅保留 P1/P2/P3"
            )
            return false
        }
        return runCatching {
            environment.registrar.exact(
                "paused.response.execute_play_pause",
                moss,
                EXECUTE_PLAY_PAUSE,
                request
            ) {
                after {
                    if (hasThrowable) return@after
                    val original = result ?: return@after
                    val updated = cleaner.clearAds(original, environment)
                    if (updated !== original) result = updated
                }
            }
            environment.reportStatus(CHANNEL_RESPONSE, "success")
            environment.logInfo("paused_p4", "[BIL] 已注册暂停页响应层广告清理（P4）")
            true
        }.getOrElse { throwable ->
            environment.reportStatus(CHANNEL_RESPONSE, "registration-failed")
            environment.logError(
                "paused_p4_reg_err",
                "[BIL] 暂停页响应层注册失败: $throwable"
            )
            false
        }
    }

    companion object {
        const val ID = "paused_ad"
        private const val CHANNEL_STATUS = "adskip_status"
        private const val INVOKE_SUSPEND = "invokeSuspend"
        private const val REQUEST_CLASS_V2 =
            "kntr.app.ad.biz.videodetail.pausedpage.AdPausedPageApi\$requestPausedPage\$2"
        private const val REQUEST_CLASS_V3 =
            "com.bilibili.ship.theseus.united.page.pausedpage.PausedPageService\$requestPausedPageData\$2"
        private const val PANEL_REPOSITORY_CLASS =
            "com.bilibili.ship.theseus.united.page.ad.AdPanelRepository"
        private const val COUNTDOWN_CLASS =
            "com.bilibili.ship.theseus.united.page.pausedpage.PausedPageService\$showPauseBarCountdownToast\$3"
        private const val PANEL_DATA_NAME = "AdPausedPagePanelData"

        /** P4 用的通道与锚点。全是未混淆的 protobuf 生成类。 */
        private const val CHANNEL_RESPONSE = "adskip_response_status"
        private const val VIEW_MOSS_CLASS = "com.bapis.bilibili.app.viewunite.v1.ViewMoss"
        private const val PLAY_PAUSE_REQ_CLASS =
            "com.bapis.bilibili.app.viewunite.v1.PlayPauseReq"
        private const val PLAY_PAUSE_REPLY_CLASS =
            "com.bapis.bilibili.app.viewunite.v1.PlayPauseReply"
        private const val EXECUTE_PLAY_PAUSE = "executePlayPause"
        internal const val HAS_ADS = "hasAds"
        internal const val CLEAR_ADS = "clearAds"

        /** 暂停进度条：正常功能，**绝不能动**。留常量是为了让测试能钉住"没碰它"。 */
        internal const val PAUSE_BAR_PRESENCE = "hasBar"
    }
}

/**
 * 只清 `PlayPauseReply.ads`，一个字段都不多动。
 *
 * 安装期解析全部反射；无广告载荷时返回原实例（不分配），异常交付原响应。
 */
internal class PausePayloadCleaner private constructor(
    private val reply: Class<*>,
    private val plan: ProtobufBuilderPlan,
    private val hasAds: java.lang.reflect.Method,
    private val clearAds: java.lang.reflect.Method,
    private val defaultInstance: Any?
) {

    fun clearAds(original: Any, environment: HookEnvironment): Any = runCatching {
        if (!reply.isInstance(original)) return@runCatching original
        if (defaultInstance != null && original === defaultInstance) return@runCatching original
        if (hasAds.invoke(original) as? Boolean != true) return@runCatching original
        environment.reportRuntimeEvidence(
            PausedAdFeatureInstaller.ID, FeatureRuntimeStage.OBSERVED
        )
        val updated = plan.edit(original) { target -> clearAds.invoke(target) }
        // 回读确认：clear* 对空字段静默成功，不回读就没有"真的清掉了"的证据。
        check(hasAds.invoke(updated) as? Boolean != true) { "Pause ads clear readback failed" }
        environment.reportRuntimeEvidence(
            PausedAdFeatureInstaller.ID, FeatureRuntimeStage.APPLIED
        )
        updated
    }.getOrElse {
        environment.reportRuntimeEvidence(
            PausedAdFeatureInstaller.ID, FeatureRuntimeStage.ERROR
        )
        environment.logError(
            "paused_p4_clean_err",
            "[BIL] 暂停页响应层清理失败，保留原响应: $it"
        )
        original
    }

    companion object {
        fun resolve(reply: Class<*>): PausePayloadCleaner? = runCatching {
            val plan = ProtobufBuilderPlan.resolve(reply) ?: return null
            val hasAds = KavaMemberLookup.methodOrNull(reply, PausedAdFeatureInstaller.HAS_ADS)
                ?.takeIf { it.returnType == java.lang.Boolean.TYPE } ?: return null
            val clearAds = plan.method(PausedAdFeatureInstaller.CLEAR_ADS) ?: return null
            val defaultInstance = runCatching {
                KavaMemberLookup.methodOrNull(reply, "getDefaultInstance")?.invoke(null)
            }.getOrNull()
            PausePayloadCleaner(reply, plan, hasAds, clearAds, defaultInstance)
        }.getOrNull()
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.hook.adapter.PgcAutoActivityPopupLocator
import java.util.concurrent.atomic.AtomicBoolean

/** 影视页运营半屏的独立安装单元；不接管播放器、支付或通用 Web 浮层。 */
internal class PgcAutoActivityPopupFeatureInstaller(
    private val enabled: Boolean,
    private val points: VersionAdapter.PgcAutoActivityPopupPoints?
) : FeatureInstaller {
    override val id = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != "tv.danmaku.bili") {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = points ?: return missing(environment, "missing-adapter-point")
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val runtime = PgcAutoActivityPopupLocator.resolveRuntime(loader, adapted)
            ?: return missing(environment, "missing-verified-nullable-structure")
        val shapeFailure = AtomicBoolean(false)
        val typeFailure = AtomicBoolean(false)
        val resultFailure = AtomicBoolean(false)
        val observed = AtomicBoolean(false)
        val applied = AtomicBoolean(false)

        fun reportOnce(flag: AtomicBoolean, reason: String) {
            if (flag.compareAndSet(false, true)) {
                runCatching {
                    environment.logError("pgc_auto_activity_$reason", "[BIL] 影视活动半屏过滤: $reason")
                }
            }
        }
        fun evidenceOnce(flag: AtomicBoolean, stage: FeatureRuntimeStage) {
            if (flag.compareAndSet(false, true)) {
                runCatching { environment.reportRuntimeEvidence(ID, stage) }
            }
        }

        return runCatching {
            environment.registrar.adapted("pgc.auto_activity.construct", adapted.construct) {
                before {
                    val decision = PgcAutoActivityPopupPolicy.filter(
                        args.singleOrNull(), runtime.parameterCount, runtime.popupIndex,
                        runtime.popupType
                    )
                    when (decision) {
                        PgcAutoActivityPopupPolicy.Decision.Absent -> Unit
                        PgcAutoActivityPopupPolicy.Decision.InvalidShape ->
                            reportOnce(shapeFailure, "argument-shape")
                        PgcAutoActivityPopupPolicy.Decision.UnexpectedType ->
                            reportOnce(typeFailure, "popup-type")
                        is PgcAutoActivityPopupPolicy.Decision.Filtered -> {
                            args[0] = decision.values
                            setObjectExtra(FILTERED_EXTRA, true)
                            evidenceOnce(observed, FeatureRuntimeStage.OBSERVED)
                        }
                    }
                }
                after {
                    if (getObjectExtra(FILTERED_EXTRA) != true) return@after
                    // 原方法成功且实际模型已没有半屏才计入 APPLIED，不能拿改参数当效果证明。
                    val removed = !hasThrowable && runCatching {
                        runtime.modelType.isInstance(result) && runtime.popupField.get(result) == null
                    }.getOrDefault(false)
                    if (removed) evidenceOnce(applied, FeatureRuntimeStage.APPLIED)
                    else reportOnce(resultFailure, "construction-unconfirmed")
                }
            }
            environment.reportStatus(CHANNEL_STATUS, "success")
            environment.logInfo("pgc_auto_activity_ready", "[BIL] 影视页自动活动半屏过滤已注册")
            FeatureInstallResult.Installed(1)
        }.getOrElse { missing(environment, "registration-failed") }
    }

    private fun missing(environment: HookEnvironment, reason: String): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("pgc_auto_activity_missing", "[BIL] 影视活动半屏适配未就绪: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "pgc_auto_activity_popup"
        private const val CHANNEL_STATUS = "pgc_auto_activity_popup_status"
        private const val FILTERED_EXTRA = "pgc_auto_activity_filtered"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.adapter.PlayerCapabilityAccess
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic

/** 同步/异步播放响应只调整已选客户端能力；不创建播放地址、不更改服务器权限。 */
internal class PlayerCapabilityFeatureInstaller(private val options: PlayerCapabilityOptions) : FeatureInstaller {
    override val id = ID
    override val capabilityIds: List<String> get() = buildList {
        if (options.background) add("player_capability_background")
        if (options.smallWindow) add("player_capability_small_window")
        if (options.cast) add("player_capability_cast")
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (options.enabled.isEmpty()) {
            environment.reportStatus(CHANNEL, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) return FeatureInstallResult.Skipped("non-main-process")
        val loader = environment.classLoader ?: return FeatureInstallResult.Skipped("missing-class-loader")
        val handler = KavaMemberLookup.classOrNull(loader, MOSS_HANDLER)?.takeIf { it.isInterface }
        // 每个已选能力的两族同步/异步边界，以及小窗的两个菜单构造槽位。
        val expected = options.enabled.size * FAMILIES.size * 2 + if (options.smallWindow) 2 else 0
        var covered = 0
        var hooks = 0
        val coverage = options.enabled.associateWith { 0 }.toMutableMap()
        val observed: (PlayerCapability) -> Unit = {
            environment.reportRuntimeEvidence(capabilityId(it), FeatureRuntimeStage.OBSERVED)
        }
        val applied: (PlayerCapability) -> Unit = {
            environment.reportRuntimeEvidence(capabilityId(it), FeatureRuntimeStage.APPLIED)
        }
        for (family in FAMILIES) {
            val access = PlayerCapabilityAccess.resolve(loader, family.reply, family.shared, options.enabled)
            val owner = KavaMemberLookup.classOrNull(loader, family.moss)
            val request = KavaMemberLookup.classOrNull(loader, family.request)
            if (access == null || owner == null || request == null) {
                environment.logError("player_capability_missing_${family.id}",
                    "[BIL] 播放器能力缺少响应结构(${family.id})，保留该链路原行为")
                continue
            }
            fun apply(reply: Any) {
                if (!access.replyClass.isInstance(reply)) return
                environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                runCatching { access.apply(reply, observed, applied) }.onSuccess { changed ->
                    if (changed > 0) environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED, changed)
                }.onFailure {
                    environment.logError("player_capability_runtime_${family.id}",
                        "[BIL] 播放器能力改写失败(${family.id}): ${it.javaClass.simpleName}")
                }
            }
            val sync = listOf("execute${family.method.replaceFirstChar(Char::uppercaseChar)}", family.method)
                .firstNotNullOfOrNull { name ->
                    KavaMemberLookup.methodOrNull(owner, name, request)?.takeIf {
                        !it.isStatic && it.returnType == access.replyClass
                    }
                }
            if (sync != null && runCatching {
                    environment.registrar.exact("player.capability.${family.id}.sync", owner,
                        sync.name, *sync.parameterTypes) {
                        after { if (!hasThrowable) result?.let(::apply) }
                    }
                }.isSuccess) {
                hooks++
                covered += access.capabilityCount
                access.capabilities.forEach { coverage[it] = coverage.getValue(it) + 1 }
            }
            val async = handler?.let {
                KavaMemberLookup.methodOrNull(owner, family.method, request, it)?.takeIf { method ->
                    !method.isStatic && method.returnType == Void.TYPE
                }
            }
            if (async != null && runCatching {
                    environment.registrar.exact("player.capability.${family.id}.async", owner,
                        async.name, *async.parameterTypes) {
                        before {
                            val delegate = argOrNull(1) ?: return@before
                            val wrapped = MossResponseHandlerProxy.wrap(handler, delegate, ::apply) ?: return@before
                            args[1] = wrapped
                        }
                    }
                }.isSuccess) {
                hooks++
                covered += access.capabilityCount
                access.capabilities.forEach { coverage[it] = coverage.getValue(it) + 1 }
            }
        }
        if (options.smallWindow) {
            val owner = KavaMemberLookup.classOrNull(loader, MINI_MENU)
            val type = KavaMemberLookup.classOrNull(loader, MINI_TYPE)
            val mini = type?.let { KavaMemberLookup.fieldOrNull(it, "MINIPLAYER") }
                ?.takeIf { it.isStatic && it.type == type }
                ?.let { runCatching { it.get(null) }.getOrNull() }
            if (owner != null && type != null && mini != null) {
                val signatures = listOf(
                    arrayOf(classOf<Boolean>(), type), arrayOf(classOf<Boolean>(), type, classOf<List<*>>())
                )
                signatures.forEachIndexed { index, parameters ->
                    val constructor = KavaMemberLookup.constructorOrNull(owner, *parameters)
                        ?: return@forEachIndexed
                    if (runCatching {
                            environment.registrar.constructor("player.capability.mini.$index", constructor) {
                                before {
                                    if (argOrNull(1) !== mini) return@before
                                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                                    if (argOrNull(0) == false) args[0] = true
                                    // 构造参数写入不是模型读回证据；APPLIED 只由上面的响应验证记录。
                                }
                            }
                        }.isSuccess) {
                        hooks++
                        covered++
                        coverage[PlayerCapability.SMALL_WINDOW] = coverage.getValue(PlayerCapability.SMALL_WINDOW) + 1
                    }
                }
            }
        }
        for (capability in options.enabled) {
            environment.reportCapabilityCoverage(capabilityId(capability), true, coverage.getValue(capability),
                FAMILIES.size * 2 + if (capability == PlayerCapability.SMALL_WINDOW) 2 else 0)
        }
        val status = if (covered == expected) "success" else "partial:$covered/$expected"
        environment.reportStatus(CHANNEL, status)
        if (hooks == 0) return FeatureInstallResult.Skipped("missing-player-capability-points")
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        environment.logInfo("player_capability_installed",
            "[BIL] 播放器客户端能力已安装($status, hooks=$hooks)，仅含 ${options.enabled.joinToString { it.name }}")
        return FeatureInstallResult.Installed(hooks, complete = covered == expected)
    }

    private data class Family(val id: String, val moss: String, val request: String,
        val reply: String, val method: String, val shared: Boolean)

    companion object {
        private fun capabilityId(capability: PlayerCapability): String = when (capability) {
            PlayerCapability.BACKGROUND -> "player_capability_background"
            PlayerCapability.SMALL_WINDOW -> "player_capability_small_window"
            PlayerCapability.CAST -> "player_capability_cast"
        }
        const val ID = "player_capabilities"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL = "player_capabilities_status"
        private const val MOSS_HANDLER = "com.bilibili.lib.moss.api.MossResponseHandler"
        private const val MINI_MENU = "com.bilibili.lib.media.resource.PlayConfig\$PlayMenuConfig"
        private const val MINI_TYPE = "com.bilibili.lib.media.resource.PlayConfig\$PlayConfigType"
        private val FAMILIES = listOf(
            Family("unite", "com.bapis.bilibili.app.playerunite.v1.PlayerMoss",
                "com.bapis.bilibili.app.playerunite.v1.PlayViewUniteReq",
                "com.bapis.bilibili.app.playerunite.v1.PlayViewUniteReply", "playViewUnite", true),
            Family("legacy", "com.bapis.bilibili.app.playurl.v1.PlayURLMoss",
                "com.bapis.bilibili.app.playurl.v1.PlayViewReq",
                "com.bapis.bilibili.app.playurl.v1.PlayViewReply", "playView", false)
        )
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.os.Bundle
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import java.lang.reflect.Method
import java.lang.reflect.Modifier

/**
 * 播放器编码偏好与硬/软解覆盖。请求改写和 ijk option 改写均为 copy-on-write/原地键覆盖，
 * 不做 DEX 扫描、I/O、IPC 或逐帧 Hook；所有定位失败都只影响本功能。
 */
internal class PlayerCodecForceFeatureInstaller(
    codecPreferenceValue: Int,
    decodeModeValue: Int
) : FeatureInstaller {
    override val id: String = ID
    private val preference = PlayerCodecPreference.fromValue(codecPreferenceValue)
    private val decodeMode = PlayerDecodeMode.fromValue(decodeModeValue)

    /** 请求侧实际使用的偏好：AV1 × 强制软解已按硬约束降级为 H.264。 */
    private val requestPreference = PlayerCodecForcePolicy.effectivePreference(preference, decodeMode)

    /** 跟随宿主 + 强制软解：请求侧只清 AV1 能力位，这段改写属于"解码方式"一项。 */
    private val stripAv1Only = PlayerCodecForcePolicy.stripsAv1Only(preference, decodeMode)
    override val capabilityIds: List<String> = buildList {
        if (preference != PlayerCodecPreference.FOLLOW_HOST) add(CODEC_CAPABILITY)
        if (decodeMode != PlayerDecodeMode.FOLLOW_HOST) add(DECODE_CAPABILITY)
    }

    private data class InstallCoverage(val available: Int = 0, val installed: Int = 0)

    private data class RequestResolution(
        val owner: Class<*>,
        val request: Class<*>,
        val sync: Method?,
        val async: Method?
    )

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (preference == PlayerCodecPreference.FOLLOW_HOST && decodeMode == PlayerDecodeMode.FOLLOW_HOST) {
            environment.reportStatus(STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        val loader = environment.classLoader ?: run {
            capabilityIds.forEach { capability ->
                environment.reportCapability(
                    capability,
                    FeatureInstallResult.Skipped("missing-class-loader")
                )
            }
            return skipped(environment, "missing-class-loader")
        }
        if (requestPreference != preference) {
            environment.logInfo(
                "$ID.downgraded",
                "[BIL] AV1 与强制软解不可同时使用，编码偏好已降级为 H.264"
            )
        }
        val requestCapability = if (stripAv1Only) DECODE_CAPABILITY else CODEC_CAPABILITY
        val requestCoverage = if (requestPreference != PlayerCodecPreference.FOLLOW_HOST || stripAv1Only) {
            listOf(
                installRequestFamily(
                    environment, loader,
                    MOSS_CLASSES_UNITE, REQUEST_CLASSES_UNITE,
                    setOf("executePlayViewUnite", "playViewUnite", "executePlayView", "playView"),
                    nestedVod = true,
                    capability = requestCapability
                ),
                installRequestFamily(
                    environment, loader,
                    MOSS_CLASSES_LEGACY, REQUEST_CLASSES_LEGACY,
                    setOf("executePlayView", "playView"),
                    nestedVod = false,
                    capability = requestCapability
                )
            ).fold(InstallCoverage()) { total, current ->
                InstallCoverage(total.available + current.available, total.installed + current.installed)
            }
        } else InstallCoverage()
        val optionCoverage = if (decodeMode != PlayerDecodeMode.FOLLOW_HOST) {
            installDecodePaths(environment, loader)
        } else InstallCoverage()
        // 强制软解的请求侧 AV1 清位与 ijk 选项改写同属"解码方式"，一并计入它的覆盖单位。
        val decodeCoverage = if (stripAv1Only) {
            InstallCoverage(optionCoverage.available + requestCoverage.available,
                optionCoverage.installed + requestCoverage.installed)
        } else optionCoverage
        if (!stripAv1Only) reportCapabilityCoverage(environment, CODEC_CAPABILITY, requestCoverage)
        reportCapabilityCoverage(environment, DECODE_CAPABILITY, decodeCoverage)

        val installed = requestCoverage.installed + optionCoverage.installed
        val expected = requestCoverage.available + optionCoverage.available
        if (installed == 0) return skipped(environment, "missing-host-structure")
        if (requestCoverage.installed > 0 && !stripAv1Only) {
            environment.reportRuntimeEvidence(CODEC_CAPABILITY, FeatureRuntimeStage.ADAPTED)
        }
        if (decodeCoverage.installed > 0) {
            environment.reportRuntimeEvidence(DECODE_CAPABILITY, FeatureRuntimeStage.ADAPTED)
        }
        val status = if (expected > 0 && installed == expected) "success" else "partial:$installed/$expected"
        environment.reportStatus(STATUS, status)
        return FeatureInstallResult.Installed(installed, complete = expected > 0 && installed == expected)
    }

    private fun installRequestFamily(
        environment: HookEnvironment,
        loader: ClassLoader,
        mossCandidates: List<String>,
        requestCandidates: List<String>,
        methodNames: Set<String>,
        nestedVod: Boolean,
        capability: String
    ): InstallCoverage = runCatching {
        val handlerClass = KavaMemberLookup.classOrNull(loader, MOSS_HANDLER)?.takeIf { it.isInterface }
        val resolved = mossCandidates.asSequence().flatMap { mossName ->
            requestCandidates.asSequence().mapNotNull { requestName ->
                val owner = KavaMemberLookup.classOrNull(loader, mossName) ?: return@mapNotNull null
                val request = KavaMemberLookup.classOrNull(loader, requestName) ?: return@mapNotNull null
                val sync = KavaMemberLookup.methods(owner, includeSuperclasses = true, makeAccessible = true) {
                    it.name in methodNames && it.parameterTypes.contentEquals(arrayOf(request)) &&
                        !Modifier.isStatic(it.modifiers) && !it.returnType.isPrimitive
                }.singleOrNull()
                val async = handlerClass?.let { handler ->
                    KavaMemberLookup.methods(owner, includeSuperclasses = true, makeAccessible = true) {
                        it.name in methodNames &&
                            it.parameterTypes.contentEquals(arrayOf(request, handler)) &&
                            it.returnType == Void.TYPE && !Modifier.isStatic(it.modifiers)
                    }.singleOrNull()
                }
                if (sync == null && async == null) return@mapNotNull null
                RequestResolution(owner, request, sync, async)
            }
        }.firstOrNull() ?: return InstallCoverage()
        val access = RequestAccess.resolve(resolved.request, nestedVod, requestPreference)
            ?: return InstallCoverage()
        var available = 0
        var installed = 0
        resolved.sync?.let { method ->
            available++
            if (registerRequestHook(
                    environment,
                    capability,
                    "$ID.request.${resolved.request.simpleName}",
                    resolved.owner,
                    method,
                    access
                )
            ) installed++
        }
        resolved.async?.let { method ->
            available++
            if (registerRequestHook(
                    environment,
                    capability,
                    "$ID.request.${resolved.request.simpleName}.async",
                    resolved.owner,
                    method,
                    access
                )
            ) installed++
        }
        InstallCoverage(available, installed)
    }.getOrElse {
        environment.logError("$ID.request", "[BIL] 编码偏好入口解析/注册失败")
        InstallCoverage()
    }

    private fun registerRequestHook(
        environment: HookEnvironment,
        capability: String,
        hookId: String,
        owner: Class<*>,
        method: Method,
        access: RequestAccess
    ): Boolean = runCatching {
        environment.registrar.exact(hookId, owner, method.name, *method.parameterTypes) {
            before {
                val original = argOrNull(0) ?: return@before
                environment.reportRuntimeEvidence(capability, FeatureRuntimeStage.OBSERVED)
                access.rewrite(original, requestPreference)?.let { updated ->
                    args[0] = updated
                    environment.reportRuntimeEvidence(capability, FeatureRuntimeStage.APPLIED)
                }
            }
        }
    }.onFailure {
        environment.logError(hookId, "[BIL] 编码偏好入口解析/注册失败")
    }.isSuccess

    private fun installDecodePaths(environment: HookEnvironment, loader: ClassLoader): InstallCoverage {
        val owner = IJK_CLIENT_CLASSES.firstNotNullOfOrNull { KavaMemberLookup.classOrNull(loader, it) }
            ?: return InstallCoverage()
        var available = 0
        var installed = 0
        val bundleMethod = KavaMemberLookup.methods(owner, includeSuperclasses = true, makeAccessible = true) {
            it.name == "setOptionBundle" && it.parameterTypes.contentEquals(
                arrayOf(Int::class.javaPrimitiveType, Bundle::class.java)
            ) && !Modifier.isStatic(it.modifiers)
        }.singleOrNull()
        if (bundleMethod != null) {
            available++
            if (runCatching {
                    environment.registrar.exact("$ID.bundle", owner, bundleMethod.name, *bundleMethod.parameterTypes) {
                        before {
                            if ((argOrNull(0) as? Number)?.toInt() != 4) return@before
                            val bundle = argOrNull(1) as? Bundle ?: return@before
                            if (!PlayerCodecForcePolicy.OPTION_KEYS.any(bundle::containsKey)) return@before
                            environment.reportRuntimeEvidence(DECODE_CAPABILITY, FeatureRuntimeStage.OBSERVED)
                            val rewrite = PlayerCodecForcePolicy.rewriteBundle(bundle, decodeMode)
                                ?: return@before
                            args[1] = rewrite.bundle
                            environment.reportRuntimeEvidence(
                                DECODE_CAPABILITY,
                                FeatureRuntimeStage.APPLIED,
                                rewrite.changed
                            )
                        }
                    }
                }.isSuccess) installed++
        }

        val optionMethods = KavaMemberLookup.declaredMethods(owner, makeAccessible = true) {
            it.name == "_setOption" && it.parameterCount == 3 && !Modifier.isStatic(it.modifiers) &&
                it.parameterTypes[0] == Int::class.javaPrimitiveType &&
                it.parameterTypes[1] == String::class.java &&
                (it.parameterTypes[2] == Long::class.javaPrimitiveType || it.parameterTypes[2] == String::class.java)
        }.distinctBy(Method::toGenericString)
        optionMethods.forEachIndexed { index, method ->
            available++
            if (runCatching {
                    environment.registrar.exact("$ID.option.$index", owner, method.name, *method.parameterTypes) {
                        before {
                            if ((argOrNull(0) as? Number)?.toInt() != 4) return@before
                            val key = argOrNull(1) as? String ?: return@before
                            val target = PlayerCodecForcePolicy.optionValue(key, decodeMode) ?: return@before
                            val current = argOrNull(2)
                            environment.reportRuntimeEvidence(DECODE_CAPABILITY, FeatureRuntimeStage.OBSERVED)
                            val currentValue = PlayerCodecForcePolicy.recognizedOptionValue(key, current)
                                ?: return@before
                            if (currentValue == target) return@before
                            when (current) {
                                is Long -> args[2] = target
                                is String -> args[2] = target.toString()
                                else -> return@before
                            }
                            environment.reportRuntimeEvidence(DECODE_CAPABILITY, FeatureRuntimeStage.APPLIED)
                        }
                    }
                }.isSuccess) installed++
        }
        return InstallCoverage(available, installed)
    }

    private fun reportCapabilityCoverage(
        environment: HookEnvironment,
        capability: String,
        coverage: InstallCoverage
    ) {
        if (capability !in capabilityIds) return
        val result = when {
            coverage.available <= 0 -> FeatureInstallResult.Skipped("missing-host-structure")
            coverage.installed <= 0 -> FeatureInstallResult.Skipped("registration-failed")
            else -> FeatureInstallResult.Installed(
                coverage.installed,
                complete = coverage.installed == coverage.available
            )
        }
        environment.reportCapability(capability, result)
    }

    private fun skipped(environment: HookEnvironment, reason: String): FeatureInstallResult.Skipped {
        environment.reportStatus(STATUS, reason)
        return FeatureInstallResult.Skipped(reason)
    }

    private data class RequestAccess(
        val requestPlan: ProtobufBuilderPlan,
        val targetGetter: Method?,
        val targetSetter: Method?,
        val targetPlan: ProtobufBuilderPlan,
        val preferGetter: Method,
        val preferSetter: Method,
        val fnvalGetter: Method,
        val fnvalSetter: Method,
        /** null = 跟随宿主编码，只清 AV1 能力位（强制软解的硬约束）。 */
        val preferredCode: Any?
    ) {
        fun rewrite(original: Any, preference: PlayerCodecPreference): Any? = runCatching {
            val targetValue = targetGetter?.invoke(original) ?: original
            val fnval = (fnvalGetter.invoke(targetValue) as? Number)?.toLong() ?: return null
            val expectedFnval = if (preferredCode == null) {
                PlayerCodecForcePolicy.withoutAv1(fnval)
            } else {
                PlayerCodecForcePolicy.expectedFnval(fnval, preference) ?: return null
            }
            val currentCode = preferGetter.invoke(targetValue)
            if ((preferredCode == null || currentCode == preferredCode) && fnval == expectedFnval) return null
            val updatedTarget = targetPlan.edit(targetValue) { builder ->
                if (preferredCode != null) preferSetter.invoke(builder, preferredCode)
                fnvalSetter.invoke(builder, adaptNumber(expectedFnval, fnvalSetter.parameterTypes[0]))
            }
            if (targetSetter == null) updatedTarget else requestPlan.edit(original) { builder ->
                targetSetter.invoke(builder, updatedTarget)
            }
        }.getOrNull()

        companion object {
            fun resolve(
                request: Class<*>,
                nestedVod: Boolean,
                preference: PlayerCodecPreference
            ): RequestAccess? = runCatching {
                val requestPlan = ProtobufBuilderPlan.resolve(request) ?: return null
                val targetGetter = if (nestedVod) request.methods.firstOrNull { method ->
                    method.name == "getVod" && method.parameterCount == 0 && !Modifier.isStatic(method.modifiers) &&
                        !method.returnType.isPrimitive
                } else null
                val target = targetGetter?.returnType ?: request
                val targetPlan = ProtobufBuilderPlan.resolve(target) ?: return null
                val preferGetter = target.methods.firstOrNull { method ->
                    method.name == "getPreferCodecType" && method.parameterCount == 0 &&
                        !Modifier.isStatic(method.modifiers)
                }
                val codeType = preferGetter?.returnType ?: return null
                val preferSetter = targetPlan.method("setPreferCodecType", codeType) ?: return null
                // 跟随宿主时不改偏好（只清 AV1 位）；其余偏好必须能解析出宿主枚举值。
                val preferredCode = if (preference == PlayerCodecPreference.FOLLOW_HOST) {
                    null
                } else {
                    codeValue(codeType, preference) ?: return null
                }
                val fnvalGetter = target.methods.firstOrNull { method ->
                    method.name == "getFnval" && method.parameterCount == 0 &&
                        Number::class.java.isAssignableFrom(box(method.returnType))
                } ?: return null
                val fnvalSetter = targetPlan.method("setFnval", fnvalGetter.returnType) ?: return null
                val targetSetter = targetGetter?.let { getter ->
                    requestPlan.method("setVod", getter.returnType)
                }
                if (nestedVod && targetSetter == null) return null
                RequestAccess(requestPlan, targetGetter, targetSetter, targetPlan,
                    preferGetter, preferSetter, fnvalGetter, fnvalSetter, preferredCode)
            }.getOrNull()

            private fun box(type: Class<*>): Class<*> = when (type) {
                Long::class.javaPrimitiveType -> Long::class.javaObjectType
                Int::class.javaPrimitiveType -> Int::class.javaObjectType
                else -> type
            }
        }
    }

    companion object {
        const val ID = "player_codec_force"
        private const val CODEC_CAPABILITY = "player_codec_preference"
        private const val DECODE_CAPABILITY = "player_decode_mode"
        private const val STATUS = "player_codec_force_status"
        private const val MOSS_HANDLER = "com.bilibili.lib.moss.api.MossResponseHandler"
        private val MOSS_CLASSES_UNITE = listOf(
            "com.bapis.bilibili.app.playerunite.v1.PlayerMoss",
            "com.bapis.bilibili.app.playerunite.v1.KPlayerMoss"
        )
        private val REQUEST_CLASSES_UNITE = listOf(
            "com.bapis.bilibili.app.playerunite.v1.PlayViewUniteReq",
            "com.bapis.bilibili.app.playerunite.v1.KPlayViewUniteReq"
        )
        private val MOSS_CLASSES_LEGACY = listOf(
            "com.bapis.bilibili.app.playurl.v1.PlayURLMoss",
            "com.bapis.bilibili.app.playurl.v1.KPlayURLMoss"
        )
        private val REQUEST_CLASSES_LEGACY = listOf(
            "com.bapis.bilibili.app.playurl.v1.PlayViewReq",
            "com.bapis.bilibili.app.playurl.v1.KPlayViewReq"
        )
        private val IJK_CLIENT_CLASSES = listOf(
            "tv.danmaku.ijk.media.player.services.IjkMediaPlayerItemClient"
        )

        private fun codeValue(type: Class<*>, preference: PlayerCodecPreference): Any? {
            val names = when (preference) {
                PlayerCodecPreference.H264 -> listOf("CODE264", "CODE_264")
                PlayerCodecPreference.H265 -> listOf("CODE265", "CODE_265")
                PlayerCodecPreference.AV1 -> listOf("CODEAV1", "CODE_AV1")
                PlayerCodecPreference.FOLLOW_HOST -> emptyList()
            }
            return names.firstNotNullOfOrNull { name ->
                runCatching {
                    type.getDeclaredField(name).apply { isAccessible = true }.get(null)
                        .takeIf { value -> type.isEnum && type.isInstance(value) }
                }.getOrNull()
            }
        }

        private fun adaptNumber(value: Long, target: Class<*>): Any =
            if (target == Int::class.javaPrimitiveType || target == Int::class.java) value.toInt() else value
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import java.lang.reflect.Method
import java.util.concurrent.atomic.AtomicBoolean

/** 清理结束页回复及合并后的播放器列表；getter 独立后备。任一路解析/注册失败都不会撤掉另一条防线。 */
internal class PlayerEndPageRecommendFeatureInstaller(
    private val enabled: Boolean,
    private val resolve: (ClassLoader?) -> PlayerEndPageRecommendLocator.Access? = PlayerEndPageRecommendLocator::resolve
) : FeatureInstaller {
    override val id = ID
    override val capabilityIds: List<String> get() = if (enabled) listOf(ID) else emptyList()

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        fun skipped(reason: String): FeatureInstallResult.Skipped {
            environment.reportStatus(STATUS, reason)
            val result = FeatureInstallResult.Skipped(reason)
            environment.reportCapability(ID, result)
            return result
        }
        if (!enabled) return skipped("disabled")
        if (environment.processName != "tv.danmaku.bili") return skipped("non-main-process")
        val access = resolve(environment.classLoader) ?: return skipped("missing-host-structure")
        val policy = PlayerEndPageRecommendPolicy(access)
        val errorLogged = AtomicBoolean(false)
        var installed = 0
        fun observed() = environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
        fun applied(count: Int) = environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED, count)
        fun transform(reply: Any): Any {
            if (!access.reply.isInstance(reply)) return reply
            observed()
            return runCatching { policy.clean(reply) }.fold(
                onSuccess = { cleaned -> if (cleaned != null) { applied(cleaned.removed); cleaned.reply } else reply },
                onFailure = {
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ERROR)
                    if (errorLogged.compareAndSet(false, true)) environment.logError(
                        "player_end_page_recommend_copy", "[BIL] 结束页推荐清理失败，保留原响应")
                    reply
                })
        }
        fun register(path: String, method: Method?, block: com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.ModernMemberHookCreator.() -> Unit) {
            if (method == null) return
            runCatching {
                environment.registrar.exact("$ID.$path", method.declaringClass, method.name, *method.parameterTypes, block = block)
                installed++
            }.onFailure { environment.logError("${ID}_$path", "[BIL] 结束页推荐入口注册失败") }
        }
        if (access.canCopy) {
            register("sync", access.sync) {
                after { if (!hasThrowable) result?.let { original -> result = transform(original) } }
            }
            register("async", access.async) {
                before {
                    val original = argOrNull(1) ?: return@before
                    val proxy = MossResponseHandlerProxy.wrapTransform(access.handler!!, original, ::transform) ?: return@before
                    args[1] = proxy
                }
            }
        }
        register("merged-list", access.mergedList) {
            after {
                if (hasThrowable) return@after
                val original = result as? List<*> ?: return@after
                observed()
                if (original.isNotEmpty()) {
                    result = emptyList<Any>()
                    if ((result as? List<*>)?.isEmpty() == true) applied(original.size)
                }
            }
        }
        register("list", access.list) {
            after {
                if (hasThrowable || policy.transformingResponse) return@after
                val original = result as? List<*> ?: return@after
                observed()
                if (original.isNotEmpty()) {
                    result = emptyList<Any>()
                    if ((result as? List<*>)?.isEmpty() == true) applied(original.size)
                }
            }
        }
        register("count", access.count) {
            after {
                if (hasThrowable || policy.transformingResponse) return@after
                val original = result as? Int ?: return@after
                observed()
                if (original > 0) { result = 0; if (result == 0) applied(original) }
            }
        }
        if (installed == 0) return skipped("no-safe-hook-point")
        val expected = PlayerEndPageRecommendLocator.EXPECTED_PATHS
        environment.reportCapabilityCoverage(ID, true, installed, expected)
        environment.reportStatus(STATUS, if (installed == expected) "success" else "partial:$installed/$expected")
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        return FeatureInstallResult.Installed(installed, complete = installed == expected)
    }

    companion object {
        const val ID = "player_end_page_recommend"
        private const val STATUS = "player_end_page_recommend_status"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.diagnostics.DiagnosticCapabilityCatalog
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup

/** 同步/异步响应为主路径；getter 补充缓存读取。各入口共用字段白名单和副本清理器。 */
internal class PlayerInteractiveOverlayFeatureInstaller(
    private val enabled: Boolean,
    private val points: VersionAdapter.PlayerInteractiveOverlayPoints?
) : FeatureInstaller {
    override val id = ID
    override val capabilityIds: List<String> get() =
        if (enabled) DiagnosticCapabilityCatalog.childrenOf(ID).map { it.id } else emptyList()

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) return missing(environment, "disabled")
        if (environment.processName != TARGET_PACKAGE) return FeatureInstallResult.Skipped("non-main-process")
        val adapted = points ?: return missing(environment, "missing-adapter-point")
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val cleaner = PlayerInteractiveReplyCleaner(loader, adapted)
        val primaryPaths = hashMapOf<String, Int>()
        val fallbackIds = hashSetOf<String>()
        var hooks = 0
        val owners = VersionAdapter.PLAYER_INTERACTIVE_MOSS_FAMILIES.associate {
            it.mossClassName to it.replyClassName
        } + (VersionAdapter.PLAYER_INTERACTIVE_DM_MOSS_CLASS to VersionAdapter.PLAYER_INTERACTIVE_DM_REPLY_CLASS)

        for (fallback in cleaner.fallbacks) {
            runCatching {
                environment.registrar.exact(
                    "player.interactive.fallback.${fallback.getter.declaringClass.name}.${fallback.getter.name}",
                    fallback.getter.declaringClass, fallback.getter.name
                ) {
                    after {
                        if (hasThrowable || cleaner.transformingResponse) return@after
                        val original = result ?: return@after
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        val updated = fallback.transform(original, environment)
                        if (updated !== original) result = updated
                    }
                }
                hooks++
                fallbackIds += fallback.ids
            }.onFailure {
                environment.logError("player_interactive_fallback_${fallback.getter.name}", "[BIL] 互动层 getter 后备注册失败: $it")
            }
        }
        fun installResponse(point: VersionAdapter.HookPoint, async: Boolean) {
            val replyName = owners[point.className] ?: return
            val ids = cleaner.responseIds(replyName)
            if (ids.isEmpty()) return
            val handler = if (async) KavaMemberLookup.classOrNull(loader, HANDLER_CLASS) else null
            if (async && (handler == null || point.paramClassNames.orEmpty().size != 2 ||
                    point.paramClassNames.orEmpty()[1] != HANDLER_CLASS)) return
            runCatching {
                environment.registrar.adapted(
                    "player.interactive.${if (async) "async" else "sync"}.${point.className}.${point.methodName}", point
                ) {
                    if (async) {
                        before {
                            val original = argOrNull(1) ?: return@before
                            val proxy = MossResponseHandlerProxy.wrapTransform(handler!!, original) { reply ->
                                environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                                cleaner.cleanResponse(reply, environment)
                            } ?: return@before
                            args[1] = proxy
                        }
                    } else {
                        after {
                            if (hasThrowable) return@after
                            val original = result ?: return@after
                            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                            val updated = cleaner.cleanResponse(original, environment)
                            if (updated !== original) result = updated
                        }
                    }
                }
                hooks++
                ids.forEach { primaryPaths[it] = (primaryPaths[it] ?: 0) or (if (async) 2 else 1) }
            }.onFailure {
                environment.logError("player_interactive_response_${point.className}_$async", "[BIL] 互动层响应 Hook 注册失败: $it")
            }
        }
        adapted.mossExecutes.distinct().forEach { installResponse(it, false) }
        adapted.mossAsync.distinct().forEach { installResponse(it, true) }
        // Kotlin 通道是**附加覆盖**，不计入上面的 primaryPaths / expected，免得改变既有的成功/部分判定。
        val kotlinPaths = installKotlinMoss(environment, loader, cleaner, owners, adapted)
        val absentFamilies = VersionAdapter.PLAYER_INTERACTIVE_MOSS_FAMILIES.filter {
            KavaMemberLookup.classOrNull(loader, it.replyClassName) == null &&
                KavaMemberLookup.classOrNull(loader, it.guideClassName) == null
        }.map { it.diagnosticFamilyId }
        val absentDm = KavaMemberLookup.classOrNull(loader, VersionAdapter.PLAYER_INTERACTIVE_DM_REPLY_CLASS) == null
        var expected = 0
        var installed = 0
        for (capability in DiagnosticCapabilityCatalog.childrenOf(ID)) {
            val absent = absentFamilies.any { capability.locatorKey?.startsWith("$it/") == true } ||
                (absentDm && capability.id in setOf("player_interactive_dm_commands", "player_interactive_activity_banner"))
            if (absent) {
                environment.reportCapability(capability.id, FeatureInstallResult.Skipped("not-applicable-host"))
                continue
            }
            expected += 2
            val paths = Integer.bitCount(primaryPaths[capability.id] ?: 0)
            installed += paths
            if (paths == 0 && capability.id in fallbackIds) {
                environment.reportCapability(capability.id, FeatureInstallResult.Installed(1, complete = false))
            } else environment.reportCapabilityCoverage(capability.id, paths > 0, paths, 2)
        }
        if (hooks == 0) return missing(environment, "no-safe-interactive-path")
        val complete = installed == expected && expected > 0
        environment.reportStatus(CHANNEL_STATUS, if (complete) "success" else "partial:$installed/$expected")
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        environment.logInfo("player_interactive_installed", "[BIL] 互动层响应覆盖=$installed/$expected，注册点=$hooks，Kotlin 通道=$kotlinPaths，getter 仅作后备")
        return FeatureInstallResult.Installed(hooks, complete)
    }
    /**
     * Kotlin 版 moss（`K*Moss`）通道：`dmView` 从 9.5.0 起、统一版 `viewProgress` 从 9.13.0 起，宿主里都有走 Kotlin
     * 版的调用者（2026-10-01 dexq 对 9.10.0 / 9.13.0 / 9.14.0 核对），与 Java 通道并行。它们的响应是被混淆字段的数据类，
     * 所以经 protobuf 线格式往返到同一 proto 的 Java 响应上，**原样复用 [PlayerInteractiveReplyCleaner]**，见
     * [KotlinMossReplyBridge]。每个 Java 入口对应的 Kotlin 类/方法都按名字与形状判存，缺哪个跳过哪个；运行期异常放行原响应。
     */
    private fun installKotlinMoss(
        environment: HookEnvironment,
        loader: ClassLoader,
        cleaner: PlayerInteractiveReplyCleaner,
        owners: Map<String, String>,
        points: VersionAdapter.PlayerInteractiveOverlayPoints
    ): Int {
        val members = KotlinMossBridgeMembers.resolve(loader)
        if (members == null) {
            environment.logInfo("player_interactive_kmoss_skip", "[BIL] 互动层 Kotlin 通道未安装: kotlinx.serialization 成员缺失")
            return 0
        }
        if (!KotlinMossBridgeSelfTest.allows(environment, loader, members, "互动层")) return 0
        val seen = hashSetOf<String>()
        var installed = 0
        (points.mossAsync + points.mossExecutes).distinct().forEach { point ->
            val replyName = owners[point.className] ?: return@forEach
            val kotlinName = KotlinMossBridgeMembers.kotlinMossClassName(point.className) ?: return@forEach
            val rpc = KotlinMossBridgeMembers.rpcName(point.methodName)
            if (!seen.add("$kotlinName#$rpc")) return@forEach
            if (cleaner.responseIds(replyName).isEmpty()) return@forEach
            // 装不上不能再静默：每个候选只在真的缺东西时记一条原因（有界：候选个数）。
            fun skip(reason: String) = environment.logInfo(
                "player_interactive_kmoss_skip_$rpc",
                "[BIL] 互动层 Kotlin 通道跳过 ${kotlinName.substringAfterLast('.')}#$rpc: $reason"
            )
            val kotlinMoss = KavaMemberLookup.classOrNull(loader, kotlinName) ?: return@forEach skip("no-kotlin-class")
            val replyClass = KavaMemberLookup.classOrNull(loader, replyName) ?: return@forEach skip("no-reply-class")
            val codec = KotlinMossBridgeMembers.JavaReplyCodec.resolve(replyClass) ?: return@forEach skip("no-java-codec")
            val entry = KotlinMossBridgeMembers.callbackEntry(kotlinMoss, rpc) ?: return@forEach skip("no-callback-entry")
            val handlerClass = entry.parameterTypes[3]
            val reported = java.util.concurrent.atomic.AtomicBoolean(false)
            val called = java.util.concurrent.atomic.AtomicBoolean(false)
            runCatching {
                environment.registrar.exact(
                    "player.interactive.kmoss.$kotlinName.$rpc",
                    entry.declaringClass, entry.name, *entry.parameterTypes
                ) {
                    before {
                        if (called.compareAndSet(false, true)) {
                            environment.logInfo(
                                "player_interactive_kmoss_call",
                                "[BIL] 互动层 Kotlin 通道请求已进入 ${kotlinMoss.simpleName}#$rpc"
                            )
                        }
                        val delegate = args.getOrNull(3) ?: return@before
                        val bridge = members.bridgeFor(args.getOrNull(4), args.getOrNull(2), codec) ?: return@before
                        val proxy = MossResponseHandlerProxy.wrapTransform(handlerClass, delegate) { reply ->
                            if (reported.compareAndSet(false, true)) {
                                environment.logInfo(
                                    "player_interactive_kmoss_active",
                                    "[BIL] 互动层 Kotlin 通道 ${kotlinMoss.simpleName}#$rpc 已收到响应并进入清理"
                                )
                            }
                            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                            runCatching {
                                bridge.transform(reply) { javaReply -> cleaner.cleanResponse(javaReply, environment) }
                            }.getOrElse { throwable ->
                                environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ERROR)
                                environment.logError(
                                    "player_interactive_kmoss_failed",
                                    "[BIL] 互动层 Kotlin 通道清理失败，已放行原响应(${kotlinMoss.simpleName}#$rpc): $throwable"
                                )
                                reply
                            }
                        } ?: return@before
                        args[3] = proxy
                    }
                }
                installed++
            }.onFailure {
                environment.logError("player_interactive_kmoss_$rpc", "[BIL] 互动层 Kotlin 通道注册失败(${kotlinMoss.simpleName}#$rpc): $it")
            }
        }
        return installed
    }

    private fun missing(environment: HookEnvironment, reason: String): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        return FeatureInstallResult.Skipped(reason)
    }
    companion object {
        const val ID = "player_interactive_overlay"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "player_interactive_overlay_status"
        private const val HANDLER_CLASS = "com.bilibili.lib.moss.api.MossResponseHandler"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

/** 独立于 VideoGuide 互动层；每个广告列表入口独立安装，局部失败保留其余路径。 */
internal class PlayerPopupPromotionFeatureInstaller(private val enabled: Boolean) : FeatureInstaller {
    override val id = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) return skipped(environment, "disabled")
        if (environment.processName != "tv.danmaku.bili") return skipped(environment, "non-main-process")
        val access = PlayerPopupPromotionLocator.resolve(environment.classLoader)
            ?: return skipped(environment, "missing-host-structure")
        var installed = 0
        val readCardType = access::cardType
        val errorLogged = java.util.concurrent.atomic.AtomicBoolean(false)
        for (reader in access.readers) {
            runCatching {
                environment.registrar.exact("player.popup.promotion.${reader.name}", reader.declaringClass, reader.name) {
                    after {
                        if (hasThrowable) return@after
                        val source = result as? List<*> ?: return@after
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        // 任一字段读取失败时保留整份原列表，不发布半份过滤结果。
                        val updated = runCatching {
                            PlayerPopupPromotionPolicy.filter(source, readCardType)
                        }.getOrElse {
                            if (errorLogged.compareAndSet(false, true)) environment.logError(
                                "player_popup_promotion_read", "[BIL] 播放器推广卡读取失败，已保留原列表")
                            return@after
                        }
                        if (updated !== source) {
                            result = updated
                            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED, source.size - updated.size)
                        }
                    }
                }
                installed++
            }.onFailure {
                environment.logError("player_popup_promotion_${reader.name}", "[BIL] 播放器推广过滤入口注册失败")
            }
        }
        if (installed == 0) return skipped(environment, "no-safe-hook-point")
        val expected = PlayerPopupPromotionLocator.READERS.size
        environment.reportStatus(STATUS, if (installed == expected) "success" else "partial:$installed/$expected")
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        return FeatureInstallResult.Installed(installed, complete = installed == expected)
    }

    private fun skipped(environment: HookEnvironment, reason: String): FeatureInstallResult.Skipped {
        environment.reportStatus(STATUS, reason)
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "player_popup_promotion"
        private const val STATUS = "player_popup_promotion_status"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.view.View
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter

/** 隐藏 Gemini 播放器的“进入看一看”竖屏切换控件，并保留宿主可见性状态机。 */
internal class PlayerPortraitFeatureInstaller(
    private val enabled: Boolean,
    private val points: VersionAdapter.PlayerPortraitPoints?
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = points?.visibilityMethods?.takeIf { it.isNotEmpty() }
            ?: return missing(environment, "missing-adapter-point")

        var installedCount = 0
        adapted.forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("player.portrait.visibility.$index", point) {
                    before {
                        val requested = args.firstOrNull() as? Int ?: return@before
                        val hidden = hiddenVisibility(requested)
                        if (hidden != requested) args[0] = hidden
                    }
                }
                installedCount += 1
            }.onFailure { throwable ->
                environment.logError(
                    "player_portrait_method_$index",
                    "[BIL] 播放器竖屏切换控件 Hook 注册失败(" +
                        "${point.className}#${point.methodName}): $throwable"
                )
            }
        }

        if (installedCount == 0) return missing(environment, "registration-failed")
        val status = if (installedCount == adapted.size) {
            "success"
        } else {
            "partial:$installedCount/${adapted.size}"
        }
        environment.reportStatus(CHANNEL_STATUS, status)
        if (installedCount != adapted.size) {
            environment.logError(
                "player_portrait_partial",
                "[BIL] 播放器竖屏切换控件部分安装，hooks=$installedCount/${adapted.size}"
            )
        } else {
            environment.logInfo(
                "player_portrait_ok",
                "[BIL] 播放器竖屏切换控件隐藏已安装，hooks=$installedCount"
            )
        }
        return FeatureInstallResult.Installed(installedCount, complete = installedCount == adapted.size)
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "player_portrait_missing",
            "[BIL] 播放器竖屏切换控件适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "player_portrait_control"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "player_portrait_status"

        /** 保留原方法调用，只把宿主请求的可见性收敛为 GONE。 */
        internal fun hiddenVisibility(requested: Int): Int =
            if (requested == View.GONE) requested else View.GONE
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

