import android.os.SystemClock
import android.view.View
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.HostThreadGuard
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.InjectedUiLocale
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import java.lang.ref.WeakReference
import java.lang.reflect.Proxy
import java.lang.reflect.Method

/** 一次更多操作的身份；来源与菜单均弱持有，旧回调不能跨操作／窗口重用。 */
internal class ReplyTopologyComposeMenuContext<A : Any, S : Any> {
    class Frame<A : Any, S : Any>(anchor: A, root: A, window: Any, val seed: S,
        val time: Long, val sourceCurrent: () -> Boolean) {
        val anchor = WeakReference(anchor)
        val root = WeakReference(root)
        val window = WeakReference(window)
        var menu = WeakReference<A>(null)
        var menuRoot = WeakReference<A>(null)
        var menuWindow = WeakReference<Any>(null)
        var menuBound = false
        var menuWindowBound = false
        var source = WeakReference<List<*>>(null)
        var replacement = WeakReference<List<*>>(null)
        var legacyRow: Pair<Method, String>? = null
        var legacyModifier: Any? = null
    }
    private var frame: Frame<A, S>? = null

    fun current(): Frame<A, S>? = frame
    fun clear() { frame = null }

    fun remember(anchor: A, root: A, window: Any?, seed: S?, time: Long,
        sourceCurrent: () -> Boolean = { true }) {
        frame = if (seed == null || window == null) null
        else Frame(anchor, root, window, seed, time, sourceCurrent)
    }

    fun acceptsSource(current: Frame<A, S>, root: A, window: Any?, now: Long): Boolean {
        if (frame !== current) return false
        val valid = current.anchor.get() != null && current.root.get() === root &&
            window != null && current.window.get() === window && now - current.time in 0L..30_000L &&
            runCatching(current.sourceCurrent).getOrDefault(false)
        if (!valid) clear()
        return valid
    }

    fun bindMenu(current: Frame<A, S>, menu: A, root: A, window: Any?): Boolean {
        if (frame !== current) return false
        if (current.menuBound && (current.menu.get() !== menu || current.menuRoot.get() !== root)) return false
        if (current.menuWindowBound && current.menuWindow.get() !== window) return false
        if (!current.menuBound) {
            current.menu = WeakReference(menu)
            current.menuRoot = WeakReference(root)
            current.menuBound = true
        }
        // Popup 可以先 composition 再 attach；首次取得 token 后锁定，不允许换窗。
        if (!current.menuWindowBound && window != null) {
            current.menuWindow = WeakReference(window)
            current.menuWindowBound = true
        }
        return true
    }

    fun ownsMenu(current: Frame<A, S>, menu: A): Boolean =
        frame === current && current.menuBound && current.menu.get() === menu
}

/** 在宿主原生 Compose 菜单追加一项，不接管三点按钮、不依赖自由复制开关。 */
internal class ReplyTopologyComposeMenu(private val open: (View, ReplyTopologySeed) -> Unit) {
    private val context = ReplyTopologyComposeMenuContext<View, ReplyTopologySeed>()
    private val injecting = ThreadLocal.withInitial { false }

    fun clear() = context.clear()

    fun remember(anchor: View, seed: ReplyTopologySeed?, sourceCurrent: () -> Boolean = { true }) {
        clear()
        if (seed == null || !anchor.isAttachedToWindow || !anchor.isShown) return
        context.remember(anchor, anchor.rootView, anchor.windowToken, seed,
            SystemClock.uptimeMillis(), sourceCurrent)
    }

    private fun activeFrame(): ReplyTopologyComposeMenuContext.Frame<View, ReplyTopologySeed>? {
        val current = context.current() ?: return null
        val anchor = current.anchor.get()
        if (anchor == null || !anchor.isAttachedToWindow || !anchor.isShown) {
            clear()
            return null
        }
        return current.takeIf { context.acceptsSource(it, anchor.rootView, anchor.windowToken, SystemClock.uptimeMillis()) }
    }

    private fun acceptsClick(current: ReplyTopologyComposeMenuContext.Frame<View, ReplyTopologySeed>, menu: View,
        menuCanBeDismissed: Boolean = false): Boolean {
        if (activeFrame() !== current || !context.ownsMenu(current, menu)) return false
        // 新气泡菜单先 requestDismiss 再执行 entry.action；来源评论仍有效时允许完成这次点击。
        if (menuCanBeDismissed && !menu.isAttachedToWindow) return true
        return menu.isAttachedToWindow && menu.isShown && menu.windowToken != null &&
            context.bindMenu(current, menu, menu.rootView, menu.windowToken)
    }

    fun install(environment: HookEnvironment): FeatureInstallResult {
        val loader = environment.classLoader ?: return FeatureInstallResult.Skipped("missing-class-loader")
        val owner = KavaMemberLookup.classOrNull(loader, "kntr.common.comment.common.ui.moremenu.MoreMenuBubbleKt")
            ?: return installLegacy(environment, loader)
        val row = KavaMemberLookup.declaredMethods(owner).singleOrNull { method ->
            method.isStatic && method.returnType == Void.TYPE &&
                method.parameterTypes.map { it.name } == listOf("java.util.List", "kotlin.jvm.functions.Function1",
                    "androidx.compose.runtime.Composer", "int")
        } ?: return FeatureInstallResult.Skipped("ambiguous-compose-menu")
        val item = KavaMemberLookup.declaredMethods(owner).mapNotNull { method ->
            val params = method.parameterTypes
            if (params.size < 4 || params.getOrNull(1)?.name != "kotlin.jvm.functions.Function0") null
            else params[0].takeIf { it.name.startsWith("kntr.common.comment.common.ui.moremenu.") }
        }.distinct().singleOrNull() ?: return FeatureInstallResult.Skipped("missing-compose-menu-entry")
        val fields = KavaMemberLookup.declaredFields(item, makeAccessible = true)
            .filterNot { it.isStatic }.sortedBy { it.name }
        if (fields.firstOrNull()?.type != classOf<String>() ||
            fields.lastOrNull()?.type?.name != "kotlin.jvm.functions.Function0"
        ) return FeatureInstallResult.Skipped("missing-compose-menu-entry-shape")
        val constructor = KavaMemberLookup.declaredConstructors(item).singleOrNull {
            it.parameterTypes.contentEquals(fields.map { field -> field.type }.toTypedArray())
        } ?: return FeatureInstallResult.Skipped("missing-compose-menu-entry-constructor")
        val function = fields.last().type
        val unit = KavaMemberLookup.classOrNull(loader, "kotlin.Unit")?.let {
            KavaMemberLookup.fieldOrNull(it, "INSTANCE")?.get(null)
        } ?: return FeatureInstallResult.Skipped("missing-host-unit")
        val viewAccess = CommentComposeViewAccess.resolve(loader)
            ?: return FeatureInstallResult.Skipped("missing-local-view")
        return runCatching {
            environment.registrar.exact("reply.topology.compose.menu", owner, row.name, *row.parameterTypes) {
                before {
                    val current = activeFrame() ?: return@before
                    val anchor = current.anchor.get() ?: return@before
                    val menuView = argOrNull(2)?.let(viewAccess::read) ?: return@before
                    val ownerActivity = commentOwnerActivity(anchor.context) ?: return@before
                    if (commentOwnerActivity(menuView.context) !== ownerActivity) return@before
                    if (!context.bindMenu(current, menuView, menuView.rootView, menuView.windowToken)) return@before
                    val source = argOrNull(0) as? List<*> ?: return@before
                    if (source.isEmpty() || source.size > 16 || source.any { !item.isInstance(it) }) return@before
                    val old = current.source.get()
                    if (old != null && old !== source) return@before
                    val merged = current.replacement.get() ?: run {
                        val sample = source.first() ?: return@before
                        val values = fields.map { it.get(sample) }.toTypedArray()
                        values[0] = InjectedUiLocale.messages().replyTopologyEntryLabel
                        val menuAnchor = WeakReference(menuView)
                        values[values.lastIndex] = Proxy.newProxyInstance(loader, arrayOf(function)) { proxy, method, args ->
                            when (method.name) {
                                "invoke" -> {
                                    HostThreadGuard.run("reply_topology.compose_menu_click") {
                                        val menu = menuAnchor.get() ?: return@run
                                        if (!acceptsClick(current, menu, menuCanBeDismissed = true)) return@run
                                        val view = current.anchor.get() ?: return@run
                                        open(view, current.seed)
                                    }
                                    unit
                                }
                                "equals" -> proxy === args?.getOrNull(0)
                                "hashCode" -> System.identityHashCode(proxy)
                                "toString" -> "InnocentReplyTopologyAction"
                                else -> hostProxyDefaultValue(method.returnType)
                            }
                        }
                        val entry = constructor.newInstance(*values)
                        (source + entry).also {
                            current.source = WeakReference(source)
                            current.replacement = WeakReference(it)
                        }
                    }
                    args[0] = merged
                    // 与 NativeFeedbackPanel 相同：参数 0 的 changed 槽是 1–3 位，保留 force 位。
                    args[3] = (argOrNull(3) as Int) and 0b1110.inv()
                    environment.reportRuntimeEvidence("reply_topology_enabled", FeatureRuntimeStage.OBSERVED)
                }
            }
            FeatureInstallResult.Installed(1)
        }.getOrElse { FeatureInstallResult.Skipped("compose-menu-registration-failed") }
    }

    /** 8.96–9.10 的菜单没有 entry 列表，在已验证的纵向菜单行之后追加同型行。 */
    private fun installLegacy(environment: HookEnvironment, loader: ClassLoader): FeatureInstallResult {
        val names = listOf("CommentMoreMenuKt") + ('a'..'z').map(Char::toString) +
            ('A'..'Z').map(Char::toString) + ('a'..'z').map { "${it}0" } + ('A'..'Z').map { "${it}0" }
        val candidates = names.mapNotNull {
            KavaMemberLookup.classOrNull(loader, "kntr.common.comment.page.ui.$it")
        }.flatMap { owner -> KavaMemberLookup.declaredMethods(owner, makeAccessible = true).filter { method ->
            val types = method.parameterTypes.map { it.name }
            method.isStatic && !method.isSynthetic && method.returnType == Void.TYPE &&
                types.size in 8..9 && types[0].startsWith("kntr.common.bilitheme.compose.bottomsheet.") &&
                types.subList(1, 5) == listOf("java.lang.String", "androidx.compose.ui.graphics.painter.Painter",
                    "androidx.compose.ui.Modifier", "androidx.compose.ui.graphics.painter.Painter") &&
                types.takeLast(3) == listOf("androidx.compose.runtime.Composer", "int", "int") &&
                (types.size == 8 || types[5] == "boolean")
        } }
        val row = candidates.singleOrNull() ?: return FeatureInstallResult.Skipped("ambiguous-legacy-compose-menu")
        val modifierClass = KavaMemberLookup.classOrNull(loader, "androidx.compose.ui.Modifier")
            ?: return FeatureInstallResult.Skipped("missing-host-modifier")
        val companion = KavaMemberLookup.fieldOrNull(modifierClass, "Companion")?.get(null)
            ?: return FeatureInstallResult.Skipped("missing-host-modifier")
        val function = KavaMemberLookup.classOrNull(loader, "kotlin.jvm.functions.Function0")
            ?: return FeatureInstallResult.Skipped("missing-host-callback")
        val clickOwner = KavaMemberLookup.classOrNull(loader, "androidx.compose.foundation.ClickableKt")
            ?: return FeatureInstallResult.Skipped("missing-host-clickable")
        val clickable = KavaMemberLookup.declaredMethods(clickOwner).singleOrNull {
            val ps = it.parameterTypes
            it.isStatic && it.name.endsWith("\$default") && it.returnType == modifierClass && ps.size == 8 &&
                ps[0] == modifierClass && ps[1] == classOf<Boolean>() && ps[5] == function && ps[6] == classOf<Int>()
        } ?: return FeatureInstallResult.Skipped("ambiguous-host-clickable")
        val unit = KavaMemberLookup.classOrNull(loader, "kotlin.Unit")?.let {
            KavaMemberLookup.fieldOrNull(it, "INSTANCE")?.get(null)
        } ?: return FeatureInstallResult.Skipped("missing-host-unit")
        val views = CommentComposeViewAccess.resolve(loader) ?: return FeatureInstallResult.Skipped("missing-local-view")
        return runCatching {
            environment.registrar.exact("reply.topology.compose.legacy_menu", row.declaringClass, row.name, *row.parameterTypes) {
                after {
                    if (hasThrowable || injecting.get() == true) return@after
                    val current = activeFrame() ?: return@after
                    val anchor = current.anchor.get() ?: return@after
                    val composerIndex = row.parameterCount - 3
                    val menuView = argOrNull(composerIndex)?.let(views::read) ?: return@after
                    val activity = commentOwnerActivity(anchor.context) ?: return@after
                    if (commentOwnerActivity(menuView.context) !== activity) return@after
                    if (!context.bindMenu(current, menuView, menuView.rootView, menuView.windowToken)) return@after
                    val title = argOrNull(1) as? String ?: return@after
                    val key = current.legacyRow
                    if (key != null && key != (row to title)) return@after
                    current.legacyRow = row to title
                    val modifier = current.legacyModifier ?: run {
                        // 旧纵向菜单不带独立 dismiss 回调；挂到它自己的窗口，避免被菜单盖住。
                        val menuAnchor = WeakReference(menuView)
                        val callback = Proxy.newProxyInstance(loader, arrayOf(function)) { proxy, method, values ->
                            when (method.name) {
                                "invoke" -> {
                                    HostThreadGuard.run("reply_topology.compose_legacy_click") {
                                        menuAnchor.get()?.takeIf { acceptsClick(current, it) }
                                            ?.let { open(it, current.seed) }
                                    }
                                    unit
                                }
                                "equals" -> proxy === values?.getOrNull(0)
                                "hashCode" -> System.identityHashCode(proxy)
                                "toString" -> "InnocentReplyTopologyAction"
                                else -> hostProxyDefaultValue(method.returnType)
                            }
                        }
                        clickable.invoke(null, companion, false, null, null, null, callback, 15, null)
                            .also { current.legacyModifier = it }
                    }
                    val values = args.copyOf()
                    values[1] = InjectedUiLocale.messages().replyTopologyEntryLabel
                    values[3] = modifier
                    // 新增调用使用 force + Uncertain；不改原菜单行的 changed/default 参数。
                    values[composerIndex + 1] = 1
                    values[composerIndex + 2] = (values[composerIndex + 2] as Int) and 4.inv()
                    injecting.set(true)
                    try {
                        row.invoke(null, *values)
                        environment.reportRuntimeEvidence("reply_topology_enabled", FeatureRuntimeStage.OBSERVED)
                    } finally {
                        injecting.remove()
                    }
                }
            }
            FeatureInstallResult.Installed(1)
        }.getOrElse { FeatureInstallResult.Skipped("legacy-compose-menu-registration-failed") }
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.adapter.SearchHomeRecommendLocator
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.ModernMemberHookCreator
import com.Bilibili_Innocent_Lab.xposedmodule.hook.modern.ModernHookParam

/** Search landing-page sections only; historical provider, search results and default words stay independent. */
internal class SearchHomeRecommendFeatureInstaller(private val enabled: Boolean) : FeatureInstaller {
    override val id = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) return FeatureInstallResult.Skipped("disabled")
        if (environment.processName != "tv.danmaku.bili") return FeatureInstallResult.Skipped("non-main-process")
        val points = environment.classLoader?.let(SearchHomeRecommendLocator::locate)
            ?: return FeatureInstallResult.Skipped("missing-search-home-model")
        var installed = 0
        // 分母按这个宿主上确实存在的落点算：delivery/cache/refresh 各自存在才计 1。
        // 固定 3 会把 cache 或 refresh 本就不存在的宿主永远钉在 partial 上，
        // 与 HomeTopBar 的"分母按存在的落点"口径一致。
        val expected = (if (points.delivery != null) 1 else 0) +
            (if (points.delivery?.cache != null) 1 else 0) +
            (if (points.delivery?.refresh != null) 1 else 0) +
            (if (points.state != null || points.stateExpected) 1 else 0)
        fun attempt(name: String, register: () -> Boolean) {
            if (runCatching(register).getOrElse {
                environment.logError("search_home_register_$name", "[BIL] 搜索首页推荐边界安装失败($name): $it")
                false
            }) installed++
        }
        points.delivery?.let { delivery ->
            attempt("delivery") {
                val method = delivery.method
                environment.registrar.exact("search.home.sections", method.declaringClass, method.name, *method.parameterTypes) {
                    filterCallbacks(environment, points, { param ->
                        param.instance?.let(delivery.owner::get)?.let(delivery.sections::get)
                    }, { param -> clearDiscovery(param.instance, delivery) })
                }
                if (delivery.cache != null) installed++
                true
            }
            delivery.refresh?.let { method ->
                attempt("refresh") {
                    environment.registrar.exact("search.home.refresh", method.declaringClass, method.name, *method.parameterTypes) {
                        before {
                            // This method only publishes discovery words to its page ViewModel.
                            // It is not a network onSuccess/onError/onCompleted callback or history updater.
                            if (argOrNull(0) !is List<*>) return@before
                            environment.reportRuntimeEvidence(CAPABILITY, FeatureRuntimeStage.OBSERVED)
                            result = null
                            environment.reportRuntimeEvidence(CAPABILITY, FeatureRuntimeStage.APPLIED)
                            runCatching { clearDiscovery(instance, delivery) }
                                .onFailure { environment.logError("search_home_refresh_cache", "[BIL] 搜索发现旧状态清理失败: $it") }
                        }
                    }
                    true
                }
            }
        }
        points.state?.let { state ->
            attempt("state") {
                environment.registrar.constructor("search.home.state", state.constructor) {
                    filterCallbacks(environment, points, readback = { param -> param.instance?.let(state.sections::get) })
                }
                true
            }
        }
        environment.reportStatus(
            "search_home_recommend_status",
            when {
                expected == 0 -> "not-applicable-host"
                installed == expected -> "success"
                else -> "partial:$installed/$expected"
            }
        )
        return when {
            installed > 0 -> FeatureInstallResult.Installed(installed, installed == expected)
            // 候选多于一个时按歧义上报：FeatureSkipReason.fromRaw 以子串 "ambiguous" 映射为
            // AMBIGUOUS_HOST_STRUCTURE，与「宿主确实没有该结构」区分开，便于日志判读。
            points.deliveryCandidateCount > 1 ->
                FeatureInstallResult.Skipped("ambiguous-search-home-boundary")
            else -> FeatureInstallResult.Skipped("missing-search-home-boundary")
        }
    }

    private fun ModernMemberHookCreator.filterCallbacks(
        env: HookEnvironment, points: SearchHomeRecommendLocator.Points, readback: (ModernHookParam) -> Any?,
        cleanup: (ModernHookParam) -> Boolean = { false }
    ) {
        before {
            val source = argOrNull(0) as? List<*> ?: return@before
            runCatching {
                val filtered = SearchHomeRecommendPolicy.filter(source, unsafeEmpty = {
                    env.logInfo("search_home_missing_anchor", "[BIL] 搜索首页分区缺少可保留锚点，保留原响应避免误隐藏历史")
                }) { entry ->
                    if (points.square.isInstance(entry)) points.type.invoke(entry) as? String else null
                }
                env.reportRuntimeEvidence(CAPABILITY, FeatureRuntimeStage.OBSERVED)
                if (filtered !== source) {
                    args[0] = filtered
                    setObjectExtra(FILTERED, filtered)
                }
            }.onFailure { env.logError("search_home_filter", "[BIL] 搜索首页分区读取失败，保留原数据: $it") }
        }
        after {
            if (hasThrowable) return@after
            val supplied = argOrNull(0) as? List<*> ?: return@after
            runCatching {
                if (readback(this) === supplied) {
                    val cleanSections = supplied.none { item ->
                        item != null && points.square.isInstance(item) &&
                            SearchHomeRecommendPolicy.blocked(points.type.invoke(item) as? String)
                    }
                    val cleared = cleanSections && cleanup(this)
                    if (getObjectExtra(FILTERED) != null || cleared) env.reportRuntimeEvidence(CAPABILITY, FeatureRuntimeStage.APPLIED)
                } else env.reportRuntimeEvidence(CAPABILITY, FeatureRuntimeStage.ERROR)
            }.onFailure { env.logError("search_home_readback", "[BIL] 搜索首页分区写后校验失败: $it") }
        }
    }

    internal fun clearDiscovery(instance: Any?, delivery: SearchHomeRecommendLocator.Delivery): Boolean {
        val cache = delivery.cache ?: return false
        val owner = instance?.let(delivery.owner::get) ?: return false
        val observable = cache.field.get(owner) ?: return false
        val old = cache.read.invoke(observable) ?: return false
        if ((cache.values.get(old) as? List<*>).isNullOrEmpty() && cache.feedback.get(old) == null) return false
        val args = arrayOfNulls<Any>(cache.constructor.parameterCount)
        args[0] = emptyList<Any>(); args[1] = ""
        for (i in 3 until args.size) args[i] = 0L
        val empty = cache.constructor.newInstance(*args)
        cache.write.invoke(observable, empty)
        val current = cache.read.invoke(observable) ?: error("Missing discovery state after publication")
        check((cache.values.get(current) as? List<*>).isNullOrEmpty() && cache.feedback.get(current) == null)
        return true
    }

    companion object {
        const val ID = "search_home_recommend_hidden"
        const val CAPABILITY = "search_home_recommend_hidden"
        private const val FILTERED = "search_home_filtered_sections"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.Method

/**
 * 在综合搜索结果的 protobuf 读边界过滤广告卡与指定内容。
 *
 * 这里可以用 getter 边界（而不是像弹幕、动态那样改写消息本身）：9.11.0 里
 * `SearchAllResponse#getItemList` 被业务侧 `classes14.dex` 跨 dex 引用，确实由宿主调用。
 * 改返回值不触碰宿主内部集合，无命中时连副本都不创建。
 *
 * 判据：
 * - 推广卡：`Item.hasCm()` 或 `Item.hasSpecial()`，即商业广告卡与特殊运营卡。
 * - 标题关键词 / 发布者：只作用于**视频卡**（`Item.hasAv()`）。番剧、直播、专栏等其它卡型
 *   的字段结构各不相同，本轮不猜测它们的作者字段，宁可少覆盖也不误删。
 *
 * **版本覆盖（2026-09-06 离线核对 9.7.0–9.11.0 五版）**：`getItemList` 每版只有一个重载
 * 且都有跨 dex 调用方；`hasCm`/`hasSpecial`/`hasAv`/`getAv` 与视频卡的
 * `getTitle`/`getAuthor`/`getMid` 五版齐全。
 *
 * 覆盖单位口径：列表边界算一个单位；每条被用户启用、但读取路径缺失的判据计入分母不计入
 * 分子，于是"开了却没生效"表现为 `partial`。
 */
internal class SearchPurifyFeatureInstaller(
    private val removeCommercial: Boolean,
    keywordFilterEnabled: Boolean,
    rawKeywords: String,
    authorFilterEnabled: Boolean,
    rawAuthorRules: String
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (removeCommercial) add("search_commercial_removed")
        if (keywords.isNotEmpty()) add("search_keyword_filter_enabled")
        if (authorRules.isNotEmpty()) add("search_author_filter_enabled")
    }

    private val keywords = if (keywordFilterEnabled) {
        RuleSetCodec.parse(rawKeywords).take(MAX_KEYWORDS).toCollection(linkedSetOf())
    } else {
        emptySet()
    }
    private val authorRules = if (authorFilterEnabled) {
        AuthorRuleSet.parse(rawAuthorRules)
    } else {
        AuthorRuleSet.EMPTY
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!removeCommercial && keywords.isEmpty() && authorRules.isEmpty()) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val responseClass = environment.hookPoints.resolveClass(
            "search.purify.response",
            SEARCH_ALL_RESPONSE_CLASS
        ) ?: return missing(environment, "missing-search-response-class")
        val itemListGetter = KavaMemberLookup.methodOrNull(responseClass, "getItemList")
            ?.takeIf {
                !it.isStatic && it.parameterCount == 0 &&
                    it.returnType isSubclassOf classOf<List<*>>()
            } ?: return missing(environment, "missing-item-list-getter")

        val resolved = resolveMembers(loader)
        val plan = Plan(
            removeCommercial = removeCommercial && resolved?.commercial != null,
            keywords = if (resolved?.videoCard?.title != null) keywords else emptySet(),
            authorRules = authorRules.available(resolved?.videoCard?.author != null, resolved?.videoCard?.mid != null)
        )
        // 判据全部不可用时不注册：留一个永远不删东西的 Hook 只会让状态好看。
        val members = resolved.takeIf { plan.hasAnyJudgement }
            ?: return missing(environment, "missing-judgement-getter")

        val installed = runCatching {
            environment.registrar.exact(
                "search.purify.item_list",
                itemListGetter.declaringClass,
                itemListGetter.name
            ) {
                after {
                    if (hasThrowable || KotlinMossChannel.isRaw()) return@after
                    val source = result as? List<*> ?: return@after
                    if (source.isEmpty()) return@after
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    val filtered = ProtobufListRetention.filterOrSame(source) { item ->
                        shouldRemove(item, members, plan)
                    }
                    if (filtered !== source) {
                        result = filtered
                        environment.reportRuntimeEvidence(
                            ID,
                            FeatureRuntimeStage.APPLIED,
                            source.size - filtered.size
                        )
                    }
                }
            }
            1
        }.getOrElse { throwable ->
            environment.logError(
                "search_purify_register",
                "[BIL] 搜索结果过滤 Hook 注册失败: $throwable"
            )
            0
        }
        if (installed == 0) return missing(environment, "registration-failed")
        // 9.12.0 起新版搜索（kntr.app.search）走 Kotlin KSearchMoss.searchAll，Java getter 碰不到；兜底通道不计入覆盖单位。
        val kotlinAll = installKotlinChannel(environment, loader, responseClass, itemListGetter, members, plan)
        val category = installCategory(environment, loader, members, plan)
        val boundaryInstalled = installed + (if (kotlinAll == true) 1 else 0) + category.first
        val boundaryExpected = 1 + (if (kotlinAll != null) 1 else 0) + category.second
        val commercialComplete = resolved?.commercial?.hasCm != null && resolved.commercial.hasSpecial != null
        if (removeCommercial) environment.reportCapabilityCoverage("search_commercial_removed", plan.removeCommercial,
            boundaryInstalled, boundaryExpected + if (commercialComplete) 0 else 1)
        if (keywords.isNotEmpty()) environment.reportCapabilityCoverage("search_keyword_filter_enabled", plan.keywords.isNotEmpty(),
            boundaryInstalled, boundaryExpected)
        if (authorRules.isNotEmpty()) environment.reportCapabilityCoverage("search_author_filter_enabled", plan.authorRules.isNotEmpty(),
            boundaryInstalled, boundaryExpected + if (plan.authorRules == authorRules) 0 else 1)

        var total = boundaryInstalled
        var expected = boundaryExpected
        val degraded = ArrayList<String>(3)
        fun account(requested: Boolean, usable: Boolean, label: String) {
            if (!requested) return
            expected += 1
            if (usable) total += 1 else degraded += label
        }
        account(removeCommercial, plan.removeCommercial && commercialComplete, "commercial")
        account(keywords.isNotEmpty(), plan.keywords.isNotEmpty(), "keyword")
        account(authorRules.isNotEmpty(), plan.authorRules == authorRules, "author")
        if (degraded.isNotEmpty()) {
            environment.logError(
                "search_purify_degraded",
                "[BIL] 搜索结果过滤判据缺少可用读取路径: ${degraded.joinToString(",")}"
            )
        }

        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        val status = if (total == expected) "success" else "partial:$total/$expected"
        environment.reportStatus(CHANNEL_STATUS, status)
        if (status == "success") {
            environment.logInfo(
                "search_purify_ok",
                "[BIL] 搜索结果过滤已安装，判据=${plan.describe()}"
            )
        } else {
            environment.logError(
                "search_purify_partial",
                "[BIL] 搜索结果过滤部分安装，status=$status"
            )
        }
        return FeatureInstallResult.Installed(total, complete = total == expected)
    }

    /**
     * 新版搜索的 Kotlin 通道：经 [KotlinMossChannel] 往返到同一 proto 的 Java `SearchAllResponse`，
     * 用与 getter 层相同的判据删卡片，再以 builder 的 `clearItem` / `addAllItem` 重建。
     */
    private fun installKotlinChannel(
        environment: HookEnvironment,
        loader: ClassLoader,
        responseClass: Class<*>,
        itemListGetter: Method,
        members: Members,
        plan: Plan,
        rpc: String = "searchAll",
        stem: String = "Item"
    ): Boolean? {
        val kotlinMossName = SEARCH_MOSS_CLASS.replace(".SearchMoss", ".KSearchMoss")
        if (KavaMemberLookup.classOrNull(loader, kotlinMossName) == null) return null
        // 装不上要留下原因，否则诊断输出与"压根没尝试接入"完全无法区分（有界：三条）。
        fun skip(reason: String): Boolean {
            environment.logInfo("search_purify_kmoss_skip_$rpc", "[BIL] 搜索结果过滤 $rpc 新通道未接入: $reason")
            return false
        }
        val builder = ProtobufBuilderPlan.resolve(responseClass) ?: return skip("no-response-builder")
        val clearItem = builder.method("clear$stem") ?: return skip("no-clear-item")
        val addAllItem = builder.method("addAll$stem", classOf<Iterable<*>>()) ?: return skip("no-add-all-item")
        val bridge = KotlinMossChannel.prepare(environment, loader, "搜索结果过滤", KMOSS_LOG_KEY) ?: return skip("no-bridge")
        val installed = KotlinMossChannel.install(
            environment, loader, bridge,
            javaMossClassName = SEARCH_MOSS_CLASS,
            rpc = rpc,
            javaReplyClass = responseClass,
            hookId = "search.purify.kmoss.$rpc",
            what = "搜索结果过滤",
            logKey = KMOSS_LOG_KEY
        ) transform@{ javaReply ->
            val source = KotlinMossChannel.raw { itemListGetter.invoke(javaReply) as? List<*> }
            if (source.isNullOrEmpty()) return@transform javaReply
            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
            val filtered = ProtobufListRetention.filterOrSame(source) { item -> shouldRemove(item, members, plan) }
            if (filtered === source) return@transform javaReply
            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED, source.size - filtered.size)
            builder.edit(javaReply) { target ->
                clearItem.invoke(target)
                addAllItem.invoke(target, filtered)
            }
        }
        environment.logInfo("search_purify_kmoss_$rpc", "[BIL] 搜索结果过滤 $rpc：Kotlin 新通道${if (installed) "已接入" else "未接入"}")
        return installed
    }

    /** 分类结果复用同一 Item 判据；不把番剧／直播等不同模型当作视频读取。 */
    private fun installCategory(environment: HookEnvironment, loader: ClassLoader, members: Members, plan: Plan): Pair<Int, Int> {
        val response = KavaMemberLookup.classOrNull(loader, "$SEARCH_PACKAGE.SearchByTypeResponse")
            ?: return 0 to 0
        val getter = KavaMemberLookup.methodOrNull(response, "getItemsList")
            ?.takeIf { !it.isStatic && it.returnType isSubclassOf classOf<List<*>>() }
        if (getter == null) {
            environment.logError("search_category_shape", "[BIL] 分类搜索列表边界缺失")
            return 0 to 1
        }
        var installed = 0
        runCatching {
            environment.registrar.exact("search.purify.category.items", response, getter.name) {
                after {
                    if (hasThrowable || KotlinMossChannel.isRaw()) return@after
                    val source = result as? List<*> ?: return@after
                    if (source.isEmpty()) return@after
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    val filtered = ProtobufListRetention.filterOrSame(source) { shouldRemove(it, members, plan) }
                    if (filtered !== source) {
                        result = filtered
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED, source.size - filtered.size)
                    }
                }
            }
            installed++
        }.onFailure { environment.logError("search_category_registration", "[BIL] 分类搜索过滤注册失败") }
        val kotlin = installKotlinChannel(environment, loader, response, getter, members, plan, "searchByType", "Items")
        val expected = 1 + if (kotlin != null) 1 else 0
        if (kotlin == true) installed++
        environment.reportStatus("search_category_layers", "$installed/$expected")
        return installed to expected
    }

    private fun shouldRemove(item: Any, members: Members, plan: Plan): Boolean {
        if (plan.removeCommercial && members.commercial != null) {
            val commercial = members.commercial
            if (invoke(commercial.hasCm, item) as? Boolean == true) return true
            if (invoke(commercial.hasSpecial, item) as? Boolean == true) return true
        }
        val video = members.videoCard ?: return false
        if (plan.keywords.isEmpty() && plan.authorRules.isEmpty()) return false
        // 只有视频卡才有确定的标题/作者字段；其它卡型直接放行。
        if (invoke(video.hasAv, item) as? Boolean != true) return false
        val card = invoke(video.avGetter, item) ?: return false
        if (plan.keywords.isNotEmpty()) {
            val title = invoke(video.title, card) as? String
            if (RuleSetCodec.matches(plan.keywords, title)) return true
        }
        if (plan.authorRules.isNotEmpty()) {
            val author = (invoke(video.author, card) as? String)?.takeIf(String::isNotBlank)
            val mid = (invoke(video.mid, card) as? Number)?.toLong()?.takeIf { it > 0L }
            if (plan.authorRules.matches(author, mid)) return true
        }
        return false
    }

    private fun resolveMembers(loader: ClassLoader): Members? {
        val itemClass = KavaMemberLookup.classOrNull(loader, SEARCH_ITEM_CLASS) ?: return null
        val commercial = run {
            val hasCm = booleanNoArg(itemClass, "hasCm")
            val hasSpecial = booleanNoArg(itemClass, "hasSpecial")
            if (hasCm == null && hasSpecial == null) null else CommercialMembers(hasCm, hasSpecial)
        }
        val videoCard = run {
            val hasAv = booleanNoArg(itemClass, "hasAv")
            val avGetter = KavaMemberLookup.methodOrNull(itemClass, "getAv")?.takeIf {
                !it.isStatic && it.parameterCount == 0 && !it.returnType.isPrimitive
            }
            if (hasAv == null || avGetter == null) return@run null
            val cardClass = avGetter.returnType
            val title = stringNoArg(cardClass, "getTitle")
            val author = stringNoArg(cardClass, "getAuthor")
            val mid = KavaMemberLookup.methodOrNull(cardClass, "getMid")?.takeIf {
                !it.isStatic && it.parameterCount == 0 && it.returnType == classOf<Long>()
            }
            if (title == null && author == null && mid == null) {
                null
            } else {
                VideoCardMembers(hasAv, avGetter, title, author, mid)
            }
        }
        if (commercial == null && videoCard == null) return null
        return Members(commercial, videoCard)
    }

    private fun invoke(method: Method?, target: Any?): Any? {
        if (method == null || target == null || !method.declaringClass.isInstance(target)) {
            return null
        }
        return runCatching { method.invoke(target) }.getOrNull()
    }

    private fun booleanNoArg(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf {
            !it.isStatic && it.parameterCount == 0 && it.returnType == classOf<Boolean>()
        }

    private fun stringNoArg(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf {
            !it.isStatic && it.parameterCount == 0 && it.returnType == classOf<String>()
        }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "search_purify_missing",
            "[BIL] 搜索结果过滤适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    /** 安装期定型的判据集合；热路径只读它。 */
    private data class Plan(
        val removeCommercial: Boolean,
        val keywords: Set<String>,
        val authorRules: AuthorRuleSet
    ) {
        val hasAnyJudgement: Boolean
            get() = removeCommercial || keywords.isNotEmpty() || authorRules.isNotEmpty()

        fun describe(): String = buildList {
            if (removeCommercial) add("commercial")
            if (keywords.isNotEmpty()) add("keyword=${keywords.size}")
            if (authorRules.isNotEmpty()) {
                add("author=${authorRules.mids.size}uid+${authorRules.names.size}name")
            }
        }.joinToString("/")
    }

    private class Members(
        val commercial: CommercialMembers?,
        val videoCard: VideoCardMembers?
    )

    private class CommercialMembers(val hasCm: Method?, val hasSpecial: Method?)

    private class VideoCardMembers(
        val hasAv: Method,
        val avGetter: Method,
        val title: Method?,
        val author: Method?,
        val mid: Method?
    )

    companion object {
        const val ID = "search_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "search_purify_status"
        private const val MAX_KEYWORDS = 64
        private const val SEARCH_PACKAGE = "com.bapis.bilibili.polymer.app.search.v1"
        private const val SEARCH_MOSS_CLASS = "$SEARCH_PACKAGE.SearchMoss"
        private const val KMOSS_LOG_KEY = "search_purify_kmoss"
        private const val SEARCH_ALL_RESPONSE_CLASS = "$SEARCH_PACKAGE.SearchAllResponse"
        private const val SEARCH_ITEM_CLASS = "$SEARCH_PACKAGE.Item"
    }
}

