package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import java.lang.reflect.Method
import java.util.Locale

/**
 * 净化分享结果：去掉链接与文案里的追踪参数，并把小程序卡片降级为普通链接分享。
 *
 * 边界是宿主分享中台的公开数据类 `ShareClickResult`——类名与 getter/setter 名都没混淆，
 * 且 9.11.0 里业务侧确实经 getter 读取（跨 dex 引用可查），不存在"按字段序列化绕过 getter"
 * 的问题。
 *
 * 改写后同步写回同名字段：分享面板会多次读取同一个结果对象，只改本次返回值会让复制链接
 * 和真正发出去的内容出现不一致。
 *
 * **版本覆盖（2026-09-06 离线核对 9.7.0–9.11.0 五版）**：全部 getter/setter 五版齐全，
 * `shareMode` 在每一版都是装箱 `java.lang.Integer`，`getLink` 每版都有跨 dex 调用方。
 *
 * 小程序降级只动 `shareMode`：6/7 是小程序，改成 0 让宿主走普通图文链接分享。附带的
 * 标题回填是因为小程序模式下 `title` 固定是应用名、真正的标题在 `content` 里，不回填会得到
 * 一张标题为"哔哩哔哩"的卡片。这里不追加任何署名文案。
 */
internal class SharePurifyFeatureInstaller(
    private val purifyContent: Boolean,
    private val miniProgramDirectLink: Boolean
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (purifyContent) add("share_content_purified")
        if (miniProgramDirectLink) add("share_mini_program_direct_link")
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!purifyContent && !miniProgramDirectLink) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val resultClass = environment.hookPoints.resolveClass(
            "share.purify.result",
            SHARE_CLICK_RESULT_CLASS
        ) ?: return missing(environment, "missing-share-result-class")

        var installed = 0
        var expected = 0

        if (purifyContent) {
            val beforeInstalled = installed
            val beforeExpected = expected
            val setLink = stringSetter(resultClass, "setLink")
            val getLink = stringGetter(resultClass, "getLink")
            expected += 1
            if (getLink == null) {
                environment.logError(
                    "share_purify_link_missing",
                    "[BIL] 分享链接净化缺少 getLink 读取路径"
                )
            } else if (installStringPurifier(
                    environment.forCapabilityRuntime("share_content_purified"),
                    "share.purify.link",
                    getLink,
                    setLink
                ) { ShareLinkPurifier.purifyUrl(it) }
            ) {
                installed += 1
            }

            val setContent = stringSetter(resultClass, "setContent")
            val getContent = stringGetter(resultClass, "getContent")
            expected += 1
            if (getContent == null) {
                environment.logError(
                    "share_purify_content_missing",
                    "[BIL] 分享文案净化缺少 getContent 读取路径"
                )
            } else if (installStringPurifier(
                    environment.forCapabilityRuntime("share_content_purified"),
                    "share.purify.content",
                    getContent,
                    setContent
                ) { ShareLinkPurifier.purifyText(it) }
            ) {
                installed += 1
            }
            environment.reportCapabilityCoverage("share_content_purified", true,
                installed - beforeInstalled, expected - beforeExpected)
        }

        if (miniProgramDirectLink) {
            val beforeInstalled = installed
            val beforeExpected = expected
            expected += 1
            if (installMiniProgramDowngrade(environment.forCapabilityRuntime("share_mini_program_direct_link"), resultClass)) installed += 1
            environment.reportCapabilityCoverage("share_mini_program_direct_link", true,
                installed - beforeInstalled, expected - beforeExpected)
        }

        if (installed == 0) return missing(environment, "registration-failed")
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        val status = if (installed == expected) "success" else "partial:$installed/$expected"
        environment.reportStatus(CHANNEL_STATUS, status)
        if (status == "success") {
            environment.logInfo(
                "share_purify_ok",
                "[BIL] 分享净化已安装，hooks=$installed，" +
                    "purify=$purifyContent，miniProgram=$miniProgramDirectLink"
            )
        } else {
            environment.logError(
                "share_purify_partial",
                "[BIL] 分享净化部分安装，status=$status"
            )
        }
        return FeatureInstallResult.Installed(installed, complete = installed == expected)
    }

    private fun installStringPurifier(
        environment: HookEnvironment,
        id: String,
        getter: Method,
        setter: Method?,
        purify: (String) -> String?
    ): Boolean = runCatching {
        environment.registrar.exact(id, getter.declaringClass, getter.name) {
            after {
                if (hasThrowable) return@after
                val original = result as? String ?: return@after
                environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                val purified = purify(original) ?: return@after
                result = purified
                // 写回同一对象，后续读取（复制链接、二次分享）拿到的也是净化后的值。
                setter?.let { runCatching { it.invoke(instance, purified) } }
                environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
            }
        }
        true
    }.getOrElse { throwable ->
        environment.logError(
            "share_purify_register_${id.substringAfterLast('.')}",
            "[BIL] 分享净化 Hook 注册失败($id): $throwable"
        )
        false
    }

    private fun installMiniProgramDowngrade(
        environment: HookEnvironment,
        resultClass: Class<*>
    ): Boolean {
        val getShareMode = KavaMemberLookup.methodOrNull(resultClass, "getShareMode")
            ?.takeIf { !it.isStatic && it.parameterCount == 0 }
            ?: run {
                environment.logError(
                    "share_mini_program_missing",
                    "[BIL] 小程序转直链缺少 getShareMode 读取路径"
                )
                return false
            }
        val setShareMode = KavaMemberLookup.declaredMethods(resultClass, makeAccessible = true) {
            !it.isStatic && it.name == "setShareMode" && it.parameterCount == 1
        }.singleOrNull()
        val getTitle = stringGetter(resultClass, "getTitle")
        val getContent = stringGetter(resultClass, "getContent")
        val setTitle = stringSetter(resultClass, "setTitle")
        val plainMode = coerceShareMode(getShareMode.returnType, PLAIN_SHARE_MODE)
            ?: run {
                environment.logError(
                    "share_mini_program_mode_type",
                    "[BIL] 小程序转直链无法构造普通分享模式返回值" +
                        "(${getShareMode.returnType.name})"
                )
                return false
            }

        return runCatching {
            environment.registrar.exact(
                "share.purify.mini_program",
                getShareMode.declaringClass,
                getShareMode.name
            ) {
                after {
                    if (hasThrowable) return@after
                    val mode = (result as? Number)?.toInt() ?: return@after
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    if (mode !in MINI_PROGRAM_SHARE_MODES) return@after
                    result = plainMode
                    val target = instance
                    if (target != null) {
                        setShareMode?.let { runCatching { it.invoke(target, plainMode) } }
                        restoreTitleFromContent(target, getTitle, getContent, setTitle)
                    }
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                }
            }
            true
        }.getOrElse { throwable ->
            environment.logError(
                "share_mini_program_register",
                "[BIL] 小程序转直链 Hook 注册失败: $throwable"
            )
            false
        }
    }

    /**
     * 小程序模式下标题固定是应用名，真正的标题在正文里。
     *
     * 只有标题为空或就是应用名时才回填，避免覆盖宿主已经写好的正常标题。
     */
    private fun restoreTitleFromContent(
        target: Any,
        getTitle: Method?,
        getContent: Method?,
        setTitle: Method?
    ) {
        getTitle ?: return
        getContent ?: return
        setTitle ?: return
        val title = runCatching { getTitle.invoke(target) }.getOrNull() as? String
        if (title != null && title.isNotBlank() &&
            title.trim().lowercase(Locale.ROOT) !in APP_NAME_TITLES
        ) {
            return
        }
        val content = (runCatching { getContent.invoke(target) }.getOrNull() as? String)
            ?.trim()
            ?.takeIf(String::isNotEmpty)
            ?: return
        runCatching { setTitle.invoke(target, content.take(MAX_TITLE_LENGTH)) }
    }

    /** `shareMode` 在不同版本可能是 `int` 或 `Integer`，返回值类型必须对得上。 */
    private fun coerceShareMode(returnType: Class<*>, value: Int): Any? = when (returnType) {
        classOf<Int>(), classOf<Int>(primitiveType = false) -> value
        else -> null
    }

    private fun stringGetter(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name)?.takeIf { method ->
            !method.isStatic && method.parameterCount == 0 &&
                method.returnType == classOf<String>()
        }

    private fun stringSetter(owner: Class<*>, name: String): Method? =
        KavaMemberLookup.methodOrNull(owner, name, classOf<String>())?.takeIf { method ->
            !method.isStatic && method.returnType == Void.TYPE
        }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "share_purify_missing",
            "[BIL] 分享净化适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "share_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "share_purify_status"
        private const val SHARE_CLICK_RESULT_CLASS =
            "com.bilibili.lib.sharewrapper.online.api.ShareClickResult"

        /** 宿主分享模式：6/7 为小程序，0 走普通图文链接。 */
        private val MINI_PROGRAM_SHARE_MODES = setOf(6, 7)
        private const val PLAIN_SHARE_MODE = 0
        private const val MAX_TITLE_LENGTH = 120

        /** 小程序占位标题；只用于判断"这不是真标题"，不参与任何文案生成。 */
        private val APP_NAME_TITLES = setOf("哔哩哔哩", "嗶哩嗶哩", "bilibili")
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf

/**
 * 开屏广告净化：两道**互不知情**的防线。
 *
 * ```
 * 第一道（数据层）：清空宿主开屏响应里的广告/策略列表
 *   SplashListResponse.getSplashList / getStrategyList
 *   BrandSplashData/PreloadBrandData.getShowList
 *   event 的 getSplashList
 *   —— 经 VersionAdapter 定位（混淆 owner 候选表），覆盖"服务端下发的列表"
 *
 * 第二道（决策层）：让选片决策直接判定"无广告可展"
 *   SplashOrder.isEmptyAd() -> true
 *   —— 硬编码未混淆类名 + 运行期哨兵，覆盖**不经过列表 getter** 的构造路径
 *      （品牌预加载 PreloadBrandData、事件开屏、本地缓存恢复）
 * ```
 *
 * ### 为什么两道要互不知情
 *
 * 第一道依赖 VersionAdapter 的混淆 owner 候选表，宿主换实现就会定位落空；
 * 第二道打在未混淆的模型类上。**任何一道失败都不许影响另一道**——
 * 早期实现里 `points == null` 会直接 return，那等于把两道串联成"与"，
 * 可用性反而变成两道之积。现在各自 try/catch、各自记状态。
 *
 * ### 为什么用 `isEmptyAd` 而不是 `isAd` / `isAdLoc`
 *
 * `isAd()` 的语义是"**这**是不是广告"，把真广告标成"不是广告"会污染
 * `ad_cb` 曝光上报链；`isEmptyAd()` 的语义是"**有没有**广告可展"，
 * 返回 true 让上报链自然静默。两者不能互换。
 *
 * ### 版本覆盖（25 个存档宿主实测，2026-09-11）
 *
 * `SplashOrder.isEmptyAd():boolean` **从 8.98.0 才有**：8.84.0–8.97.0 那 12 版
 * 没有这个方法（原方案只在 9.11.0 上核过，据此推广到全版本是不成立的）。
 * 所以第二道在旧版本上按哨兵降级为 skipped，第一道照常工作。
 */
internal class SplashAdFeatureInstaller(
    private val enabled: Boolean,
    private val points: VersionAdapter.SplashAdPoints?
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            environment.reportStatus(CHANNEL_DECISION, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }

        val listInstalled = installListLayer(environment)
        val decisionInstalled = installDecisionLayer(environment)

        if (listInstalled == 0 && !decisionInstalled) {
            return missing(environment, if (points == null) "missing-adapter-point" else "registration-failed")
        }
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        // 第一道的状态语义保持原样（历史诊断与遥测按它对齐），第二道单独一条通道。
        environment.reportStatus(
            CHANNEL_STATUS,
            if (listInstalled > 0) "success" else "decision-only"
        )
        environment.logInfo(
            "splash_purify_ok",
            "[BIL] 开屏广告净化已安装，列表层 hooks=$listInstalled，决策层=$decisionInstalled"
        )
        return FeatureInstallResult.Installed(listInstalled + if (decisionInstalled) 1 else 0)
    }

    /** 第一道：清列表。@return 实际装上的 hook 数。 */
    private fun installListLayer(environment: HookEnvironment): Int {
        val adapted = points ?: run {
            environment.logInfo(
                "splash_purify_list_absent",
                "[BIL] 开屏列表层未适配（无 VersionAdapter 点位），仅保留决策层"
            )
            return 0
        }
        var installed = 0
        adapted.listGetters.forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("splash.purify.$index", point) {
                    after {
                        val source = result as? List<*> ?: return@after
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        if (source.isNotEmpty()) {
                            result = ArrayList<Any>(0)
                            environment.reportRuntimeEvidence(
                                ID,
                                FeatureRuntimeStage.APPLIED,
                                source.size
                            )
                        }
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "splash_purify_$index",
                    "[BIL] 开屏广告净化 Hook 注册失败(${point.className}#${point.methodName}): " +
                        throwable
                )
            }
        }
        return installed
    }

    /**
     * 第二道：决策层。
     *
     * `replaceToTrue()` 是纯返回值改写——无参、无副作用，所以不需要线程门禁；
     * 每次选片才走一次，不在任何帧预算热路径上。
     */
    private fun installDecisionLayer(environment: HookEnvironment): Boolean {
        val loader = environment.classLoader ?: run {
            environment.reportStatus(CHANNEL_DECISION, "missing-class-loader")
            return false
        }
        val orderClass = KavaMemberLookup.classOrNull(loader, SPLASH_ORDER_CLASS)
        val method = orderClass?.let {
            KavaMemberLookup.methodOrNull(it, IS_EMPTY_AD)
                ?.takeIf { candidate ->
                    candidate.returnType == classOf<Boolean>() &&
                        candidate.parameterTypes.isEmpty()
                }
        }
        if (method == null) {
            // 8.84.0–8.97.0 本来就没有这个方法，属于预期降级，记 info 不记 error。
            environment.reportStatus(CHANNEL_DECISION, "not-applicable-host")
            environment.logInfo(
                "splash_decision_absent",
                "[BIL] 开屏决策层不可用（本宿主无 $SPLASH_ORDER_CLASS#$IS_EMPTY_AD），" +
                    "仅保留列表层"
            )
            return false
        }
        return runCatching {
            environment.registrar.exact(
                "splash.decision.$IS_EMPTY_AD",
                method.declaringClass,
                IS_EMPTY_AD
            ) {
                replaceToTrue()
            }
            environment.reportStatus(CHANNEL_DECISION, "success")
            true
        }.getOrElse { throwable ->
            environment.reportStatus(CHANNEL_DECISION, "registration-failed")
            environment.logError(
                "splash_decision_register",
                "[BIL] 开屏决策层 Hook 注册失败: $throwable"
            )
            false
        }
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("splash_purify_missing", "[BIL] 开屏广告净化适配不完整: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "splash_ad_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "splash_ad_purify_status"
        private const val CHANNEL_DECISION = "splash_decision_status"

        /**
         * 决策汇合点。`splash.ad.model` 包在 25 个存档宿主里都是明文类名
         * （现有 `SPLASH_RESPONSE_CLASS_CANDIDATES` 也依赖这个事实）。
         * `SplashShowStrategy.isEmptyAd()` 内部调的就是它，所以一个点覆盖全部策略类型；
         * 刻意**不碰** `SplashShowStrategy.isEmptyAd()`，留作"只想屏蔽某类策略"时的第二粒度。
         */
        private const val SPLASH_ORDER_CLASS = "tv.danmaku.bili.splash.ad.model.SplashOrder"
        private const val IS_EMPTY_AD = "isEmptyAd"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.content.res.Configuration
import android.graphics.Color
import android.os.Bundle
import android.view.View
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import java.util.concurrent.atomic.AtomicInteger

/**
 * 让开屏页底色跟随系统深色模式。
 *
 * 宿主的品牌开屏底色固定为白色，夜里从深色首页切过去会闪一下白屏。这里只在开屏 Fragment
 * 的 `onViewCreated` 之后改一次背景色：深色模式黑、浅色模式白。
 *
 * 只改背景，不碰开屏图、logo、时长和跳过按钮——那些属于开屏广告净化的范围，两个功能互不
 * 依赖也互不覆盖。
 *
 * **版本覆盖（2026-09-06 离线核对 9.7.0–9.11.0 五版）**：`onViewCreated(View, Bundle)` 与
 * `splash_container` 资源名五版齐全。
 *
 * 资源 id 按名解析并缓存：宿主 `R$id` 数值每版都漂，名字稳定（[SPLASH_CONTAINER_ID_NAME]）。
 * 解析不到时退回 Fragment 根视图，仍然是一次性的、有界的降级。
 */
internal class SplashAutoNightFeatureInstaller(
    private val enabled: Boolean
) : FeatureInstaller {

    override val id: String = ID

    /** 0 = 尚未解析；-1 = 解析失败（后续一律用根视图），其余为宿主资源 id。 */
    private val containerId = AtomicInteger(ID_UNRESOLVED)

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val fragmentClass = KavaMemberLookup.classOrNull(loader, BRAND_SPLASH_FRAGMENT_CLASS)
            ?: return missing(environment, "missing-splash-fragment")
        val method = KavaMemberLookup.methodOrNull(
            fragmentClass,
            "onViewCreated",
            classOf<View>(),
            classOf<Bundle>()
        )?.takeIf { !it.isStatic && it.returnType == Void.TYPE }
            ?: return missing(environment, "missing-on-view-created")

        return runCatching {
            environment.registrar.exact(
                "splash.auto_night.on_view_created",
                method.declaringClass,
                method.name,
                *method.parameterTypes
            ) {
                after {
                    if (hasThrowable) return@after
                    val root = args.getOrNull(0) as? View ?: return@after
                    environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                    if (applyNightBackground(root)) {
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                    }
                }
            }
            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
            environment.reportStatus(CHANNEL_STATUS, "success")
            environment.logInfo(
                "splash_auto_night_ok",
                "[BIL] 开屏页自动亮暗已安装"
            )
            FeatureInstallResult.Installed(1)
        }.getOrElse { throwable ->
            environment.logError(
                "splash_auto_night_register",
                "[BIL] 开屏页自动亮暗 Hook 注册失败: $throwable"
            )
            missing(environment, "registration-failed")
        }
    }

    /** @return 是否真的写了背景色。 */
    private fun applyNightBackground(root: View): Boolean {
        val night = root.resources.configuration.uiMode and
            Configuration.UI_MODE_NIGHT_MASK == Configuration.UI_MODE_NIGHT_YES
        val target = resolveContainer(root) ?: root
        return runCatching {
            target.setBackgroundColor(if (night) Color.BLACK else Color.WHITE)
            true
        }.getOrDefault(false)
    }

    private fun resolveContainer(root: View): View? {
        var resolved = containerId.get()
        if (resolved == ID_UNRESOLVED) {
            resolved = runCatching {
                root.resources.getIdentifier(SPLASH_CONTAINER_ID_NAME, "id", TARGET_PACKAGE)
            }.getOrDefault(0).takeIf { it != 0 } ?: ID_MISSING
            containerId.compareAndSet(ID_UNRESOLVED, resolved)
            resolved = containerId.get()
        }
        if (resolved == ID_MISSING) return null
        return runCatching { root.findViewById<View>(resolved) }.getOrNull()
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "splash_auto_night_missing",
            "[BIL] 开屏页自动亮暗适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "splash_auto_night"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "splash_auto_night_status"
        private const val BRAND_SPLASH_FRAGMENT_CLASS =
            "tv.danmaku.bili.ui.splash.brand.ui.BaseBrandSplashFragment"
        private const val SPLASH_CONTAINER_ID_NAME = "splash_container"
        private const val ID_UNRESOLVED = 0
        private const val ID_MISSING = -1
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.view.View
import android.view.ViewGroup
import androidx.core.view.isGone
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic

/**
 * 隐藏 Story 竖屏流右侧的互动图标（每个图标单独开关），见 [StoryActionIcon]。
 *
 * 每个组件类挂两处：
 * - 构造之后 `post` 一次折叠——布局填充完、第一帧之前生效，滑到下一条时不会先闪出来；
 * - `onStart(int)` 之后再折叠一次——页面每次被激活都会走，宿主在绑定数据时改回的可见性被压回去。
 * 两处都只按类名判断归属，不读任何宿主数据。
 */
internal class StoryActionIconsFeatureInstaller(
    private val hidden: Set<StoryActionIcon>,
    /** 单测替换：把宿主实例变成可折叠的盒子；真机走 [ViewActionIconBox]。 */
    private val boxOf: (Any) -> ActionIconBox? = { (it as? View)?.let(::ViewActionIconBox) },
    /** 单测替换：构造后延迟到下一帧执行；真机走 `View.post`。 */
    private val postToView: (Any, () -> Unit) -> Unit = { target, block -> (target as? View)?.post { block() } }
) : FeatureInstaller {

    override val id: String = ID

    /** 已排过构造后折叠的实例；弱引用，不让组件活过它的页面。 */
    private val posted: MutableSet<Any> = java.util.Collections.newSetFromMap(java.util.WeakHashMap())
    override val capabilityIds: List<String> get() = hidden.map { it.capabilityId }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (hidden.isEmpty()) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        var total = 0
        var expected = 0
        val degraded = mutableListOf<String>()
        StoryActionIcon.entries.filter { it in hidden }.forEach { icon ->
            var installedForIcon = 0
            var expectedForIcon = 0
            var primaryInstalled = false
            if (icon.widgetClasses.none { KavaMemberLookup.classOrNull(loader, it) != null }) {
                // 整个图标在该宿主上都不存在（弹幕开关 9.4.0 起才有）：没有东西可藏，不算缺失。
                environment.reportCapability(icon.capabilityId, FeatureInstallResult.Skipped("not-applicable-host"))
                return@forEach
            }
            icon.widgetClasses.forEachIndexed { index, className ->
                val widget = KavaMemberLookup.classOrNull(loader, className) ?: return@forEachIndexed
                expectedForIcon += 1
                if (installWidget(environment, icon, widget)) {
                    installedForIcon += 1
                    if (index == 0) primaryInstalled = true
                }
            }
            if (!primaryInstalled) degraded += icon.name.lowercase()
            environment.reportCapabilityCoverage(
                icon.capabilityId,
                primaryInstalled,
                installedForIcon,
                expectedForIcon.coerceAtLeast(1)
            )
            total += installedForIcon
            expected += expectedForIcon.coerceAtLeast(1)
        }
        if (total == 0) return missing(environment, "missing-host-structure")
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        val complete = degraded.isEmpty() && total == expected
        val status = if (complete) "success" else "partial:$total/$expected" +
            degraded.takeIf { it.isNotEmpty() }?.joinToString(prefix = ";missing=", separator = ",").orEmpty()
        environment.reportStatus(CHANNEL_STATUS, status)
        if (complete) {
            environment.logInfo("story_action_icons_ok", "[BIL] 竖屏页互动图标隐藏已安装，widgets=$total")
        } else {
            environment.logError("story_action_icons_partial", "[BIL] 竖屏页互动图标隐藏部分安装，status=$status")
        }
        return FeatureInstallResult.Installed(total, complete = complete)
    }

    /** 一个组件类：`onStart(int)` 必须装上才算这个类可用；构造后的提前折叠是锦上添花。 */
    private fun installWidget(environment: HookEnvironment, icon: StoryActionIcon, widget: Class<*>): Boolean {
        val onStart = KavaMemberLookup.declaredMethods(widget, makeAccessible = true) {
            !it.isStatic && it.name == ON_START && it.parameterTypes.contentEquals(arrayOf(classOf<Int>()))
        }.singleOrNull() ?: run {
            environment.logError("story_action_icons_${icon.name.lowercase()}_shape",
                "[BIL] 竖屏页互动图标 ${widget.simpleName} 缺少 onStart(int)")
            return false
        }
        val installed = runCatching {
            environment.registrar.exact(
                "$ID.${widget.simpleName}.onStart",
                onStart.declaringClass,
                onStart.name,
                *onStart.parameterTypes
            ) {
                after { instance?.let { collapse(environment, icon, it) } }
            }
        }.onFailure { throwable ->
            environment.logError("story_action_icons_${widget.simpleName}",
                "[BIL] 竖屏页互动图标 Hook 注册失败(${widget.simpleName}#onStart): $throwable")
        }.isSuccess
        if (!installed) return false
        KavaMemberLookup.declaredConstructors(widget) { constructor ->
            constructor.parameterTypes.firstOrNull()?.name == CONTEXT_CLASS
        }.forEachIndexed { index, constructor ->
            runCatching {
                environment.registrar.constructor("$ID.${widget.simpleName}.init.$index", constructor) {
                    after {
                        val target = instance ?: return@after
                        // 宿主的构造函数互相委托，一次填充会触发多次；每个实例只排一次。
                        if (!synchronized(posted) { posted.add(target) }) return@after
                        postToView(target) { collapse(environment, icon, target) }
                    }
                }
            }
        }
        return true
    }

    private fun collapse(environment: HookEnvironment, icon: StoryActionIcon, target: Any) {
        val box = runCatching { boxOf(target) }.getOrNull() ?: return
        environment.reportRuntimeEvidence(icon.capabilityId, FeatureRuntimeStage.OBSERVED)
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
        val changed = runCatching { StoryActionIconCollapse.collapse(box) }.getOrElse { throwable ->
            environment.reportRuntimeEvidence(icon.capabilityId, FeatureRuntimeStage.ERROR)
            environment.logError("story_action_icons_collapse", "[BIL] 竖屏页互动图标折叠失败: $throwable")
            false
        }
        if (changed) {
            environment.reportRuntimeEvidence(icon.capabilityId, FeatureRuntimeStage.APPLIED)
            environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
        }
    }

    private fun missing(environment: HookEnvironment, reason: String): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("story_action_icons_missing", "[BIL] 竖屏页互动图标隐藏适配不完整: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "story_action_icons"
        private const val CHANNEL_STATUS = "story_action_icons_status"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val ON_START = "onStart"
        private const val CONTEXT_CLASS = "android.content.Context"
    }
}

/** [ActionIconBox] 到真 `View` 的适配；只做属性转发，不做判断。 */
private class ViewActionIconBox(private val view: View) : ActionIconBox {
    override var gone: Boolean
        get() = view.isGone
        set(value) { if (value) view.isGone = true }

    override var width: Int
        get() = view.layoutParams?.width ?: 0
        set(value) { view.layoutParams?.let { it.width = value; view.layoutParams = it } }

    override var height: Int
        get() = view.layoutParams?.height ?: 0
        set(value) { view.layoutParams?.let { it.height = value; view.layoutParams = it } }

    override var margins: IntArray
        get() = (view.layoutParams as? ViewGroup.MarginLayoutParams)
            ?.let { intArrayOf(it.leftMargin, it.topMargin, it.rightMargin, it.bottomMargin) } ?: IntArray(4)
        set(value) {
            (view.layoutParams as? ViewGroup.MarginLayoutParams)?.let {
                it.setMargins(value[0], value[1], value[2], value[3])
                view.layoutParams = it
            }
        }

    override var alpha: Float
        get() = view.alpha
        set(value) { view.alpha = value }

    override var clickable: Boolean
        get() = view.isClickable
        set(value) { view.isClickable = value }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import java.lang.reflect.Method

/** 在 Story 响应与播放器列表边界按 StoryDetail 的公开类型判断过滤。 */
internal class StoryPurifyFeatureInstaller(
    private val removeAds: Boolean,
    private val removeLive: Boolean,
    private val removeGames: Boolean,
    private val removeBangumi: Boolean,
    private val removeCourses: Boolean,
    private val removeShortDrama: Boolean,
    private val removeShopping: Boolean,
    private val removeMovies: Boolean,
    private val removeDocumentaries: Boolean,
    private val removeTv: Boolean,
    private val removeVariety: Boolean,
    private val removeMusic: Boolean,
    private val points: VersionAdapter.StoryFeedPoints?
) : FeatureInstaller {

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (removeAds) add("story_ads_removed")
        if (removeLive) add("story_live_removed")
        if (removeGames) add("story_games_removed")
        if (removeBangumi) add("story_bangumi_removed")
        if (removeCourses) add("story_courses_removed")
        if (removeShortDrama) add("story_short_drama_removed")
        if (removeShopping) add("story_shopping_removed")
        if (removeMovies) add("story_movies_removed")
        if (removeDocumentaries) add("story_documentaries_removed")
        if (removeTv) add("story_tv_removed")
        if (removeVariety) add("story_variety_removed")
        if (removeMusic) add("story_music_removed")
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!removeAds && !removeLive && !removeGames && !removeBangumi && !removeCourses &&
            !removeShortDrama && !removeShopping && !removeMovies && !removeDocumentaries &&
            !removeTv && !removeVariety && !removeMusic) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = points ?: return missing(environment, "missing-adapter-point")
        val accessors = Accessors(
            ad = resolveOptional(environment, "ad", adapted.adGetter),
            live = resolveOptional(environment, "live", adapted.liveGetter),
            game = resolveOptional(environment, "game", adapted.gameGetter),
            bangumi = resolveOptional(environment, "bangumi", adapted.bangumiGetter),
            course = resolveOptional(environment, "course", adapted.courseGetter),
            music = resolveOptional(environment, "music", adapted.musicGetter),
            cartInfo = resolveOptional(environment, "cart_info", adapted.cartInfoGetter),
            dramaPrompt = resolveOptional(environment, "drama_prompt", adapted.dramaPromptGetter),
            seasonInfo = resolveOptional(environment, "season_info", adapted.seasonInfoGetter),
            seasonType = resolveOptional(environment, "season_type", adapted.seasonTypeGetter)
        )
        val readable = capabilityIds.associateWith { capability -> when (capability) {
            "story_ads_removed" -> accessors.ad != null
            "story_live_removed" -> accessors.live != null
            "story_games_removed" -> accessors.game != null
            "story_bangumi_removed" -> accessors.bangumi != null
            "story_courses_removed" -> accessors.course != null
            "story_short_drama_removed" -> accessors.dramaPrompt != null
            "story_shopping_removed" -> accessors.cartInfo != null
            "story_music_removed" -> accessors.music != null
            else -> accessors.seasonInfo != null && accessors.seasonType != null
        } }
        if (readable.values.none { it }) {
            return missing(environment, "missing-enabled-type-getter")
        }

        var installed = 0
        adapted.responseItemGetters.forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("story.response.$index", point) {
                    after {
                        if (hasThrowable) return@after
                        val source = result as? List<*> ?: return@after
                        filter(source, accessors)?.let { filtered -> result = filtered }
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "story_response_$index",
                    "[BIL] Story 响应过滤 Hook 注册失败: $throwable"
                )
            }
        }
        adapted.pagerListMethods.forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("story.pager.$index", point) {
                    before {
                        val source = args.firstOrNull() as? List<*> ?: return@before
                        filter(source, accessors)?.let { filtered -> args[0] = filtered }
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "story_pager_$index",
                    "[BIL] Story 播放器过滤 Hook 注册失败: $throwable"
                )
            }
        }
        if (installed == 0) return missing(environment, "registration-failed")
        // 缺失一个类型时只降级该类型；其他已选判据继续在原有响应/播放器边界工作。
        val expected = adapted.responseItemGetters.size + adapted.pagerListMethods.size
        capabilityIds.forEach { environment.reportCapabilityCoverage(it, readable.getValue(it), installed, expected) }
        val complete = installed == expected && readable.values.all { it }
        environment.reportStatus(CHANNEL_STATUS, if (complete) "success" else "partial:$installed/$expected;unreadable=${readable.count { !it.value }}")
        environment.logInfo("story_purify_ok", "[BIL] Story 竖屏视频净化已安装")
        return FeatureInstallResult.Installed(installed, complete)
    }

    private fun filter(source: List<*>, accessors: Accessors): List<*>? {
        val filtered = CopyOnFilter.list(source) { item -> shouldRemove(signals(item, accessors)) }
        return filtered.takeIf { it !== source }
    }

    private fun signals(item: Any, accessors: Accessors): Signals = Signals(
        ad = removeAds && invokeBoolean(accessors.ad, item),
        live = removeLive && invokeBoolean(accessors.live, item),
        game = removeGames && invokeBoolean(accessors.game, item),
        bangumi = removeBangumi && invokeBoolean(accessors.bangumi, item),
        course = removeCourses && invokeBoolean(accessors.course, item),
        shortDrama = removeShortDrama && invokePresent(accessors.dramaPrompt, item),
        shopping = removeShopping && invokePresent(accessors.cartInfo, item),
        music = removeMusic && invokeBoolean(accessors.music, item),
        seasonType = if (removeMovies || removeDocumentaries || removeTv || removeVariety) {
            invokeInt(accessors.seasonType, invokeCompatible(accessors.seasonInfo, item))
        } else {
            null
        }
    )

    private fun shouldRemove(signals: Signals): Boolean =
        (removeAds && signals.ad) ||
            (removeLive && signals.live) ||
            (removeGames && signals.game) ||
            (removeBangumi && signals.bangumi) ||
            (removeCourses && signals.course) ||
            (removeShortDrama && signals.shortDrama) ||
            (removeShopping && signals.shopping) ||
            (removeMusic && signals.music) ||
            (removeMovies && signals.seasonType == SEASON_TYPE_MOVIE) ||
            (removeDocumentaries && signals.seasonType == SEASON_TYPE_DOCUMENTARY) ||
            (removeTv && signals.seasonType == SEASON_TYPE_TV) ||
            (removeVariety && signals.seasonType == SEASON_TYPE_VARIETY)

    private fun resolveOptional(
        environment: HookEnvironment,
        suffix: String,
        point: VersionAdapter.HookPoint?
    ): Method? = point?.let {
        environment.hookPoints.resolveAdapted(
            "story.resolve.$suffix",
            it.className,
            it.methodName,
            it.paramClassNames
        )
    }

    private fun invokeBoolean(method: Method?, target: Any): Boolean {
        return (invokeCompatible(method, target) as? Boolean) == true
    }

    private fun invokePresent(method: Method?, target: Any): Boolean =
        invokeCompatible(method, target) != null

    private fun invokeInt(method: Method?, target: Any?): Int? =
        invokeCompatible(method, target) as? Int

    private fun invokeCompatible(method: Method?, target: Any?): Any? {
        if (method == null || target == null || !method.declaringClass.isInstance(target)) return null
        return runCatching { method.invoke(target) }.getOrNull()
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError("story_purify_missing", "[BIL] Story 净化适配不完整: $reason")
        return FeatureInstallResult.Skipped(reason)
    }

    internal data class Signals(
        val ad: Boolean = false,
        val live: Boolean = false,
        val game: Boolean = false,
        val bangumi: Boolean = false,
        val course: Boolean = false,
        val shortDrama: Boolean = false,
        val shopping: Boolean = false,
        val music: Boolean = false,
        val seasonType: Int? = null
    )

    private data class Accessors(
        val ad: Method?,
        val live: Method?,
        val game: Method?,
        val bangumi: Method?,
        val course: Method?,
        val music: Method?,
        val cartInfo: Method?,
        val dramaPrompt: Method?,
        val seasonInfo: Method?,
        val seasonType: Method?
    )

    companion object {
        const val ID = "story_purify"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "story_purify_status"
        internal const val SEASON_TYPE_MOVIE = 2
        internal const val SEASON_TYPE_DOCUMENTARY = 3
        internal const val SEASON_TYPE_TV = 5
        internal const val SEASON_TYPE_VARIETY = 7

        internal fun shouldRemove(
            signals: Signals,
            removeAds: Boolean,
            removeLive: Boolean,
            removeGames: Boolean,
            removeBangumi: Boolean = false,
            removeCourses: Boolean = false,
            removeShortDrama: Boolean = false,
            removeShopping: Boolean = false,
            removeMovies: Boolean = false,
            removeDocumentaries: Boolean = false,
            removeTv: Boolean = false,
            removeVariety: Boolean = false,
            removeMusic: Boolean = false
        ): Boolean = (removeAds && signals.ad) ||
            (removeLive && signals.live) ||
            (removeGames && signals.game) ||
            (removeBangumi && signals.bangumi) ||
            (removeCourses && signals.course) ||
            (removeShortDrama && signals.shortDrama) ||
            (removeShopping && signals.shopping) ||
            (removeMusic && signals.music) ||
            (removeMovies && signals.seasonType == SEASON_TYPE_MOVIE) ||
            (removeDocumentaries && signals.seasonType == SEASON_TYPE_DOCUMENTARY) ||
            (removeTv && signals.seasonType == SEASON_TYPE_TV) ||
            (removeVariety && signals.seasonType == SEASON_TYPE_VARIETY)
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isStatic
import java.lang.reflect.Method

/**
 * 打开宿主自带的「后台播放使用系统媒体控制」开关。
 *
 * 这个能力宿主已经实现，只是被设备决策位关着。所以这里不自己造通知，只在
 * `DeviceDecision#getBoolean(String, ...)` 这一个查询边界上，对
 * [DEVICE_DECISION_KEY] 这一个 key 返回 true。
 *
 * **为什么不挂 `ConfigManager$Companion#isHitFF`**（哔哩漫游的做法）：
 * 2026-09-06 对 8.84.0–9.11.0 共 26 个宿主版本逐个扫描 dex 字符串，
 * `ff_background_use_system_media_controls` **一次都没有出现过**，而
 * `dd_enable_system_media_control` 26 版全都在。`isHitFF` 又是启动期被 20 个 dex 调用的热
 * 路径，挂一个永远不可能命中的拦截器既白付开销，又会让覆盖分母虚高（"2/2 success"里有
 * 一半永远不干活）。将来某次宿主接入若在 dex 里扫到了那个 key，再按同样的
 * [installKeyOverride] 形状加回来即可。
 *
 * **版本覆盖（2026-09-06 离线核对 8.84.0–9.11.0 共 26 版）**：`getBoolean(String, boolean)`
 * 26 版齐全；`dd_enable_system_media_control` 字符串 26 版都在。
 *
 * **热路径提醒**：这个方法在启动期会被调用成百上千次。回调体因此只做一次字符串相等
 * 判断，命中才写返回值，未命中立刻回落到原实现；不要在这里加任何解析、日志或集合分配。
 */
internal class SystemMediaNotificationFeatureInstaller(
    private val enabled: Boolean
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val loader = environment.classLoader ?: return missing(environment, "missing-class-loader")
        val owner = KavaMemberLookup.classOrNull(loader, DEVICE_DECISION_CLASS)
            ?: return missing(environment, "missing-config-boundary")

        // 同名多重载（当前版本有 (String, boolean) 与 (String, boolean, Function1) 两个），
        // 每个都是独立的查询入口，各算一个覆盖单位。
        val methods = KavaMemberLookup.declaredMethods(owner, makeAccessible = true) { method ->
            !method.isStatic && method.name == DEVICE_DECISION_METHOD &&
                method.returnType == classOf<Boolean>() &&
                method.parameterTypes.firstOrNull() == classOf<String>()
        }
        if (methods.isEmpty()) return missing(environment, "missing-config-boundary")

        var installed = 0
        methods.forEachIndexed { index, method ->
            if (installKeyOverride(environment, "system.media.dd.$index", method)) {
                installed += 1
            }
        }
        if (installed == 0) return missing(environment, "registration-failed")

        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        val status = if (installed == methods.size) {
            "success"
        } else {
            "partial:$installed/${methods.size}"
        }
        environment.reportStatus(CHANNEL_STATUS, status)
        if (status == "success") {
            environment.logInfo(
                "system_media_ok",
                "[BIL] 系统媒体控制通知已安装，hooks=$installed"
            )
        } else {
            environment.logError(
                "system_media_partial",
                "[BIL] 系统媒体控制通知部分安装，status=$status"
            )
        }
        return FeatureInstallResult.Installed(installed, complete = installed == methods.size)
    }

    private fun installKeyOverride(
        environment: HookEnvironment,
        id: String,
        method: Method
    ): Boolean = runCatching {
        environment.registrar.exact(
            id,
            method.declaringClass,
            method.name,
            *method.parameterTypes
        ) {
            before {
                if (argOrNull(0) != DEVICE_DECISION_KEY) return@before
                result = true
                environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
            }
        }
        true
    }.getOrElse { throwable ->
        environment.logError(
            "system_media_register_${id.substringAfterLast('.')}",
            "[BIL] 系统媒体控制通知 Hook 注册失败($id): $throwable"
        )
        false
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "system_media_missing",
            "[BIL] 系统媒体控制通知适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "system_media_notification"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "system_media_notification_status"
        private const val DEVICE_DECISION_CLASS = "com.bilibili.lib.dd.DeviceDecision"
        private const val DEVICE_DECISION_METHOD = "getBoolean"
        private const val DEVICE_DECISION_KEY = "dd_enable_system_media_control"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import android.app.Activity
import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter

/** 仅关闭青少年模式提示页，不修改青少年模式状态、账户数据或设置页面。 */
internal class TeenagersModeFeatureInstaller(
    private val enabled: Boolean,
    private val points: VersionAdapter.TeenagersModePoints?
) : FeatureInstaller {

    override val id: String = ID

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        if (!enabled) {
            environment.reportStatus(CHANNEL_STATUS, "disabled")
            return FeatureInstallResult.Skipped("disabled")
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = points?.onCreateMethods?.takeIf { it.isNotEmpty() }
            ?: return missing(environment, "missing-adapter-point")

        var installedCount = 0
        adapted.forEachIndexed { index, point ->
            runCatching {
                environment.registrar.adapted("teenagers.mode.on_create.$index", point) {
                    after {
                        val activity = instance as? Activity ?: return@after
                        if (activity.isFinishing || activity.isDestroyed) return@after
                        runCatching { activity.finish() }
                            .onFailure { throwable ->
                                environment.logError(
                                    "teenagers_mode_finish_$index",
                                    "[BIL] 关闭青少年模式提示页失败(${activity.javaClass.name}): " +
                                        throwable
                                )
                            }
                    }
                }
                installedCount += 1
            }.onFailure { throwable ->
                environment.logError(
                    "teenagers_mode_method_$index",
                    "[BIL] 青少年模式提示页 Hook 注册失败(" +
                        "${point.className}#${point.methodName}): $throwable"
                )
            }
        }

        if (installedCount == 0) return missing(environment, "registration-failed")
        val status = if (installedCount == adapted.size) {
            "success"
        } else {
            "partial:$installedCount/${adapted.size}"
        }
        environment.reportStatus(CHANNEL_STATUS, status)
        if (installedCount == adapted.size) {
            environment.logInfo(
                "teenagers_mode_ok",
                "[BIL] 青少年模式提示页关闭功能已安装，hooks=$installedCount"
            )
        } else {
            environment.logError(
                "teenagers_mode_partial",
                "[BIL] 青少年模式提示页关闭功能部分安装，hooks=$installedCount/${adapted.size}"
            )
        }
        return FeatureInstallResult.Installed(installedCount, complete = installedCount == adapted.size)
    }

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "teenagers_mode_missing",
            "[BIL] 青少年模式提示页适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val ID = "teenagers_mode_prompt"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "teenagers_mode_status"
    }
}

package com.Bilibili_Innocent_Lab.xposedmodule.hook.feature

import com.Bilibili_Innocent_Lab.xposedmodule.hook.VersionAdapter
import com.Bilibili_Innocent_Lab.xposedmodule.runtime.KavaMemberLookup
import com.highcapable.kavaref.extension.classOf
import com.highcapable.kavaref.extension.isSubclassOf
import java.lang.reflect.Field
import java.lang.reflect.Method
import java.util.concurrent.atomic.AtomicBoolean

/** 按相关推荐卡片的公开枚举/路由类型做精确过滤。 */
internal class VideoRelateFilterFeatureInstaller(
    private val hiddenTypes: Set<String>,
    minDurationSeconds: Int,
    maxDurationSeconds: Int,
    private val matchingEnhancementEnabled: Boolean = false,
    private val strongModeEnabled: Boolean = false,
    private val reasonFilterEnabled: Boolean = false,
    rawReasonKeywords: String = "",
    private val points: VersionAdapter.VideoRelatePoints?,
    /** 作者黑名单（UP 名或 mid，整串相等）。 */
    rawBlockedAuthors: String = "",
    /** 标签黑名单（分区标签，整串相等）。 */
    rawBlockedTags: String = "",
    private val sectionPickEnabled: Boolean = false,
    rawPickedTagIds: String = "",
    minPlayCount: Int = 0,
    maxPlayCount: Int = 0,
    /**
     * 智能过滤推荐视频（JEV，按标题）。列表 getter 可能在主线程：主线程只查缓存并投后台；
     * 后台线程且开了"首屏等待"时在当前线程等结果。
     */
    semanticJudge: SemanticJudge? = null,
    /** debug 构建的观测日志目录；release 为 null。 */
    semanticLogDir: java.io.File? = null,
    isMainThread: () -> Boolean = { android.os.Looper.myLooper() == android.os.Looper.getMainLooper() }
) : FeatureInstaller {

    private val semantic = SemanticTitleFilter(semanticJudge, semanticLogDir, isMainThread, "relate")

    private val durationRange = VideoDurationRange(minDurationSeconds, maxDurationSeconds)
    private val playCountRange = VideoPlayCountRange(minPlayCount, maxPlayCount)
    private val customReasonKeywords = if (matchingEnhancementEnabled && reasonFilterEnabled) {
        VideoRelateReasonMatcher.parseCustom(rawReasonKeywords)
    } else {
        emptySet()
    }
    private val blockedAuthors = ExactRuleSetCodec.parse(rawBlockedAuthors)
    private val blockedTags = ExactRuleSetCodec.parse(rawBlockedTags)
    private val pickedTagIds = if (sectionPickEnabled) TidBlocklistCodec.parse(rawPickedTagIds) else emptySet()

    override val id: String = ID
    override val capabilityIds: List<String> get() = buildList {
        if (hiddenTypes.any { normalizeType(it) == "CM" }) add("video_related_commercial_removed")
        if (hiddenTypes.any { normalizeType(it) == "GAME" }) add("video_related_game_removed")
        if (hiddenTypes.any { normalizeType(it) == "LIVE" }) add("video_related_live_removed")
        if (hiddenTypes.any { normalizeType(it) == "COURSE" }) add("video_related_course_removed")
        if (hiddenTypes.any { normalizeType(it) == "SPECIAL" }) add("video_related_special_removed")
        // 声明口径必须与覆盖判定的 usable 一致：勾的类型里没有广告/话题、也没开强力模式
        // 或自定义理由时，增强逻辑根本不会生效，声明出来只会得到"声明了却不可用"的假覆盖。
        if (matchingEnhancementEnabled && (hiddenTypes.any {
                HostContentSemanticClassifier.hiddenKind(normalizeType(it)) in REASON_ENHANCEMENT_KINDS
            } || customReasonKeywords.isNotEmpty() || strongModeEnabled)
        ) add("video_related_matching_enhancement_enabled")
        if (matchingEnhancementEnabled && strongModeEnabled) add("video_related_strong_mode_enabled")
        if (customReasonKeywords.isNotEmpty()) add("video_related_reason_filter_enabled")
        if (durationRange.isEnabled) add("video_related_duration_filter")
        if (playCountRange.isEnabled) add("video_related_play_count_filter")
        if (blockedAuthors.isNotEmpty()) add("video_related_author_block")
        if (blockedTags.isNotEmpty()) add("video_related_tag_block")
        if (semantic.enabled) add(CAPABILITY_SEMANTIC)
    }

    override fun install(environment: HookEnvironment): FeatureInstallResult {
        val normalizedHidden = hiddenTypes.mapTo(linkedSetOf(), ::normalizeType)
            .filterTo(linkedSetOf()) { it.isNotBlank() }
        val promotionReasonEnhancementActive = matchingEnhancementEnabled &&
            normalizedHidden.any { hidden ->
                HostContentSemanticClassifier.hiddenKind(hidden) in REASON_ENHANCEMENT_KINDS
            }
        val strongModeActive = matchingEnhancementEnabled && strongModeEnabled
        val reasonFilteringActive = promotionReasonEnhancementActive ||
            customReasonKeywords.isNotEmpty() || strongModeActive
        val typeObservationActive = normalizedHidden.isNotEmpty() || strongModeActive
        if (durationRange.isConfigured && !durationRange.isValid) {
            environment.logError(
                "video_relate_duration_invalid",
                "[BIL] 推荐视频时长范围无效，已保守放行: " +
                    "min=${durationRange.minSeconds},max=${durationRange.maxSeconds}"
            )
        }
        if (playCountRange.isConfigured && !playCountRange.isValid) {
            environment.logError(
                "video_relate_play_count_invalid",
                "[BIL] 推荐视频播放量范围无效，已保守放行: " +
                    "min=${playCountRange.minimum},max=${playCountRange.maximum}"
            )
        }
        // 作者/标签名单也算"开着"，否则只设名单不勾类型时整个功能会被判 disabled。
        if (normalizedHidden.isEmpty() && !durationRange.isEnabled && !playCountRange.isEnabled &&
            !reasonFilteringActive &&
            blockedAuthors.isEmpty() && blockedTags.isEmpty() && !sectionPickEnabled && pickedTagIds.isEmpty() &&
            !semantic.enabled
        ) {
            val reason = when {
                durationRange.isConfigured && !durationRange.isValid -> "invalid-duration-range"
                playCountRange.isConfigured && !playCountRange.isValid -> "invalid-play-count-range"
                else -> "disabled"
            }
            environment.reportStatus(CHANNEL_STATUS, reason)
            return FeatureInstallResult.Skipped(reason)
        }
        if (environment.processName != TARGET_PACKAGE) {
            return FeatureInstallResult.Skipped("non-main-process")
        }
        val adapted = points ?: return missing(environment, "missing-adapter-point")
        val typeEvidence = if (typeObservationActive) {
            buildList {
                adapted.cardCaseGetters.forEachIndexed { index, point ->
                    resolve(environment, "case.$index", point)?.let(::add)
                }
                adapted.gotoGetters.forEachIndexed { index, point ->
                    resolve(environment, "goto.$index", point)?.let(::add)
                }
                adapted.cardTypeGetters.forEachIndexed { index, point ->
                    resolve(environment, "type.$index", point)?.let(::add)
                }
            }
                .distinctBy(Method::toGenericString)
        } else {
            emptyList()
        }
        val relateTypeEvidence = if (typeObservationActive) {
            adapted.relateCardTypeGetters.mapIndexedNotNull { index, point ->
                resolve(environment, "relate_type.$index", point)
            }.distinctBy(Method::toGenericString)
        } else {
            emptyList()
        }
        val sourceTypeEvidence = if (typeObservationActive) {
            adapted.fromSourceTypeGetters.mapIndexedNotNull { index, point ->
                resolve(environment, "source_type.$index", point)
            }.distinctBy(Method::toGenericString)
        } else {
            emptyList()
        }
        val sourceTypeChainEvidence = if (typeObservationActive) {
            adapted.fromSourceTypeChains.mapIndexedNotNull { index, chain ->
                val itemGetter = resolve(
                    environment,
                    "source_type_chain.item.$index",
                    chain.itemGetter
                ) ?: return@mapIndexedNotNull null
                val sourceTypeGetter = resolve(
                    environment,
                    "source_type_chain.value.$index",
                    chain.sourceTypeGetter
                ) ?: return@mapIndexedNotNull null
                itemGetter to sourceTypeGetter
            }.distinctBy { (itemGetter, sourceTypeGetter) ->
                itemGetter.toGenericString() + "->" + sourceTypeGetter.toGenericString()
            }
        } else {
            emptyList()
        }
        val relateTypeValueEvidence = if (typeObservationActive) {
            adapted.relateCardTypeValueGetters.mapIndexedNotNull { index, point ->
                resolve(environment, "relate_type_value.$index", point)
            }.distinctBy(Method::toGenericString)
        } else {
            emptyList()
        }
        val hasTypeEvidence = typeEvidence.isNotEmpty() || relateTypeEvidence.isNotEmpty() ||
            sourceTypeEvidence.isNotEmpty() || sourceTypeChainEvidence.isNotEmpty() ||
            relateTypeValueEvidence.isNotEmpty()
        val durationPaths = resolveDurationPaths(environment, adapted)
        val playCountPaths = resolvePlayCountPaths(environment, adapted)
        val reasonPaths = resolveReasonPaths(environment, adapted, reasonFilteringActive)
        // 作者名与 mid 合成同一组链：两者都按字符串比，用户填名或填 mid 都能命中。
        val authorPaths = resolveChainPaths(
            environment,
            adapted.authorNameChains + adapted.authorMidChains,
            "author",
            blockedAuthors.isNotEmpty()
        )
        val tagPaths = resolveChainPaths(
            environment, adapted.tagNameChains, "tag", blockedTags.isNotEmpty()
        )
        val commercialEvidencePaths = resolveCommercialEvidencePaths(
            environment,
            adapted,
            strongModeActive
        )
        val partialReasons = mutableListOf<String>()
        if (typeObservationActive && !hasTypeEvidence) {
            if (!strongModeActive && durationPaths.isEmpty() && reasonPaths.isEmpty()) {
                return missing(environment, "missing-type-getter")
            }
            partialReasons += "missing-type-getter"
            environment.logError(
                "video_relate_type_missing",
                "[BIL] 详情页推荐类型读取适配不完整，按当前模式继续处理"
            )
        }
        if (durationRange.isEnabled && durationPaths.isEmpty()) {
            if (!strongModeActive && !hasTypeEvidence && reasonPaths.isEmpty() &&
                playCountPaths.isEmpty() && blockedAuthors.isEmpty() && blockedTags.isEmpty()
            ) {
                return missing(environment, "missing-duration-accessor")
            }
            partialReasons += "missing-duration-accessor"
            environment.logError(
                "video_relate_duration_missing",
                "[BIL] 详情页推荐时长读取适配不完整，现有类型过滤继续生效"
            )
        }
        if (playCountRange.isEnabled && playCountPaths.isEmpty()) {
            if (!strongModeActive && !hasTypeEvidence && durationPaths.isEmpty() &&
                reasonPaths.isEmpty() && blockedAuthors.isEmpty() && blockedTags.isEmpty()
            ) {
                return missing(environment, "missing-play-count-accessor")
            }
            partialReasons += "missing-play-count-accessor"
            environment.logError(
                "video_relate_play_count_missing",
                "[BIL] 详情页推荐播放量读取适配不完整，现有过滤继续生效"
            )
        }
        if (reasonFilteringActive && reasonPaths.isEmpty()) {
            if (!strongModeActive && !hasTypeEvidence && durationPaths.isEmpty()) {
                return missing(environment, "missing-reason-accessor")
            }
            partialReasons += "missing-reason-accessor"
            environment.logError(
                "video_relate_reason_missing",
                "[BIL] 详情页结构化推荐理由读取适配不完整，按当前模式继续处理"
            )
        }

        // 名单非空却读不到对应字段：必须报 partial，否则每张卡都拿空值、
        // 静默变成"从不命中"，用户只会看到"设了名单但没生效"而状态一路 success。
        if (blockedAuthors.isNotEmpty() && authorPaths.isEmpty()) {
            partialReasons += "missing-author-accessor"
            environment.logError(
                "video_relate_author_missing",
                "[BIL] 详情页作者读取适配不完整，作者档不生效，其余判据继续"
            )
        }
        if (blockedTags.isNotEmpty() && tagPaths.isEmpty()) {
            partialReasons += "missing-tag-accessor"
            environment.logError(
                "video_relate_tag_missing",
                "[BIL] 详情页标签读取适配不完整，标签档不生效，其余判据继续"
            )
        }

        val responseListFields = adapted.responseItemGetters.map { point ->
            resolveResponseListField(environment, point)
        }
        if (responseListFields.any { it == null }) {
            partialReasons += "missing-response-writeback"
            environment.logError(
                "video_relate_response_writeback_missing",
                "[BIL] 部分详情页推荐响应缺少唯一列表字段，返回值过滤仍继续生效"
            )
        }
        val detailServiceAccess = adapted.detailRelateService?.let { point ->
            resolveDetailRelateServiceAccess(environment, point)
        }
        if (detailServiceAccess == null) {
            partialReasons += "missing-service-layer"
            environment.logError(
                "video_relate_service_missing",
                "[BIL] 详情页推荐组件第二层未唯一定位，第一层过滤仍继续生效"
            )
        }

        val shouldRemoveResponseItem: (Any) -> Boolean = filter@{ item ->
            val evidence = if (typeObservationActive) {
                extractEvidence(
                    item,
                    typeEvidence,
                    relateTypeEvidence,
                    sourceTypeEvidence,
                    sourceTypeChainEvidence,
                    relateTypeValueEvidence
                )
            } else {
                null
            }
            val typeMatched = if (normalizedHidden.isNotEmpty() && evidence != null) {
                matchesNormalizedEvidence(
                    evidence.types,
                    evidence.relateCardTypes,
                    evidence.fromSourceTypes,
                    evidence.relateCardTypeValues,
                    normalizedHidden
                )
            } else {
                false
            }
            if (typeMatched) return@filter true
            // 作者与标签是独立维度：整串相等，读不到一律放行。
            // 放在类型之后、时长之前，判据互不依赖，谁缺失都不影响其余档。
            if (blockedAuthors.isNotEmpty() && ExactRuleSetCodec.matches(
                    blockedAuthors, *readTexts(item, authorPaths).toTypedArray()
                )) return@filter true
            if (blockedTags.isNotEmpty() && ExactRuleSetCodec.matches(
                    blockedTags, *readTexts(item, tagPaths).toTypedArray()
                )) return@filter true
            if (durationRange.shouldRemove(
                    VideoDurationReader.fromMethods(item, durationPaths)
                )) return@filter true
            if (playCountRange.shouldRemove(
                    VideoPlayCountReader.fromMethods(item, playCountPaths)
                )) return@filter true
            if (strongModeActive && VideoRelateBooleanEvidenceReader
                    .hasPositiveEvidence(item, commercialEvidencePaths)
            ) return@filter true
            if (strongModeActive && (
                    evidence == null || !hasRecognizedTypeEvidence(evidence)
                )
            ) return@filter true
            if (!reasonFilteringActive) return@filter false
            val observation = VideoRelateReasonReader.observe(item, reasonPaths)
            val reasons = observation.reasons
            val regularReasonMatched = VideoRelateReasonMatcher.matchesCustom(
                reasons,
                customReasonKeywords
            ) || (
                promotionReasonEnhancementActive &&
                    VideoRelateReasonMatcher.matchesHighConfidencePromotion(reasons)
                )
            regularReasonMatched || (
                strongModeActive && (
                    !observation.hasUsableReason ||
                        VideoRelateReasonMatcher.matchesStrongModePromotion(reasons) ||
                        VideoRelateReasonMatcher.matchesLikeCount(reasons)
                    )
                )
        }
        val writeBackFailureLogged = AtomicBoolean(false)

        var installed = 0
        adapted.responseItemGetters.forEachIndexed { index, point ->
            val responseListField = responseListFields[index]
            runCatching {
                environment.registrar.adapted("video.relate.response.$index", point) {
                    after {
                        val source = result as? List<*> ?: return@after
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        val semanticVerdicts = semantic.verdicts(source) { item -> SemanticTitleReader.read(item) }
                        val filtered = CopyOnFilter.list(source) { item ->
                            semanticVerdicts?.get(item) == SemanticVerdict.BLOCK || shouldRemoveResponseItem(item)
                        }
                        if (filtered !== source) {
                            result = filtered
                            if (responseListField != null && !writeBackVideoRelateItems(
                                    target = thisObject,
                                    field = responseListField,
                                    items = filtered
                                ) && writeBackFailureLogged.compareAndSet(false, true)
                            ) {
                                environment.logError(
                                    "video_relate_response_writeback_failed",
                                    "[BIL] 详情页推荐响应列表写回失败，已保留返回值过滤结果"
                                )
                            }
                            environment.reportRuntimeEvidence(
                                ID,
                                FeatureRuntimeStage.APPLIED,
                                source.size - filtered.size
                            )
                            environment.logInfo(
                                "video_relate_removed",
                                "[BIL] 视频相关推荐过滤已移除 " +
                                    "${source.size - filtered.size} 项"
                            )
                        }
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                environment.logError(
                    "video_relate_$index",
                    "[BIL] 视频相关推荐类型过滤 Hook 注册失败(" +
                        "${point.className}#${point.methodName}): $throwable"
                )
            }
        }

        detailServiceAccess?.let { access ->
            val pickedTags = if (sectionPickEnabled || pickedTagIds.isNotEmpty()) {
                access.componentFactory.parameterTypes.firstOrNull()?.let(RelatedFeedbackTags::resolve)
            } else null
            if ((sectionPickEnabled || pickedTagIds.isNotEmpty()) && pickedTags == null) {
                partialReasons += "missing-picked-tag-accessor"
            }
            runCatching {
                environment.registrar.exact(
                    "video.relate.service",
                    access.componentFactory.declaringClass,
                    access.componentFactory.name,
                    *access.componentFactory.parameterTypes
                ) {
                    before {
                        val item = args.firstOrNull() ?: return@before
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.OBSERVED)
                        val tagBlocked = runCatching {
                            pickedTags?.matches(item, pickedTagIds,
                                if (sectionPickEnabled) SectionPickSession.current else emptySet()) == true
                        }.getOrElse {
                            environment.logError("video_relate_picked_tag_read", "[BIL] 所选标签读取失败，保留其他推荐过滤: ${it.javaClass.simpleName}")
                            false
                        }
                        val semanticBlocked = semantic.enabled && semantic.verdictOf(item) { card ->
                            access.titleGetter?.takeIf { it.declaringClass.isInstance(card) }
                                ?.let { runCatching { it.invoke(card) as? String }.getOrNull() }
                                ?: SemanticTitleReader.read(card)
                        } == SemanticVerdict.BLOCK
                        if (!tagBlocked && !semanticBlocked && !shouldRemoveDetailServiceItem(
                                item = item,
                                access = access,
                                normalizedHidden = normalizedHidden,
                                typeMethods = typeEvidence,
                                relateTypeMethods = relateTypeEvidence,
                                sourceTypeMethods = sourceTypeEvidence,
                                sourceTypePaths = sourceTypeChainEvidence,
                                relateTypeValueMethods = relateTypeValueEvidence,
                                reasonPaths = reasonPaths,
                                commercialEvidencePaths = commercialEvidencePaths,
                                promotionReasonEnhancementActive = promotionReasonEnhancementActive,
                                strongModeActive = strongModeActive
                            )
                        ) return@before
                        result = null
                        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.APPLIED)
                        environment.logInfo(
                            "video_relate_service_blocked",
                            "[BIL] 详情页推荐组件第二层已阻止一个匹配条目"
                        )
                    }
                }
                installed += 1
            }.onFailure { throwable ->
                partialReasons += "service-registration-failed"
                environment.logError(
                    "video_relate_service_registration",
                    "[BIL] 详情页推荐组件第二层注册失败，第一层仍继续生效: $throwable"
                )
            }
        }
        if (installed == 0) return missing(environment, "registration-failed")
        val sharedExpected = adapted.responseItemGetters.size.coerceAtLeast(1) + 1 +
            if (responseListFields.any { it == null }) 1 else 0
        for (capability in capabilityIds) {
            val usable = when (capability) {
                "video_related_duration_filter" -> durationPaths.isNotEmpty()
                "video_related_play_count_filter" -> playCountPaths.isNotEmpty()
                "video_related_reason_filter_enabled" -> reasonPaths.isNotEmpty()
                "video_related_matching_enhancement_enabled" ->
                    (promotionReasonEnhancementActive && reasonPaths.isNotEmpty()) ||
                        (customReasonKeywords.isNotEmpty() && reasonPaths.isNotEmpty()) || strongModeActive
                "video_related_strong_mode_enabled" -> strongModeActive
                "video_related_author_block" -> authorPaths.isNotEmpty()
                "video_related_tag_block" -> tagPaths.isNotEmpty()
                CAPABILITY_SEMANTIC -> true // 标题按运行期结构定位；读不到的卡片按规则放行
                else -> hasTypeEvidence
            }
            // Strong mode's fallbacks are intentional, but missing readable inputs are still partial coverage.
            val incompleteStrongInputs = capability == "video_related_strong_mode_enabled" &&
                (!hasTypeEvidence || reasonPaths.isEmpty())
            environment.reportCapabilityCoverage(capability, usable, installed,
                sharedExpected + if (incompleteStrongInputs) 1 else 0)
        }
        environment.reportRuntimeEvidence(ID, FeatureRuntimeStage.ADAPTED)
        environment.reportStatus(
            CHANNEL_STATUS,
            partialReasons.takeIf { it.isNotEmpty() }
                ?.joinToString(prefix = "partial:", separator = "+")
                ?: "success"
        )
        environment.logInfo(
            "video_relate_ok",
            "[BIL] 视频相关推荐过滤已安装，types=$normalizedHidden," +
                "duration=${durationRange.isEnabled}," +
                "playCount=${playCountRange.isEnabled}," +
                "reasonEnhancement=$promotionReasonEnhancementActive," +
                "strongMode=$strongModeActive," +
                "responseWriteback=${responseListFields.count { it != null }}," +
                "service=${detailServiceAccess != null}," +
                "commercialEvidence=${commercialEvidencePaths.size}," +
                "customReasonKeywords=${customReasonKeywords.size}"
        )
        return FeatureInstallResult.Installed(installed, complete = partialReasons.isEmpty())
    }

    private fun resolveResponseListField(
        environment: HookEnvironment,
        point: VersionAdapter.HookPoint
    ): Field? {
        val fieldName = point.viewField?.takeIf(String::isNotBlank) ?: return null
        val loader = environment.classLoader ?: return null
        val owner = KavaMemberLookup.classOrNull(loader, point.className)
            ?: return null
        return KavaMemberLookup.fields(
            owner,
            includeSuperclasses = true,
            makeAccessible = true
        ) { field -> field.name == fieldName && field.type isSubclassOf classOf<List<*>>() }
            .distinctBy(Field::toGenericString)
            .singleOrNull()
    }

    private fun resolveDetailRelateServiceAccess(
        environment: HookEnvironment,
        point: VersionAdapter.DetailRelateServicePoint
    ): DetailRelateServiceAccess? {
        val componentFactory = resolve(environment, "service.factory", point.componentFactory)
            ?: return null
        if (componentFactory.parameterCount != 1 || componentFactory.returnType.isPrimitive ||
            componentFactory.returnType == Void.TYPE
        ) return null
        val itemClass = componentFactory.parameterTypes.single()
        val typeField = point.typeField?.let { fieldName ->
            KavaMemberLookup.fields(
                itemClass,
                includeSuperclasses = true,
                makeAccessible = true
            ) { field -> field.name == fieldName }
                .distinctBy(Field::toGenericString)
                .singleOrNull()
        }
        val typeGetter = point.typeGetter?.let {
            resolve(environment, "service.type", it)
        }
        val titleGetter = point.titleGetter?.let {
            resolve(environment, "service.title", it)
        }
        return DetailRelateServiceAccess(
            componentFactory = componentFactory,
            typeField = typeField,
            typeGetter = typeGetter,
            titleGetter = titleGetter
        )
    }

    private fun shouldRemoveDetailServiceItem(
        item: Any,
        access: DetailRelateServiceAccess,
        normalizedHidden: Set<String>,
        typeMethods: List<Method>,
        relateTypeMethods: List<Method>,
        sourceTypeMethods: List<Method>,
        sourceTypePaths: List<Pair<Method, Method>>,
        relateTypeValueMethods: List<Method>,
        reasonPaths: List<VideoRelateReasonMethodPath>,
        commercialEvidencePaths: List<VideoRelateBooleanMethodPath>,
        promotionReasonEnhancementActive: Boolean,
        strongModeActive: Boolean
    ): Boolean {
        val baseEvidence = extractEvidence(
            item,
            typeMethods,
            relateTypeMethods,
            sourceTypeMethods,
            sourceTypePaths,
            relateTypeValueMethods
        )
        val serviceTypes = buildSet {
            access.typeGetter?.let { getter ->
                if (getter.declaringClass.isInstance(item)) {
                    runCatching { getter.invoke(item) }.getOrNull()
                        ?.let(::normalizedObservedType)
                        ?.let(::add)
                }
            }
            access.typeField?.let { field ->
                if (field.declaringClass.isInstance(item)) {
                    runCatching { field.get(item) }.getOrNull()
                        ?.let(::normalizedObservedType)
                        ?.let(::add)
                }
            }
        }
        val evidence = baseEvidence.copy(types = baseEvidence.types + serviceTypes)
        if (normalizedHidden.isNotEmpty() && matchesNormalizedEvidence(
                evidence.types,
                evidence.relateCardTypes,
                evidence.fromSourceTypes,
                evidence.relateCardTypeValues,
                normalizedHidden
            )
        ) return true
        if (strongModeActive && VideoRelateBooleanEvidenceReader.hasPositiveEvidence(
                item,
                commercialEvidencePaths
            )
        ) return true
        if (strongModeActive && !hasRecognizedTypeEvidence(evidence)) return true

        val reasonObservation = VideoRelateReasonReader.observe(item, reasonPaths)
        val reasons = reasonObservation.reasons
        if (VideoRelateReasonMatcher.matchesCustom(reasons, customReasonKeywords) ||
            promotionReasonEnhancementActive &&
            VideoRelateReasonMatcher.matchesHighConfidencePromotion(reasons)
        ) return true
        val title = access.titleGetter?.takeIf { it.declaringClass.isInstance(item) }
            ?.let { getter -> runCatching { getter.invoke(item) }.getOrNull() as? CharSequence }
            ?.toString()
            ?.trim()
            ?.takeIf { it.isNotEmpty() && it.length <= MAX_SERVICE_TITLE_LENGTH }
        if (promotionReasonEnhancementActive && title != null &&
            VideoRelateReasonMatcher.matchesHighConfidencePromotion(setOf(title))
        ) return true
        return strongModeActive && (
            !reasonObservation.hasUsableReason ||
                VideoRelateReasonMatcher.matchesStrongModePromotion(reasons) ||
                VideoRelateReasonMatcher.matchesLikeCount(reasons) ||
                title != null && (
                    VideoRelateReasonMatcher.matchesStrongModePromotion(setOf(title)) ||
                        VideoRelateReasonMatcher.matchesLikeCount(setOf(title))
                    )
            )
    }

    private fun normalizedObservedType(raw: Any): String? {
        val value = (raw as? Enum<*>)?.name ?: raw.toString()
        return normalizeType(value).takeIf { it.isNotBlank() && it !in UNKNOWN_TYPES }
    }

    private fun resolveDurationPaths(
        environment: HookEnvironment,
        points: VersionAdapter.VideoRelatePoints
    ): List<VideoDurationMethodPath> {
        if (!durationRange.isEnabled) return emptyList()
        val direct = points.directDurationGetters.mapIndexedNotNull { index, point ->
            resolve(environment, "duration.direct.$index", point)
        }
        val chains = points.durationChains.mapIndexedNotNull { index, chain ->
            val itemGetter = resolve(environment, "duration.item.$index", chain.itemGetter)
                ?: return@mapIndexedNotNull null
            val durationGetter = resolve(
                environment,
                "duration.value.$index",
                chain.durationGetter
            ) ?: return@mapIndexedNotNull null
            itemGetter to durationGetter
        }
        return VideoDurationReader.buildMethodPaths(direct, chains)
    }

    private fun resolvePlayCountPaths(
        environment: HookEnvironment,
        points: VersionAdapter.VideoRelatePoints
    ): List<VideoPlayCountMethodPath> {
        if (!playCountRange.isEnabled) return emptyList()
        val chains = points.playCountChains.mapIndexedNotNull { index, chain ->
            val itemGetter = resolve(environment, "play_count.item.$index", chain.itemGetter)
                ?: return@mapIndexedNotNull null
            val statGetter = resolve(environment, "play_count.stat.$index", chain.statGetter)
                ?: return@mapIndexedNotNull null
            val vtGetter = resolve(environment, "play_count.vt.$index", chain.vtGetter)
                ?: return@mapIndexedNotNull null
            val valueGetter = resolve(environment, "play_count.value.$index", chain.valueGetter)
                ?: return@mapIndexedNotNull null
            listOf(itemGetter, statGetter, vtGetter, valueGetter)
        }
        return VideoPlayCountReader.buildMethodPaths(chains)
    }

    private fun resolveReasonPaths(
        environment: HookEnvironment,
        points: VersionAdapter.VideoRelatePoints,
        enabled: Boolean
    ): List<VideoRelateReasonMethodPath> {
        if (!enabled) return emptyList()
        val chains = points.reasonChains.mapIndexedNotNull { chainIndex, chain ->
            val methods = chain.steps.mapIndexed { stepIndex, point ->
                resolve(environment, "reason.$chainIndex.$stepIndex", point)
            }
            if (methods.any { it == null }) return@mapIndexedNotNull null
            methods.filterNotNull()
        }
        return VideoRelateReasonReader.buildMethodPaths(chains)
    }

    /** 与 reason/commercial 同模式的链解析；任一级解析不到就丢掉整条链。 */
    private fun resolveChainPaths(
        environment: HookEnvironment,
        chains: List<VersionAdapter.ReasonMethodChain>,
        tag: String,
        enabled: Boolean
    ): List<List<Method>> {
        if (!enabled) return emptyList()
        return chains.mapIndexedNotNull { chainIndex, chain ->
            val methods = chain.steps.mapIndexed { stepIndex, point ->
                resolve(environment, "$tag.$chainIndex.$stepIndex", point)
            }
            if (methods.any { it == null }) null else methods.filterNotNull()
        }
    }

    /**
     * 走链取值。任一级为 null、接收者类型不匹配或调用抛出，就跳过这条链——
     * **绝不回退到 toString 或标题**，那会把无关文本喂进整串相等的判据里。
     * 数值（作者 mid）按十进制字符串出口，与用户填的 mid 直接可比。
     */
    private fun readTexts(item: Any, paths: List<List<Method>>): List<String> {
        if (paths.isEmpty()) return emptyList()
        return paths.mapNotNull { methods ->
            var current: Any? = item
            for (method in methods) {
                val receiver = current ?: return@mapNotNull null
                if (!method.declaringClass.isInstance(receiver)) return@mapNotNull null
                current = runCatching { method.invoke(receiver) }.getOrNull()
            }
            when (val value = current) {
                is CharSequence -> value.toString().takeIf { it.isNotBlank() }
                is Number -> value.toLong().takeIf { it > 0L }?.toString()
                else -> null
            }
        }
    }

    private fun resolveCommercialEvidencePaths(
        environment: HookEnvironment,
        points: VersionAdapter.VideoRelatePoints,
        enabled: Boolean
    ): List<VideoRelateBooleanMethodPath> {
        if (!enabled) return emptyList()
        val chains = points.commercialEvidenceChains.mapIndexedNotNull { chainIndex, chain ->
            val methods = chain.steps.mapIndexed { stepIndex, point ->
                resolve(environment, "commercial.$chainIndex.$stepIndex", point)
            }
            if (methods.any { it == null }) return@mapIndexedNotNull null
            methods.filterNotNull()
        }
        return VideoRelateBooleanEvidenceReader.buildMethodPaths(chains)
    }

    private fun extractEvidence(
        item: Any,
        typeMethods: List<Method>,
        relateTypeMethods: List<Method>,
        sourceTypeMethods: List<Method>,
        sourceTypePaths: List<Pair<Method, Method>>,
        relateTypeValueMethods: List<Method>
    ): VideoRelateTypeEvidence {
        val types = extractTypes(item, typeMethods)
        val relateCardTypes = extractTypes(item, relateTypeMethods)
        val fromSourceTypes = buildSet {
            extractNumbersInto(item, sourceTypeMethods, this) { it.toLong() }
            extractNumbersFromPathsInto(item, sourceTypePaths, this) { it.toLong() }
        }
        val relateCardTypeValues = extractNumbers(item, relateTypeValueMethods) { it.toInt() }
        return VideoRelateTypeEvidence(
            types,
            relateCardTypes,
            fromSourceTypes,
            relateCardTypeValues
        )
    }

    private fun extractTypes(item: Any, methods: List<Method>): Set<String> {
        if (methods.isEmpty()) return emptySet()
        return buildSet {
            methods.forEach { method ->
                if (!method.declaringClass.isInstance(item)) return@forEach
                val raw = runCatching { method.invoke(item) }.getOrNull() ?: return@forEach
                val value = (raw as? Enum<*>)?.name ?: raw.toString()
                val normalized = normalizeType(value)
                if (normalized.isNotBlank() && normalized !in UNKNOWN_TYPES) add(normalized)
            }
        }
    }

    private fun <T> extractNumbers(
        item: Any,
        methods: List<Method>,
        convert: (Number) -> T
    ): Set<T> {
        if (methods.isEmpty()) return emptySet()
        return buildSet { extractNumbersInto(item, methods, this, convert) }
    }

    private inline fun <T> extractNumbersInto(
        item: Any,
        methods: List<Method>,
        destination: MutableSet<T>,
        convert: (Number) -> T
    ) {
        methods.forEach { method ->
            if (!method.declaringClass.isInstance(item)) return@forEach
            val raw = runCatching { method.invoke(item) }.getOrNull() as? Number
                ?: return@forEach
            destination.add(convert(raw))
        }
    }

    private inline fun <T> extractNumbersFromPathsInto(
        item: Any,
        paths: List<Pair<Method, Method>>,
        destination: MutableSet<T>,
        convert: (Number) -> T
    ) {
        paths.forEach { (itemGetter, valueGetter) ->
            if (!itemGetter.declaringClass.isInstance(item)) return@forEach
            val raw = runCatching {
                val nested = itemGetter.invoke(item) ?: return@runCatching null
                if (!valueGetter.declaringClass.isInstance(nested)) return@runCatching null
                valueGetter.invoke(nested)
            }.getOrNull() as? Number ?: return@forEach
            destination.add(convert(raw))
        }
    }

    private fun resolve(
        environment: HookEnvironment,
        suffix: String,
        point: VersionAdapter.HookPoint
    ): Method? = environment.hookPoints.resolveAdapted(
        "video.relate.resolve.$suffix",
        point.className,
        point.methodName,
        point.paramClassNames
    )

    private fun missing(
        environment: HookEnvironment,
        reason: String
    ): FeatureInstallResult.Skipped {
        environment.reportStatus(CHANNEL_STATUS, reason)
        environment.logError(
            "video_relate_missing",
            "[BIL] 视频相关推荐类型过滤适配不完整: $reason"
        )
        return FeatureInstallResult.Skipped(reason)
    }

    companion object {
        const val CAPABILITY_SEMANTIC = "video_related_semantic_filter_enabled"
        const val ID = "video_relate_filter"
        private const val TARGET_PACKAGE = "tv.danmaku.bili"
        private const val CHANNEL_STATUS = "video_relate_filter_status"
        private const val MAX_SERVICE_TITLE_LENGTH = 256
        /** 匹配增强真正能生效的宿主内容类型；能力声明与覆盖判定都以它为准。 */
        private val REASON_ENHANCEMENT_KINDS = setOf(
            HostContentKind.ADVERTISEMENT,
            HostContentKind.SPECIAL
        )
        private val UNKNOWN_TYPES = setOf("UNKNOWN", "CARD_NOT_SET")
        private val KNOWN_CARD_TYPES = setOf(
            "AV",
            "BANGUMI",
            "RESOURCE",
            "GAME",
            "CM",
            "LIVE",
            "BANGUMI_AV",
            "AI_CARD",
            "BANGUMI_UGC",
            "SPECIAL",
            "COURSE",
            "MINI_PROGRAM",
            "HISTORY_AV"
        )
        private val KNOWN_RELATE_TYPE_VALUES = setOf(1, 3, 4, 5, 10)

        internal fun normalizeType(raw: String): String =
            HostContentSemanticClassifier.normalizedToken(raw).orEmpty()

        internal fun matchesAnyType(types: Set<String>, hiddenTypes: Set<String>): Boolean {
            return matchesEvidence(types, emptySet(), emptySet(), hiddenTypes)
        }

        internal fun matchesEvidence(
            types: Set<String>,
            fromSourceTypes: Set<Long>,
            relateCardTypeValues: Set<Int>,
            hiddenTypes: Set<String>,
            relateCardTypes: Set<String> = emptySet()
        ): Boolean {
            if (hiddenTypes.isEmpty()) return false
            val normalizedHidden = hiddenTypes.mapTo(linkedSetOf(), ::normalizeType)
            return matchesNormalizedEvidence(
                types,
                relateCardTypes,
                fromSourceTypes,
                relateCardTypeValues,
                normalizedHidden
            )
        }

        private fun matchesNormalizedEvidence(
            types: Set<String>,
            relateCardTypes: Set<String>,
            fromSourceTypes: Set<Long>,
            relateCardTypeValues: Set<Int>,
            normalizedHidden: Set<String>
        ): Boolean {
            if (types.any { normalizeType(it) in normalizedHidden } ||
                relateCardTypes.any { normalizeType(it) in normalizedHidden }
            ) return true
            val kinds = buildSet {
                types.forEach { type ->
                    HostContentSemanticClassifier.classifyInto(
                        HostContentSignals(
                            cardCase = type,
                            cardType = type,
                            goTo = type,
                            relateCardType = type
                        ), this
                    )
                }
                relateCardTypes.forEach { type ->
                    HostContentSemanticClassifier.classifyInto(
                        HostContentSignals(relateCardType = type), this
                    )
                }
                fromSourceTypes.forEach { sourceType ->
                    HostContentSemanticClassifier.classifyInto(
                        HostContentSignals(fromSourceType = sourceType), this
                    )
                }
                relateCardTypeValues.forEach { typeValue ->
                    HostContentSemanticClassifier.classifyInto(
                        HostContentSignals(relateCardTypeValue = typeValue), this
                    )
                }
            }
            return normalizedHidden.any { hidden ->
                HostContentSemanticClassifier.hiddenKind(hidden)?.let(kinds::contains) == true
            }
        }

        internal fun hasRecognizedTypeEvidence(evidence: VideoRelateTypeEvidence): Boolean {
            fun tokenRecognized(raw: String): Boolean {
                val token = normalizeType(raw)
                return token in KNOWN_CARD_TYPES || HostContentSemanticClassifier.classify(
                    HostContentSignals(
                        cardCase = token,
                        cardType = token,
                        goTo = token,
                        relateCardType = token
                    )
                ).isNotEmpty()
            }
            if (evidence.types.any(::tokenRecognized) ||
                evidence.relateCardTypes.any(::tokenRecognized)
            ) return true
            if (evidence.fromSourceTypes.any { sourceType ->
                    HostContentSemanticClassifier.classify(
                        HostContentSignals(fromSourceType = sourceType)
                    ).isNotEmpty()
                }
            ) return true
            return evidence.relateCardTypeValues.any { it in KNOWN_RELATE_TYPE_VALUES }
        }

        internal fun shouldRemove(type: String?, hiddenTypes: Set<String>): Boolean =
            type != null && matchesAnyType(setOf(type), hiddenTypes)
    }
}

internal data class DetailRelateServiceAccess(
    val componentFactory: Method,
    val typeField: Field?,
    val typeGetter: Method?,
    val titleGetter: Method?
)

/** 同步响应对象内部列表，避免宿主后续绕过 getter 返回值继续读取原集合。 */
internal fun writeBackVideoRelateItems(
    target: Any?,
    field: Field,
    items: List<*>
): Boolean {
    if (target == null || !field.declaringClass.isInstance(target)) return false
    if (!(items.javaClass isSubclassOf field.type)) return false
    return runCatching {
        field.set(target, items)
        true
    }.getOrDefault(false)
}

internal data class VideoRelateTypeEvidence(
    val types: Set<String>,
    val relateCardTypes: Set<String>,
    val fromSourceTypes: Set<Long>,
    val relateCardTypeValues: Set<Int>
)

